function ouProjectionsBenchmarksRoot() {
  return DATA?.meta?.pga_tour_market_benchmarks ? DATA.meta : DATA;
}

function ouBenchmarkYearLabel(meta) {
  const y0 = Math.round(num(meta?.min_year, NaN));
  const y1 = Math.round(num(meta?.max_year, NaN));
  if (Number.isFinite(y0) && Number.isFinite(y1)) return y0 === y1 ? String(y0) : `${y0}–${y1}`;
  return "2025–2026";
}

function ouPgaTourBenchmarkYearLabel() {
  return ouBenchmarkYearLabel(ouProjectionsBenchmarksRoot().pga_tour_market_benchmarks?.meta);
}

function ouCourseBenchmarkYearLabel() {
  return ouBenchmarkYearLabel(ouProjectionsBenchmarksRoot().pga_tour_course_benchmarks?.meta);
}

function ouCourseBenchmarkVenueCount(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const key =
    mKey === "Total score"
      ? "score"
      : mKey === "Birdies"
        ? "birdies"
        : mKey === "Pars"
          ? "pars"
          : mKey === "Bogeys"
            ? "bogeys"
            : mKey === "GIR"
              ? "gir"
              : mKey === "Fairways hit"
                ? "fairways"
                : "";
  const nc = ouProjectionsBenchmarksRoot().pga_tour_course_benchmarks?.meta?.n_courses;
  return key && nc && typeof nc === "object" ? Math.round(num(nc[key], NaN)) : NaN;
}

function ouMarketRatingOpportunities(mKey) {
  if (mKey === "GIR") return 18;
  if (mKey === "Fairways hit") return fairwayHolesModeledFromData();
  return null;
}

const OU_MARKET_RATING_PLAYER_MIN_ROUNDS = 4;
const OU_MARKET_RATING_PLAYER_MAX_ROUNDS = 24;

function ouMarketRatingHistoryReady() {
  return Boolean(HISTORY?._ok) && !HISTORY._loading && !HISTORY._partial;
}

function ouMarketRatingHistoryStatKey(mKey) {
  if (mKey === "Total score") return "total";
  if (mKey === "Birdies") return "birdies";
  if (mKey === "Pars") return "pars";
  if (mKey === "Bogeys") return "bogeys";
  if (mKey === "GIR") return "gir";
  if (mKey === "Fairways hit") return "fairways";
  return "total";
}

/** Completed-round sample for market rating (prefer 2025–2026 when enough rounds exist). */
function ouMarketRatingPlayerRounds(player) {
  const id = Math.round(num(player?.dg_id, NaN));
  if (!Number.isFinite(id)) return [];
  const cacheKey = `${historyMutationEpoch}|${id}`;
  if (OU_MARKET_RATING_ROUNDS_CACHE.has(cacheKey)) return OU_MARKET_RATING_ROUNDS_CACHE.get(cacheKey) || [];
  const all = historyRoundsChronoNewestFirst(id).filter((r) => historyRoundCountsAsActual(r));
  const y2025 = all.filter((r) => {
    const y = parseInt(String(r.year ?? r.season ?? ""), 10);
    return Number.isFinite(y) && y >= 2025 && y <= 2026;
  });
  const pool =
    y2025.length >= OU_MARKET_RATING_PLAYER_MIN_ROUNDS ? y2025 : all;
  const out = pool.slice(0, OU_MARKET_RATING_PLAYER_MAX_ROUNDS);
  if (ouMarketRatingHistoryReady()) OU_MARKET_RATING_ROUNDS_CACHE.set(cacheKey, out);
  return out;
}

/** Round projections field — not Props-tab DK/course filters. */
function ouProjectionFieldPlayerDgIds() {
  const ids = new Set();
  for (const p of roundProjectionPlayersForOuRound()) {
    const id = Math.round(num(p.dg_id, NaN));
    if (Number.isFinite(id) && id > 0) ids.add(id);
  }
  for (const r of [
    ...draftKingsRoundPropsOnly(),
    ...prizePicksRoundPropsOnly(),
    ...sleeperRoundPropsOnly(),
    ...underdogRoundPropsOnly(),
    ...fanduelRoundPropsOnly(),
    ...kalshiRoundPropsOnly(),
    ...caesarsRoundPropsOnly(),
  ]) {
    const id = Math.round(num(r.dg_id, NaN));
    if (Number.isFinite(id) && id > 0) ids.add(id);
  }
  return ids;
}

function invalidateOuProjectionAvgCaches() {
  OU_PROJ_AVG_CACHE.clear();
  ouProjectionFlatRowsCache = null;
  ouProjectionFlatRowsCacheSig = "";
}

function syncOuProjAvgColumnHeader() {
  const th = document.querySelector("#table-ou thead th[data-sort-key='pr-avg']");
  if (!th) return;
  const label = ouProjAvgWindowLabel();
  const sortInd = th.querySelector(".sort-ind");
  for (const child of [...th.childNodes]) {
    if (child !== sortInd) th.removeChild(child);
  }
  th.insertBefore(document.createTextNode(label), sortInd);
  if (!sortInd) {
    th.insertAdjacentHTML(
      "beforeend",
      `<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`,
    );
  }
  th.title = `Historical average — ${label}`;
}

/** Live average for one projection row (always uses toolbar window + row market). */
function ouProjectionRowMarketAvgHit(row) {
  const { player, col } = row;
  const mKey = ouModelMarketKey(col?.market) || ouModelMarketKey(col?.label) || "Total score";
  return ouCachedPlayerMarketAverage(mKey, player, ouProjAvgWindowMode());
}

/** Round projections Average column window (toolbar filter). */
function ouProjAvgWindowMode() {
  const raw = String(document.getElementById("ou-proj-avg-window")?.value || "").trim();
  if (raw === "course" || raw === "season") return raw;
  const n = Math.round(num(raw, NaN));
  if (n === 4 || n === 12 || n === 24 || n === 36 || n === 48) return n;
  return "season";
}

function ouProjAvgWindowLabel(mode = ouProjAvgWindowMode()) {
  if (mode === "season") return `This season (${propsFieldDefaultSeasonYear()})`;
  if (mode === "course") {
    const raw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
    const vn = raw ? formatCourseNameForDisplay(raw) : "";
    return vn ? `At ${vn}` : "At this course";
  }
  if (typeof mode === "number") return `Last ${mode} rounds`;
  return "Average";
}

/** Course-shard rounds for one player (same source as Course Fit distributions). */
function ouPlayerMarketCourseShardRounds(player, venueKey) {
  const id = Math.round(num(player?.dg_id, NaN));
  const vk = String(venueKey || "").trim();
  if (!Number.isFinite(id) || !vk) return [];
  const bucket = propsGetSingleCourseBucketSync(vk);
  if (!bucket?.entries?.length) return [];
  const out = [];
  for (const e of bucket.entries) {
    const row = e?.row;
    if (!row) continue;
    const dg = Math.round(num(e.dgId ?? e.dg_id ?? row.dg_id, NaN));
    if (dg !== id) continue;
    if (!courseFitDistRoundCountsAsActual(row)) continue;
    out.push(row);
  }
  return out.sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
}

function ouCourseShardReadyForProjAvg() {
  const vk = courseFitDistActiveVenueKey();
  if (!vk) return true;
  const bucket = propsGetSingleCourseBucketSync(vk);
  if (bucket?.entries?.length) return true;
  return Boolean(bucket?.shardMissing);
}

let ouCourseShardForProjAvgPromise = null;

function scheduleOuCourseShardForProjAvg() {
  if (ouProjAvgWindowMode() !== "course") return null;
  const vk = courseFitDistActiveVenueKey();
  if (!vk || ouCourseShardReadyForProjAvg()) return null;
  if (ouCourseShardForProjAvgPromise) return ouCourseShardForProjAvgPromise;
  ouCourseShardForProjAvgPromise = ensurePropsCourseIndexForKeyAsync(vk)
    .then(() => {
      invalidateOuProjectionAvgCaches();
      if (activeAppTabId() === "ou") scheduleBuildOuTable(true);
    })
    .catch(() => {
      if (activeAppTabId() === "ou") scheduleBuildOuTable(true);
    })
    .finally(() => {
      ouCourseShardForProjAvgPromise = null;
    });
  return ouCourseShardForProjAvgPromise;
}

function ouPlayerMarketAvgSampleRounds(player, windowMode = ouProjAvgWindowMode()) {
  const id = Math.round(num(player?.dg_id, NaN));
  if (!Number.isFinite(id)) return [];
  let rounds = historyRoundsChronoNewestFirst(id).filter((r) => historyRoundCountsAsActual(r));
  if (windowMode === "course") {
    const venueKey = courseFitDistActiveVenueKey();
    if (venueKey) {
      const shardRounds = ouPlayerMarketCourseShardRounds(player, venueKey);
      if (shardRounds.length) return shardRounds;
      const displayVenue =
        formatCourseNameForDisplay(DATA?.meta?.course_used || DATA?.course_used || "") || venueKey;
      rounds = rounds.filter((r) => {
        const cn = historyRoundCourseName(r);
        const ck = normCourseNameKey(cn);
        return (
          ck === venueKey ||
          courseNameMatchesVenueLoose(cn, displayVenue) ||
          courseNameMatchesVenueLoose(cn, venueKey)
        );
      });
    }
  } else if (windowMode === "season") {
    const seasonY = propsFieldDefaultSeasonYear();
    const seasonRounds = rounds.filter((r) => historyRoundSeasonYear(r) === seasonY);
    rounds = seasonRounds.length ? seasonRounds : rounds.slice(0, 12);
  } else if (typeof windowMode === "number") {
    rounds = rounds.slice(0, windowMode);
  }
  return rounds;
}

/** History / course shards still loading — don't show model μ as a fake historical average. */
function ouPlayerMarketAvgHistoryStillLoading(player, windowMode = ouProjAvgWindowMode()) {
  if (windowMode === "course") {
    if (!ouCourseShardReadyForProjAvg()) return true;
    if (ouFieldHistoryLoadPromise || ouCourseShardForProjAvgPromise) return true;
  } else if (windowMode === "season" || typeof windowMode === "number") {
    if (!ouFieldHistoryReadyForAverages()) return true;
  }
  const id = Math.round(num(player?.dg_id, NaN));
  if (!Number.isFinite(id)) return false;
  if (historyBucketLoaded(id) || playerHistoryAbsentDgIds.has(id)) return false;
  return Boolean(HISTORY?._loading) || Boolean(ouFieldHistoryLoadPromise) || Boolean(ouCourseShardForProjAvgPromise);
}

/** Round Projections Average: only count rows with a real posted stat (not inferred 0 from live placeholders). */
function ouMarketAvgValueForRoundRow(statKey, row) {
  const enriched = enrichHistoryRowFromLiveActuals(row);
  const v = actualForRoundRow(statKey, enriched);
  if (!Number.isFinite(v)) return NaN;
  if (statKey === "total") return v;
  if (statKey === "birdies" || statKey === "pars" || statKey === "bogeys") {
    return historyLiveCountingTrusted(enriched) ? v : NaN;
  }
  return v;
}

/** Player historical average for the selected window (raw completed-round stats only). */
function ouPlayerMarketAverage(market, player, windowMode = ouProjAvgWindowMode()) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rounds = ouPlayerMarketAvgSampleRounds(player, windowMode);
  if (!rounds.length) {
    if (ouPlayerMarketAvgHistoryStillLoading(player, windowMode)) {
      return { avg: NaN, n: 0, source: "pending", windowMode };
    }
    return { avg: NaN, n: 0, source: "none", windowMode };
  }
  const statKey = ouMarketRatingHistoryStatKey(mKey);
  const vals = [];
  for (const r of rounds) {
    const v = ouMarketAvgValueForRoundRow(statKey, r);
    if (Number.isFinite(v)) vals.push(v);
  }
  if (!vals.length) {
    if (ouPlayerMarketAvgHistoryStillLoading(player, windowMode)) {
      return { avg: NaN, n: 0, source: "pending", windowMode };
    }
    return { avg: NaN, n: 0, source: "none", windowMode };
  }
  return {
    avg: vals.reduce((a, b) => a + b, 0) / vals.length,
    n: vals.length,
    source: "history",
    windowMode,
  };
}

let ouFieldHistoryLoadPromise = null;
let ouFieldHistoryLoadedSig = "";
let ouHistoryMergeRebuildRaf = 0;
/** @type {object[] | null} */
let ouProjectionFlatRowsCache = null;
let ouProjectionFlatRowsCacheSig = "";

function ouFieldHistoryLoadSig() {
  const seasonYear = ouProjectionFieldHistorySeasonYear();
  const avgMode = ouProjAvgWindowMode();
  const courseKey = avgMode === "course" ? courseFitDistActiveVenueKey() : "";
  const ids = [...ouProjectionFieldPlayerDgIds()]
    .map((id) => Math.round(num(id, NaN)))
    .filter((id) => Number.isFinite(id))
    .sort((a, b) => a - b)
    .join(",");
  return `${seasonYear}|${avgMode}|${courseKey}|${ids}`;
}

function ouFieldHistoryReadyForAverages() {
  if (ouProjAvgWindowMode() === "course" && !ouCourseShardReadyForProjAvg()) return false;
  const seasonYear = ouProjectionFieldHistorySeasonYear();
  const ids = [...ouProjectionFieldPlayerDgIds()];
  if (!ids.length) return true;
  const bucketReady = (id) =>
    Number.isFinite(seasonYear) ? historyBucketReadyForFieldSeason(id, seasonYear) : historyBucketLoaded(id);
  return ids.every((id) => bucketReady(id) || playerHistoryAbsentDgIds.has(id));
}

function scheduleOuTableRebuildAfterHistory() {
  if (activeAppTabId() !== "ou") return;
  if (ouHistoryMergeRebuildRaf) cancelAnimationFrame(ouHistoryMergeRebuildRaf);
  ouHistoryMergeRebuildRaf = requestAnimationFrame(() => {
    ouHistoryMergeRebuildRaf = 0;
    invalidateOuProjectionAvgCaches();
    scheduleBuildOuTable(true);
  });
}

function ensureOuFieldHistoryOnce() {
  scheduleOuCourseShardForProjAvg();
  if (ouFieldHistoryReadyForAverages() && ouCourseShardReadyForProjAvg()) return;
  if (ouFieldHistoryLoadPromise) return;
  scheduleOuProjectionFieldHistoryLoad();
}

async function ensureOuProjectionFieldHistoryLoaded() {
  const sig = ouFieldHistoryLoadSig();
  if (ouFieldHistoryLoadedSig === sig && ouFieldHistoryReadyForAverages() && ouCourseShardReadyForProjAvg()) return;
  if (!HISTORY._ok && !playerHistoryLoadPromise) {
    await loadPlayerHistory();
  }
  await ensurePgatourEventRoundsLoaded();
  if (HISTORY._ok && lastLiveInPlayBundleForHistory) {
    reapplyLiveInPlayHistoryMerge();
  }
  const seasonYear = ouProjectionFieldHistorySeasonYear();
  await ensurePropsFieldPlayerHistoryLoaded({ seasonYear, ids: ouProjectionFieldPlayerDgIds() });
  if (ouProjAvgWindowMode() === "course") {
    const vk = courseFitDistActiveVenueKey();
    if (vk && !ouCourseShardReadyForProjAvg()) {
      await ensurePropsCourseIndexForKeyAsync(vk);
    }
  }
  ouFieldHistoryLoadedSig = sig;
  invalidateOuProjectionAvgCaches();
  HISTORY_ROUNDS_CHRONO_CACHE.clear();
}

function scheduleOuProjectionFieldHistoryLoad() {
  if (ouFieldHistoryLoadPromise) return ouFieldHistoryLoadPromise;
  ouFieldHistoryLoadPromise = ensureOuProjectionFieldHistoryLoaded()
    .then(() => {
      if (activeAppTabId() === "ou") scheduleBuildOuTable(true);
    })
    .catch(() => {
      if (activeAppTabId() === "ou") scheduleBuildOuTable(true);
    })
    .finally(() => {
      ouFieldHistoryLoadPromise = null;
    });
  return ouFieldHistoryLoadPromise;
}

const OU_PROJ_AVG_CACHE = new Map();

function ouPlayerAvgHistoryPending(player) {
  return ouPlayerMarketAvgHistoryStillLoading(player, ouProjAvgWindowMode());
}

function ouProjectionFieldHistorySeasonYear() {
  return ouProjAvgWindowMode() === "season" ? propsFieldDefaultSeasonYear() : NaN;
}

function ouCachedPlayerMarketAverage(market, player, windowMode = ouProjAvgWindowMode()) {
  const id = Math.round(num(player?.dg_id, NaN));
  const mKey = OU_STAT_MAP[market] ? market : ouModelMarketKey(market) || "Total score";
  const cacheKey = `${historyMutationEpoch}|${windowMode}|${id}|${mKey}`;
  if (OU_PROJ_AVG_CACHE.has(cacheKey)) return OU_PROJ_AVG_CACHE.get(cacheKey);
  const hit = ouPlayerMarketAverage(mKey, player, windowMode);
  OU_PROJ_AVG_CACHE.set(cacheKey, hit);
  return hit;
}

function ouPlayerMarketAverageTitle(market, hit) {
  const label = ouProjAvgWindowLabel(hit?.windowMode);
  const n = Math.round(num(hit?.n, 0));
  if (!Number.isFinite(hit?.avg)) {
    if (hit?.source === "pending" || ouFieldHistoryLoadPromise || ouCourseShardForProjAvgPromise) {
      return `${label} — loading history…`;
    }
    return `${label} — no rounds in window`;
  }
  if (n > 0) return `${label} · n=${n}`;
  return label;
}

/** Player historical average for a market (counts / strokes), not the round projection μ. */
function ouPlayerHistoricalAvgForMarket(market, player) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rounds = ouMarketRatingPlayerRounds(player);
  if (rounds.length < OU_MARKET_RATING_PLAYER_MIN_ROUNDS) return NaN;
  const statKey = ouMarketRatingHistoryStatKey(mKey);
  const vals = [];
  for (const r of rounds) {
    const v = actualForRoundRow(statKey, r);
    if (Number.isFinite(v)) vals.push(v);
  }
  if (vals.length < OU_MARKET_RATING_PLAYER_MIN_ROUNDS) return NaN;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

/** Player historical average for market ratings (completed rounds only — never projection μ). */
function ouPlayerAvgForMarketRating(market, player) {
  const fromHist = ouPlayerHistoricalAvgForMarket(market, player);
  if (Number.isFinite(fromHist)) return { playerAvg: fromHist, ratingSource: "history" };
  return { playerAvg: NaN, ratingSource: "none" };
}

/** Field-relative market rating uses the same raw historical averages as the Average column logic. */
function ouPlayerValueForFieldMarketRating(market, player) {
  const fromHist = ouPlayerHistoricalAvgForMarket(market, player);
  if (Number.isFinite(fromHist)) return { playerAvg: fromHist, ratingSource: "history" };
  return { playerAvg: NaN, ratingSource: "none" };
}

function ouMarketHigherBetter(mKey) {
  return mKey !== "Total score" && mKey !== "Bogeys";
}

/** Field μ/σ for one market (same units as ouPlayerValueForFieldMarketRating). */
function buildOuFieldMarketStats(players, markets) {
  const out = new Map();
  const list = Array.isArray(players) ? players : [];
  for (const market of markets) {
    const mKey = ouModelMarketKey(market) || "Total score";
    const vals = [];
    for (const p of list) {
      const { playerAvg } = ouPlayerValueForFieldMarketRating(market, p);
      if (Number.isFinite(playerAvg)) vals.push(playerAvg);
    }
    if (vals.length < 2) continue;
    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
    const variance = vals.reduce((a, v) => a + (v - mean) ** 2, 0) / (vals.length - 1);
    const sd = Math.sqrt(Math.max(variance, 0));
    out.set(mKey, { mean, sd: Math.max(sd, 1e-6), n: vals.length });
  }
  return out;
}

/** Z-score vs this week's field average (higher rating = stronger on this stat). */
function ouFieldMarketRatingZ(market, playerAvg, fieldStats) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const mu = num(playerAvg, NaN);
  const fs = fieldStats?.get?.(mKey) || fieldStats?.[mKey];
  if (!fs || !Number.isFinite(mu)) return NaN;
  const fieldMean = num(fs.mean, NaN);
  const fieldSd = num(fs.sd, NaN);
  if (!Number.isFinite(fieldMean) || !Number.isFinite(fieldSd) || fieldSd <= 1e-6) return NaN;
  let z = (mu - fieldMean) / fieldSd;
  if (!ouMarketHigherBetter(mKey)) z = -z;
  return z;
}

function ouCachedTourMarketRating(market, player) {
  const id = Math.round(num(player?.dg_id, NaN));
  const mKey = ouModelMarketKey(market) || "Total score";
  const cacheKey = `tour|${historyMutationEpoch}|${id}|${mKey}`;
  if (OU_MARKET_RATING_CACHE.has(cacheKey)) {
    const cached = OU_MARKET_RATING_CACHE.get(cacheKey);
    if (Number.isFinite(cached?.marketRating100)) return cached;
  }
  const { playerAvg, ratingSource } = ouPlayerAvgForMarketRating(market, player);
  const marketRatingZ = ouMarketRatingZ(market, playerAvg);
  const hit = {
    playerAvg,
    marketRatingZ,
    marketRating100: ouZToRating100(marketRatingZ),
    ratingSource,
  };
  if (Number.isFinite(hit.marketRating100)) OU_MARKET_RATING_CACHE.set(cacheKey, hit);
  return hit;
}

function ouCachedFieldMarketRating(market, player, fieldStats) {
  const id = Math.round(num(player?.dg_id, NaN));
  const mKey = ouModelMarketKey(market) || "Total score";
  const fs = fieldStats?.get?.(mKey);
  const fieldSig = fs ? `${fs.mean}|${fs.sd}|${fs.n}` : "na";
  const cacheKey = `field|${historyMutationEpoch}|${fieldSig}|${id}|${mKey}`;
  if (OU_MARKET_RATING_CACHE.has(cacheKey)) {
    const cached = OU_MARKET_RATING_CACHE.get(cacheKey);
    if (Number.isFinite(cached?.marketRating100)) return cached;
  }
  const { playerAvg, ratingSource } = ouPlayerValueForFieldMarketRating(market, player);
  const marketRatingZ = ouFieldMarketRatingZ(market, playerAvg, fieldStats);
  const hit = {
    playerAvg,
    marketRatingZ,
    marketRating100: ouZToRating100(marketRatingZ),
    ratingSource,
    fieldMean: fs?.mean,
    fieldSd: fs?.sd,
    fieldN: fs?.n,
  };
  if (Number.isFinite(hit.marketRating100)) OU_MARKET_RATING_CACHE.set(cacheKey, hit);
  return hit;
}

function ouCachedCourseRating(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  if (OU_COURSE_RATING_CACHE.has(mKey)) return OU_COURSE_RATING_CACHE.get(mKey);
  const venueVal = ouVenueHistoricalValueForMarket(market);
  const courseRatingZ = ouCourseRatingZ(market, venueVal);
  const hit = {
    venueVal,
    courseRatingZ,
    courseRating100: ouZToRating100(courseRatingZ),
  };
  OU_COURSE_RATING_CACHE.set(mKey, hit);
  return hit;
}

function prewarmOuMarketRatingCache(players, cols) {
  const fieldStats = buildOuFieldMarketStats(players, cols.map((c) => c.market));
  for (const p of players) {
    for (const col of cols) {
      ouCachedFieldMarketRating(col.market, p, fieldStats);
    }
  }
}

/** Normalize baked benchmarks (rate for GIR/FW; legacy count rows → rate). */
function ouNormalizePgaTourBenchmark(raw, mKey) {
  if (!raw) return null;
  const mean = num(raw.mean, NaN);
  const sd = num(raw.sd, NaN);
  if (!Number.isFinite(mean) || !Number.isFinite(sd) || sd <= 1e-6) return null;
  const higherBetter = raw.higherBetter !== false;
  let unit = String(raw.unit || "").trim();
  if (!unit) {
    if (mKey === "Total score") unit = "strokes";
    else if (mKey === "GIR" || mKey === "Fairways hit") unit = mean <= 1.05 ? "rate" : "count";
    else unit = "count";
  }
  if (unit === "rate") return { mean, sd, higherBetter, unit: "rate" };
  if (unit === "strokes" || unit === "count") return { mean, sd, higherBetter, unit };
  const opp = mKey === "GIR" ? 18 : Math.round(num(raw.holes, 14)) || 14;
  return { mean: mean / opp, sd: sd / opp, higherBetter, unit: "rate" };
}

function ouPgaTourBenchmarkForMarket(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const root = ouProjectionsBenchmarksRoot();
  const raw = root.pga_tour_market_benchmarks?.[mKey];
  const norm = ouNormalizePgaTourBenchmark(raw, mKey);
  if (norm) return norm;
  return ouNormalizePgaTourBenchmark(OU_PGA_TOUR_BENCHMARK_FALLBACK[mKey], mKey);
}

function ouPgaTourCourseBenchmarkForMarket(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const root = ouProjectionsBenchmarksRoot();
  const raw = root.pga_tour_course_benchmarks?.[mKey];
  const norm = ouNormalizePgaTourBenchmark(raw, mKey);
  if (norm) return norm;
  return ouNormalizePgaTourBenchmark(OU_PGA_TOUR_COURSE_BENCHMARK_FALLBACK[mKey], mKey);
}

/** This week's venue historical average for a market (counts or strokes; GIR/FW as rate). */
function ensureProjectionCourseBasisComplete(basis, payload = {}) {
  const out = basis && typeof basis === "object" ? basis : {};
  const meta = payload && typeof payload === "object" ? payload : {};
  const holePars = Array.isArray(meta.hole_pars) ? meta.hole_pars : DATA?.hole_pars;
  const fromPars = fairwayHoleCountFromHoleParsClient(holePars);
  const coursePar18 = (() => {
    if (Array.isArray(holePars) && holePars.length === 18) {
      let sum = 0;
      for (const p of holePars) {
        const v = Math.round(num(p, NaN));
        if (!Number.isFinite(v) || v < 3 || v > 5) break;
        sum += v;
      }
      if (sum >= 63 && sum <= 76) return sum;
    }
    return Math.round(num(meta.course_par_18, NaN)) || 72;
  })();
  const lo = coursePar18 - 14;
  const hi = coursePar18 + 22;
  out.fairway_holes_modeled = Number.isFinite(fromPars)
    ? fromPars
    : Math.round(num(out.fairway_holes_modeled, 14)) || 14;

  const roundScores = [];
  for (const m of [out.field_avg_score_by_round, out.event_week_field_avg_score_by_round]) {
    if (!m || typeof m !== "object") continue;
    for (const v of Object.values(m)) {
      const x = num(v, NaN);
      if (Number.isFinite(x) && x >= lo && x <= hi) roundScores.push(x);
    }
  }

  if (!Number.isFinite(num(out.venue_avg_round_score, NaN))) {
    const stp = num(out.venue_avg_score_to_par, NaN);
    if (Number.isFinite(stp)) out.venue_avg_round_score = Math.round((coursePar18 + stp) * 100) / 100;
  }
  if (!Number.isFinite(num(out.venue_avg_round_score, NaN)) && roundScores.length) {
    out.venue_avg_round_score =
      Math.round((roundScores.reduce((a, b) => a + b, 0) / roundScores.length) * 100) / 100;
  }
  if (!Number.isFinite(num(out.venue_avg_round_score, NaN)) && Array.isArray(payload.players)) {
    const fromRows = [];
    for (const pl of payload.players) {
      const ts = num(pl.total_score, NaN);
      if (Number.isFinite(ts) && ts >= lo && ts <= hi) fromRows.push(ts);
    }
    if (fromRows.length >= 8) {
      out.venue_avg_round_score =
        Math.round((fromRows.reduce((a, b) => a + b, 0) / fromRows.length) * 100) / 100;
    }
  }
  if (
    !Number.isFinite(num(out.venue_avg_round_score, NaN)) &&
    Number.isFinite(num(out.venue_avg_birdies, NaN)) &&
    Number.isFinite(num(out.venue_avg_bogeys, NaN))
  ) {
    const stpEst = num(out.venue_avg_bogeys, 0) - num(out.venue_avg_birdies, 0);
    out.venue_avg_round_score = Math.round((coursePar18 + stpEst) * 100) / 100;
  }
  if (!Number.isFinite(num(out.venue_avg_score_to_par, NaN)) && Number.isFinite(num(out.venue_avg_round_score, NaN))) {
    out.venue_avg_score_to_par = Math.round((out.venue_avg_round_score - coursePar18) * 1000) / 1000;
  }
  if (!Number.isFinite(num(out.venue_avg_fairways, NaN)) && Number.isFinite(num(out.venue_avg_gir, NaN))) {
    const nFw = out.fairway_holes_modeled;
    out.venue_avg_fairways = Math.round(num(out.venue_avg_gir, 0) * (nFw / 18) * 0.92 * 100) / 100;
  }
  if (
    !Number.isFinite(num(out.venue_avg_pars, NaN)) &&
    Number.isFinite(num(out.venue_avg_birdies, NaN)) &&
    Number.isFinite(num(out.venue_avg_bogeys, NaN))
  ) {
    const p = 18 - num(out.venue_avg_birdies, 0) - num(out.venue_avg_bogeys, 0);
    if (p > 8 && p < 14) out.venue_avg_pars = Math.round(p * 100) / 100;
  }
  return out;
}

function ouVenueHistoricalValueForMarket(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const b = ensureProjectionCourseBasisComplete(DATA?.meta?.projection_course_basis || {}, {
    ...(DATA?.meta || {}),
    players: DATA?.players || [],
  });
  if (DATA?.meta) DATA.meta.projection_course_basis = b;
  if (mKey === "Total score") {
    let v = num(b.venue_avg_round_score, NaN);
    if (!Number.isFinite(v)) {
      const par = Math.round(num(DATA?.meta?.course_par_18, NaN)) || 72;
      const stp = num(b.venue_avg_score_to_par, NaN);
      if (Number.isFinite(stp)) v = par + stp;
    }
    return v;
  }
  if (mKey === "Birdies") return num(b.venue_avg_birdies, NaN);
  if (mKey === "Pars") return num(b.venue_avg_pars, NaN);
  if (mKey === "Bogeys") return num(b.venue_avg_bogeys, NaN);
  if (mKey === "GIR") {
    const g = num(b.venue_avg_gir, NaN);
    if (!Number.isFinite(g)) return NaN;
    return g <= 1.05 ? g : g / 18;
  }
  if (mKey === "Fairways hit") {
    const fw = num(b.venue_avg_fairways, NaN);
    if (!Number.isFinite(fw)) return NaN;
    const opp = fairwayHolesModeledFromData();
    return fw <= 1.05 ? fw : fw / opp;
  }
  return NaN;
}

/**
 * Z-score: player historical average vs PGA Tour average (strokes/counts; GIR/FW as rate per opportunity).
 */
function ouMarketRatingZ(market, playerAvg) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const mu = num(playerAvg, NaN);
  if (!Number.isFinite(mu)) return NaN;
  const b = ouPgaTourBenchmarkForMarket(market);
  if (!b) return NaN;
  let x = mu;
  let tourMu = b.mean;
  let tourSd = b.sd;
  if (b.unit === "rate") {
    const opp = ouMarketRatingOpportunities(mKey);
    if (!Number.isFinite(opp) || opp <= 0) return NaN;
    x = mu / opp;
    tourMu = b.mean;
    tourSd = b.sd;
  }
  if (!Number.isFinite(tourSd) || tourSd <= 1e-6) return NaN;
  let z = (x - tourMu) / tourSd;
  if (!b.higherBetter) z = -z;
  return z;
}

/**
 * Z-score: venue historical average vs distribution of venue averages across PGA courses.
 */
function ouCourseRatingZ(market, venueVal) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const mu = num(venueVal, NaN);
  if (!Number.isFinite(mu)) return NaN;
  const b = ouPgaTourCourseBenchmarkForMarket(market);
  if (!b) return NaN;
  let x = mu;
  let tourMu = b.mean;
  let tourSd = b.sd;
  if (b.unit === "rate") {
    const opp = ouMarketRatingOpportunities(mKey);
    if (Number.isFinite(opp) && opp > 0 && mu > 1.05) {
      x = mu / opp;
      tourMu = b.mean;
      tourSd = b.sd;
    }
  }
  if (!Number.isFinite(tourSd) || tourSd <= 1e-6) return NaN;
  let z = (x - tourMu) / tourSd;
  if (!b.higherBetter) z = -z;
  return z;
}

/** Map z-score to 1–100 (50 ≈ average; higher = stronger on this dimension). */
function ouZToRating100(z) {
  if (!Number.isFinite(z)) return NaN;
  const t = 1 / (1 + 0.3275911 * Math.abs(z));
  const erf =
    1 -
    t *
      (0.254829592 +
        t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429)))) *
      Math.exp(-z * z);
  const sign = z < 0 ? -1 : 1;
  const p = 0.5 * (1 + sign * erf);
  return Math.round(clamp(p * 100, 1, 100));
}

function formatOuRating100(score) {
  if (!Number.isFinite(score)) return "—";
  return String(Math.round(score));
}

function ouRating100CellClass(score) {
  if (!Number.isFinite(score)) return "num";
  if (score >= 55) return "num pos";
  if (score <= 45) return "num neg";
  return "num";
}

function ouMarketRatingFormatValue(market, value, unit) {
  const v = num(value, NaN);
  if (!Number.isFinite(v)) return "—";
  if (unit === "strokes") return v.toFixed(2);
  return v.toFixed(1);
}

/** Fairways/GIR as per-round counts in tooltips (not 0–1 rate). */
function ouRatingAvgDisplay(market, value, bench) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const v = num(value, NaN);
  if (!Number.isFinite(v) || !bench) return "—";
  if (bench.unit === "rate") {
    const opp = ouMarketRatingOpportunities(mKey);
    if (!Number.isFinite(opp) || opp <= 0) return "—";
    const rate = v > 1.05 ? v / opp : v;
    return (rate * opp).toFixed(1);
  }
  return ouMarketRatingFormatValue(market, v, bench.unit);
}

function ouMarketRatingTourAvgDisplay(market, bench) {
  return ouRatingAvgDisplay(market, bench?.mean, bench);
}

function ouMarketRatingTitle(market, playerAvg, ratingSource = "history", fieldStats = null) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const label = ouPropsCanonicalMarket(market);
  const src = "player historical avg";
  const fs = fieldStats?.get?.(mKey);
  if (!fs || !Number.isFinite(playerAvg)) {
    return `Market rating: ${src} vs field average (1–100; higher = better on this stat)`;
  }
  const bench = {
    unit: mKey === "Total score" ? "strokes" : "count",
  };
  const playerStr = ouRatingAvgDisplay(market, playerAvg, bench);
  const fieldStr = ouRatingAvgDisplay(market, fs.mean, bench);
  return `Market rating (${label}: ${src} ${playerStr} vs field avg ${fieldStr}, n=${fs.n}; 50 ≈ field average)`;
}

function ouCourseRatingTitle(market, venueVal) {
  const b = ouPgaTourCourseBenchmarkForMarket(market);
  const yrs = ouCourseBenchmarkYearLabel();
  const label = ouPropsCanonicalMarket(market);
  const nCourses = ouCourseBenchmarkVenueCount(market);
  const nSuffix =
    Number.isFinite(nCourses) && nCourses > 0 ? `, ${nCourses} courses` : "";
  if (!b || !Number.isFinite(venueVal)) {
    return `Course rating: venue avg vs all course averages (${yrs})`;
  }
  const venueStr = ouRatingAvgDisplay(market, venueVal, b);
  const crossStr = ouRatingAvgDisplay(market, b.mean, b);
  return `Course rating (${label}: venue avg ${venueStr} vs all courses avg ${crossStr}${nSuffix}, ${yrs})`;
}

/** Model O/U tab market order; displayed columns are dynamic from live book props. */
const OU_PROJECTION_MARKETS = Object.freeze([
  { market: "Total score", label: "Round score" },
  { market: "Birdies", label: "Birdies or better" },
  { market: "Pars", label: "Pars" },
  { market: "Bogeys", label: "Bogeys" },
  { market: "GIR", label: "GIR" },
  { market: "Fairways hit", label: "Fairways" },
]);

/**
 * Props used to resolve lines and odds (DK scrape + CSV + model fallback rows in JSON).
 * {@link ouProjectionColumnsActive} lists every standard market once `players` exist; these rows supply lines when present.
 */
function ouRoundOuPropsForLines() {
  const props = Array.isArray(DATA.props) ? DATA.props : [];
  const merged = props.filter((r) => {
    const s = String(r.source || "").trim().toLowerCase();
    return (
      !s ||
      s === "draftkings" ||
      s === "prizepicks" ||
      s === "sleeper" ||
      s === "underdog" ||
      s === "fanduel" ||
      s === "kalshi" ||
      s === "caesars" ||
      s === "csv" ||
      s === "model_fallback"
    );
  });
  return merged.length ? merged : props;
}

function draftKingsRoundPropOddsAvailable() {
  return draftKingsRoundPropsOnly().length > 0;
}

function prizePicksRoundPropOddsAvailable() {
  return prizePicksRoundPropsOnly().length > 0;
}

function sleeperRoundPropOddsAvailable() {
  return sleeperRoundPropsOnly().length > 0;
}

function underdogRoundPropOddsAvailable() {
  return underdogRoundPropsOnly().length > 0;
}

function fanduelRoundPropOddsAvailable() {
  return fanduelRoundPropsOnly().length > 0;
}

function kalshiRoundPropOddsAvailable() {
  return kalshiRoundPropsOnly().length > 0;
}

function caesarsRoundPropOddsAvailable() {
  return caesarsRoundPropsOnly().length > 0;
}

function roundBookPropOddsAvailable() {
  return (
    draftKingsRoundPropOddsAvailable() ||
    prizePicksRoundPropOddsAvailable() ||
    sleeperRoundPropOddsAvailable() ||
    underdogRoundPropOddsAvailable() ||
    fanduelRoundPropOddsAvailable() ||
    kalshiRoundPropOddsAvailable() ||
    caesarsRoundPropOddsAvailable()
  );
}

function updateOuDkStatusNoteVisibility() {
  const el = document.getElementById("ou-dk-status-note");
  if (!el) return;
  if (roundBookPropOddsAvailable()) {
    el.hidden = true;
    el.textContent = "";
    return;
  }
  el.hidden = false;
  el.textContent = ouRoundBookLinesUnavailableUserMessage();
}

/** User-facing copy when no DK/PP lines — never surface scraper/env internals. */
function ouRoundBookLinesUnavailableUserMessage() {
  return "Round lines are not available yet for this event.";
}

function ouPickIsDraftKings(pick) {
  return String(pick?.source || "").trim().toLowerCase() === "draftkings";
}

function ouPickIsPrizePicks(pick) {
  return String(pick?.source || "").trim().toLowerCase() === "prizepicks";
}

function ouPropBookLineValue(r) {
  const v = num(r?.line, NaN);
  if (!Number.isFinite(v)) return NaN;
  const src = String(r?.source || "").trim().toLowerCase();
  if (src === "prizepicks" && v === Math.round(v)) return v;
  return enforceHalfLine(v);
}

/** PP milestone lines (e.g. Birdies 0.5) must lose to real counting lines in pick maps. */
function ouPpLineSanityScore(market, line) {
  const bands = {
    "Total Score": [60, 85],
    Birdies: [1.5, 8.5],
    Pars: [6, 14.5],
    Bogeys: [1.5, 8.5],
    GIR: [5, 16.5],
    "Fairways hit": [3, 14.5],
  };
  const b = bands[String(market || "").trim()];
  const v = num(line, NaN);
  if (!b || !Number.isFinite(v)) return -1;
  return v >= b[0] && v <= b[1] ? 2 : -1;
}

function ouBookPickRank(pick, canon) {
  if (!pick) return -1;
  if (String(pick.source || "").trim().toLowerCase() === "prizepicks") {
    return ouPpLineSanityScore(canon, pick.line);
  }
  if (
    String(pick.source || "").trim().toLowerCase() === "sleeper" ||
    String(pick.source || "").trim().toLowerCase() === "underdog" ||
    String(pick.source || "").trim().toLowerCase() === "fanduel" ||
    String(pick.source || "").trim().toLowerCase() === "kalshi" ||
    String(pick.source || "").trim().toLowerCase() === "caesars"
  ) {
    return 2;
  }
  return 2;
}

function ouMapStorePick(map, key, pick, canon) {
  const prev = map.get(key);
  if (!prev || ouBookPickRank(pick, canon) >= ouBookPickRank(prev, canon)) map.set(key, pick);
}

/** Canonical course par from export meta (root course_par_18 or summed hole_pars). */
function coursePar18FromData() {
  const m = DATA?.meta;
  const cp = num(m?.course_par_18, NaN);
  if (Number.isFinite(cp) && cp >= 68 && cp <= 73) return Math.round(cp);
  const hp = m?.hole_pars;
  if (Array.isArray(hp) && hp.length === 18) {
    const s = hp.reduce((sum, p) => sum + Math.round(num(p, 4)), 0);
    if (Number.isFinite(s) && s >= 68 && s <= 73) return s;
  }
  return 72;
}

/**
 * Columns for the Round projections grid + Market filter.
 * Core counting markets always listed; GIR / Fairways when DK or PrizePicks has posted lines for a field player.
 */
function draftKingsHasMarketForRound(market, round) {
  const canon = ouPropsCanonicalMarket(market);
  if (!canon) return false;
  const wantR = Math.round(num(round, NaN));
  const bookRows = [
    ...draftKingsRoundPropsOnly(true),
    ...prizePicksRoundPropsOnly(true),
    ...sleeperRoundPropsOnly(true),
    ...underdogRoundPropsOnly(true),
    ...fanduelRoundPropsOnly(true),
    ...kalshiRoundPropsOnly(true),
    ...caesarsRoundPropsOnly(true),
  ];
  const needFieldMatch = canon === "GIR" || canon === "Fairways hit";
  const fieldPlayers = needFieldMatch ? roundProjectionPlayersForOuRound() : [];
  for (const r of bookRows) {
    if (ouPropsCanonicalMarket(r.market) !== canon) continue;
    const pr = Math.round(num(r.round_num, NaN));
    if (Number.isFinite(wantR) && wantR >= 1 && wantR <= 4) {
      if (Number.isFinite(pr) && pr >= 1 && pr <= 4 && pr !== wantR) continue;
    }
    if (!needFieldMatch) return true;
    for (const p of fieldPlayers) {
      if (ouPropRowMatchesPlayer(r, p)) return true;
    }
  }
  return false;
}

function ouProjectionColumnsActive() {
  const players = Array.isArray(DATA.players) ? DATA.players : [];
  if (players.length) {
    const round = getOuRound();
    return OU_PROJECTION_MARKETS.filter((col) => {
      if (col.market === "GIR" || col.market === "Fairways hit") {
        return draftKingsHasMarketForRound(col.market, round);
      }
      return true;
    });
  }

  const props = Array.isArray(DATA.props) ? DATA.props : [];
  const dk = props.filter((r) => String(r.source || "").trim().toLowerCase() === "draftkings");
  const pp = props.filter((r) => String(r.source || "").trim().toLowerCase() === "prizepicks");
  const nonDk = props.filter((r) => {
    const s = String(r.source || "").trim().toLowerCase();
    return s === "csv" || s === "model_fallback" || !s;
  });
  const dkSet = new Set(dk.map((r) => String(r.market || "").trim()));
  const ppSet = new Set(pp.map((r) => String(r.market || "").trim()));
  const nonDkSet = new Set(nonDk.map((r) => String(r.market || "").trim()));
  const out = [];
  for (const col of OU_PROJECTION_MARKETS) {
    const canon = ouPropsCanonicalMarket(col.market);
    if (col.market === "GIR" || col.market === "Fairways hit") {
      if (dkSet.has(canon) || ppSet.has(canon)) out.push(col);
      continue;
    }
    if (dkSet.has(canon) || ppSet.has(canon) || nonDkSet.has(canon)) out.push(col);
  }
  return out;
}

/**
 * Canonical `OU_STAT_MAP` key for O/U pricing (handles "Total Score", lowercase, minor aliases).
 * Unknown labels still fall back in `ouStatRec` to round score — avoid passing non-O/U markets here.
 */
function ouModelMarketKey(market) {
  const raw = String(market || "").trim();
  if (OU_STAT_MAP[raw]) return raw;
  const sl = raw.toLowerCase().replace(/\s+/g, " ");
  if (sl === "total score" || sl === "round score") return "Total score";
  if (sl === "birdies") return "Birdies";
  if (sl === "pars") return "Pars";
  if (sl === "bogeys" || sl.includes("bogey")) return "Bogeys";
  if (sl === "gir" || sl.includes("green")) return "GIR";
  if (sl.includes("fairway")) return "Fairways hit";
  if (sl.includes("putt")) return "Putts";
  return null;
}

/**
 * Damp in-round live-hole nudges on non-total props when `in_play_affects_round_odds` is false.
 * Prior-round course difficulty uses `meta.prior_round_course_stroke_shift` via combinedCourseDifficultyOUMuAdjustment.
 */
function liveCourseOuNonTotalScale() {
  return inPlayAffectsRoundOdds() ? 1 : 0.28;
}

