function normCourseKeyForForecast(name) {
  return String(name || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/** Cached Open-Meteo hourly payload; recomputed player snapshots when tee times / round change. */
let OPEN_METEO_FORECAST_CACHE = /** @type {{ key: string; atMs: number; hourly: object | null }} */ ({
  key: "",
  atMs: 0,
  hourly: null,
});
const OPEN_METEO_TTL_MS = 30 * 60 * 1000;

function courseCoordinatesFromMeta() {
  const baked = DATA?.meta?.forecast_weather_coords;
  if (baked && Number.isFinite(num(baked.lat, NaN)) && Number.isFinite(num(baked.lon, NaN))) {
    return { lat: num(baked.lat), lon: num(baked.lon) };
  }
  const key = normCourseKeyForForecast(DATA?.meta?.course_used || "");
  return COURSE_COORDINATES_BY_NAME[key] || null;
}

function forecastTimezoneFromMeta() {
  const lab = String(DATA?.meta?.display_round_label || "");
  const m = lab.match(/America\/[A-Za-z_/]+/);
  if (m) return m[0];
  return "America/New_York";
}

function openMeteoForecastUrl(lat, lon, timezone) {
  const u = new URL("https://api.open-meteo.com/v1/forecast");
  u.searchParams.set("latitude", String(lat));
  u.searchParams.set("longitude", String(lon));
  u.searchParams.set(
    "hourly",
    "temperature_2m,relativehumidity_2m,precipitation_probability,precipitation,windspeed_10m,windgusts_10m,weathercode",
  );
  u.searchParams.set("windspeed_unit", "mph");
  u.searchParams.set("temperature_unit", "fahrenheit");
  u.searchParams.set("forecast_days", "8");
  u.searchParams.set("timezone", timezone || "America/New_York");
  return u.href;
}

/** Date + clock from DataGolf tee strings (`YYYY-MM-DD HH:MM` or ISO `YYYY-MM-DDTHH:MM`). */
function parseDgTeetimeParts(teetimeStr) {
  const m = String(teetimeStr || "")
    .trim()
    .match(/^(\d{4}-\d{2}-\d{2})[ T](\d{1,2}):(\d{2})/);
  if (!m) return null;
  return { ymd: m[1], hh: parseInt(m[2], 10), mm: parseInt(m[3], 10) };
}

/** DataGolf field_updates tee times are Eastern (event local) — display as e.g. 7:30 AM. */
function formatDgTeetimeEasternDisplay(teetimeStr) {
  const p = parseDgTeetimeParts(teetimeStr);
  if (!p) return "—";
  let h = p.hh;
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12;
  if (h === 0) h = 12;
  return `${h}:${String(p.mm).padStart(2, "0")} ${ampm}`;
}

function dgTeetimeSortMinutes(teetimeStr) {
  const p = parseDgTeetimeParts(teetimeStr);
  if (!p) return Number.POSITIVE_INFINITY;
  return p.hh * 60 + p.mm;
}

function teeHourFloorIsoFromDg(teetimeStr) {
  const p = parseDgTeetimeParts(teetimeStr);
  if (!p) return "";
  const hh = String(p.hh).padStart(2, "0");
  return `${p.ymd}T${hh}:00`;
}

function hourlyIndexForDgTeetime(timesArr, teetimeStr) {
  const floorIso = teeHourFloorIsoFromDg(teetimeStr);
  const p = parseDgTeetimeParts(teetimeStr);
  if (!floorIso || !p || !Array.isArray(timesArr) || !timesArr.length) return -1;
  for (let i = 0; i < timesArr.length; i++) {
    const t = String(timesArr[i] || "");
    if (t.length >= 16 && t.slice(0, 16) >= floorIso.slice(0, 16)) return i;
  }
  /* Tee after last model hour: use last hour ON THAT CALENDAR DAY — never snap all players to final array slot. */
  let lastSameDay = -1;
  for (let i = 0; i < timesArr.length; i++) {
    const t = String(timesArr[i] || "");
    if (t.slice(0, 10) !== p.ymd) continue;
    lastSameDay = i;
  }
  return lastSameDay;
}

function weatherCodeSeverity(c) {
  const code = Math.round(num(c, NaN));
  if (!Number.isFinite(code)) return 0;
  const stormCodes = [95, 96, 99];
  const rainyCodes = [51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82];
  if (stormCodes.includes(code)) return 50;
  if ([61, 63, 65, 66, 67, 80, 81, 82].includes(code)) return 40;
  if ([51, 53, 55, 56, 57].includes(code)) return 35;
  if ([45, 48].includes(code)) return 25;
  if (code === 3) return 20;
  if (code === 2) return 15;
  if (code === 1) return 5;
  return 0;
}

function openMeteoConditionFromHourSlice(codeWorst, maxPrecipProb, maxPrecipMm = 0, maxWindMph = 0) {
  const p = num(maxPrecipProb, 0);
  const mm = num(maxPrecipMm, 0);
  const c = Math.round(num(codeWorst, NaN));
  const w = num(maxWindMph, 0);
  const rainyCodes = [51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82];
  const stormCodes = [95, 96, 99];
  if (stormCodes.includes(c)) return "storm";
  if (mm >= 0.05 || rainyCodes.includes(c)) return "rain";
  if (p >= 40 || (p >= 28 && (rainyCodes.includes(c) || c === 3))) return "rain";
  if (p >= 22 && c >= 51) return "rain";
  if (w >= 18 && p < 35 && !rainyCodes.includes(c) && !stormCodes.includes(c)) return "windy";
  if ([45, 48, 2, 3].includes(c)) return "cloudy";
  if (Number.isFinite(c) && c <= 1 && p < 15 && mm < 0.02) return "clear";
  if (c === 0) return "clear";
  return "cloudy";
}

/** Median of mean sustained wind and peak gust in a tee-time window (two-value median). */
function windMphFromMeanSustainedAndMaxGust(meanSustainedMph, maxGustMph) {
  const s = num(meanSustainedMph, NaN);
  const g = num(maxGustMph, NaN);
  if (!Number.isFinite(s) && !Number.isFinite(g)) return NaN;
  if (!Number.isFinite(s)) return g;
  if (!Number.isFinite(g)) return s;
  return (s + g) / 2;
}

function hourlySliceWeatherSnapshot(hourly, startIdx, spanHours) {
  const times = hourly?.time;
  const T = hourly?.temperature_2m;
  const W = hourly?.windspeed_10m;
  const G = hourly?.windgusts_10m;
  const H = hourly?.relativehumidity_2m;
  const P = hourly?.precipitation_probability;
  const R = hourly?.precipitation;
  const C = hourly?.weathercode;
  if (!Array.isArray(times) || startIdx < 0 || startIdx >= times.length) return null;
  const end = Math.min(times.length, startIdx + spanHours);
  let nt = 0;
  let sT = 0;
  let sW = 0;
  let sH = 0;
  let worstCode = NaN;
  let worstRank = -1;
  let maxPP = 0;
  let maxMm = 0;
  let maxWind = 0;
  let peakGust = 0;
  for (let i = startIdx; i < end; i++) {
    const ti = num(T?.[i], NaN);
    if (!Number.isFinite(ti)) continue;
    sT += ti;
    const wi = num(W?.[i], NaN);
    if (Number.isFinite(wi)) {
      sW += wi;
      if (wi > maxWind) maxWind = wi;
    }
    const gi = num(G?.[i], NaN);
    if (Number.isFinite(gi) && gi > peakGust) peakGust = gi;
    sH += num(H?.[i], 0);
    const cc = num(C?.[i], NaN);
    if (Number.isFinite(cc)) {
      const rank = weatherCodeSeverity(cc);
      if (rank > worstRank) {
        worstRank = rank;
        worstCode = cc;
      }
    }
    const pp = num(P?.[i], 0);
    if (pp > maxPP) maxPP = pp;
    const mm = num(R?.[i], 0);
    if (mm > maxMm) maxMm = mm;
    nt++;
  }
  if (!nt) return null;
  const meanSustained = Number.isFinite(sW) && nt > 0 ? sW / nt : NaN;
  const maxGust = peakGust > 0 ? peakGust : maxWind;
  const windMph = windMphFromMeanSustainedAndMaxGust(meanSustained, maxGust);
  const peakForCond = Math.max(maxWind, peakGust);
  const cond = openMeteoConditionFromHourSlice(worstCode, maxPP, maxMm, peakForCond);
  return {
    tempF: sT / nt,
    /** Median of mean sustained 10 m wind and max gust in the tee-time window (mph). */
    windMph,
    humidityPct: sH / nt,
    condition: cond,
  };
}

function medianFinite(vals) {
  const a = vals.filter((x) => Number.isFinite(x)).sort((x, y) => x - y);
  if (!a.length) return NaN;
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}

function medianWeatherSnapshotFromSamples(samples) {
  if (!samples.length) return null;
  const mt = medianFinite(samples.map((s) => s.tempF));
  const mw = medianFinite(samples.map((s) => s.windMph));
  const mh = medianFinite(samples.map((s) => s.humidityPct));
  if (!Number.isFinite(mt) || !Number.isFinite(mw) || !Number.isFinite(mh)) return null;
  const rank = { storm: 5, rain: 4, windy: 3, cloudy: 2, clear: 1, default: 0 };
  let bestC = "default";
  let br = -1;
  for (const s of samples) {
    const c = String(s.condition || "default").toLowerCase();
    const r = rank[c] ?? 0;
    if (r > br) {
      br = r;
      bestC = c;
    }
  }
  return {
    tempF: mt,
    windMph: mw,
    humidityPct: mh,
    condition: bestC,
  };
}

function weatherConditionDisplayLabel(condRaw) {
  const c = String(condRaw || "").trim().toLowerCase();
  if (!c || c === "default") return "neutral";
  return c;
}

/** Emoji for Open-Meteo-derived condition buckets (wave banner + accessible companion text stays in the stats line). */
function weatherConditionEmoji(condRaw) {
  const c = String(condRaw || "").trim().toLowerCase();
  if (c === "storm") return "⛈️";
  if (c === "rain") return "🌧️";
  if (c === "windy") return "💨";
  if (c === "cloudy") return "☁️";
  if (c === "clear") return "☀️";
  return "🌤️";
}

function escapeHtmlText(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatPinSheetBannerCopy(pinMeta) {
  if (!pinMeta || typeof pinMeta !== "object") return "";
  const summary = String(pinMeta.summary || "").trim();
  if (summary) return summary;
  const delta = num(pinMeta.total_score_delta, NaN);
  const hard = Array.isArray(pinMeta.hard_holes) ? pinMeta.hard_holes : [];
  const easy = Array.isArray(pinMeta.easy_holes) ? pinMeta.easy_holes : [];
  const parts = [];
  if (Number.isFinite(delta)) {
    const sign = delta >= 0 ? "+" : "";
    parts.push(`${sign}${delta.toFixed(2)} stroke impact on projected total`);
  }
  if (hard.length) parts.push(`Tough: ${hard.join(", ")}`);
  if (easy.length) parts.push(`Easier: ${easy.join(", ")}`);
  const note = String(pinMeta.analyst_note || "").trim();
  if (note && parts.length < 2) parts.push(note);
  return parts.join(" · ");
}

/** Stacked morning / afternoon / pin-sheet rows for WEATHER toolbars. */
function weatherWaveForecastBannerInnerHtml(morningSnap, afternoonSnap, pinMeta) {
  const bits = [];
  if (morningSnap) {
    const line = formatWeatherSnapshotCompact(morningSnap);
    if (line) {
      const em = weatherConditionEmoji(morningSnap.condition);
      bits.push(
        `<div class="weather-wave-line"><span class="weather-wave-emoji" aria-hidden="true">${em}</span><span class="weather-wave-copy"><strong class="weather-wave-kicker">Morning tees</strong><span class="weather-wave-sep"> · </span><span class="weather-wave-stats">${escapeHtmlText(line)}</span></span></div>`,
      );
    }
  }
  if (afternoonSnap) {
    const line = formatWeatherSnapshotCompact(afternoonSnap);
    if (line) {
      const em = weatherConditionEmoji(afternoonSnap.condition);
      bits.push(
        `<div class="weather-wave-line"><span class="weather-wave-emoji" aria-hidden="true">${em}</span><span class="weather-wave-copy"><strong class="weather-wave-kicker">Afternoon tees</strong><span class="weather-wave-sep"> · </span><span class="weather-wave-stats">${escapeHtmlText(line)}</span></span></div>`,
      );
    }
  }
  if (pinMeta && typeof pinMeta === "object") {
    const pinSummary = formatPinSheetBannerCopy(pinMeta);
    if (pinSummary) {
      const rnd = Math.round(num(pinMeta.round, NaN));
      bits.push(
        `<div class="weather-wave-line pin-sheet-line"><span class="weather-wave-emoji" aria-hidden="true">📍</span><span class="weather-wave-copy"><strong class="weather-wave-kicker">Pin sheet${Number.isFinite(rnd) ? ` R${rnd}` : ""}</strong><span class="weather-wave-sep"> · </span><span class="weather-wave-stats">${escapeHtmlText(pinSummary)}</span></span></div>`,
      );
    }
  }
  if (!bits.length) return "";
  return `<div class="weather-wave-banner-inner">${bits.join("")}</div>`;
}

/** One-line weather for banners and model-input panels (matches projection row snapshot). */
function formatWeatherSnapshotCompact(w) {
  if (!w || typeof w !== "object" || !Number.isFinite(w.tempF)) return "";
  if (!Number.isFinite(w.windMph) || !Number.isFinite(w.humidityPct)) return "";
  const cond = String(w.condition || "default").toLowerCase();
  const condTxt =
    cond && cond !== "default" && cond !== "clear" ? ` · ${cond}` : "";
  return `${w.tempF.toFixed(1)}°F · ${w.windMph.toFixed(1)} mph · ${w.humidityPct.toFixed(0)}% humidity${condTxt}`;
}

function seedWeatherStateFromForecastMeta() {
  const slots = DATA?.meta?.forecast_wave_slots;
  const snap =
    slots && typeof slots === "object"
      ? slots.morning && Number.isFinite(num(slots.morning.tempF, NaN))
        ? slots.morning
        : slots.afternoon
      : null;
  if (!snap || !Number.isFinite(num(snap.tempF, NaN))) return;
  WEATHER_STATE = {
    tempF: num(snap.tempF, WEATHER_DEFAULTS.tempF),
    windMph: num(snap.windMph, WEATHER_DEFAULTS.windMph),
    humidityPct: num(snap.humidityPct, WEATHER_DEFAULTS.humidityPct),
    condition: String(snap.condition || WEATHER_DEFAULTS.condition).toLowerCase(),
  };
}

/** Pick forecast day: current display_round tee majority, then field majority, then event start. */
function forecastAnchorDateYmd(hourly) {
  const times = hourly?.time;
  if (!Array.isArray(times) || !times.length) return "";
  const hasDay = (ymd) => times.some((t) => String(t || "").slice(0, 10) === ymd);

  const majorityTeeDate = (roundFilter) => {
    const counts = new Map();
    for (const pl of DATA.players || []) {
      if (roundFilter != null && Math.round(num(pl?.round, NaN)) !== roundFilter) continue;
      const tt = parseDgTeetimeParts(pl?.dg_teetime_local);
      if (!tt || !hasDay(tt.ymd)) continue;
      counts.set(tt.ymd, (counts.get(tt.ymd) || 0) + 1);
    }
    let best = "";
    let bestN = -1;
    for (const [ymd, n] of counts) {
      if (n > bestN) {
        bestN = n;
        best = ymd;
      }
    }
    return best;
  };

  const displayRound = Math.round(
    num(DATA?.meta?.display_round ?? DATA?.meta?.datagolf_live_current_round, NaN),
  );
  if (Number.isFinite(displayRound) && displayRound >= 1) {
    const roundDay = majorityTeeDate(displayRound);
    if (roundDay) return roundDay;
  }

  const fieldDay = majorityTeeDate(null);
  if (fieldDay) return fieldDay;

  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/);
  if (ds && hasDay(ds[1])) return ds[1];

  return String(times[0]).slice(0, 10);
}

function firstHourIndexOnDate(hourly, dateYmd) {
  const times = hourly?.time;
  if (!Array.isArray(times) || !dateYmd) return -1;
  for (let i = 0; i < times.length; i++) {
    if (String(times[i] || "").slice(0, 10) === dateYmd) return i;
  }
  return -1;
}

function hourlyIndexNearLocalHour(hourly, dateYmd, hour) {
  const times = hourly?.time;
  if (!Array.isArray(times) || !dateYmd) return -1;
  const want = `${dateYmd}T${String(Math.min(23, Math.max(0, hour))).padStart(2, "0")}`;
  let lastSameDay = -1;
  for (let i = 0; i < times.length; i++) {
    const t = String(times[i] || "");
    if (t.slice(0, 10) !== dateYmd) continue;
    lastSameDay = i;
    if (t.length >= 13 && t.slice(0, 13) >= want) return i;
  }
  return lastSameDay;
}

/**
 * Banner summary: median per-tee forecast in each wave (early/morning vs late/afternoon).
 * Falls back to fixed ~8:00 / ~15:00 only when tee times are missing.
 */
function computeMorningAfternoonForecastSnapshots(hourly) {
  if (!hourly) return { morning: null, afternoon: null };
  const timesArr = hourly.time;
  if (!Array.isArray(timesArr) || !timesArr.length) return { morning: null, afternoon: null };

  const forecastRound = effectiveUiModelRoundFromMeta();
  const morningSamples = [];
  const afternoonSamples = [];

  for (const pl of DATA.players || []) {
    if (Number.isFinite(forecastRound) && Math.round(num(pl?.round, NaN)) !== forecastRound) continue;
    const tt = pl?.dg_teetime_local;
    if (!tt) continue;
    const ix = hourlyIndexForDgTeetime(timesArr, tt);
    if (ix < 0) continue;
    const snap = hourlySliceWeatherSnapshot(hourly, ix, 5);
    if (!snap) continue;
    const wave = normalizedTeeWave(pl);
    if (wave === "afternoon") afternoonSamples.push(snap);
    else if (wave === "morning") morningSamples.push(snap);
  }

  if (morningSamples.length || afternoonSamples.length) {
    return {
      morning: medianWeatherSnapshotFromSamples(morningSamples),
      afternoon: medianWeatherSnapshotFromSamples(afternoonSamples),
    };
  }

  const dateYmd = forecastAnchorDateYmd(hourly);
  if (!dateYmd) return { morning: null, afternoon: null };

  const dayStart = firstHourIndexOnDate(hourly, dateYmd);
  if (dayStart < 0) return { morning: null, afternoon: null };

  let ixM = hourlyIndexNearLocalHour(hourly, dateYmd, 8);
  let ixA = hourlyIndexNearLocalHour(hourly, dateYmd, 15);
  if (ixM < 0) ixM = dayStart;
  if (ixA < 0) ixA = hourlyIndexNearLocalHour(hourly, dateYmd, 14);
  if (ixA < 0) ixA = Math.min(timesArr.length - 5, dayStart + 7);

  const minGap = 5;
  if (ixA - ixM < minGap) ixA = Math.min(timesArr.length - 5, ixM + minGap);
  if (ixA <= ixM) ixA = Math.min(timesArr.length - 5, ixM + minGap);

  return {
    morning: hourlySliceWeatherSnapshot(hourly, ixM, 5),
    afternoon: hourlySliceWeatherSnapshot(hourly, ixA, 5),
  };
}

function buildForecastWaveSummaryString(morningSnap, afternoonSnap) {
  const m = morningSnap ? formatWeatherSnapshotCompact(morningSnap) : "";
  const a = afternoonSnap ? formatWeatherSnapshotCompact(afternoonSnap) : "";
  if (!m && !a) return "";
  const parts = [];
  if (m) parts.push(`Morning tees: ${m}.`);
  if (a) parts.push(`Afternoon tees: ${a}.`);
  return parts.join("\n");
}

function finalizeForecastWaveSummary(hourlyOrNull) {
  if (!DATA.meta) DATA.meta = {};
  if (hourlyOrNull && DATA.players?.length) {
    const { morning, afternoon } = computeMorningAfternoonForecastSnapshots(hourlyOrNull, DATA.players);
    DATA.meta.forecast_wave_slots = { morning, afternoon };
    DATA.meta.forecast_wave_summary = buildForecastWaveSummaryString(morning, afternoon);
  } else if (DATA.meta.forecast_wave_slots && typeof DATA.meta.forecast_wave_slots === "object") {
    const slots = DATA.meta.forecast_wave_slots;
    const morning = slots.morning ?? null;
    const afternoon = slots.afternoon ?? null;
    if (!String(DATA.meta.forecast_wave_summary || "").trim()) {
      DATA.meta.forecast_wave_summary = buildForecastWaveSummaryString(morning, afternoon);
    }
  } else {
    DATA.meta.forecast_wave_slots = { morning: null, afternoon: null };
    DATA.meta.forecast_wave_summary = "";
  }
  syncForecastWaveBannerTexts();
}

/** Trust server-baked Open-Meteo on projections.json (push:live / bake:weather) for several hours. */
const BAKED_FORECAST_WEATHER_MAX_AGE_MS = 6 * 60 * 60 * 1000;

function projectionsWeatherUsableFromBaked() {
  if (!DATA.meta || !DATA.players?.length) return false;
  const st = String(DATA.meta.forecast_weather_status || "");
  if (["open_meteo_fetch_failed", "empty_hourly", "no_course_coords", "no_players"].includes(st)) return false;
  const at = DATA.meta.forecast_weather_updated_at;
  if (!at) return false;
  const age = Date.now() - Date.parse(at);
  if (!Number.isFinite(age) || age > BAKED_FORECAST_WEATHER_MAX_AGE_MS) return false;
  if (age < -30 * 60 * 1000) return false;
  const bakedRound = Math.round(num(DATA.meta.forecast_weather_display_round, NaN));
  const currentRound = effectiveUiModelRoundFromMeta();
  if (Number.isFinite(bakedRound) && Number.isFinite(currentRound) && bakedRound !== currentRound) return false;
  const forecastRound = Number.isFinite(currentRound) ? currentRound : bakedRound;
  const field = DATA.players.filter((p) => {
    if (Number.isFinite(forecastRound) && Math.round(num(p.round, NaN)) !== forecastRound) return false;
    if (Number.isFinite(num(p.weather_temp_f, NaN))) return true;
    const auto = p.dg_auto_weather;
    return auto && typeof auto === "object" && Number.isFinite(num(auto.tempF, NaN));
  });
  return field.length > 0;
}

/** Sync baked weather_* columns ↔ dg_auto_weather after loading projections.json. */
function hydrateBakedWeatherFromPlayerFields() {
  if (!DATA.players?.length) return;
  for (const p of DATA.players) {
    const t = num(p.weather_temp_f, NaN);
    const w = num(p.weather_wind_mph, NaN);
    const h = num(p.weather_humidity, NaN);
    if (Number.isFinite(t) && Number.isFinite(w) && Number.isFinite(h)) {
      p.dg_auto_weather = {
        tempF: t,
        windMph: w,
        humidityPct: h,
        condition: String(p.weather_condition || p.dg_auto_weather?.condition || "default").toLowerCase(),
      };
      continue;
    }
    const auto = p.dg_auto_weather;
    if (auto && typeof auto === "object" && Number.isFinite(num(auto.tempF, NaN))) {
      p.weather_temp_f = Math.round(auto.tempF * 10) / 10;
      p.weather_wind_mph = Math.round(num(auto.windMph, 0) * 10) / 10;
      p.weather_humidity = Math.round(num(auto.humidityPct, 0));
      p.weather_condition = String(auto.condition || "default").toLowerCase();
    }
  }
}

async function ensureForecastWeatherLoaded() {
  hydrateBakedWeatherFromPlayerFields();
  const status = String(DATA.meta?.forecast_weather_status || "");
  const slots = DATA.meta?.forecast_wave_slots;
  const hasWave =
    Boolean(slots && typeof slots === "object" && (slots.morning || slots.afternoon)) ||
    Boolean(String(DATA.meta?.forecast_wave_summary || "").trim());
  const needsFetch =
    !projectionsWeatherUsableFromBaked() ||
    !hasWave ||
    ["no_course_coords", "open_meteo_fetch_failed", "empty_hourly", "no_players"].includes(status);
  if (needsFetch) {
    await refreshForecastWeatherFromOpenMeteo();
  } else {
    finalizeForecastWaveSummary(null);
    PRICING_MU_BONUS_CACHE.clear();
  }
  syncForecastWaveBannerTexts();
}

function syncForecastWaveBannerTexts() {
  const fallback =
    "Morning and afternoon snapshots appear once the venue forecast loads.";
  const slots = DATA.meta?.forecast_wave_slots;
  const morning = slots && typeof slots === "object" ? slots.morning : null;
  const afternoon = slots && typeof slots === "object" ? slots.afternoon : null;
  const html = weatherWaveForecastBannerInnerHtml(morning, afternoon, DATA.meta?.pin_sheet);
  const status = String(DATA.meta?.forecast_weather_status || "");
  const forecastLoaded =
    Boolean(DATA.meta?.forecast_weather_updated_at) &&
    !["open_meteo_fetch_failed", "empty_hourly", "no_course_coords", "no_players"].includes(status);
  const summaryText =
    typeof DATA.meta?.forecast_wave_summary === "string" ? DATA.meta.forecast_wave_summary.trim() : "";
  for (const id of ["ou-weather-wave-summary", "ev-weather-wave-summary"]) {
    const el = document.getElementById(id);
    if (!el) continue;
    el.hidden = false;
    if (html) {
      el.innerHTML = html;
      el.classList.add("weather-wave-banner");
    } else if (summaryText) {
      el.classList.remove("weather-wave-banner");
      el.textContent = summaryText;
    } else if (forecastLoaded) {
      el.classList.remove("weather-wave-banner");
      el.textContent = "";
      el.hidden = true;
    } else {
      el.classList.remove("weather-wave-banner");
      el.textContent = fallback;
    }
  }
}

/**
 * DataGolf documents tee times in field-updates (bundled as live-in-play `field_updates`).
 * Hourly conditions come from Open-Meteo at the venue — DG website hourly tables are not in the public API feed.
 */
async function refreshForecastWeatherFromOpenMeteo() {
  if (typeof fetch !== "function") return false;
  if (projectionsWeatherUsableFromBaked()) {
    hydrateBakedWeatherFromPlayerFields();
    finalizeForecastWaveSummary(null);
    PRICING_MU_BONUS_CACHE.clear();
    return true;
  }
  const coords = courseCoordinatesFromMeta();
  const tz = forecastTimezoneFromMeta();
  if (!DATA.meta) DATA.meta = {};
  if (!coords || !DATA.players?.length) {
    for (const p of DATA.players || []) delete p.dg_auto_weather;
    DATA.meta.forecast_weather_status = coords ? "no_players" : "no_course_coords";
    finalizeForecastWaveSummary(null);
    return false;
  }
  const cacheKey = `${coords.lat}|${coords.lon}|${tz}|${DATA.meta.datagolf_field_date_start || ""}`;
  const now = Date.now();
  let hourly = OPEN_METEO_FORECAST_CACHE.hourly;
  if (
    OPEN_METEO_FORECAST_CACHE.key !== cacheKey ||
    now - OPEN_METEO_FORECAST_CACHE.atMs > OPEN_METEO_TTL_MS ||
    !hourly
  ) {
    try {
      const res = await fetch(openMeteoForecastUrl(coords.lat, coords.lon, tz));
      if (!res.ok) throw new Error(String(res.status));
      const j = await res.json();
      hourly = j.hourly;
      OPEN_METEO_FORECAST_CACHE = { key: cacheKey, atMs: now, hourly };
    } catch {
      DATA.meta.forecast_weather_status = "open_meteo_fetch_failed";
      finalizeForecastWaveSummary(null);
      return false;
    }
  }
  const timesArr = hourly?.time;
  if (!Array.isArray(timesArr) || !timesArr.length) {
    DATA.meta.forecast_weather_status = "empty_hourly";
    finalizeForecastWaveSummary(null);
    return false;
  }

  const forecastRound = effectiveUiModelRoundFromMeta();
  if (Number.isFinite(forecastRound) && forecastRound >= 1) {
    DATA.meta.forecast_weather_display_round = forecastRound;
  }

  const perTeeSamples = [];
  for (const p of DATA.players) {
    if (Number.isFinite(forecastRound) && Math.round(num(p.round, NaN)) !== forecastRound) continue;
    const tt = p?.dg_teetime_local;
    if (!tt) continue;
    const ix = hourlyIndexForDgTeetime(timesArr, tt);
    if (ix < 0) continue;
    const snap = hourlySliceWeatherSnapshot(hourly, ix, 5);
    if (snap) perTeeSamples.push(snap);
  }
  const medianSnap = medianWeatherSnapshotFromSamples(perTeeSamples);

  for (const p of DATA.players) {
    if (Number.isFinite(forecastRound) && Math.round(num(p.round, NaN)) !== forecastRound) {
      delete p.dg_auto_weather;
      p.weather_temp_f = null;
      p.weather_wind_mph = null;
      p.weather_humidity = null;
      p.weather_condition = "";
      continue;
    }
    const tt = p?.dg_teetime_local;
    let snap = null;
    if (tt) {
      const ix = hourlyIndexForDgTeetime(timesArr, tt);
      if (ix >= 0) snap = hourlySliceWeatherSnapshot(hourly, ix, 5);
    }
    if (!snap && medianSnap && Number.isFinite(medianSnap.tempF)) {
      snap = { ...medianSnap };
    }
    if (snap && Number.isFinite(snap.tempF) && Number.isFinite(snap.windMph) && Number.isFinite(snap.humidityPct)) {
      p.dg_auto_weather = snap;
      p.weather_temp_f = Math.round(snap.tempF * 10) / 10;
      p.weather_wind_mph = Math.round(snap.windMph * 10) / 10;
      p.weather_humidity = Math.round(snap.humidityPct);
      p.weather_condition = String(snap.condition || "default").toLowerCase();
    } else delete p.dg_auto_weather;
  }

  DATA.meta.forecast_weather_status = perTeeSamples.length ? "ok_tee_time" : medianSnap ? "ok_median" : "no_tee_match";
  DATA.meta.forecast_weather_updated_at = new Date().toISOString();
  finalizeForecastWaveSummary(hourly);
  PRICING_MU_BONUS_CACHE.clear();
  return true;
}

const PRICING_STATE = Object.freeze({ mode: "default", skill: "default" });
const PRICING_SKILL_COLUMNS = Object.freeze(["sg_total", "sg_ott", "sg_app", "sg_arg", "sg_putt", "sg_t2g"]);

function pricingSkillHistoryKey() {
  return "sg_total";
}

function refreshPricingAffectedViews() {
  const tab = activeAppTabId();
  if (!tab) {
    updateHomePage();
    return;
  }
  if (tab === "ou") return void scheduleBuildOuTable(true);
  if (tab === "ev") return void buildEvTable();
  if (tab === "matchups") return void buildMatchupsTable();
  if (tab === "matchup-analysis") return void buildMatchupAnalysisTool();
  if (tab === "outrights") return void buildOutrightsTable();
  if (tab === "props") {
    scheduleRenderPropsTrends(0);
    updatePropsFooterEv();
    return;
  }
  if (tab === "live-prop") return void renderLivePropPredictor();
  if (tab === "course-fit") return void buildCourseFitTab();
  if (tab === "live-stats") return void buildLiveStatsTab();
  if (tab === "parlay-pro" && window.ParlayPro) return void window.ParlayPro.render();
}

function weatherScalarFromInput(raw, cur, lo, hi) {
  const s = String(raw ?? "").trim();
  if (s === "") return cur;
  const n = Number(s);
  if (!Number.isFinite(n)) return cur;
  return clamp(n, lo, hi);
}

function weatherFromUiIds(ids) {
  const tempEl = document.getElementById(ids.temp);
  const windEl = document.getElementById(ids.wind);
  const humEl = document.getElementById(ids.humidity);
  const condEl = document.getElementById(ids.condition);
  return {
    tempF: weatherScalarFromInput(tempEl?.value, WEATHER_STATE.tempF, 20, 120),
    windMph: weatherScalarFromInput(windEl?.value, WEATHER_STATE.windMph, 0, 60),
    humidityPct: weatherScalarFromInput(humEl?.value, WEATHER_STATE.humidityPct, 0, 100),
    condition: String(condEl?.value || WEATHER_DEFAULTS.condition).toLowerCase(),
  };
}

function syncWeatherUiFromState() {
  const ae = document.activeElement;
  for (const ids of WEATHER_UI_IDS) {
    const tempEl = document.getElementById(ids.temp);
    const windEl = document.getElementById(ids.wind);
    const humEl = document.getElementById(ids.humidity);
    const condEl = document.getElementById(ids.condition);
    if (tempEl && tempEl !== ae) tempEl.value = String(Math.round(WEATHER_STATE.tempF));
    if (windEl && windEl !== ae) windEl.value = String(Math.round(WEATHER_STATE.windMph));
    if (humEl && humEl !== ae) humEl.value = String(Math.round(WEATHER_STATE.humidityPct));
    if (condEl && condEl !== ae) condEl.value = WEATHER_STATE.condition;
  }
}

function weatherDifficultyDeltaFromSnapshot(w) {
  if (!w || typeof w !== "object") return 0;
  const tempF = num(w.tempF, 72);
  const wind = num(w.windMph, 8);
  const hum = num(w.humidityPct, 55);
  const cond = String(w.condition || "default").toLowerCase();
  let tempAdj = tempF >= 72 ? 0.03 * (tempF - 72) : 0.02 * (tempF - 72);
  if (wind < WIND_EFFECT_FLOOR_MPH && cond !== "windy" && cond !== "storm") tempAdj *= 0.35;
  let priorMm = num(w.priorPrecipMm, NaN);
  if (!Number.isFinite(priorMm) && (w.priorRainSoft === true || w.priorRainSoft === 1)) priorMm = 3;
  if (!Number.isFinite(priorMm)) priorMm = 0;
  let windAdj = Math.max(0, wind - WIND_EFFECT_FLOOR_MPH) * WIND_STROKES_PER_MPH;
  if (priorMm >= 8) windAdj *= 0.35;
  else if (priorMm >= 5) windAdj *= 0.42;
  else if (priorMm >= 3) windAdj *= 0.55;
  else if (priorMm >= 1.5) windAdj *= 0.72;
  else if (priorMm >= 0.5) windAdj *= 0.88;
  const humAdj = 0.006 * (hum - 55);
  let d = tempAdj + windAdj + humAdj;
  if (cond !== "default") {
    let condD = WEATHER_CONDITION_MEAN_DELTA[cond] ?? 0;
    if (priorMm >= 4 && (cond === "rain" || cond === "storm")) condD *= 0.35;
    d += condD;
  }
  if (priorMm >= 0.3) {
    if (priorMm < 1) d -= 0.35;
    else if (priorMm < 3) d -= 0.7;
    else if (priorMm < 6) d -= 1.2;
    else if (priorMm < 12) d -= 1.5;
    else if (priorMm < 20) d -= 1.7;
    else d -= 1.9;
  }
  if (
    !(priorMm >= 0.3) &&
    wind < WIND_EFFECT_FLOOR_MPH &&
    cond !== "windy" &&
    cond !== "storm" &&
    cond !== "rain"
  ) {
    d -= 0.08;
  }
  return clamp(d, -2.2, 2.6);
}

function projectionCountsWeatherBaked(row) {
  if (!row?.weather_counts_baked) return false;
  const meta = DATA?.meta;
  if (meta?.projection_counts_weather_baked) return true;
  if (meta?.hierarchical_mu?.owns_weather) return true;
  if (String(meta?.projection_recipe || row?.projection_recipe || "").includes("hierarchical_mu")) return true;
  // Snapshot alone means export already baked weather into μ (hierarchical / bake:weather).
  return Boolean(row._weather_bake_snapshot);
}

/** Hierarchical export already includes weather + course/form — do not re-stack runtime overlays. */
function hierarchicalMuOwnsRow(row) {
  if (String(row?.projection_recipe || "").includes("hierarchical_mu")) return true;
  if (DATA?.meta?.hierarchical_mu?.owns_weather) return true;
  if (String(DATA?.meta?.projection_recipe || "").includes("hierarchical_mu") && row?.weather_counts_baked) {
    return true;
  }
  return Number.isFinite(num(row?.hierarchical_weather_stp, NaN));
}

/** Weather difficulty delta: full snapshot, or incremental vs export bake when counts are baked in. */
function weatherDifficultyDeltaForProjectionRow(row) {
  const cur = effectiveWeatherForProjectionRow(row);
  const snap = row?._weather_bake_snapshot;
  if (projectionCountsWeatherBaked(row) && snap && typeof snap === "object") {
    const dCur = weatherDifficultyDeltaFromSnapshot(cur);
    const dSnap = weatherDifficultyDeltaFromSnapshot(snap);
    if (Number.isFinite(dCur) && Number.isFinite(dSnap)) return dCur - dSnap;
    return 0;
  }
  return weatherDifficultyDeltaFromSnapshot(cur);
}

function weatherDifficultyDelta() {
  return weatherDifficultyDeltaFromSnapshot(WEATHER_STATE);
}

function weatherSigmaMultiplierFromSnapshot(w) {
  if (!w || typeof w !== "object") return 1;
  const windVar = 0.012 * Math.max(0, w.windMph - WIND_EFFECT_FLOOR_MPH);
  const humVar = 0.0015 * Math.max(0, w.humidityPct - 55);
  const priorMm = num(w.priorPrecipMm, 0);
  const softVar = priorMm >= 2 ? 0.03 : 0;
  if (w.condition === "default") {
    return clamp(1 + windVar + humVar + softVar, 0.9, 1.55);
  }
  const condVar = WEATHER_CONDITION_SIGMA_DELTA[w.condition] ?? 0;
  return clamp(1 + windVar + humVar + condVar + softVar, 0.9, 1.55);
}

function weatherSigmaMultiplier() {
  return weatherSigmaMultiplierFromSnapshot(WEATHER_STATE);
}

/** Tee-time forecast (bundled live field_updates + Open-Meteo hourly) when present; else global fallback. */
function effectiveWeatherForProjectionRow(row) {
  const auto = row?.dg_auto_weather;
  if (
    auto &&
    typeof auto === "object" &&
    Number.isFinite(auto.tempF) &&
    Number.isFinite(auto.windMph) &&
    Number.isFinite(auto.humidityPct)
  ) {
    return {
      tempF: auto.tempF,
      windMph: auto.windMph,
      humidityPct: auto.humidityPct,
      condition: String(auto.condition || "default").toLowerCase(),
      priorPrecipMm: num(auto.priorPrecipMm, NaN),
      priorRainSoft: Boolean(auto.priorRainSoft),
    };
  }
  return {
    ...WEATHER_STATE,
    priorPrecipMm: num(row?.weather_prior_precip_mm, NaN),
    priorRainSoft: Boolean(row?.weather_prior_rain_soft),
  };
}

/** Weather line for expanded projection “Model inputs” (every player gets a readable snapshot). */
function formatEffectiveWeatherLine(row) {
  return formatWeatherSnapshotCompact(effectiveWeatherForProjectionRow(row)) || "—";
}

function statWeatherMuAdjustment(market, row) {
  const d = weatherDifficultyDeltaForProjectionRow(row);
  if (!Number.isFinite(d)) return 0;
  if (market === "Total score") return d;
  if (market === "Bogeys") return 0.45 * d;
  if (market === "Birdies") return -0.5 * d;
  if (market === "Pars") return 0.2 * d;
  if (market === "Putts") return 0.35 * d;
  if (market === "GIR") return -0.5 * d;
  if (market === "Fairways hit") return -0.4 * d;
  return 0;
}

function pinSheetAppliesToProjectionRow(row) {
  const ps = DATA?.meta?.pin_sheet;
  if (!ps || typeof ps !== "object") return false;
  const rnd = Math.round(num(row?.round, NaN));
  const psRnd = Math.round(num(ps.round, NaN));
  if (!Number.isFinite(rnd) || !Number.isFinite(psRnd) || rnd !== psRnd) return false;
  return true;
}

/** Pin-sheet setup deltas for O/U μ when not already baked into export row values. */
function pinSheetMuAdjustment(market, row) {
  if (!pinSheetAppliesToProjectionRow(row)) return 0;
  if (row?._pin_adjusted) return 0;
  const ps = DATA.meta.pin_sheet;
  const mKey = ouModelMarketKey(market) || "Total score";
  if (mKey === "Total score") return num(ps.total_score_delta, 0);
  if (mKey === "Birdies") return num(ps.birdies_delta, 0);
  if (mKey === "Pars") return num(ps.pars_delta, 0);
  if (mKey === "Bogeys") return num(ps.bogeys_delta, 0);
  if (mKey === "GIR") return num(ps.gir_delta, 0);
  if (mKey === "Fairways hit") return num(ps.fairways_delta, 0);
  if (mKey === "Putts") return num(ps.putts_delta, num(ps.total_score_delta, 0) * 0.35);
  return 0;
}

/**
 * Maps DataGolf live-hole-stats round excess (strokes vs par for the field) into a stroke-unit shift `d`
 * for O/U / +EV.
 * Keep "course playing hard" responsive, but damp "course playing easy" so totals do not get unrealistically low.
 */
const LIVE_COURSE_EXCESS_TO_STROKE_K_HARD = 1.5;
const LIVE_COURSE_EXCESS_TO_STROKE_K_EASY = 0.8;
const LIVE_COURSE_D_CLAMP_NEG = -1.6;
const LIVE_COURSE_D_CLAMP_POS = 3.4;
/** Prior completed rounds at this event (fetch-datagolf / course-round-adjustments.mjs defaults). */
const PRIOR_ROUND_EXCESS_TO_STROKE_K_HARD = 1.5;
const PRIOR_ROUND_EXCESS_TO_STROKE_K_EASY = 0.8;
const PRIOR_ROUND_STROKE_SHIFT_CLAMP_NEG = -1.2;
const PRIOR_ROUND_STROKE_SHIFT_CLAMP_POS = 2.15;

/** True only after tournament play has actually started (at least one player has begun the live round). */
function hasStartedLiveRoundData() {
  if (!inPlayAffectsRoundOdds()) return false;
  const liveR = Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN));
  if (!Number.isFinite(liveR) || liveR < 1 || liveR > 4) return false;
  const rows = Array.isArray(DATA?.live_in_play_snapshot)
    ? DATA.live_in_play_snapshot
    : Array.isArray(DATA?.data)
      ? DATA.data
      : [];
  for (const r of rows) {
    const rr = Math.round(num(r?.round, NaN));
    if (rr !== liveR) continue;
    const thru = Math.round(num(r?.thru ?? r?.Thru, NaN));
    if (Number.isFinite(thru) && thru >= 1) return true;
  }
  return false;
}

function liveCourseDifficultyDForMu() {
  if (hasStartedLiveRoundData()) {
    const exR = num(DATA?.meta?.live_course_round_excess_strokes, NaN);
    if (Number.isFinite(exR)) {
      const k = exR < 0 ? LIVE_COURSE_EXCESS_TO_STROKE_K_EASY : LIVE_COURSE_EXCESS_TO_STROKE_K_HARD;
      return clamp(exR * k, LIVE_COURSE_D_CLAMP_NEG, LIVE_COURSE_D_CLAMP_POS);
    }
  }
  /* Avoid stacking course_table prior on top of fetch:dg venue + prior-round bake (was inflating all O/U markets). */
  if (courseProjectionDifficultyBakedInExport()) return 0;
  const d0 = courseTableStaticDifficultyD();
  if (!Number.isFinite(d0) || d0 === 0) return 0;
  return clamp(d0 * 0.42, -0.85, 1.45);
}

/** Stroke shift from prior-round field excess (+ = harder vs par). Mirrors course-round-adjustments.mjs. */
function courseDifficultyStrokeShiftFromExcess(excessStrokes) {
  const exR = num(excessStrokes, NaN);
  if (!Number.isFinite(exR) || exR === 0) return 0;
  const k = exR < 0 ? PRIOR_ROUND_EXCESS_TO_STROKE_K_EASY : PRIOR_ROUND_EXCESS_TO_STROKE_K_HARD;
  return clamp(exR * k, PRIOR_ROUND_STROKE_SHIFT_CLAMP_NEG, PRIOR_ROUND_STROKE_SHIFT_CLAMP_POS);
}

/** Refresh meta prior-round course difficulty from live hole stats (blend with fetch/historical when present). */
function refreshPriorRoundCourseMetaFromLiveHoleStats(lh) {
  if (!lh || typeof lh !== "object") return false;
  if (!DATA.meta) DATA.meta = {};
  const prevEx = DATA.meta.prior_round_course_excess_strokes;
  const prevSh = DATA.meta.prior_round_course_stroke_shift;
  const nextEx =
    prevEx && typeof prevEx === "object" ? { ...prevEx } : { 1: 0, 2: 0, 3: 0, 4: 0 };
  const nextSh =
    prevSh && typeof prevSh === "object" ? { ...prevSh } : { 1: 0, 2: 0, 3: 0, 4: 0 };
  let touched = false;
  for (let tr = 2; tr <= 4; tr++) {
    const liveEx = priorRoundsMeanExcessFromLiveHoleStats(lh, tr);
    if (!Number.isFinite(liveEx)) continue;
    const histEx = num(nextEx[String(tr)] ?? nextEx[tr], NaN);
    const ex = Number.isFinite(histEx) && histEx !== 0 ? 0.55 * liveEx + 0.45 * histEx : liveEx;
    const sh = courseDifficultyStrokeShiftFromExcess(ex);
    const exR = Math.round(ex * 1000) / 1000;
    const shR = Math.round(sh * 1000) / 1000;
    if (nextEx[tr] !== exR) touched = true;
    if (nextSh[tr] !== shR) touched = true;
    nextEx[tr] = exR;
    nextSh[tr] = shR;
  }
  if (touched) {
    DATA.meta.prior_round_course_excess_strokes = nextEx;
    DATA.meta.prior_round_course_stroke_shift = nextSh;
  }
  return touched;
}

function priorRoundCourseStrokeShiftBakedOnRow(row) {
  return Object.prototype.hasOwnProperty.call(row || {}, "prior_round_course_stroke_shift");
}

/** fetch:dg baked venue scoring + prior-round shifts into player rows (see projection_round_adjustments). */
function courseProjectionDifficultyBakedInExport() {
  const adj = DATA?.meta?.projection_round_adjustments;
  if (adj?.course_prior_round_difficulty === true) return true;
  if (adj?.skip_runtime_course_overlay === true) return true;
  return Array.isArray(DATA?.players) && DATA.players.some((p) => priorRoundCourseStrokeShiftBakedOnRow(p));
}

/** Prior-round stroke shift for this projection row (0 when fetch:dg already baked into μ / totals). */
function priorRoundCourseStrokeShiftForProjectionRow(row) {
  if (priorRoundCourseStrokeShiftBakedOnRow(row)) return 0;
  const rnd = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(rnd) || rnd < 2) return 0;
  const pack = DATA?.meta?.prior_round_course_stroke_shift;
  if (!pack || typeof pack !== "object") return 0;
  const v = num(pack[String(rnd)] ?? pack[rnd], NaN);
  return Number.isFinite(v) ? v : 0;
}

/** Map stroke-unit difficulty `d` into O/U counting-stat means (+d ⇒ harder ⇒ higher totals / bogeys). */
function ouMuAdjustmentFromCourseDifficultyD(market, d) {
  if (!Number.isFinite(d) || d === 0) return 0;
  const mKey = ouModelMarketKey(market) || "Total score";
  const scale = mKey === "Total score" ? 1 : liveCourseOuNonTotalScale();
  if (mKey === "Total score") return d;
  if (mKey === "Bogeys") return 0.48 * d * scale;
  if (mKey === "Birdies") return -0.55 * d * scale;
  if (mKey === "Pars") return -0.11 * d * scale;
  if (mKey === "Putts") return 0.42 * d * scale;
  if (mKey === "GIR") return -0.28 * d * scale;
  if (mKey === "Fairways hit") return -0.2 * d * scale;
  return 0;
}

function priorRoundCourseOUMuAdjustment(market, row) {
  return ouMuAdjustmentFromCourseDifficultyD(market, priorRoundCourseStrokeShiftForProjectionRow(row));
}

/** In-round live hole-stats difficulty for the active live round only. */
function liveCourseOUMuAdjustmentForRound(market, targetRound) {
  const tr = Math.round(num(targetRound, NaN));
  const liveR = Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN));
  if (!Number.isFinite(tr) || !Number.isFinite(liveR) || tr !== liveR) return 0;
  return ouMuAdjustmentFromCourseDifficultyD(market, liveCourseDifficultyDForMu());
}

/**
 * Prior rounds at this venue + in-round live difficulty for `row.round`.
 * Used by Round projections, +EV props, Historical Trends model line, Live Prop, etc.
 */
function combinedCourseDifficultyOUMuAdjustment(market, row) {
  if (!row || typeof row !== "object") return 0;
  const tr = Math.round(num(row.round, NaN));
  if (courseProjectionDifficultyBakedInExport() && !hasStartedLiveRoundData()) return 0;
  return (
    priorRoundCourseOUMuAdjustment(market, row) +
    (Number.isFinite(tr) ? liveCourseOUMuAdjustmentForRound(market, tr) : 0)
  );
}

/** @deprecated Use combinedCourseDifficultyOUMuAdjustment with a projection row when possible. */
function liveCourseOUMuAdjustment(market) {
  return ouMuAdjustmentFromCourseDifficultyD(market, liveCourseDifficultyDForMu());
}

function liveCoursePropHistoryNudge(statKey, projectionRowOpt) {
  const market = ouMarketKeyFromStatKey(statKey);
  if (projectionRowOpt && typeof projectionRowOpt === "object") {
    return combinedCourseDifficultyOUMuAdjustment(market, projectionRowOpt);
  }
  return liveCourseOUMuAdjustment(market);
}

/** μ_SG delta from prior-round course hardness when projections were not rebuilt by fetch:dg. */
function priorRoundCourseMuSgDelta(row) {
  if (!row || priorRoundCourseStrokeShiftBakedOnRow(row)) return 0;
  const shift = priorRoundCourseStrokeShiftForProjectionRow(row);
  const form = num(row?.within_event_form_shift, NaN);
  const formAdj = Number.isFinite(form) ? form : 0;
  return -shift + formAdj;
}

/** Sum par for holes 1..n (n = holes completed, e.g. thru=14 → first 14 holes). */
function courseParSumFirstNHoles(holePars, nHolesCompleted) {
  const n = Math.min(18, Math.max(0, Math.floor(num(nHolesCompleted, NaN))));
  if (!n) return 0;
  if (!Array.isArray(holePars) || holePars.length < n) return NaN;
  let s = 0;
  for (let i = 0; i < n; i++) {
    const p = num(holePars[i], NaN);
    if (!Number.isFinite(p)) return NaN;
    s += p;
  }
  return s;
}

/**
 * Mid-round: blend pre-round `total_score` with realized strokes + prorated remainder.
 * Uses preds/in-play `today` (vs par through `thru`) on the row whose `round` matches live DG round.
 */
function liveCurrentRoundTotalScoreMuDelta(row) {
  if (!inPlayAffectsRoundOdds()) return 0;
  const liveR = Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN));
  const pr = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(liveR) || liveR < 1 || liveR > 4 || pr !== liveR) return 0;
  const thru = Math.round(num(row.dg_live_thru, NaN));
  const today = num(row.dg_live_today, NaN);
  const baseMu = num(row.total_score, NaN);
  const par18 = num(DATA?.meta?.course_par_18, NaN);
  const holePars = DATA.meta?.hole_pars;
  if (!Number.isFinite(baseMu) || !Number.isFinite(par18)) return 0;
  if (!Number.isFinite(today)) return 0;

  if (Number.isFinite(thru) && thru >= 18) {
    return 0;
  }
  if (!Number.isFinite(thru) || thru < 1) return 0;

  let parThru = courseParSumFirstNHoles(holePars, thru);
  if (!Number.isFinite(parThru)) parThru = (par18 / 18) * thru;
  const parRem = par18 - parThru;
  const rem = 18 - thru;
  if (rem <= 0) return 0;
  const expExcessRem = ((baseMu - par18) * rem) / 18;
  const actualStrokes = parThru + today;
  const muLive = actualStrokes + parRem + expExcessRem;
  return clamp(muLive - baseMu, -12, 12);
}

function liveRowMatchesDgLiveRound(row) {
  const liveR = Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN));
  const pr = Math.round(num(row?.round, NaN));
  return Number.isFinite(liveR) && liveR >= 1 && liveR <= 4 && pr === liveR;
}

/** When DG omits hole counts, infer minimum plausible birdies / bogeys from strokes vs par through `thru`. */
function inferBirdiesSoFarFromTodayVsPar(today, thru) {
  if (!Number.isFinite(today) || !Number.isFinite(thru) || thru < 1) return NaN;
  if (today >= 0) return 0;
  const under = -today;
  return Math.min(thru, Math.max(0, Math.round(under * 0.52)));
}

function inferBogeysSoFarFromTodayVsPar(today, thru) {
  if (!Number.isFinite(today) || !Number.isFinite(thru) || thru < 1) return NaN;
  if (today <= 0) return 0;
  return Math.min(thru, Math.max(0, Math.round(today * 0.52)));
}

/**
 * Birdies / pars / bogeys O/U: expected full-round mean becomes (count so far) + (proj rate × holes left).
 * Uses merged dg_live_*_so_far when present; else infers birdies/bogeys from `today` vs par and pars as residual holes.
 * Tightens sigma by √(holes_left / 18) (and near lock when round complete).
 */
function livePartialRoundCountPropAdjust(market, row) {
  const out = { muDelta: 0, sigmaScale: 1 };
  if (!inPlayAffectsRoundOdds()) return out;
  if (market !== "Birdies" && market !== "Pars" && market !== "Bogeys") return out;
  if (!liveRowMatchesDgLiveRound(row)) return out;
  const thru = Math.round(num(row.dg_live_thru, NaN));
  const today = num(row.dg_live_today, NaN);
  if (!Number.isFinite(thru) || thru < 1) return out;
  if (thru >= 18) return out;
  const rem = 18 - thru;
  if (rem < 0) return out;

  const field = market === "Birdies" ? "birdies" : market === "Pars" ? "pars" : "bogeys";
  let muFull = num(row[field], NaN);
  if (market === "Birdies") muFull = birdiesPlusEaglesFromRow(row);
  else if (market === "Bogeys") muFull = bogeysPlusDoublesFromRow(row);
  if (!Number.isFinite(muFull) || muFull < 0) return out;

  let b = num(row.dg_live_birdies_so_far, NaN);
  let bg = num(row.dg_live_bogeys_so_far, NaN);
  if (!Number.isFinite(b)) b = inferBirdiesSoFarFromTodayVsPar(today, thru);
  if (!Number.isFinite(bg)) bg = inferBogeysSoFarFromTodayVsPar(today, thru);
  if (!Number.isFinite(b)) b = 0;
  if (!Number.isFinite(bg)) bg = 0;

  const eg = num(row.dg_live_eagles_so_far, NaN);
  const eagles = Number.isFinite(eg) && eg >= 0 ? Math.min(thru, Math.round(eg)) : 0;
  const dblRaw = num(row.dg_live_doubles_so_far, NaN);
  const doubles = Number.isFinite(dblRaw) && dblRaw >= 0 ? Math.min(thru, Math.round(dblRaw)) : 0;

  let pSo = num(row.dg_live_pars_so_far, NaN);
  if (!Number.isFinite(pSo)) {
    pSo = Math.max(0, thru - b - bg - eagles - doubles);
    pSo = Math.min(thru, pSo);
  }

  const rate = muFull / 18;
  let soFar;
  if (market === "Birdies") soFar = b + eagles;
  else if (market === "Bogeys") soFar = bg + doubles;
  else soFar = pSo;

  let muLive = soFar + rate * rem;
  muLive = clamp(muLive, 0, 18);

  out.muDelta = muLive - muFull;
  if (thru >= 18) out.sigmaScale = 0.26;
  else out.sigmaScale = clamp(Math.sqrt(rem / 18), 0.17, 1);
  return out;
}

/**
 * Matchups / 3-ball +EV use `mu_sg`; map in-round total-score revision to the same stroke↔SG scale
 * as bundled demo rows (mu_sg ≈ (par − total_score) × 0.2 ⇒ Δsg ≈ −0.2 × Δstrokes).
 */
function liveCurrentRoundMuSgDelta(row) {
  const d = liveCurrentRoundTotalScoreMuDelta(row);
  if (!Number.isFinite(d) || d === 0) return 0;
  return clamp(-0.2 * d, -1.45, 1.45);
}

/** Tighten Total score O/U sigma as the live round progresses (less variance left to play). */
function sigmaLiveRoundShrinkForTotalScore(row, rec) {
  if (!inPlayAffectsRoundOdds()) return 1;
  if (!rec || rec.field !== "total_score") return 1;
  const liveR = Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN));
  const pr = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(liveR) || pr !== liveR) return 1;
  const thru = Math.round(num(row.dg_live_thru, NaN));
  if (!Number.isFinite(thru) || thru < 1) return 1;
  if (thru >= 18) return 0.32;
  return clamp(Math.sqrt((18 - thru) / 18), 0.2, 1);
}

function playerSkillWeatherEdge(row) {
  if (projectionCountsWeatherBaked(row)) return 0;
  const baseSg = modeledMuSgFromRow(row);
  const roundSd = num(row?.round_sd, NaN);
  const sgEdge = Number.isFinite(baseSg) ? baseSg * 0.12 : 0;
  const consistencyEdge = Number.isFinite(roundSd) ? clamp((2.8 - roundSd) * 0.03, -0.06, 0.06) : 0;
  return weatherDifficultyDeltaFromSnapshot(effectiveWeatherForProjectionRow(row)) * (sgEdge + consistencyEdge);
}

function weatherAdjustedMuSg(row) {
  const base = modeledMuSgFromRow(row);
  if (!Number.isFinite(base)) return NaN;
  if (projectionCountsWeatherBaked(row)) return base;
  return base + playerSkillWeatherEdge(row);
}

function ouStatRec(market) {
  const key = ouModelMarketKey(market);
  if (key && OU_STAT_MAP[key]) return OU_STAT_MAP[key];
  return OU_STAT_MAP["Total score"];
}

/** Maps Historical Trends statKey / prop-stat value → `OU_STAT_MAP` / `getOuMarket()` label. */
function ouMarketKeyFromStatKey(statKey) {
  if (statKey === "total") return "Total score";
  if (statKey === "birdies") return "Birdies";
  if (statKey === "pars") return "Pars";
  if (statKey === "bogeys") return "Bogeys";
  if (statKey === "gir") return "GIR";
  if (statKey === "fairways") return "Fairways hit";
  if (statKey === "putts") return "Putts";
  if (statKey === "sg_total") return "SG: Total";
  if (statKey === "sg_ott") return "SG: Off the tee";
  if (statKey === "sg_app") return "SG: Approach";
  if (statKey === "sg_arg") return "SG: Around the green";
  if (statKey === "sg_putt") return "SG: Putting";
  if (statKey === "sg_t2g") return "SG: Tee to green";
  if (statKey === "sg_50_100_fw") return "SG: App 50–100 (FW)";
  if (statKey === "sg_100_150_fw") return "SG: App 100–150 (FW)";
  if (statKey === "sg_150_200_fw") return "SG: App 150–200 (FW)";
  if (statKey === "sg_over_200_fw") return "SG: App 200+ (FW)";
  if (statKey === "sg_under_150_rgh") return "SG: App <150 (RGH)";
  if (statKey === "sg_over_150_rgh") return "SG: App 150+ (RGH)";
  if (statKey === "sg_app_dist_total") return "SG: App distance total";
  if (statKey === "sg_putt_0_5ft") return "SG: Putt 0–5 ft";
  if (statKey === "sg_putt_5_10ft") return "SG: Putt 5–10 ft";
  if (statKey === "sg_putt_10_15ft") return "SG: Putt 10–15 ft";
  if (statKey === "sg_putt_15_25ft") return "SG: Putt 15–25 ft";
  if (statKey === "sg_putt_25plus_ft") return "SG: Putt 25+ ft";
  if (statKey === "sg_putt_dist_total") return "SG: Putt distance total";
  if (statKey === "gir_pct") return "GIR %";
  if (statKey === "fairways_pct") return "Fairways %";
  return "Total score";
}

/** Per-round SD for counting O/U: GIR/FW use binomial-ish spread; others use sqrt-mean with floors. */
function sigmaOuDiscreteCounting(market, muAbs) {
  const m = num(muAbs, NaN);
  if (!Number.isFinite(m) || m <= 0) return 2.4;
  if (market === "GIR") {
    const n = 18;
    const p = clamp(m / n, 0.07, 0.93);
    return Math.max(1.05, Math.sqrt(n * p * (1 - p)));
  }
  if (market === "Fairways hit") {
    const n = fairwayHolesModeledFromData();
    if (!Number.isFinite(n) || n <= 0) return 2.4;
    const p0 = m / n;
    const p = Number.isFinite(p0) ? Math.min(1 - 1e-12, Math.max(1e-12, p0)) : 0.5;
    return Math.sqrt(n * p * (1 - p));
  }
  if (market === "Putts") {
    return clamp(Math.sqrt(m * 1.15), 2.35, 5.85);
  }
  if (market === "Birdies" || market === "Bogeys") {
    return clamp(Math.sqrt(m * 1.22), 1.35, 2.85);
  }
  if (market === "Pars") {
    return clamp(Math.sqrt(m * 1.12), 1.55, 3.15);
  }
  return Math.max(0.55, Math.sqrt(Math.max(m, 0.2)) * 0.9);
}

const WITHIN_EVENT_PRIOR_FIELD_SHARE_RT = 0.85;
const WITHIN_EVENT_COUNT_BLEND_BASE_RT = 0.28;
const WITHIN_EVENT_COUNT_BLEND_PER_ROUND_RT = 0.08;
const WITHIN_EVENT_COUNT_BLEND_CAP_RT = 0.52;
const WITHIN_EVENT_BOGEY_BLEND_SCALE_RT = 1;
const WITHIN_EVENT_SKILL_ANCHOR_BASE_RT = 0.14;
const WITHIN_EVENT_SKILL_ANCHOR_MU_SCALE_RT = 0.05;

function withinEventSkillTrustFactorRuntime(row) {
  const mu = num(row?.mu_sg, 0);
  return clamp(0.32 + 0.14 * Math.max(0, mu), 0.32, 0.78);
}

function adjustWithinEventBlendWeightRuntime(w, priorAvg, skillBase, row, statKey) {
  if (!Number.isFinite(priorAvg) || !Number.isFinite(skillBase)) return w;
  const dev = priorAvg - skillBase;
  const trust = withinEventSkillTrustFactorRuntime(row);
  const mu = num(row?.mu_sg, 0);
  if (mu >= 0.35 && dev < -0.75) {
    w *= clamp(1 - trust * Math.min(1, (-dev - 0.5) / 2.5), 0.18, 1);
  }
  if (mu < 0.25 && dev > 0.75) {
    w *= clamp(1 - (1 - trust) * Math.min(1, (dev - 0.5) / 2.5), 0.18, 1);
  }
  if (statKey === "bogeys" && mu >= 0.5 && dev < -0.5) {
    w *= clamp(1 - trust * 0.45, 0.35, 1);
  }
  return w;
}

function liveCountingUntrustworthyRuntime(counts, coursePar18) {
  const cp = num(coursePar18, NaN);
  const rs = num(counts.round_score ?? counts.score, NaN);
  if (!Number.isFinite(cp) || !Number.isFinite(rs)) return false;
  const stp = rs - cp;
  const bird = num(counts.birdies, NaN);
  const par = num(counts.pars, NaN);
  const bog = num(counts.bogeys ?? counts.bogies, NaN);
  const e = num(counts.eagles ?? counts.eagles_or_better, 0);
  const d = num(counts.doubles ?? counts.doubles_or_worse, 0);
  if (Number.isFinite(par) && par >= 17.5 && Math.abs(stp) > 0.5) return true;
  if (Number.isFinite(bird) && bird <= 0.01 && stp < -0.5) return true;
  const hat = -(bird || 0) - 2 * e + (bog || 0) + 2 * d;
  return Math.abs(hat - stp) > 1.25;
}

function inferHoleCountsFromScoreSplitRuntime(stp, venueBirdies, venueBogeys) {
  const vBird = num(venueBirdies, 2.88);
  const vBog = num(venueBogeys, 2.93);
  let bird = 0;
  let bog = 0;
  if (stp <= 0) {
    bird = Math.max(0, Math.min(7, vBird + -stp * 0.85));
    bog = Math.max(0, stp + bird);
  } else {
    bird = Math.max(0.15, Math.min(7, vBird - stp * 0.42));
    bog = Math.max(0.15, Math.min(8, stp + bird));
  }
  bird = Math.round(bird * 100) / 100;
  bog = Math.round(bog * 100) / 100;
  return {
    birdies: bird,
    bogeys: bog,
    pars: Math.max(0.12, Math.round((18 - bird - bog) * 100) / 100),
  };
}

function softAlignHoleCountsToStpRuntime(counts, targetStp, strength = 0.58) {
  const e = Math.max(0, num(counts.eagles, 0));
  const d = Math.max(0, num(counts.doubles, 0));
  let b = num(counts.birdies, 0);
  let p = num(counts.pars, 0);
  let bg = num(counts.bogeys, 0);
  const t = num(targetStp, 0);
  const st = Math.max(0.08, Math.min(1, strength));
  const hat = -b - 2 * e + bg + 2 * d;
  const diff = t - hat;
  const delta = (st * diff) / 2;
  b = Math.max(0.15, b - delta);
  bg = Math.max(0.15, bg + delta);
  p = 18 - e - d - b - bg;
  if (p < 0.12) {
    const need = 0.12 - p;
    const take = Math.min(need / 2, b - 0.15, bg - 0.15);
    b -= take;
    bg -= take;
    p = 18 - e - d - b - bg;
  }
  return { eagles: e, birdies: b, pars: Math.max(0.12, p), bogeys: bg, doubles: d };
}

function projectionCountsCoherentFromExport() {
  const adj = DATA?.meta?.projection_round_adjustments;
  return Boolean(adj?.projection_counts_coherent || adj?.within_event_counting_from_actuals);
}

function spreadParsIntoBirdBogPairsRuntime(counts, opts = {}) {
  const e = Math.max(0, num(counts?.eagles, 0));
  const d = Math.max(0, num(counts?.doubles, 0));
  let b = num(counts?.birdies, 0);
  let bg = num(counts?.bogeys, 0);
  let p = num(counts?.pars, NaN);
  if (!Number.isFinite(p)) p = 18 - e - d - b - bg;

  const venueBird = num(opts?.venueBirdies, 3.2);
  const venueBog = num(opts?.venueBogeys, 2.9);
  const venuePar = num(opts?.venuePars, 11.5);
  const strength = num(opts?.spreadStrength, 0.75);
  const parFloor = num(opts?.parFloor, Math.max(9.2, venuePar * 0.72));

  const parsExcess = Math.max(0, p - parFloor);
  const pairRoom = parsExcess / 2;
  let shift = Math.min(strength * pairRoom, pairRoom);
  if (shift <= 1e-6) {
    return { eagles: e, birdies: b, pars: Math.max(parFloor, p), bogeys: bg, doubles: d };
  }
  b += shift;
  bg += shift;
  p -= 2 * shift;
  const parSlack = Math.max(0, p - parFloor);
  const birdShort = Math.max(0, venueBird - b);
  const bogShort = Math.max(0, venueBog - bg);
  const extra = Math.min(parSlack / 2, birdShort, bogShort, 0.9);
  if (extra > 1e-6) {
    b += extra;
    bg += extra;
    p -= 2 * extra;
  }
  return {
    eagles: e,
    birdies: Math.max(0.15, b),
    pars: Math.max(parFloor, p),
    bogeys: Math.max(0.15, bg),
    doubles: d,
  };
}

function fairwaysFromScoreAnchorRuntime(stp, muSg, venueFw, nFw) {
  const ln = DATA?.meta?.historical_projection_calibration?.fw_stp_line;
  if (ln && Number.isFinite(ln.a) && Number.isFinite(ln.b)) {
    const x = Number.isFinite(muSg) ? Math.max(-10, Math.min(10, -muSg)) : -num(stp, 0);
    return clamp(ln.a + ln.b * x, 4, nFw + 0.2);
  }
  return clamp(venueFw - num(stp, 0) * 0.28, 4, nFw + 0.2);
}

/** Bird/bog/pars from weather-adjusted score + venue history; GIR/FW from score anchor. */
function coherentCountingMeansAtTotal(row, projectedTotal) {
  const par18 = coursePar18FromData();
  const stp = projectedTotal - par18;
  const basis = DATA?.meta?.projection_course_basis || {};
  const vBird = num(basis.venue_avg_birdies, 4.2);
  const vBog = num(basis.venue_avg_bogeys, 2.1);
  const vGir = num(basis.venue_avg_gir, 12);
  const vFw = num(basis.venue_avg_fairways, 9);
  const nFw = fairwayHolesModeledFromData();
  const split = inferHoleCountsFromScoreSplitRuntime(stp, vBird, vBog);
  const girFromScore = clamp(vGir - stp * 0.55, 7.5, 16.2);
  const fwFromScore = fairwaysFromScoreAnchorRuntime(stp, num(row.mu_sg, NaN), vFw, nFw);
  const girRaw = num(row.gir, NaN);
  const fwRaw = num(row.fairways, NaN);
  const gir = Number.isFinite(girRaw) ? 0.78 * girRaw + 0.22 * girFromScore : girFromScore;
  const fw = Number.isFinite(fwRaw) ? 0.8 * fwRaw + 0.2 * fwFromScore : fwFromScore;
  return {
    Birdies: split.birdies,
    Bogeys: split.bogeys,
    Pars: split.pars,
    GIR: gir,
    "Fairways hit": fw,
  };
}

function ouProjectedTotalScoreMean(row, opts = {}) {
  const dgId = Math.round(num(row?.dg_id, NaN));
  const liveRoundAdj = ouInPlayMuDeltaForTotalScore(row, opts);
  const baseMean = ouMeanCountingStat("Total score", row);
  const baseScalar = Number.isFinite(baseMean) ? baseMean : ouFallbackScalarForProjectedMean("Total score", row, ouStatRec("Total score"));
  // Hierarchical μ already has weather + skill×course + form baked in — show export μ (+ live thru only).
  if (hierarchicalMuOwnsRow(row)) {
    return (
      baseScalar +
      pinSheetMuAdjustment("Total score", row) +
      liveRoundAdj +
      ouInPlayCountingAdjust("Total score", row, opts).muDelta +
      pricingStatMuAdjustment("Total score", dgId)
    );
  }
  return (
    baseScalar +
    statWeatherMuAdjustment("Total score", row) +
    pinSheetMuAdjustment("Total score", row) +
    combinedCourseDifficultyOUMuAdjustment("Total score", row) +
    eventWeekFieldScoringMuAdjustment(row) +
    liveRoundAdj +
    ouInPlayCountingAdjust("Total score", row, opts).muDelta +
    pricingStatMuAdjustment("Total score", dgId)
  );
}

/** Infer bogeys/pars from score when live feed reports bogus hole counts. */
function reconcileHoleCountsFromScoreRuntime(counts, coursePar18) {
  if (!counts || typeof counts !== "object") return counts;
  const cp = num(coursePar18, NaN);
  const rs = num(counts.round_score ?? counts.score, NaN);
  if (!Number.isFinite(cp) || !Number.isFinite(rs)) return counts;
  const stp = rs - cp;
  const vBird = num(DATA?.meta?.projection_course_basis?.venue_avg_birdies, 2.88);
  const vBog = num(DATA?.meta?.projection_course_basis?.venue_avg_bogeys, 2.93);
  if (liveCountingUntrustworthyRuntime(counts, cp)) {
    return { ...counts, ...inferHoleCountsFromScoreSplitRuntime(stp, vBird, vBog), round_score: rs };
  }
  const e = Math.max(0, num(counts.eagles ?? counts.eagles_or_better, 0));
  const d = Math.max(0, num(counts.doubles ?? counts.doubles_or_worse, 0));
  const bird = num(counts.birdies, NaN);
  if (!Number.isFinite(bird)) return counts;
  let bog = num(counts.bogeys ?? counts.bogies, NaN);
  const impliedBog = stp + bird + 2 * e - 2 * d;
  const hatStp = -bird - 2 * e + (Number.isFinite(bog) ? bog : 0) + 2 * d;
  const err = Math.abs(hatStp - stp);
  if (!Number.isFinite(bog) || (bog <= 0.01 && impliedBog >= 0.45) || err > 0.85) {
    bog = Math.max(0, Math.round(impliedBog * 100) / 100);
  }
  const pars = Math.max(0, Math.round((18 - bird - bog - e - d) * 100) / 100);
  return { ...counts, birdies: bird, bogeys: bog, pars, eagles: e, doubles: d };
}

/** Player historical σ for counting props (last 12 rounds with data). */
function ouPlayerHistoricalCountingSigma(market, dgId) {
  if (!HISTORY._ok) return NaN;
  const statKey =
    market === "Birdies" ? "birdies" : market === "Bogeys" ? "bogeys" : market === "Pars" ? "pars" : null;
  if (!statKey) return NaN;
  const rec = HISTORY.byDgId?.[String(Math.round(num(dgId, NaN)))];
  if (!rec || !Array.isArray(rec.rounds)) return NaN;
  const vals = rec.rounds
    .slice()
    .sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a))
    .slice(0, 12)
    .map((r) => actualForRoundRow(statKey, r))
    .filter((v) => Number.isFinite(v));
  if (vals.length < 4) return NaN;
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  const vari = vals.reduce((s, v) => s + (v - mean) ** 2, 0) / (vals.length - 1);
  return Math.sqrt(vari);
}
const FIELD_DAY_COUNTING_LIFT_FRAC_RT = 0.38;

function plainMeanFromArrRuntime(arr) {
  if (!Array.isArray(arr) || !arr.length) return NaN;
  const vals = arr.map((v) => num(v, NaN)).filter(Number.isFinite);
  if (!vals.length) return NaN;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

function fieldCountingMeansFromMeta() {
  return DATA?.meta?.projection_course_basis?.field_counting_means_by_round || null;
}

function priorRoundCountingTargetRuntime(statKey, priorArr, targetRound) {
  const playerMean = plainMeanFromArrRuntime(priorArr);
  const fieldMeans = fieldCountingMeansFromMeta();
  const tr = Math.round(num(targetRound, NaN));
  if (!fieldMeans || !Number.isFinite(tr) || tr < 2) return playerMean;
  const rn = tr - 1;
  const bucket = fieldMeans[statKey];
  const fieldAvg = num(bucket?.[rn] ?? bucket?.[String(rn)], NaN);
  if (!Number.isFinite(fieldAvg)) return playerMean;
  if (!Number.isFinite(playerMean)) return fieldAvg;
  return WITHIN_EVENT_PRIOR_FIELD_SHARE_RT * fieldAvg + (1 - WITHIN_EVENT_PRIOR_FIELD_SHARE_RT) * playerMean;
}

function withinEventCountingStarTrustBoostRuntime(row) {
  if (!row || typeof row !== "object") return 0;
  const win = num(row.win, NaN);
  const t10 = num(row.top_10, NaN);
  const t20 = num(row.top_20, NaN);
  const mu = num(row.mu_sg, NaN);
  let boost = 0;
  if (Number.isFinite(win) && win >= 0.045) boost = Math.max(boost, 0.05);
  else if (Number.isFinite(win) && win >= 0.018) boost = Math.max(boost, 0.04);
  else if (Number.isFinite(t10) && t10 >= 0.18) boost = Math.max(boost, 0.03);
  else if (Number.isFinite(t20) && t20 >= 0.32) boost = Math.max(boost, 0.02);
  if (Number.isFinite(mu) && mu >= 0.85) boost = Math.max(boost, 0.04);
  else if (Number.isFinite(mu) && mu >= 0.4) boost = Math.max(boost, 0.02);
  return Math.min(0.06, boost);
}

function withinEventCountingBlendWeightRuntime(nPriorRounds, row) {
  const n = Math.max(0, Math.round(num(nPriorRounds, NaN)));
  if (!n) return 0;
  let w = Math.min(
    WITHIN_EVENT_COUNT_BLEND_CAP_RT,
    WITHIN_EVENT_COUNT_BLEND_BASE_RT + WITHIN_EVENT_COUNT_BLEND_PER_ROUND_RT * n,
  );
  w += withinEventCountingStarTrustBoostRuntime(row);
  return Math.min(0.92, w);
}

/** Prior-round bird/bog/GIR actuals this week from loaded round history. */
function tournamentWeekPriorByStatFromHistory(dgId, targetRound) {
  if (!HISTORY._ok) return null;
  const tr = Math.round(num(targetRound, NaN));
  if (!Number.isFinite(tr) || tr < 2) return null;
  const metaEv = String(DATA?.meta?.event_name || "").trim();
  if (!metaEv) return null;
  const rec = HISTORY.byDgId?.[String(Math.round(num(dgId, NaN)))];
  if (!rec || !Array.isArray(rec.rounds)) return null;
  /** @type {Record<string, number[]>} */
  const out = { birdies: [], bogeys: [], gir: [] };
  const rounds = rec.rounds
    .filter((r) => {
      if (!r || typeof r !== "object") return false;
      if (!eventNameMatchesCurrentSchedule(String(r.event_name || "").trim(), metaEv)) return false;
      const yr = Math.round(num(r.year, NaN));
      const cy = currentEventSeasonYearFromMeta();
      if (Number.isFinite(yr) && Number.isFinite(cy) && yr !== cy) return false;
      const rnd = Math.round(num(r.round_num ?? r.round, NaN));
      return Number.isFinite(rnd) && rnd >= 1 && rnd < tr;
    })
    .sort((a, b) => {
      const ra = Math.round(num(a.round_num ?? a.round, 0));
      const rb = Math.round(num(b.round_num ?? b.round, 0));
      if (ra !== rb) return ra - rb;
      const pa = a._from_live_tournament_stats ? 1 : 0;
      const pb = b._from_live_tournament_stats ? 1 : 0;
      if (pa !== pb) return pb - pa;
      return Math.round(num(b.sortKey, 0)) - Math.round(num(a.sortKey, 0));
    });
  const seenRnd = new Set();
  for (const r of rounds) {
    const rnd = Math.round(num(r.round_num ?? r.round, NaN));
    if (seenRnd.has(rnd)) continue;
    seenRnd.add(rnd);
    const cp = num(r.course_par, NaN) || num(DATA?.meta?.course_par_18, NaN);
    const rec = reconcileHoleCountsFromScoreRuntime(
      {
        birdies: r.birdies,
        bogeys: r.bogeys ?? r.bogies,
        gir: r.gir,
        round_score: r.round_score ?? r.score,
        eagles_or_better: r.eagles_or_better,
        doubles_or_worse: r.doubles_or_worse,
      },
      cp,
    );
    if (Number.isFinite(rec.birdies)) out.birdies.push(rec.birdies);
    if (Number.isFinite(rec.bogeys)) out.bogeys.push(rec.bogeys);
    if (Number.isFinite(rec.gir)) out.gir.push(num(r.gir, NaN));
  }
  return Object.values(out).some((a) => a.length) ? out : null;
}

/** μ delta when export predates this-week counting actuals (history is fresher than fetch bake). */
function tournamentWeekCountingMuAdjustment(mKey, row) {
  if (DATA?.meta?.projection_round_adjustments?.within_event_counting_from_actuals) return 0;
  const tr = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(tr) || tr < 2) return 0;
  const dgId = Math.round(num(row?.dg_id, NaN));
  const priorByStat = tournamentWeekPriorByStatFromHistory(dgId, tr);
  if (!priorByStat) return 0;
  let nRounds = 0;
  for (const k of ["birdies", "bogeys"]) {
    if (priorByStat[k]?.length > nRounds) nRounds = priorByStat[k].length;
  }
  if (!nRounds) return 0;
  const wBird = withinEventCountingBlendWeightRuntime(nRounds, row);
  const wBog = wBird * WITHIN_EVENT_BOGEY_BLEND_SCALE_RT;
  const statMap = {
    Birdies: { key: "birdies", w: wBird },
    Bogeys: { key: "bogeys", w: wBog },
    GIR: { key: "gir", w: Math.min(0.55, wBird * 0.65) },
  };
  const spec = statMap[mKey];
  if (!spec) {
    if (mKey === "Pars") {
      const bAdj = tournamentWeekCountingMuAdjustment("Birdies", row);
      const bgAdj = tournamentWeekCountingMuAdjustment("Bogeys", row);
      return Number.isFinite(bAdj) || Number.isFinite(bgAdj) ? -(bAdj + bgAdj) : 0;
    }
    return 0;
  }
  const arr = priorByStat[spec.key];
  if (!Array.isArray(arr) || !arr.length) return 0;
  const avg = priorRoundCountingTargetRuntime(spec.key, arr, tr);
  const base = ouMeanCountingStat(mKey, row);
  if (!Number.isFinite(avg) || !Number.isFinite(base)) return 0;
  let w = spec.w;
  w = adjustWithinEventBlendWeightRuntime(w, avg, base, row, spec.key);
  return w * (avg - base);
}

let COUNTING_COURSE_FIT_Z = { round: NaN, rev: -1, byDg: new Map() };

function rebuildCountingCourseFitZForRound(targetRound) {
  const tr = Math.round(num(targetRound, NaN));
  if (
    COUNTING_COURSE_FIT_Z.round === tr &&
    COUNTING_COURSE_FIT_Z.rev === projectionsDataRev &&
    COUNTING_COURSE_FIT_Z.byDg.size
  ) {
    return COUNTING_COURSE_FIT_Z;
  }
  const byDg = new Map();
  const pool = (DATA.players || []).filter((p) => Math.round(num(p.round, NaN)) === tr);
  const vk = propsEffectiveCourseKey() || venueCourseName().replace(/\s+/g, " ").trim();
  const ctRow = resolveCourseTableRowForNormKey(String(vk || "").toLowerCase());
  if (pool.length >= 8 && ctRow) {
    const fits = pool.map((r) => ({ dg: Math.round(num(r.dg_id, NaN)), fit: courseFitPlayerCourseFitRaw(r, ctRow) }));
    const vals = fits.map((x) => x.fit).filter(Number.isFinite);
    if (vals.length >= 8) {
      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const sd = Math.sqrt(vals.reduce((s, v) => s + (v - mean) ** 2, 0) / (vals.length - 1)) || 0.9;
      for (const { dg, fit } of fits) {
        if (Number.isFinite(dg) && Number.isFinite(fit)) byDg.set(dg, (fit - mean) / sd);
      }
    }
  }
  COUNTING_COURSE_FIT_Z = { round: tr, rev: projectionsDataRev, byDg };
  return COUNTING_COURSE_FIT_Z;
}

/** Market rating + course-fit nudge on counting μ (skill tier should dominate one-round noise). */
function countingSkillRatingMuAdjustment(mKey, row) {
  let adj = 0;
  const { marketRatingZ } = ouCachedTourMarketRating(mKey, row);
  if (Number.isFinite(marketRatingZ)) {
    const k =
      mKey === "Birdies"
        ? 0.38
        : mKey === "Bogeys"
          ? -0.32
          : mKey === "Pars"
            ? -0.1
            : mKey === "GIR"
              ? 0.42
              : mKey === "Fairways hit"
                ? 0.28
                : 0;
    adj += k * clamp(marketRatingZ, -2.2, 2.2);
  }
  const tr = Math.round(num(row?.round, NaN));
  const dg = Math.round(num(row?.dg_id, NaN));
  if (Number.isFinite(tr) && Number.isFinite(dg)) {
    const fitZ = rebuildCountingCourseFitZForRound(tr).byDg.get(dg);
    if (Number.isFinite(fitZ)) {
      const k2 =
        mKey === "Birdies"
          ? 0.34
          : mKey === "Bogeys"
            ? -0.28
            : mKey === "Pars"
              ? -0.08
              : mKey === "GIR"
                ? 0.36
                : mKey === "Fairways hit"
                  ? 0.24
                  : 0;
      adj += k2 * clamp(fitZ, -2.2, 2.2);
    }
  }
  return adj;
}

/** Field-wide bird/bog lift from this week's completed round vs venue history. */
function fieldDayCountingMuAdjustment(mKey, row) {
  if (DATA?.meta?.projection_round_adjustments?.within_event_counting_from_actuals) return 0;
  const tr = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(tr) || tr < 2) return 0;
  const means = DATA?.meta?.projection_course_basis?.field_counting_means_by_round;
  const venue = DATA?.meta?.projection_course_basis;
  if (!means || !venue) return 0;
  const rn = tr - 1;
  const lift = (fieldAvg, venueAvg) => {
    const f = num(fieldAvg, NaN);
    const v = num(venueAvg, NaN);
    if (!Number.isFinite(f) || !Number.isFinite(v)) return 0;
    return FIELD_DAY_COUNTING_LIFT_FRAC_RT * (f - v);
  };
  if (mKey === "Birdies") return lift(means.birdies?.[rn], venue.venue_avg_birdies);
  if (mKey === "Bogeys") return lift(means.bogeys?.[rn], venue.venue_avg_bogeys);
  if (mKey === "GIR") return lift(means.gir?.[rn], venue.venue_avg_gir);
  if (mKey === "Pars") {
    const b = fieldDayCountingMuAdjustment("Birdies", row);
    const bg = fieldDayCountingMuAdjustment("Bogeys", row);
    return Number.isFinite(b) || Number.isFinite(bg) ? -(b + bg) : 0;
  }
  return 0;
}

/** This week's field scoring vs venue history → total-score μ (easier week → lower μ). */
function eventWeekFieldScoringMuAdjustment(row) {
  if (courseProjectionDifficultyBakedInExport()) return 0;
  const tr = Math.round(num(row?.round, NaN));
  if (!Number.isFinite(tr) || tr < 2) return 0;
  const b = DATA?.meta?.projection_course_basis;
  if (!b) return 0;
  const eventAvg = num(b.event_week_field_avg_score_by_round?.[String(tr - 1)], NaN);
  const venueAvg = num(b.venue_avg_round_score, NaN);
  if (!Number.isFinite(eventAvg) || !Number.isFinite(venueAvg)) return 0;
  return 0.55 * (eventAvg - venueAvg);
}

const OUTCOME_SIGMA_SCALE_DEFAULT = {
  "Total score": 1.45,
  Birdies: 0.945,
  Bogeys: 0.945,
  GIR: 1.449,
  "Fairways hit": 1.45,
};

function outcomeSigmaScaleForMarket(market) {
  const mKey = ouModelMarketKey(market) || market;
  const s = DATA?.meta?.outcome_calibration?.sigma_scales?.[mKey];
  if (Number.isFinite(s) && s > 0) return s;
  return OUTCOME_SIGMA_SCALE_DEFAULT[mKey] || 1;
}

function sigmaForOu(market, row) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rec = ouStatRec(mKey);
  const outcomeScale = outcomeSigmaScaleForMarket(mKey);
  const weatherMult = projectionCountsWeatherBaked(row)
    ? 1
    : weatherSigmaMultiplierFromSnapshot(effectiveWeatherForProjectionRow(row));
  const liveShrink = sigmaLiveRoundShrinkForTotalScore(row, rec);
  if (rec.sdKey) {
    const s = num(row[rec.sdKey], NaN);
    if (Number.isFinite(s) && s > 0.05) return s * weatherMult * liveShrink * outcomeScale;
    return 2.75 * weatherMult * liveShrink * outcomeScale;
  }
  const muFull = ouMeanCountingStat(mKey, row);
  const muFallback = ouFallbackScalarForProjectedMean(mKey, row, rec);
  const muAbs = Number.isFinite(muFull) && muFull > 0 ? Math.abs(muFull) : Math.abs(num(muFallback, NaN));
  if (!Number.isFinite(muAbs) || muAbs <= 0) return 2.75 * weatherMult * liveShrink * outcomeScale;
  let sig = sigmaOuDiscreteCounting(mKey, muAbs);
  const bench = ouPgaTourBenchmarkForMarket(mKey);
  if (bench && Number.isFinite(bench.sd) && bench.sd > 0) {
    sig = Math.max(sig, bench.sd * 0.88);
    if (mKey === "Birdies" || mKey === "Bogeys" || mKey === "Pars") {
      sig = Math.min(sig, bench.sd * 1.08);
    }
  }
  return sig * weatherMult * liveShrink * outcomeScale;
}

/** Prop_Pricing_Model_2.xlsx — Round projections use distribution-based pricing (not μ-vs-line caps). */
const PROP_PRICING_MIN_HISTORY_N = 8;

function ouUsesPropPricingModel(opts = {}) {
  if (opts.useFullRoundBookMean === true || opts.usePropPricingModel === true) return true;
  try {
    return activeAppTabId() === "ou";
  } catch {
    return false;
  }
}

function propPricingUsesLogNormalSkew(market) {
  const mKey = ouModelMarketKey(market) || market;
  return mKey === "Total score" || mKey === "Bogeys";
}

function propPricingLeagueSdMultiplier(market) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const bench = ouPgaTourBenchmarkForMarket(mKey);
  if (bench && Number.isFinite(bench.mean) && bench.mean > 0 && Number.isFinite(bench.sd) && bench.sd > 0) {
    if (bench.unit === "rate" && (mKey === "GIR" || mKey === "Fairways hit")) {
      const n = mKey === "GIR" ? 18 : fairwayHolesModeledFromData() || 14;
      const muCount = bench.mean * n;
      const sdCount = bench.sd * n;
      if (muCount > 0) return sdCount / muCount;
    }
    return bench.sd / bench.mean;
  }
  const fallback = {
    "Total score": 0.047,
    Birdies: 0.52,
    Bogeys: 0.68,
    Pars: 0.27,
    GIR: 0.19,
    "Fairways hit": 0.21,
  };
  return fallback[mKey] || 0.35;
}

/** Layer 2 — measured round-to-round SD from player history (Game Log Builder analogue). */
function ouPlayerMarketStdDev(market, player, windowMode = ouProjAvgWindowMode()) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rounds = ouPlayerMarketAvgSampleRounds(player, windowMode);
  if (rounds.length < PROP_PRICING_MIN_HISTORY_N) return NaN;
  const statKey = ouMarketRatingHistoryStatKey(mKey);
  const vals = [];
  for (const r of rounds) {
    const v = ouMarketAvgValueForRoundRow(statKey, r);
    if (Number.isFinite(v)) vals.push(v);
  }
  if (vals.length < PROP_PRICING_MIN_HISTORY_N) return NaN;
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  const variance = vals.reduce((a, v) => a + (v - mean) ** 2, 0) / (vals.length - 1);
  const sd = Math.sqrt(variance);
  return Number.isFinite(sd) && sd > 0.05 ? sd : NaN;
}

function propPricingWeatherSigmaMult(row) {
  return projectionCountsWeatherBaked(row)
    ? 1
    : weatherSigmaMultiplierFromSnapshot(effectiveWeatherForProjectionRow(row));
}

function propPricingSigmaForOu(market, row, mu, opts = {}) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rec = ouStatRec(mKey);
  const weatherMult = propPricingWeatherSigmaMult(row);

  if (mKey === "Total score" && rec.sdKey) {
    const s = num(row[rec.sdKey], NaN);
    if (Number.isFinite(s) && s > 0.05) return s * weatherMult;
  }

  const histSd = ouPlayerMarketStdDev(market, row);
  if (Number.isFinite(histSd)) return histSd * weatherMult;

  if (Number.isFinite(mu) && mu > 0) {
    let sig = mu * propPricingLeagueSdMultiplier(mKey);
    if (mKey === "GIR" || mKey === "Fairways hit") {
      sig = Math.max(sig, sigmaOuDiscreteCounting(mKey, mu));
    }
    const bench = ouPgaTourBenchmarkForMarket(mKey);
    if (bench && Number.isFinite(bench.sd) && bench.sd > 0) {
      sig = Math.max(sig, bench.sd * 0.88);
    }
    return sig * weatherMult;
  }

  const legacy = sigmaForOu(market, row);
  const outcomeScale = outcomeSigmaScaleForMarket(mKey);
  return Number.isFinite(legacy) && outcomeScale > 0 ? legacy / outcomeScale : legacy;
}

function propPricingNormalProbOver(mu, sigma, line) {
  if (!Number.isFinite(mu) || !Number.isFinite(sigma) || !Number.isFinite(line) || sigma <= 0) return NaN;
  return 1 - normalCdf((line - mu) / sigma);
}

/** Layer 3 — right-skewed outcomes (total score, bogeys): log-normal P(over). */
function propPricingLogNormalProbOver(mu, sigma, line) {
  if (!Number.isFinite(mu) || !Number.isFinite(sigma) || !Number.isFinite(line)) return NaN;
  if (mu <= 0 || sigma <= 0 || line <= 0) return NaN;
  const sigmaLn2 = Math.log(1 + (sigma / mu) ** 2);
  const sigmaLn = Math.sqrt(sigmaLn2);
  const muLn = Math.log(mu) - sigmaLn2 / 2;
  return 1 - normalCdf((Math.log(line) - muLn) / sigmaLn);
}

function propPricingProbOverMarket(market, row, line, opts = {}) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const mu = ouProjectedMean(market, row, opts);
  if (!Number.isFinite(mu)) return NaN;
  const sig = propPricingSigmaForOu(market, row, mu, opts);
  if (!Number.isFinite(sig) || sig <= 0) return NaN;
  if (propPricingUsesLogNormalSkew(mKey)) return propPricingLogNormalProbOver(mu, sig, line);
  return propPricingNormalProbOver(mu, sig, line);
}

/** Step 4 — expected ROI per unit staked at posted American odds. */
function propPricingExpectedRoi(prob, americanOdds) {
  const p = num(prob, NaN);
  const d = decimalFromAmerican(americanOdds);
  if (!Number.isFinite(p) || !Number.isFinite(d) || d <= 1) return NaN;
  return p * d - 1;
}

/** Model vs DK props aligned this week — use baked export μ (+ in-round partials only). */
function eventPropBookAlignedMarket(mKey) {
  const mk = mKey === "Total Score" ? "Total score" : mKey;
  const align =
    DATA?.meta?.event_prop_book_alignment?.markets?.[mk] ||
    DATA?.event_prop_book_alignment?.markets?.[mk];
  return Boolean(align);
}

/** Round Projections vs DK/PrizePicks full-round O/U — never apply in-play μ collapse on this table. */
const OU_PROJ_TABLE_MEAN_OPTS = Object.freeze({ useFullRoundBookMean: true });

function ouUsesFullRoundBookMean(opts = {}) {
  return opts.useFullRoundBookMean === true || opts.skipLivePartial === true;
}

function ouInPlayMuDeltaForTotalScore(row, opts = {}) {
  if (ouUsesFullRoundBookMean(opts)) return 0;
  return liveCurrentRoundTotalScoreMuDelta(row);
}

function ouInPlayCountingAdjust(market, row, opts = {}) {
  if (ouUsesFullRoundBookMean(opts)) return { muDelta: 0, sigmaScale: 1 };
  return livePartialRoundCountPropAdjust(market, row);
}

function ouInPlaySigmaScaleForMarket(market, row, rec, opts = {}) {
  if (ouUsesFullRoundBookMean(opts)) return 1;
  const countLive = livePartialRoundCountPropAdjust(market, row);
  const mKey = ouModelMarketKey(market) || "Total score";
  if (mKey === "Total score") {
    return countLive.sigmaScale * sigmaLiveRoundShrinkForTotalScore(row, rec);
  }
  return countLive.sigmaScale;
}

/** Model-projected mean μ for one market / player / round (weather, live course, partial live round, pricing). */
function ouProjectedMean(market, row, opts = {}) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rec = ouStatRec(mKey);
  const dgId = Math.round(num(row?.dg_id, NaN));
  const countLive = ouInPlayCountingAdjust(mKey, row, opts);

  if (eventPropBookAlignedMarket(mKey)) {
    if (mKey === "Total score") {
      const base = ouMeanCountingStat(mKey, row);
      const baseScalar = Number.isFinite(base)
        ? base
        : ouFallbackScalarForProjectedMean(mKey, row, rec);
      return (
        baseScalar +
        ouInPlayMuDeltaForTotalScore(row, opts) +
        countLive.muDelta
      );
    }
    const base = ouMeanCountingStat(mKey, row);
    if (Number.isFinite(base)) return base + countLive.muDelta;
  }

  if (mKey === "Total score") {
    return ouProjectedTotalScoreMean(row, opts);
  }

  if (
    row?.weather_counts_baked || hierarchicalMuOwnsRow(row)
  ) {
    if (mKey === "Birdies" || mKey === "Pars" || mKey === "Bogeys" || mKey === "GIR" || mKey === "Fairways hit") {
      const base = ouMeanCountingStat(mKey, row);
      if (Number.isFinite(base)) {
        return (
          base +
          pinSheetMuAdjustment(mKey, row) +
          countLive.muDelta +
          pricingStatMuAdjustment(mKey, dgId)
        );
      }
    }
  }

  if (
    projectionCountsCoherentFromExport() &&
    !row?.weather_counts_baked &&
    !hierarchicalMuOwnsRow(row) &&
    !row?._pin_adjusted &&
    !pinSheetAppliesToProjectionRow(row) &&
    (mKey === "Birdies" || mKey === "Pars" || mKey === "Bogeys" || mKey === "GIR" || mKey === "Fairways hit")
  ) {
    const totalMu = ouProjectedTotalScoreMean(row, opts);
    if (Number.isFinite(totalMu)) {
      const coherent = coherentCountingMeansAtTotal(row, totalMu);
      const v = coherent[mKey];
      if (Number.isFinite(v)) {
        return (
          v +
          pinSheetMuAdjustment(mKey, row) +
          countLive.muDelta +
          pricingStatMuAdjustment(mKey, dgId)
        );
      }
    }
  }

  const liveRoundAdj = mKey === "Total score" ? ouInPlayMuDeltaForTotalScore(row, opts) : 0;
  const baseMean = ouMeanCountingStat(mKey, row);
  const baseScalar = Number.isFinite(baseMean) ? baseMean : ouFallbackScalarForProjectedMean(mKey, row, rec);

  /* Birdies / pars / bogeys: export + this-week form + field day + weather + course playing + skill. */
  if (mKey === "Birdies" || mKey === "Pars" || mKey === "Bogeys") {
    return (
      baseScalar +
      tournamentWeekCountingMuAdjustment(mKey, row) +
      fieldDayCountingMuAdjustment(mKey, row) +
      countingSkillRatingMuAdjustment(mKey, row) +
      statWeatherMuAdjustment(mKey, row) +
      pinSheetMuAdjustment(mKey, row) +
      combinedCourseDifficultyOUMuAdjustment(mKey, row) +
      countLive.muDelta +
      pricingStatMuAdjustment(mKey, dgId)
    );
  }
  if (mKey === "GIR" || mKey === "Fairways hit") {
    return (
      baseScalar +
      tournamentWeekCountingMuAdjustment(mKey, row) +
      fieldDayCountingMuAdjustment(mKey, row) +
      countingSkillRatingMuAdjustment(mKey, row) +
      statWeatherMuAdjustment(mKey, row) +
      pinSheetMuAdjustment(mKey, row) +
      combinedCourseDifficultyOUMuAdjustment(mKey, row) +
      countLive.muDelta +
      pricingStatMuAdjustment(mKey, dgId)
    );
  }

  return (
    baseScalar +
    statWeatherMuAdjustment(mKey, row) +
    pinSheetMuAdjustment(mKey, row) +
    combinedCourseDifficultyOUMuAdjustment(mKey, row) +
    eventWeekFieldScoringMuAdjustment(row) +
    liveRoundAdj +
    countLive.muDelta +
    pricingStatMuAdjustment(mKey, dgId)
  );
}

function modelProbOverMarket(market, row, line, opts = {}) {
  if (ouUsesPropPricingModel(opts)) return propPricingProbOverMarket(market, row, line, opts);
  const mKey = ouModelMarketKey(market) || "Total score";
  const rec = ouStatRec(mKey);
  const mu = ouProjectedMean(market, row, opts);
  if (!Number.isFinite(mu)) return NaN;
  const sig =
    sigmaForOu(mKey, row) *
    ouInPlaySigmaScaleForMarket(mKey, row, rec, opts) *
    marketBookSigmaScale(mKey);
  const z = (line - mu) / sig;
  return 1 - normalCdf(z);
}

function getOuViewMode() {
  const priceOn = document.getElementById("ou-mode-price")?.classList.contains("active");
  return priceOn ? "price" : "prob";
}

function setOuViewMode(mode) {
  const prob = document.getElementById("ou-mode-prob");
  const price = document.getElementById("ou-mode-price");
  if (!prob || !price) return;
  const isPrice = mode === "price";
  prob.classList.toggle("active", !isPrice);
  price.classList.toggle("active", isPrice);
  prob.setAttribute("aria-selected", (!isPrice).toString());
  price.setAttribute("aria-selected", isPrice.toString());
}

function getOuMarket() {
  const el = document.getElementById("ou-market-filter");
  const v = el && el.value ? el.value : "Total score";
  return v === "Putts" ? "Total score" : v;
}

/** Round score & bogeys: chart shows P(over) (falls as line rises). Birdies/pars: P(under) (rises as line rises). */
function ouMarketLowerIsBetter(market) {
  return market === "Total score" || market === "Bogeys" || market === "Putts";
}

function enforceHalfLine(v) {
  if (!Number.isFinite(v)) return NaN;
  return Math.round(v - 0.5) + 0.5;
}

/** R export / CSV uses "Total Score"; O/U UI uses "Total score". */
function ouPropsCanonicalMarket(market) {
  const m = String(market || "");
  if (m === "Total score") return "Total Score";
  return m;
}

function ouPropPlayerKeyRaw(name) {
  return String(name || "").trim().toLowerCase();
}

function ouPropPlayerKeyDisplay(name) {
  return String(displayGolferName(name || ""))
    .trim()
    .toLowerCase();
}

function ouPropPlayerKeyLoose(name) {
  return String(name || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function ouGolferNameMatchParts(name) {
  const disp = displayGolferName(name);
  const loose = ouPropPlayerKeyLoose(disp || name);
  const parts = loose.split(/\s+/).filter((t) => t.length >= 2);
  return { loose, parts, last: parts.length ? parts[parts.length - 1] : "" };
}

function ouFirstNamesLikelySame(a, b) {
  if (!a || !b) return false;
  const la = String(a).toLowerCase();
  const lb = String(b).toLowerCase();
  if (la === lb) return true;
  if (la.length >= 2 && lb.length >= 2 && (la.startsWith(lb) || lb.startsWith(la))) return true;
  if (la.length >= 3 && lb.length >= 3 && la.slice(0, 3) === lb.slice(0, 3)) return true;
  return false;
}

/** DK labels vs DataGolf field names (John/Johnny, Matti/Matthias, Last/First order). */
function golferNamesLikelySame(nameA, nameB) {
  const a = String(nameA || "").trim();
  const b = String(nameB || "").trim();
  if (!a || !b) return false;
  if (a.toLowerCase() === b.toLowerCase()) return true;
  const ta = ouGolferNameMatchParts(a);
  const tb = ouGolferNameMatchParts(b);
  if (ta.loose && tb.loose && ta.loose === tb.loose) return true;
  if (!ta.last || !tb.last || ta.last !== tb.last) return false;
  if (ta.parts.length >= 2 && tb.parts.length >= 2) {
    if (ouFirstNamesLikelySame(ta.parts[0], tb.parts[0])) return true;
  }
  const setB = new Set(tb.parts);
  const overlap = ta.parts.filter((t) => setB.has(t)).length;
  if (overlap >= 2) return true;
  if (overlap >= 1 && ta.parts.length <= 2 && tb.parts.length <= 2) {
    return ouFirstNamesLikelySame(ta.parts[0], tb.parts[0]);
  }
  if (ta.loose.length >= 4 && tb.loose.length >= 4) {
    if (ta.loose.includes(tb.loose) || tb.loose.includes(ta.loose)) return true;
  }
  return false;
}

let projectionsDataRev = 0;
let ouDkRoundPropsCacheSig = "";
/** @type {object[]} */
let ouDkRoundPropsCache = [];
let ouProjectionSortCacheSig = "";
/** @type {object[] | null} */
let ouProjectionSortCache = null;
let ouGolferSuggestLabelsSig = "";
