/** DraftKings when posted; otherwise next available book lines for the Round projections tab. */
function roundBookPropsOnly(allRounds = false) {
  const dk = draftKingsRoundPropsOnly(allRounds);
  if (dk.length) return dk;
  const pp = prizePicksRoundPropsOnly(allRounds);
  if (pp.length) return pp;
  const sl = sleeperRoundPropsOnly(allRounds);
  if (sl.length) return sl;
  const ud = underdogRoundPropsOnly(allRounds);
  if (ud.length) return ud;
  const fd = fanduelRoundPropsOnly(allRounds);
  if (fd.length) return fd;
  const kl = kalshiRoundPropsOnly(allRounds);
  if (kl.length) return kl;
  return caesarsRoundPropsOnly(allRounds);
}

function draftKingsPostedRounds() {
  const out = new Set();
  for (const r of draftKingsRoundPropsOnly(true)) {
    const pr = Math.round(num(r.round_num, NaN));
    if (pr >= 1 && pr <= 4) out.add(pr);
  }
  return [...out].sort((a, b) => a - b);
}

/** Default auto round: cap stale export/live with calendar week; prefer latest DK round within cap. */
function preferredOuRoundForPicker() {
  if (eventTournamentWeekNotStarted()) return 1;
  const cal = calendarTournamentRoundFromDateStart(tournamentDateStartIso());
  const meta = effectiveUiModelRoundFromMeta();
  const live = currentEventLiveRoundNum();
  const dkRounds = draftKingsPostedRounds();
  const capParts = [cal, meta, live].filter((x) => Number.isFinite(x) && x >= 1 && x <= 4);
  const cap = capParts.length ? Math.min(...capParts) : Number.isFinite(cal) ? cal : 1;
  if (dkRounds.length) {
    const eligible = dkRounds.filter((r) => r <= cap);
    if (eligible.length) return Math.max(...eligible);
  }
  if (Number.isFinite(live) && live >= 1 && live <= 4) return Math.min(live, cap);
  if (Number.isFinite(meta) && meta >= 1 && meta <= 4) return Math.min(meta, cap);
  if (Number.isFinite(cal) && cal >= 1 && cal <= 4) return cal;
  return 1;
}

function parseDkAuditCsvRow(line) {
  const out = [];
  let cur = "";
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQ) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          cur += '"';
          i++;
        } else inQ = false;
      } else cur += ch;
    } else if (ch === '"') inQ = true;
    else if (ch === ",") {
      out.push(cur);
      cur = "";
    } else cur += ch;
  }
  out.push(cur);
  return out;
}

function propsEventNameForDkAudit() {
  return String(DATA?.meta?.event_name || DATA?.meta?.datagolf_event_name || "").trim();
}

function dkAuditEventMatchesCurrent(evRaw) {
  const meta = propsEventNameForDkAudit();
  const ev = String(evRaw || "").trim();
  if (!meta || !ev) return false;
  return eventNameMatchesCurrentSchedule(ev, meta) || scheduleNameMatchesMeta(ev, meta);
}

function buildDkAuditPropsLineKeysFromCsvText(text) {
  const lines = String(text || "")
    .split(/\r?\n/)
    .filter((ln) => ln.trim());
  if (!lines.length) return new Set();
  const hdr = parseDkAuditCsvRow(lines[0]);
  const col = (name) => hdr.indexOf(name);
  const iEv = col("event_name");
  const iRnd = col("display_round");
  const iDg = col("dg_id");
  const iMkt = col("market");
  const iCap = col("captured_at");
  const iLine = col("dk_line");
  const iOver = col("over_odds");
  const iUnder = col("under_odds");
  if (iEv < 0 || iRnd < 0 || iDg < 0 || iMkt < 0) return new Set();

  const bestCap = new Map();
  const keys = new Set();
  for (let li = 1; li < lines.length; li++) {
    const cols = parseDkAuditCsvRow(lines[li]);
    if (!dkAuditEventMatchesCurrent(cols[iEv])) continue;
    const rnd = Math.round(num(cols[iRnd], NaN));
    const dg = Math.round(num(cols[iDg], NaN));
    const market = String(cols[iMkt] || "").trim();
    if (!Number.isFinite(rnd) || rnd < 1 || rnd > 4 || !Number.isFinite(dg) || !market) continue;
    const line = num(iLine >= 0 ? cols[iLine] : NaN, NaN);
    const over = num(iOver >= 0 ? cols[iOver] : NaN, NaN);
    const under = num(iUnder >= 0 ? cols[iUnder] : NaN, NaN);
    if (!Number.isFinite(line) || !Number.isFinite(over) || !Number.isFinite(under)) continue;
    const key = `${dg}|${rnd}|${market}`;
    const capturedMs = iCap >= 0 ? Date.parse(String(cols[iCap] || "").trim()) : NaN;
    const prev = bestCap.get(key);
    if (!Number.isFinite(prev) || (Number.isFinite(capturedMs) && capturedMs > prev)) {
      bestCap.set(key, Number.isFinite(capturedMs) ? capturedMs : 0);
      keys.add(key);
    }
  }
  return keys;
}

function ensureDkAuditPropsIndexLoaded() {
  const metaEv = propsEventNameForDkAudit();
  const sig = `${metaEv}|rev${projectionsDataRev}`;
  if (dkAuditPropsCacheSig === sig && dkAuditPropsLineKeys) return Promise.resolve(dkAuditPropsLineKeys);
  if (dkAuditPropsLoadPromise) return dkAuditPropsLoadPromise;
  dkAuditPropsLoadPromise = (async () => {
    let keys = new Set();
    try {
      const res = await fetch(cacheBustFetchUrl("data/dk_round_projection_audit.csv"), { cache: "no-store" });
      if (res.ok) keys = buildDkAuditPropsLineKeysFromCsvText(await res.text());
    } catch {
      keys = new Set();
    }
    dkAuditPropsLineKeys = keys;
    dkAuditPropsCacheSig = sig;
    invalidateCourseWindowRoundEntriesCache();
    return keys;
  })().finally(() => {
    dkAuditPropsLoadPromise = null;
  });
  return dkAuditPropsLoadPromise;
}

function draftKingsTournamentPropsAvailable() {
  if (dkAuditPropsLineKeys?.size) return true;
  return draftKingsRoundPropsOnly(true).length > 0 || draftKingsRoundPropsOnly().length > 0;
}

/** Match projections field row to a props row (dg_id + display/raw/loose/fuzzy name). */
function ouPropRowMatchesPlayer(propRow, playerRow) {
  if (!propRow || !playerRow) return false;
  const wantId = Math.round(num(playerRow.dg_id, NaN));
  const rid = Math.round(num(propRow.dg_id, NaN));
  if (Number.isFinite(wantId) && wantId > 0 && rid === wantId) return true;
  const wantRaw = ouPropPlayerKeyRaw(playerRow.player_name || "");
  const wantDisp = ouPropPlayerKeyDisplay(playerRow.player_name || "");
  const wantLoose = ouPropPlayerKeyLoose(displayGolferName(playerRow.player_name || ""));
  const rRaw = ouPropPlayerKeyRaw(propRow.player_name || "");
  const rDisp = ouPropPlayerKeyDisplay(propRow.player_name || "");
  const rLoose = ouPropPlayerKeyLoose(displayGolferName(propRow.player_name || ""));
  if (wantRaw && rRaw && wantRaw === rRaw) return true;
  if (wantDisp && rDisp && wantDisp === rDisp) return true;
  if (wantLoose && rLoose && wantLoose === rLoose) return true;
  if (golferNamesLikelySame(playerRow.player_name, propRow.player_name)) return true;
  if (golferNameMatchesQuery(propRow.player_name, wantRaw)) return true;
  if (golferNameMatchesQuery(playerRow.player_name, rRaw)) return true;
  return false;
}

function buildOuProjectionFieldIndex(players) {
  const byId = new Map();
  const list = [];
  for (const p of players) {
    const id = Math.round(num(p.dg_id, NaN));
    if (Number.isFinite(id) && id > 0) byId.set(id, p);
    list.push(p);
  }
  return { byId, list };
}

function resolveFieldPlayerForDkProp(propRow, index) {
  if (!propRow || !index) return null;
  const rid = Math.round(num(propRow.dg_id, NaN));
  if (Number.isFinite(rid) && rid > 0 && index.byId.has(rid)) return index.byId.get(rid);
  for (const p of index.list) {
    if (ouPropRowMatchesPlayer(propRow, p)) return p;
  }
  return null;
}

/** O(1) name/id lookup for DK prop rows; falls back to fuzzy match only when keys miss. */
function ouBuildFastFieldPlayerResolver(index) {
  const byKey = new Map();
  for (const p of index.list) {
    const id = Math.round(num(p.dg_id, NaN));
    if (Number.isFinite(id) && id > 0) byKey.set(`id:${id}`, p);
    const keys = [
      ouPropPlayerKeyRaw(p.player_name || ""),
      ouPropPlayerKeyDisplay(p.player_name || ""),
      ouPropPlayerKeyLoose(displayGolferName(p.player_name || "")),
    ].filter(Boolean);
    for (const k of keys) {
      if (!byKey.has(`nm:${k}`)) byKey.set(`nm:${k}`, p);
    }
  }
  return (propRow) => {
    if (!propRow || !index) return null;
    const rid = Math.round(num(propRow.dg_id, NaN));
    if (Number.isFinite(rid) && rid > 0) {
      const byId = index.byId.get(rid) || byKey.get(`id:${rid}`);
      if (byId) return byId;
    }
    const rKeys = [
      ouPropPlayerKeyRaw(propRow.player_name || ""),
      ouPropPlayerKeyDisplay(propRow.player_name || ""),
      ouPropPlayerKeyLoose(displayGolferName(propRow.player_name || "")),
    ].filter(Boolean);
    for (const k of rKeys) {
      const hit = byKey.get(`nm:${k}`);
      if (hit) return hit;
    }
    return resolveFieldPlayerForDkProp(propRow, index);
  };
}

/** Index props rows by canonical market + player keys for fast line lookup. */
function ouBuildPropsRowsLookup(propsList) {
  const byCanonPlayer = new Map();
  for (const r of propsList) {
    const canon = String(r.market || "").trim();
    const L = enforceHalfLine(num(r.line, NaN));
    const o = num(r.over_odds, NaN);
    const u = num(r.under_odds, NaN);
    if (!canon || !Number.isFinite(L) || !Number.isFinite(o) || !Number.isFinite(u)) continue;
    const row = {
      line: L,
      over: o,
      under: u,
      source: String(r.source || "").trim().toLowerCase(),
    };
    const id = Math.round(num(r.dg_id, NaN));
    const keys = [];
    if (Number.isFinite(id) && id > 0) keys.push(`id:${id}`);
    const raw = String(r.player_name || "").trim();
    if (raw) {
      keys.push(
        `nm:${ouPropPlayerKeyRaw(raw)}`,
        `nm:${ouPropPlayerKeyDisplay(raw)}`,
        `nm:${ouPropPlayerKeyLoose(raw)}`,
        `nm:${ouPropPlayerKeyLoose(displayGolferName(raw))}`,
      );
    }
    for (const k of keys) {
      const bucketKey = `${canon}|${k}`;
      let arr = byCanonPlayer.get(bucketKey);
      if (!arr) {
        arr = [];
        byCanonPlayer.set(bucketKey, arr);
      }
      arr.push(row);
    }
  }
  return (market, playerRow) => {
    const canon = ouPropsCanonicalMarket(market);
    const id = Math.round(num(playerRow?.dg_id, NaN));
    const keys = [];
    if (Number.isFinite(id) && id > 0) keys.push(`id:${id}`);
    const nm = String(playerRow?.player_name || "").trim();
    if (nm) {
      keys.push(
        `nm:${ouPropPlayerKeyRaw(nm)}`,
        `nm:${ouPropPlayerKeyDisplay(nm)}`,
        `nm:${ouPropPlayerKeyLoose(nm)}`,
        `nm:${ouPropPlayerKeyLoose(displayGolferName(nm))}`,
      );
    }
    const out = [];
    const seenLine = new Set();
    for (const k of keys) {
      const arr = byCanonPlayer.get(`${canon}|${k}`);
      if (!arr) continue;
      for (const r of arr) {
        const sig = `${r.line}|${r.over}|${r.under}`;
        if (seenLine.has(sig)) continue;
        seenLine.add(sig);
        out.push(r);
      }
    }
    return out;
  };
}

function chooseOuPropLineFromLookup(propLookup, market, playerRow, mu) {
  const rows = propLookup(market, playerRow);
  if (!rows.length) return null;
  let best = rows[0];
  let bestDist = Number.POSITIVE_INFINITY;
  for (const r of rows) {
    const d = Number.isFinite(mu) ? Math.abs(r.line - mu) : 0;
    if (d < bestDist) {
      best = r;
      bestDist = d;
    }
  }
  const dkOnly = rows.filter((r) => r.source === "draftkings");
  if (dkOnly.length) {
    let bestDk = dkOnly[0];
    let bestDkDist = Number.POSITIVE_INFINITY;
    for (const r of dkOnly) {
      const d = Number.isFinite(mu) ? Math.abs(r.line - mu) : 0;
      if (d < bestDkDist) {
        bestDk = r;
        bestDkDist = d;
      }
    }
    return bestDk;
  }
  return best;
}

/** Map id:${dgId}:${line} / nm:${name}:${line} → { over, under } American odds. */
function ouBuildPropsOddsIndex(market, opts = {}) {
  const canon = ouPropsCanonicalMarket(market);
  const map = new Map();
  const props = opts.dkOnly ? draftKingsRoundPropsOnly() : ouRoundOuPropsForLines();
  for (const r of props) {
    if (String(r.market || "").trim() !== canon) continue;
    const L = enforceHalfLine(num(r.line, NaN));
    if (!Number.isFinite(L)) continue;
    const o = num(r.over_odds, NaN);
    const u = num(r.under_odds, NaN);
    if (!Number.isFinite(o) || !Number.isFinite(u)) continue;
    const id = Math.round(num(r.dg_id, NaN));
    if (Number.isFinite(id) && id > 0) map.set(`id:${id}:${L}`, { over: o, under: u });
    const raw = String(r.player_name || "").trim();
    if (raw) {
      map.set(`nm:${ouPropPlayerKeyRaw(raw)}:${L}`, { over: o, under: u });
      map.set(`nm:${ouPropPlayerKeyDisplay(raw)}:${L}`, { over: o, under: u });
      map.set(`nm:${ouPropPlayerKeyLoose(raw)}:${L}`, { over: o, under: u });
      map.set(`nm:${ouPropPlayerKeyLoose(displayGolferName(raw))}:${L}`, { over: o, under: u });
    }
  }
  return map;
}

function ouPropsBookOddsFromIndex(idx, playerRow, line) {
  const L = enforceHalfLine(line);
  if (!Number.isFinite(L) || !idx) return null;
  const id = Math.round(num(playerRow?.dg_id, NaN));
  if (Number.isFinite(id) && id > 0) {
    const byId = idx.get(`id:${id}:${L}`);
    if (byId) return byId;
  }
  const nm = String(playerRow?.player_name || "").trim();
  if (!nm) return null;
  let hit = idx.get(`nm:${ouPropPlayerKeyRaw(nm)}:${L}`);
  if (hit) return hit;
  hit = idx.get(`nm:${ouPropPlayerKeyDisplay(nm)}:${L}`);
  return hit || null;
}

function ouPropsRowsForMarketPlayer(market, playerRow, opts = {}) {
  const canon = ouPropsCanonicalMarket(market);
  const props = opts.dkOnly ? draftKingsRoundPropsOnly(Boolean(opts.allDkRounds)) : ouRoundOuPropsForLines();
  const wantR = Number.isFinite(Math.round(num(opts.roundNum, NaN))) ? Math.round(num(opts.roundNum, NaN)) : NaN;
  const out = [];
  for (const r of props) {
    if (String(r.market || "").trim() !== canon) continue;
    const pr = Math.round(num(r.round_num, NaN));
    if (Number.isFinite(wantR) && Number.isFinite(pr) && pr !== wantR) continue;
    const L = enforceHalfLine(num(r.line, NaN));
    const o = num(r.over_odds, NaN);
    const u = num(r.under_odds, NaN);
    if (!Number.isFinite(L) || !Number.isFinite(o) || !Number.isFinite(u)) continue;
    if (!ouPropRowMatchesPlayer(r, playerRow)) continue;
    out.push({ line: L, over: o, under: u, source: String(r.source || "").trim().toLowerCase() });
  }
  if (opts.dkOnly) return out;
  const dkOnly = out.filter((r) => r.source === "draftkings");
  if (dkOnly.length) return dkOnly;
  return out;
}

function chooseOuPropLineForProjection(market, playerRow, mu, opts = {}) {
  const rows = ouPropsRowsForMarketPlayer(market, playerRow, { ...opts, dkOnly: true });
  if (!rows.length) return null;
  let best = rows[0];
  let bestDist = Number.POSITIVE_INFINITY;
  for (const r of rows) {
    const d = Number.isFinite(mu) ? Math.abs(r.line - mu) : 0;
    if (d < bestDist) {
      best = r;
      bestDist = d;
    }
  }
  return best;
}

function ouBookImpliedForSortColumn(playerRow, market, L, lineSel, pImpOverSel, pImpUnderSel, propIdx, side) {
  const useCustom = lineMatchesOuHighlight(lineSel, L, market);
  if (useCustom) return side === "over" ? pImpOverSel : pImpUnderSel;
  const pk = ouPropsBookOddsFromIndex(propIdx, playerRow, L);
  if (pk && Number.isFinite(pk.over) && Number.isFinite(pk.under)) {
    return side === "over" ? impliedProbFromAmerican(pk.over) : impliedProbFromAmerican(pk.under);
  }
  return impliedProbFromAmerican(OU_DEFAULT_ODDS_AM);
}

function formatAmericanOddsInput(am) {
  const v = Math.round(num(am, NaN));
  if (!Number.isFinite(v) || v === 0) return "";
  return v > 0 ? `+${v}` : String(v);
}

/** When one golfer is selected and props include their line, mirror DK over/under into the toolbar. */
function syncOuToolbarOddsFromProps(market, lineSel, round) {
  const oEl = document.getElementById("ou-odds-over-filter");
  const uEl = document.getElementById("ou-odds-under-filter");
  const pf = document.getElementById("ou-player-filter");
  if (!oEl || !uEl || !pf || !(pf instanceof HTMLInputElement)) return;
  if (document.activeElement === oEl || document.activeElement === uEl) return;
  const r = Math.round(num(round, NaN));
  const allRows = ouSortedPlayerRowsProjection(r);
  const want = ouResolveSinglePlayerNameForToolbar(allRows, String(pf.value || "").trim());
  if (!want) return;
  const row = DATA.players.find((p) => String(p.player_name || "").trim() === want && samePlayerRound(p, r));
  if (!row) return;
  const idx = ouBuildPropsOddsIndex(market, { dkOnly: true });
  const L = enforceHalfLine(lineSel);
  if (!Number.isFinite(L)) return;
  const pk = ouPropsBookOddsFromIndex(idx, row, L);
  if (!pk || !Number.isFinite(pk.over) || !Number.isFinite(pk.under)) return;
  oEl.value = formatAmericanOddsInput(pk.over);
  uEl.value = formatAmericanOddsInput(pk.under);
}

function parseOuLineFilterInput() {
  const el = document.getElementById("ou-line-filter");
  if (!el) return NaN;
  const s = String(el.value ?? "").trim();
  if (!s || s === "-" || s === "+" || s === "." || s === "-." || s === "+.") return NaN;
  const raw = num(s, NaN);
  if (!Number.isFinite(raw)) return NaN;
  return enforceHalfLine(raw);
}

/** Highlight / odds column: parsed line if valid, else last committed (typing must not snap every keystroke). */
function lineSelForOuTable() {
  const v = parseOuLineFilterInput();
  return Number.isFinite(v) ? v : ouLineCommitted;
}

function commitOuLineFilterValue() {
  const el = document.getElementById("ou-line-filter");
  if (!el) return;
  let v = parseOuLineFilterInput();
  if (!Number.isFinite(v)) v = ouLineCommitted;
  else ouLineCommitted = v;
  el.value = ouLineCommitted.toFixed(1);
}

function selectedOuOddsById(inputId, normalizeInput = false) {
  const el = document.getElementById(inputId);
  const raw = String(el?.value || "").trim().replace(/\s+/g, "");
  const m = raw.match(/^([+-]?)(\d+)$/);
  let v = m ? parseInt(`${m[1] || ""}${m[2]}`, 10) : OU_DEFAULT_ODDS_AM;
  if (!Number.isFinite(v) || v === 0) v = OU_DEFAULT_ODDS_AM;
  if (el && normalizeInput) el.value = v > 0 ? `+${v}` : String(v);
  return v;
}

function formatEdgePct(edge) {
  if (!Number.isFinite(edge)) return "—";
  const p = edge * 100;
  return `${p >= 0 ? "+" : ""}${p.toFixed(1)}%`;
}

/** Posted American odds + no-vig fair American for one book cell. */
function paintOuProjOddsTd(td, pick, side, fairP) {
  td.textContent = "";
  if (!pick) return;
  const am = ouProjSideAmerican(pick, side);
  if (!Number.isFinite(am)) {
    td.textContent = "—";
    return;
  }
  const stack = document.createElement("div");
  stack.className = "ou-proj-odds-stack";
  const posted = document.createElement("div");
  posted.className = "ou-proj-odds-posted";
  posted.textContent = formatAmerican(am);
  stack.appendChild(posted);
  if (Number.isFinite(fairP)) {
    const fair = document.createElement("div");
    fair.className = "ou-proj-odds-fair";
    fair.textContent = modelAmericanFromProb(fairP);
    fair.title = "No-vig fair value";
    stack.appendChild(fair);
  }
  td.appendChild(stack);
}

function paintOuProjDeltaTd(td, delta) {
  if (!Number.isFinite(delta)) {
    td.textContent = "";
    return;
  }
  td.textContent = formatEdgePct(delta);
  if (delta > 0) td.classList.add("pos");
  else if (delta < 0) td.classList.add("neg");
}

const OU_PROJ_KELLY_PREFS_KEY = "alphaCaddie_ou_proj_kelly_v1";

function loadOuProjKellyPrefs() {
  try {
    const j = JSON.parse(localStorage.getItem(OU_PROJ_KELLY_PREFS_KEY) || "{}");
    const frac = num(j.fraction, 0.25);
    return {
      bankroll: Math.max(1, Math.round(num(j.bankroll, 1000))),
      fraction: frac === 0.5 || frac === 1 ? frac : 0.25,
    };
  } catch {
    return { bankroll: 1000, fraction: 0.25 };
  }
}

function persistKellySizingPrefs(bankroll, fraction) {
  const br = Math.max(1, Math.round(num(bankroll, 1000)));
  const frac = num(fraction, 0.25);
  const saved = {
    bankroll: br,
    fraction: frac === 0.5 || frac === 1 ? frac : 0.25,
  };
  try {
    localStorage.setItem(OU_PROJ_KELLY_PREFS_KEY, JSON.stringify(saved));
  } catch {
    /* ignore */
  }
  syncOuProjKellyPrefsToUi();
  return saved;
}

function saveOuProjKellyPrefs() {
  persistKellySizingPrefs(ouProjBankrollFromUi(), ouProjKellyFractionFromUi());
}

function saveMatchupAnalysisKellyPrefs() {
  persistKellySizingPrefs(matchupAnalysisBankrollFromUi(), matchupAnalysisKellyFractionFromUi());
}

function syncOuProjKellyPrefsToUi() {
  const p = loadOuProjKellyPrefs();
  for (const id of ["ou-proj-bankroll", "analysis-bankroll"]) {
    const br = document.getElementById(id);
    if (br instanceof HTMLInputElement) br.value = String(p.bankroll);
  }
  for (const id of ["ou-proj-kelly-fraction", "analysis-kelly-fraction"]) {
    const kf = document.getElementById(id);
    if (kf instanceof HTMLSelectElement) kf.value = String(p.fraction);
  }
}

function ouProjBankrollFromUi() {
  const el = document.getElementById("ou-proj-bankroll");
  const v = num(el instanceof HTMLInputElement ? el.value : NaN, NaN);
  return Number.isFinite(v) && v >= 1 ? v : loadOuProjKellyPrefs().bankroll;
}

function ouProjKellyFractionFromUi() {
  const el = document.getElementById("ou-proj-kelly-fraction");
  const v = num(el instanceof HTMLSelectElement ? el.value : NaN, NaN);
  if (v === 0.25 || v === 0.5 || v === 1) return v;
  return loadOuProjKellyPrefs().fraction;
}

function matchupAnalysisBankrollFromUi() {
  const el = document.getElementById("analysis-bankroll");
  const v = num(el instanceof HTMLInputElement ? el.value : NaN, NaN);
  return Number.isFinite(v) && v >= 1 ? v : loadOuProjKellyPrefs().bankroll;
}

function matchupAnalysisKellyFractionFromUi() {
  const el = document.getElementById("analysis-kelly-fraction");
  const v = num(el instanceof HTMLSelectElement ? el.value : NaN, NaN);
  if (v === 0.25 || v === 0.5 || v === 1) return v;
  return loadOuProjKellyPrefs().fraction;
}

/** Selected sportsbook key on the Matchup Analysis "Book" filter; "" = all books. */
function matchupAnalysisBookFilterFromUi() {
  const el = document.getElementById("analysis-book-filter");
  const v = normalizeEvSportsbookKey(el instanceof HTMLSelectElement ? el.value : "");
  return v && v !== "all" ? v : "";
}

function matchupAnalysisFilteredBookCards() {
  const cards = matchupAnalysisBookCardsCache || [];
  const book = matchupAnalysisBookFilterFromUi();
  if (!book) return cards;
  return cards.filter((c) => normalizeEvSportsbookKey(c.book) === book);
}

/** Rebuild the Book filter options from the books present in the current card set (keeps selection). */
function syncMatchupAnalysisBookFilterOptions() {
  const el = document.getElementById("analysis-book-filter");
  if (!(el instanceof HTMLSelectElement)) return;
  const prev = normalizeEvSportsbookKey(el.value) || "all";
  const books = new Map();
  for (const c of matchupAnalysisBookCardsCache || []) {
    const k = normalizeEvSportsbookKey(c.book);
    if (k && !books.has(k)) books.set(k, c.bookLabel || bookMeta(k).label.toUpperCase());
  }
  el.innerHTML = "";
  const all = document.createElement("option");
  all.value = "all";
  all.textContent = "All books";
  el.appendChild(all);
  for (const [k, label] of [...books.entries()].sort((a, b) => a[1].localeCompare(b[1]))) {
    const opt = document.createElement("option");
    opt.value = k;
    opt.textContent = label;
    el.appendChild(opt);
  }
  el.value = books.has(prev) ? prev : "all";
}

function refreshMatchupAnalysisKellyDisplay() {
  const host = document.getElementById("matchup-analysis-pricing");
  if (!host || !matchupAnalysisBookCardsCache?.length) return;
  renderMatchupAnalysisBookCardsGrid(host, matchupAnalysisFilteredBookCards(), matchupAnalysisSelectedKey, (mk) => {
    selectMatchupAnalysisMatchup(mk, { scroll: false });
  });
}

function ouProjKellyFractionLabel(frac) {
  if (frac >= 0.99) return "Full Kelly";
  if (frac >= 0.49) return "½ Kelly";
  return "¼ Kelly";
}

/** Kelly stake in dollars from model win probability and American odds. */
function ouKellyStakeDollars(modelProb, americanOdds, bankroll, kellyFraction = 0.25) {
  const dec = decimalFromAmerican(americanOdds);
  if (!Number.isFinite(modelProb) || modelProb <= 0 || !Number.isFinite(dec) || dec <= 1) return NaN;
  if (!Number.isFinite(bankroll) || bankroll <= 0) return NaN;
  const b = dec - 1;
  if (b <= 0) return NaN;
  const fFull = (modelProb * dec - 1) / b;
  if (!Number.isFinite(fFull) || fFull <= 0) return 0;
  const mult = Number.isFinite(kellyFraction) && kellyFraction > 0 ? kellyFraction : 0.25;
  return fFull * mult * bankroll;
}

function formatOuKellyDollars(v) {
  if (!Number.isFinite(v) || v <= 0) return "";
  if (v >= 100) return `$${Math.round(v)}`;
  if (v >= 10) return `$${Math.round(v)}`;
  return `$${v.toFixed(2)}`;
}

function ouKellyStakeForProjectionSide(market, player, pick, side, bankroll, kellyFraction) {
  if (!pick) return NaN;
  const pImpOver = impliedProbFromAmerican(pick.over);
  const pImpUnder = impliedProbFromAmerican(pick.under);
  const { pOver, pUnder, edgeO, edgeU } = ouEdgeForCell(
    market,
    player,
    pick.line,
    pImpOver,
    pImpUnder,
    OU_PROJ_TABLE_MEAN_OPTS,
  );
  const edge = side === "over" ? edgeO : edgeU;
  if (!Number.isFinite(edge) || edge <= 0) return 0;
  const pModel = side === "over" ? pOver : pUnder;
  const am = side === "over" ? pick.over : pick.under;
  return ouKellyStakeDollars(pModel, am, bankroll, kellyFraction);
}

/** Round-proj books in column order (line / odds / edge / fair). */
const OU_PROJ_BOOK_SPECS = Object.freeze([
  { key: "draftkings", pick: "dkPick", edge: "dkEdge", roi: "dkRoi", kelly: "dkKelly", fair: "dkFairP", model: "dkModelP" },
  { key: "prizepicks", pick: "ppPick", edge: "ppEdge", roi: "ppRoi", kelly: "ppKelly", fair: "ppFairP", model: "ppModelP" },
  { key: "sleeper", pick: "slPick", edge: "slEdge", roi: "slRoi", kelly: "slKelly", fair: "slFairP", model: "slModelP" },
  { key: "underdog", pick: "udPick", edge: "udEdge", roi: "udRoi", kelly: "udKelly", fair: "udFairP", model: "udModelP" },
  { key: "fanduel", pick: "fdPick", edge: "fdEdge", roi: "fdRoi", kelly: "fdKelly", fair: "fdFairP", model: "fdModelP" },
  { key: "kalshi", pick: "klPick", edge: "klEdge", roi: "klRoi", kelly: "klKelly", fair: "klFairP", model: "klModelP" },
  { key: "caesars", pick: "czrPick", edge: "czrEdge", roi: "czrRoi", kelly: "czrKelly", fair: "czrFairP", model: "czrModelP" },
]);

function ouProjSideAmerican(pick, side) {
  if (!pick) return NaN;
  const am = side === "over" ? pick.over : pick.under;
  return Number.isFinite(am) ? am : NaN;
}

function ouProjNoVigSideProb(pick, side) {
  if (!pick) return NaN;
  const nv = propsNoVigOverProb(pick.over, pick.under);
  if (!Number.isFinite(nv)) return NaN;
  return side === "over" ? nv : clampProb01(1 - nv);
}

/** Pick best available book for this side: max expected ROI among +edge, else max Kelly $. */
function ouProjPickBestBook(entries) {
  const priced = (entries || []).filter((e) => e && Number.isFinite(e.dec) && e.dec > 1);
  if (!priced.length) return null;
  const withEdge = priced.filter((e) => num(e.edge, 0) > 0);
  const pool = withEdge.length ? withEdge : priced;
  let best = pool[0];
  for (let i = 1; i < pool.length; i++) {
    const e = pool[i];
    const broi = num(best.roi, -Infinity);
    const eroi = num(e.roi, -Infinity);
    if (eroi > broi + 1e-9) best = e;
    else if (Math.abs(eroi - broi) <= 1e-9 && num(e.kelly, 0) > num(best.kelly, 0)) best = e;
    else if (Math.abs(eroi - broi) <= 1e-9 && Math.abs(num(e.kelly, 0) - num(best.kelly, 0)) <= 1e-9 && e.dec > best.dec)
      best = e;
  }
  return best;
}

function ouEdgeForCell(market, p, L, pImpOver, pImpUnder, opts = {}) {
  const mKey = ouModelMarketKey(market) || market;
  const pOver = clampProb01(modelProbOverMarket(market, p, L, opts));
  if (!Number.isFinite(pOver)) return { pOver: NaN, pUnder: NaN, edgeO: NaN, edgeU: NaN };
  const pUnder = clampProb01(1 - pOver);
  let edgeO = Number.isFinite(pImpOver) ? pOver - pImpOver : NaN;
  let edgeU = Number.isFinite(pImpUnder) ? pUnder - pImpUnder : NaN;
  if (!ouUsesPropPricingModel(opts)) {
    const mu = ouProjectedMean(market, p, opts);
    if (eventPropBookAlignedMarket(mKey) && Number.isFinite(mu) && Number.isFinite(L)) {
      if (mu <= L) edgeO = Number.isFinite(edgeO) ? Math.min(0, edgeO) : edgeO;
      if (mu >= L) edgeU = Number.isFinite(edgeU) ? Math.min(0, edgeU) : edgeU;
    }
  }
  return { pOver, pUnder, edgeO, edgeU };
}

function ouCellEdgeStackHtml(market, p, L, pImpOver, pImpUnder, viewMode, oddsOverAm, oddsUnderAm) {
  const { pOver, pUnder, edgeO, edgeU } = ouEdgeForCell(
    market,
    p,
    L,
    pImpOver,
    pImpUnder,
    OU_PROJ_TABLE_MEAN_OPTS,
  );
  const lineStr = String(L);
  const oddsTxtOver = formatAmerican(oddsOverAm);
  const oddsTxtUnder = formatAmerican(oddsUnderAm);
  const clsO = edgeO > 0 ? "pos" : edgeO < 0 ? "neg" : "";
  const clsU = edgeU > 0 ? "pos" : edgeU < 0 ? "neg" : "";
  let modelLine = "";
  if (Number.isFinite(pOver)) {
    if (viewMode === "prob") {
      modelLine = `<div class="ou-model-line">O ${(pOver * 100).toFixed(1)}% · U ${(pUnder * 100).toFixed(1)}%</div>`;
    } else {
      const { do: dO, du: dU } = viggedDecimalsForOverUnder(pOver);
      modelLine = `<div class="ou-model-line">O ${formatAmerican(americanFromDecimal(dO))} · U ${formatAmerican(
        americanFromDecimal(dU)
      )}</div>`;
    }
  }
  return `<div class="ou-edge-stack">${modelLine}
    <div class="ou-edge-row ou-edge-row-over"><span class="ou-edge ${clsO}">${formatEdgePct(edgeO)}</span><span class="ou-edge-meta"><span class="ou-side-pill">O</span><span class="ou-line-pill">${lineStr}</span><span class="ou-edge-odds">${oddsTxtOver}</span></span></div>
    <div class="ou-edge-row ou-edge-row-under"><span class="ou-edge ${clsU}">${formatEdgePct(edgeU)}</span><span class="ou-edge-meta"><span class="ou-side-pill">U</span><span class="ou-line-pill">${lineStr}</span><span class="ou-edge-odds">${oddsTxtUnder}</span></span></div>
  </div>`;
}

/** Default: same order as projections (expected total ↑, or stat ↓ for props-style markets). */
let ouTableSort = { key: "pr-best-roi", dir: -1 };
let ouTableSortInited = false;
/** Last snapped O/U line; used while the line input is empty or mid-edit (avoid rewriting on every keystroke). */
let ouLineCommitted = 70.5;
/** Expanded round-projection row key (`rawName\\x1e${col.label}\\x1e${side}`); empty = none. */
let ouProjExpandedKey = "";
/** Set while building the open detail drawer so the chart can redraw after layout. */
let ouProjExpandedDetail = null;

function ouTableSortValue(playerRow, market, lineSel, pImpOverSel, pImpUnderSel, sortKey, propIdx) {
  if (sortKey === "golfer") return displayGolferName(playerRow.player_name || "").toLowerCase();
  if (sortKey && sortKey.startsWith("line-")) {
    const L = parseFloat(sortKey.slice(5));
    const pImpOver = ouBookImpliedForSortColumn(playerRow, market, L, lineSel, pImpOverSel, pImpUnderSel, propIdx, "over");
    const pImpUnder = ouBookImpliedForSortColumn(playerRow, market, L, lineSel, pImpOverSel, pImpUnderSel, propIdx, "under");
    const { edgeO } = ouEdgeForCell(market, playerRow, L, pImpOver, pImpUnder, OU_PROJ_TABLE_MEAN_OPTS);
    return Number.isFinite(edgeO) ? edgeO : -Infinity;
  }
  return 0;
}

function updateOuSortIndicators() {
  const table = document.getElementById("table-ou");
  if (!table) return;
  table.querySelectorAll("thead th.sortable").forEach((th) => {
    const key = th.dataset.sortKey;
    const up = th.querySelector(".sort-up");
    const dn = th.querySelector(".sort-down");
    if (up) up.classList.toggle("active", key === ouTableSort.key && ouTableSort.dir > 0);
    if (dn) dn.classList.toggle("active", key === ouTableSort.key && ouTableSort.dir < 0);
  });
}

function syncOuProjMarketFilterOptions(cols) {
  const pmf = document.getElementById("ou-proj-market-filter");
  if (!pmf) return;
  const prevProjMarket = String(pmf.value || "");
  const wantVals = ["", ...cols.map((c) => c.label)];
  const haveVals = [...pmf.options].map((o) => String(o.value || ""));
  if (wantVals.join("\x1e") !== haveVals.join("\x1e")) {
    pmf.innerHTML = "";
    const allM = document.createElement("option");
    allM.value = "";
    allM.textContent = "All markets";
    pmf.appendChild(allM);
    for (const col of cols) {
      const opt = document.createElement("option");
      opt.value = col.label;
      opt.textContent = col.label;
      pmf.appendChild(opt);
    }
  }
  const labels = new Set(cols.map((c) => c.label));
  if (prevProjMarket && labels.has(prevProjMarket)) pmf.value = prevProjMarket;
  else if (!labels.has(String(pmf.value || ""))) pmf.value = "";
}

function ouProjMakeBookColumnTh(sortKey, label, thClass, bookKey, sortIndHtml) {
  const th = document.createElement("th");
  th.className = `sortable ou-proj-long-th num ${thClass}`;
  th.dataset.sortKey = sortKey;
  const meta = bookMeta(bookKey);
  th.title = `${meta.label} ${label}`;
  const headWrap = document.createElement("span");
  headWrap.className = "ou-proj-th-book-head";
  const logoWrap = document.createElement("span");
  logoWrap.className = "ou-proj-th-book-logo-wrap";
  const img = document.createElement("img");
  img.className = "ou-proj-th-book-logo-img";
  img.alt = meta.label;
  img.loading = "lazy";
  const fb = document.createElement("span");
  fb.className = "ou-proj-th-book-logo-fallback";
  fb.textContent = meta.short;
  fb.style.display = "none";
  logoWrap.appendChild(img);
  logoWrap.appendChild(fb);
  attachBookLogoWithFallback(img, fb, meta.domain);
  const lbl = document.createElement("span");
  lbl.className = "ou-proj-th-book-text";
  lbl.textContent = label;
  headWrap.appendChild(logoWrap);
  headWrap.appendChild(lbl);
  th.appendChild(headWrap);
  th.insertAdjacentHTML("beforeend", sortIndHtml);
  return th;
}

function initOuTableHorizontalScroll() {
  const shell = document.getElementById("ou-table-scroll-shell");
  const scroller = document.getElementById("ou-table-scroll");
  const btnL = document.getElementById("ou-table-scroll-left");
  const btnR = document.getElementById("ou-table-scroll-right");
  if (!shell || !scroller || scroller.dataset.ouHScrollBound === "1") return;
  scroller.dataset.ouHScrollBound = "1";

  const sync = () => {
    const max = Math.max(0, scroller.scrollWidth - scroller.clientWidth);
    const x = scroller.scrollLeft;
    const canL = x > 2;
    const canR = x < max - 2;
    shell.classList.toggle("can-scroll-left", canL);
    shell.classList.toggle("can-scroll-right", canR);
    if (btnL) btnL.hidden = !canL;
    if (btnR) btnR.hidden = !canR;
  };

  const step = () => Math.max(220, Math.round(scroller.clientWidth * 0.55));
  btnL?.addEventListener("click", () => {
    scroller.scrollBy({ left: -step(), behavior: "smooth" });
  });
  btnR?.addEventListener("click", () => {
    scroller.scrollBy({ left: step(), behavior: "smooth" });
  });
  scroller.addEventListener("scroll", sync, { passive: true });
  scroller.addEventListener(
    "wheel",
    (ev) => {
      // Convert vertical wheel to horizontal when the table overflows (easier to pan books).
      if (scroller.scrollWidth <= scroller.clientWidth + 2) return;
      if (Math.abs(ev.deltaY) <= Math.abs(ev.deltaX)) return;
      ev.preventDefault();
      scroller.scrollLeft += ev.deltaY;
    },
    { passive: false },
  );
  window.addEventListener("resize", sync, { passive: true });
  // After chrome/rows paint
  requestAnimationFrame(() => {
    sync();
    setTimeout(sync, 50);
    setTimeout(sync, 300);
  });
  scroller._ouSyncHScroll = sync;
}

function syncOuTableHorizontalScroll() {
  const scroller = document.getElementById("ou-table-scroll");
  if (typeof scroller?._ouSyncHScroll === "function") scroller._ouSyncHScroll();
  else initOuTableHorizontalScroll();
}

