function courseBreakdownSgImpactSegments(rows) {
  const defs = [
    { key: "sg_ott", label: "Off the Tee" },
    { key: "sg_app", label: "Approach" },
    { key: "sg_arg", label: "Around the Green" },
    { key: "sg_putt", label: "Putting" },
  ];
  const spreads = defs.map((d) => courseBreakdownStdDev(rows.map((r) => num(r[d.key], NaN))));
  const total = spreads.reduce((s, v) => s + (Number.isFinite(v) ? v : 0), 0);
  return defs
    .map((d, i) => ({
      label: d.label,
      pct: total > 0 && Number.isFinite(spreads[i]) ? (spreads[i] / total) * 100 : 0,
    }))
    .sort((a, b) => b.pct - a.pct);
}

async function courseBreakdownApproachImpactSegments(rows) {
  const bins = [
    { key: "50_100_fw_shot_count", label: "50-100 yards" },
    { key: "100_150_fw_shot_count", label: "100-150 yards" },
    { key: "150_200_fw_shot_count", label: "150-200 yards" },
    { key: "over_200_fw_shot_count", label: "200+ yards" },
    { key: "under_150_rgh_shot_count", label: "Rough < 150 yards" },
    { key: "over_150_rgh_shot_count", label: "Rough 150+ yards" },
  ];
  let asJson = null;
  try {
    asJson = await loadApproachSkillYtdJson();
  } catch {
    asJson = null;
  }
  const fieldIds = new Set(rows.map((r) => Math.round(num(r.dg_id, NaN))).filter(Number.isFinite));
  const totals = bins.map(() => 0);
  let matched = 0;
  if (asJson?.players?.length) {
    for (const p of asJson.players) {
      const id = Math.round(num(p?.dg_id, NaN));
      if (!fieldIds.has(id)) continue;
      matched++;
      bins.forEach((b, i) => {
        totals[i] += Math.max(0, num(p[b.key], 0));
      });
    }
  }
  const grand = totals.reduce((s, v) => s + v, 0);
  if (!matched || grand <= 0) return [];
  return bins
    .map((b, i) => ({ label: b.label, pct: (totals[i] / grand) * 100 }))
    .sort((a, b) => b.pct - a.pct);
}

function courseBreakdownMetricSnapshots() {
  const benchmarks = courseBreakdownBenchmarksRoot()?.pga_tour_course_benchmarks || {};
  return COURSE_BOXPLOT_METRICS.map((metric) => {
    const bench = benchmarks[metric.benchKey];
    const distRaw = bench?.distribution;
    const courseRaw = courseBreakdownVenueRaw(metric.venueKey);
    const courseDisplay = courseBreakdownToDisplay(metric.fmt, courseRaw);
    const tourDisplay = courseBreakdownToDisplay(
      metric.fmt,
      num(distRaw?.mean ?? bench?.mean, NaN),
    );
    return {
      ...metric,
      courseRaw,
      courseDisplay,
      tourDisplay,
      distRaw,
      nCourses: Math.round(num(distRaw?.n_courses, 0)) || 0,
      difficulty: courseBreakdownDifficulty(metric.benchKey, courseRaw, distRaw),
    };
  });
}

let courseEventContextCache = null;
let courseEventContextPromise = null;

async function ensureCourseEventContextLoaded() {
  if (courseEventContextCache) return courseEventContextCache;
  if (!courseEventContextPromise) {
    courseEventContextPromise = (async () => {
      try {
        const res = await fetch(cacheBustFetchUrl("data/course_event_context.json"), { cache: "no-store" });
        if (!res.ok) return {};
        const json = await res.json();
        courseEventContextCache = json?.by_course && typeof json.by_course === "object" ? json.by_course : {};
        return courseEventContextCache;
      } catch {
        courseEventContextCache = {};
        return {};
      }
    })();
  }
  return courseEventContextPromise;
}

function courseBreakdownResolveEventContext(allCtx, courseName, eventName) {
  const inline = DATA?.meta?.course_event_context || DATA?.course_event_context;
  if (inline && typeof inline === "object" && Object.keys(inline).length) return inline;
  if (!allCtx || typeof allCtx !== "object") return null;
  const vk = normCourseNameKey(courseName);
  const ek = normCourseNameKey(eventName);
  if (vk && allCtx[vk]) return allCtx[vk];
  if (ek && allCtx[ek]) return allCtx[ek];
  for (const [k, v] of Object.entries(allCtx)) {
    if (!vk) continue;
    if (vk === k || vk.includes(k) || k.includes(vk)) return v;
  }
  return null;
}

function courseBreakdownMetricTourRankPhrase(benchKey, courseRaw, distRaw) {
  if (!Number.isFinite(courseRaw) || !distRaw) return "";
  const n = Math.round(num(distRaw.n_courses, 0));
  const q1 = num(distRaw.q1, NaN);
  const q3 = num(distRaw.q3, NaN);
  const med = num(distRaw.median, NaN);
  if (!Number.isFinite(q1) || !Number.isFinite(q3)) return "";
  const harderWhenLow = ["Fairways hit", "GIR", "Scrambling", "Birdies"].includes(benchKey);
  const suffix = n > 0 ? ` among ${n} tour venues` : "";
  if (harderWhenLow) {
    if (courseRaw < q1) return `bottom quartile${suffix}`;
    if (courseRaw > q3) return `top quartile${suffix}`;
    if (Number.isFinite(med)) {
      return courseRaw >= med ? `above median${suffix}` : `below median${suffix}`;
    }
    return `middle of the pack${suffix}`;
  }
  if (courseRaw > q3) return `top quartile (highest)${suffix}`;
  if (courseRaw < q1) return `bottom quartile (lowest)${suffix}`;
  if (Number.isFinite(med)) {
    return courseRaw >= med ? `above median${suffix}` : `below median${suffix}`;
  }
  return `middle of the pack${suffix}`;
}

/** Skill takeaway per venue metric — only metrics that meaningfully skew get a line. */
const COURSE_BREAKDOWN_METRIC_SKILL_NOTES = Object.freeze({
  "Fairways hit": {
    harder: "tight corridors make driving accuracy a genuine separator; wild drivers give back their length",
    easier: "landing zones are generous, muting the driving-accuracy edge",
  },
  GIR: {
    harder: "greens are hard to hold — elite approach play and a reliable short game carry rounds",
    easier: "greens are receptive; good iron proximity converts straight into birdie looks",
  },
  Scrambling: {
    harder: "up-and-downs are scarce, so a missed green usually costs a full shot",
    easier: "misses are savable; short-game specialists claw back strokes",
  },
  Birdies: {
    harder: "birdies are scarce — bogey avoidance and par grinding beat raw firepower",
    easier: "birdies flow freely, rewarding aggressive iron play and hot putters",
  },
  Bogeys: {
    harder: "bogeys cluster here — ball-striking consistency and avoiding the big miss rank above upside",
    easier: "clean cards are common; damage control matters less than usual",
  },
  "Scoring vs Par": {
    harder: "the venue plays over its card — total-score overs get a structural tailwind",
    easier: "the venue yields low scores — total-score unders get a structural tailwind",
  },
});

function courseBreakdownMetricGranularLine(m) {
  if (!Number.isFinite(m.courseDisplay)) return "";
  const note = COURSE_BREAKDOWN_METRIC_SKILL_NOTES[m.benchKey]?.[m.difficulty];
  if (!note) return "";
  const title = m.title.replace(/ per Round|\s\(%\)/g, "");
  const courseFmt = courseBreakdownFormatDisplay(m.fmt, m.courseDisplay);
  const tourFmt = courseBreakdownFormatDisplay(m.fmt, m.tourDisplay);
  return `${title} ${courseFmt} vs ${tourFmt} tour: ${note}.`;
}

function courseBreakdownBasisInsightBullets(basis, metrics) {
  const bullets = [];
  const nHist = Math.round(num(basis.venue_historical_rounds ?? basis.venue_rounds, 0));
  if (nHist > 0) {
    const stp = num(basis.venue_avg_score_to_par, NaN);
    const bird = num(basis.historical_venue_avg_birdies ?? basis.venue_avg_birdies, NaN);
    const bog = num(basis.historical_venue_avg_bogeys ?? basis.venue_avg_bogeys, NaN);
    const bits = [`${nHist.toLocaleString()} archived rounds at this venue`];
    if (Number.isFinite(stp)) bits.push(`avg ${stp >= 0 ? "+" : ""}${stp.toFixed(2)} vs par`);
    if (Number.isFinite(bird)) bits.push(`${bird.toFixed(2)} birdies`);
    if (Number.isFinite(bog)) bits.push(`${bog.toFixed(2)} bogeys`);
    bullets.push(`${bits.join(" — ")}.`);
  }
  const fieldBird = num(basis.field_counting_means_by_round?.birdies?.["1"], NaN);
  const venueBird = num(basis.venue_avg_birdies, NaN);
  if (Number.isFinite(fieldBird) && Number.isFinite(venueBird) && Math.abs(fieldBird - venueBird) >= 0.12) {
    bullets.push(
      fieldBird > venueBird
        ? `This week's field projects ${fieldBird.toFixed(2)} birdies/round vs ${venueBird.toFixed(2)} venue history — expect more scoring than the course's past suggests.`
        : `This week's field projects ${fieldBird.toFixed(2)} birdies/round vs ${venueBird.toFixed(2)} venue history — a tighter birdie environment; lean cautious on birdie overs.`,
    );
  }
  // The Scoring-vs-Par skill note already covers strong scoring skews; only add the bias
  // line when the metric sits in the "average" band but still leans one way.
  const stpM = metrics.find((x) => x.venueKey === "stp");
  if (stpM && Number.isFinite(stpM.courseDisplay) && stpM.difficulty === "average") {
    const v = stpM.courseDisplay;
    if (v > 0.2) {
      bullets.push(`Venue historically plays +${v.toFixed(2)} vs par — a mild tailwind for total-score overs.`);
    } else if (v < -0.2) {
      bullets.push(`Venue historically plays ${v.toFixed(2)} vs par — a mild tailwind for total-score unders.`);
    }
  }
  return bullets;
}

function courseBreakdownModelCoeffBullets(courseRow, tourMeans) {
  if (!courseRow) return [];
  const bullets = [];
  const means = tourMeans || {};
  const amplified = [];
  const discounted = [];
  const coeff = (label, key) => {
    const v = num(courseRow[key], NaN);
    const m = num(means[key], NaN);
    if (!Number.isFinite(v) || !Number.isFinite(m)) return;
    const gap = v - m;
    if (Math.abs(gap) < 0.018) return;
    (gap > 0 ? amplified : discounted).push(label);
  };
  coeff("off-the-tee", "ott_sg");
  coeff("approach", "app_sg");
  coeff("around-the-green", "arg_sg");
  coeff("putting", "putt_sg");
  if (amplified.length) {
    bullets.push(
      `The course model amplifies ${amplified.join(" and ")} skill — edges there convert into more strokes than at a typical tour stop.`,
    );
  }
  if (discounted.length) {
    bullets.push(
      `Raw ${discounted.join(", ")} skill converts below tour norm here — course management and links adaptability close the gap on paper-superior ball-strikers.`,
    );
  }
  const fwW = num(courseRow.fw_width, NaN);
  const fwM = num(means.fw_width, NaN);
  if (Number.isFinite(fwW) && Number.isFinite(fwM) && Math.abs(fwW - fwM) >= 1.5) {
    bullets.push(
      fwW < fwM
        ? `Fairways average ${fwW.toFixed(0)} yds wide (tour ${fwM.toFixed(0)}) — accuracy off the tee is a real separator, and many players will club down.`
        : `Fairways average ${fwW.toFixed(0)} yds wide (tour ${fwM.toFixed(0)}) — bombers can swing freely without paying for misses.`,
    );
  }
  const rgh = num(courseRow.rgh_diff, NaN);
  const rghM = num(means.rgh_diff, NaN);
  if (Number.isFinite(rgh) && Number.isFinite(rghM) && Math.abs(rgh - rghM) >= 0.04) {
    bullets.push(
      rgh > rghM
        ? "Rough penalty runs above tour norm — missed fairways bleed strokes, favoring straight drivers over long ones."
        : "Rough is lighter than tour norm — wayward drives are recoverable, so length keeps its value even without precision.",
    );
  }
  return bullets;
}

function courseBreakdownPlayerFitCategory(row, courseRow) {
  const pool = courseFitPlayerPool();
  const tour5 = courseFitTourCourseMean5();
  const venue5 = courseFitVenue5Profile(courseRow);
  const player5 = courseFitPlayerRadarVectorMerged(pool, row);
  const axisIdxs = courseFitVenueEmphasisAxisIndices(tour5, venue5);
  return courseFitPlayerCatAndFitOnAxes(tour5, venue5, player5, axisIdxs);
}

function courseBreakdownApproachLeadersSection(approachImpact, binLeaders) {
  if (!binLeaders?.length) return null;
  const volumeOrder = new Map(
    (approachImpact || []).map((x, i) => [String(x.label || "").trim().toLowerCase(), num(x.pct, 0) || 100 - i]),
  );
  const sorted = [...binLeaders].sort((a, b) => {
    const pa = volumeOrder.get(String(a.label || "").toLowerCase()) ?? 0;
    const pb = volumeOrder.get(String(b.label || "").toLowerCase()) ?? 0;
    return pb - pa;
  });
  const bullets = [];
  for (const bin of sorted.slice(0, 6)) {
    if (!bin.leaders?.length) continue;
    const names = bin.leaders
      .map((p) => `${p.name} (${p.sg >= 0 ? "+" : ""}${p.sg.toFixed(3)}/shot, n=${p.n})`)
      .join("; ");
    const vol = (approachImpact || []).find((x) => String(x.label || "").trim().toLowerCase() === String(bin.label || "").split(" (")[0].toLowerCase());
    const volNote = Number.isFinite(vol?.pct) ? ` — ${vol.pct.toFixed(0)}% of approaches here` : "";
    bullets.push(`<strong>${bin.label}${volNote}</strong>: ${names}`);
  }
  if (!bullets.length) return null;
  return {
    title: "Approach distance leaders (YTD)",
    paragraphs: [
      "Top players in this field by strokes gained per shot in each approach window. These bins feed Course Fit ratings using this course's approach mix.",
    ],
    bullets,
  };
}

/**
 * Skills that historically / model-wise correlate with scoring at this venue, plus who in the
 * field ranks best on each. Uses course-table coeffs, approach mix, and venue counting skews.
 */
function courseBreakdownSuccessSkillsSection(ctx) {
  const { courseRow, tourMeans, fieldRows, approachImpact, binLeaders, driving, metrics, asMap } = ctx;
  if (!fieldRows?.length) return null;
  const skills = [];

  const addSgSkill = (label, why, getter, higherBetter = true) => {
    const scored = [];
    for (const r of fieldRows) {
      const v = getter(r);
      if (!Number.isFinite(v)) continue;
      scored.push({ name: displayGolferName(r.player_name || ""), v, dg_id: Math.round(num(r.dg_id, NaN)) });
    }
    if (scored.length < 5) return;
    scored.sort((a, b) => (higherBetter ? b.v - a.v : a.v - b.v));
    const top = scored.slice(0, 3);
    const fmt = (x) =>
      Math.abs(x.v) >= 1 ? x.v.toFixed(2) : `${x.v >= 0 ? "+" : ""}${x.v.toFixed(3)}`;
    skills.push({
      label,
      why,
      leaders: top.map((x) => `${x.name} (${fmt(x)})`).join("; "),
    });
  };

  if (courseRow) {
    const ottGap = num(courseRow.ott_sg, 0) - num(tourMeans?.ott_sg, 0);
    const appGap = num(courseRow.app_sg, 0) - num(tourMeans?.app_sg, 0);
    const argGap = num(courseRow.arg_sg, 0) - num(tourMeans?.arg_sg, 0);
    const puttGap = num(courseRow.putt_sg, 0) - num(tourMeans?.putt_sg, 0);
    const fwW = num(courseRow.fw_width, NaN);
    const fwM = num(tourMeans?.fw_width, NaN);

    if (ottGap >= 0.01 || (driving && driving.bomber >= 6)) {
      addSgSkill(
        "SG: Off the Tee",
        "Course model and driver-hole profile reward tee-ball quality/length here",
        (r) => num(r.sg_ott, NaN),
      );
    }
    if (Number.isFinite(fwW) && Number.isFinite(fwM) && fwW < fwM - 1.5) {
      addSgSkill(
        "Driving accuracy",
        `Fairways average ${fwW.toFixed(0)} yds (tour ${fwM.toFixed(0)}) — accuracy separates the field`,
        (r) => playerDrivingAccuracyFrac(r),
      );
    }
    if (appGap >= 0.01 || (approachImpact || []).some((x) => num(x.pct, 0) >= 20)) {
      addSgSkill(
        "SG: Approach",
        "Iron play is a primary strokes-gained separator on this setup",
        (r) => num(r.sg_app, NaN),
      );
    }
    if (argGap >= 0.015) {
      addSgSkill(
        "SG: Around the Green",
        "Short-game coefficient is elevated vs tour mean at this venue",
        (r) => num(r.sg_arg, NaN),
      );
    }
    if (puttGap >= 0.015) {
      addSgSkill(
        "SG: Putting",
        "Putting coefficient is elevated — lag and make % show up on the card",
        (r) => num(r.sg_putt, NaN),
      );
    }
    if (driving && driving.shortPen < -0.5) {
      addSgSkill(
        "Driving distance",
        `Short drives cost ~${Math.abs(driving.shortPen).toFixed(2)} SG/round across ${driving.driverHoles} driver holes`,
        (r) => playerDrivingDistanceYds(r),
      );
    }
  }

  // Highest-volume approach bins from Course Breakdown — leaders already computed.
  for (const bin of binLeaders || []) {
    const vol = (approachImpact || []).find(
      (x) => String(x.label || "").trim().toLowerCase() === String(bin.label || "").split(" (")[0].toLowerCase(),
    );
    if (!vol || num(vol.pct, 0) < 12) continue;
    if (!bin.leaders?.length) continue;
    skills.push({
      label: `Approach SG: ${bin.short}`,
      why: `${num(vol.pct, 0).toFixed(0)}% of approaches at this course come from this window (DataGolf YTD SG/shot)`,
      leaders: bin.leaders
        .map((p) => `${p.name} (${p.sg >= 0 ? "+" : ""}${p.sg.toFixed(3)}/shot)`)
        .join("; "),
    });
  }

  const bog = metrics?.find((m) => m.benchKey === "Bogeys");
  if (bog?.difficulty === "harder") {
    addSgSkill(
      "SG: Total (bogey avoidance proxy)",
      "Bogey rate runs high here — overall ball-striking stability matters more than pure upside",
      (r) => num(r.sg_total, NaN),
    );
  }

  if (!skills.length && asMap?.size) {
    addSgSkill("SG: Approach", "Default iron-play separator when venue coeffs are thin", (r) => num(r.sg_app, NaN));
  }
  if (!skills.length) return null;

  return {
    title: "Skills that correlate with success here",
    paragraphs: [
      "These are the traits the course model, approach mix, and venue scoring profile point to. Leaders are from this week's field (DataGolf skill ratings / approach-skill YTD).",
    ],
    bullets: skills.map((s) => `<strong>${s.label}</strong>: ${s.why}. Best in field — ${s.leaders}.`),
  };
}

function courseBreakdownKeySkillAxisIndices(courseRow, tour5, venue5) {
  const weights = courseRequirementSgWeights(courseRow || {});
  const sgToIdx = { sg_ott: 1, sg_app: 2, sg_arg: 3, sg_putt: 4 };
  const byCoeff = Object.entries(sgToIdx)
    .map(([sk, idx]) => ({ idx, w: num(weights[sk], 0) }))
    .filter((x) => x.w > 0.05)
    .sort((a, b) => b.w - a.w);
  const venueEmphasis = courseFitVenueEmphasisAxisIndices(tour5, venue5);
  const out = [];
  const seen = new Set();
  for (const { idx } of byCoeff.slice(0, 2)) {
    if (!seen.has(idx)) {
      out.push(idx);
      seen.add(idx);
    }
  }
  for (const i of venueEmphasis) {
    if (!seen.has(i) && out.length < 2) {
      out.push(i);
      seen.add(i);
    }
  }
  if (!out.length && byCoeff.length) out.push(byCoeff[0].idx);
  if (!out.length && venueEmphasis.length) out.push(venueEmphasis[0]);
  return out;
}

function courseBreakdownElitePlayerIds(pool, opts = {}) {
  const minCount = opts.minCount ?? 20;
  const maxCount = opts.maxCount ?? 35;
  const fraction = opts.fraction ?? 0.4;
  const ranked = [...pool]
    .map((r) => ({ id: Math.round(num(r.dg_id, NaN)), sg: num(r.sg_total, NaN) }))
    .filter((x) => Number.isFinite(x.id) && Number.isFinite(x.sg))
    .sort((a, b) => b.sg - a.sg);
  const cut = Math.min(maxCount, Math.max(minCount, Math.ceil(pool.length * fraction)));
  return { ids: new Set(ranked.slice(0, cut).map((x) => x.id)), cut, ranked };
}

function courseBreakdownEliteKeySkillScore(axisZ, keyIdxs, venue5, tour5) {
  let sum = 0;
  let wSum = 0;
  for (const i of keyIdxs) {
    const z = axisZ[i];
    if (!Number.isFinite(z)) continue;
    const stress = Math.abs(num(venue5?.[i], 0.5) - num(tour5?.[i], 0.5));
    const w = stress > 0.02 ? stress : 1;
    sum += z * w;
    wSum += w;
  }
  return wSum > 0 ? sum / wSum : NaN;
}

function courseBreakdownDominantSkillLabel(axisZ, keyIdxs, pickLowest = false) {
  if (!keyIdxs?.length) return "";
  let pickI = keyIdxs[0];
  let pickZ = pickLowest ? Infinity : -Infinity;
  for (const i of keyIdxs) {
    const z = axisZ[i];
    if (!Number.isFinite(z)) continue;
    if (pickLowest ? z < pickZ : z > pickZ) {
      pickZ = z;
      pickI = i;
    }
  }
  return COURSE_FIT_RADAR_SPOKE_LABELS[pickI] || "";
}

function courseBreakdownPlayerFitLists(courseRow, fieldRows = null, limit = 5) {
  if (!courseRow) return { fits: [], struggles: [], emphasis: [], eliteCut: 0 };
  const pool = fieldRows?.length ? fieldRows : courseFitPlayerPool();
  if (!pool.length) return { fits: [], struggles: [], emphasis: [], eliteCut: 0 };
  const tour5 = courseFitTourCourseMean5();
  const venue5 = courseFitVenue5Profile(courseRow);
  const keyIdxs = courseBreakdownKeySkillAxisIndices(courseRow, tour5, venue5);
  const emphasis = keyIdxs.map((i) => COURSE_FIT_RADAR_SPOKE_LABELS[i]).filter(Boolean);
  const { ids: eliteIds, cut: eliteCut } = courseBreakdownElitePlayerIds(pool);
  const archetypeRows = courseFitArchetypeTableRows(pool, tour5, venue5, courseRow);
  const scored = archetypeRows
    .filter((row) => eliteIds.has(Math.round(num(row.r?.dg_id, NaN))))
    .map((row) => {
      const skillZ = courseBreakdownEliteKeySkillScore(row.axisZ, keyIdxs, venue5, tour5);
      return {
        row: row.r,
        skillZ,
        sgTotal: num(row.r?.sg_total, NaN),
        name: displayGolferName(row.r?.player_name || ""),
        catBest: courseBreakdownDominantSkillLabel(row.axisZ, keyIdxs, false),
        catWorst: courseBreakdownDominantSkillLabel(row.axisZ, keyIdxs, true),
      };
    })
    .filter((x) => x.name && Number.isFinite(x.skillZ));
  scored.sort((a, b) => b.skillZ - a.skillZ || b.sgTotal - a.sgTotal);
  const fits = scored.slice(0, limit).map((x) => ({
    ...x,
    fit: x.skillZ,
    cat: x.catBest,
  }));
  const fitNames = new Set(fits.map((x) => x.name));
  const strugglePool = [...scored].reverse().filter((x) => x.skillZ <= 0 && !fitNames.has(x.name));
  const strugglesSource =
    strugglePool.length >= Math.min(limit, 3) ? strugglePool : [...scored].reverse().filter((x) => !fitNames.has(x.name));
  const struggles = strugglesSource.slice(0, limit).map((x) => ({
    ...x,
    fit: x.skillZ,
    cat: x.catWorst,
  }));
  return { fits, struggles, emphasis, eliteCut };
}

function courseBreakdownExternalContextSection(externalCtx, eventName, courseRow) {
  if (!externalCtx) return null;
  const paragraphs = [];
  const bullets = [];
  if (externalCtx.style && !externalCtx.terrain) paragraphs.push(externalCtx.style);
  if (externalCtx.designer) {
    const loc = externalCtx.location ? ` in ${externalCtx.location}` : "";
    paragraphs.push(`${externalCtx.designer} design${loc}.`);
  }
  const yard = Math.round(num(externalCtx.yardage, NaN));
  const ctYard = Math.round(num(courseRow?.yardage, NaN));
  if (Number.isFinite(yard)) {
    const note = Number.isFinite(ctYard) && Math.abs(yard - ctYard) >= 80 ? ` (course-table model: ${ctYard.toLocaleString()} yds)` : "";
    bullets.push(`Tournament card: par ${externalCtx.par || 70}, ${yard.toLocaleString()} yards${note}.`);
  }
  for (const note of externalCtx.event_notes || []) {
    if (note) bullets.push(note);
  }
  for (const h of externalCtx.key_holes || []) {
    if (!h?.note) continue;
    const hole = Math.round(num(h.hole, NaN));
    const yards = Math.round(num(h.yards, NaN));
    const par = Math.round(num(h.par, NaN));
    const tag = Number.isFinite(hole) ? `Hole ${hole}` : "Key hole";
    const card = Number.isFinite(par) && Number.isFinite(yards) ? ` (par ${par}, ${yards} yds)` : "";
    bullets.push(`${tag}${card}: ${h.note}`);
  }
  if (externalCtx.weather_notes) bullets.push(externalCtx.weather_notes);
  if (!paragraphs.length && !bullets.length) return null;
  return {
    title: eventName ? `${eventName} setup notes` : "Course setup notes",
    paragraphs,
    bullets,
    sources: Array.isArray(externalCtx.sources) ? externalCtx.sources : [],
  };
}

function courseBreakdownTerrainAndTurfSection(externalCtx) {
  if (!externalCtx) return null;
  const terrain = externalCtx.terrain && typeof externalCtx.terrain === "object" ? externalCtx.terrain : null;
  const grass = externalCtx.grass && typeof externalCtx.grass === "object" ? externalCtx.grass : null;
  if (!terrain && !grass && !externalCtx.style) return null;
  const paragraphs = [];
  const bullets = [];
  if (terrain?.summary || externalCtx.style) paragraphs.push(String(terrain?.summary || externalCtx.style));
  const add = (label, value) => {
    if (value) bullets.push(`${label}: ${value}.`);
  };
  add("Topography", terrain?.topography);
  add("Exposure and wind", terrain?.exposure);
  add("Ground and drainage", terrain?.ground);
  add("Primary hazards", terrain?.hazards);
  const grassList = (value) =>
    Array.isArray(value) ? value.filter(Boolean).join(", ") : String(value || "").trim();
  add("Greens", grassList(grass?.greens));
  add("Fairways and tees", grassList(grass?.fairways));
  add("Rough", grassList(grass?.rough));
  add("Green surrounds", grassList(grass?.surrounds));
  add("Turf behavior", grass?.playing_characteristics);
  return {
    title: "Terrain and turf",
    paragraphs,
    bullets,
    sources: Array.isArray(externalCtx.sources) ? externalCtx.sources : [],
  };
}

function courseBreakdownCurrentEventDateBase() {
  const m = DATA?.meta || {};
  const raw = String(
    m.datagolf_field_date_start ??
      DATA?.datagolf_field_date_start ??
      m.event_start_date ??
      DATA?.event_start_date ??
      "",
  ).trim();
  const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return Number(`${iso[1]}${iso[2]}${iso[3]}`);
  return NaN;
}

function courseBreakdownPriorEventFromEntries(entries) {
  const currentDateBase = courseBreakdownCurrentEventDateBase();
  const currentYear = Number.isFinite(currentDateBase)
    ? Math.floor(currentDateBase / 10000)
    : new Date().getFullYear();
  const groups = new Map();
  for (const entry of entries || []) {
    const row = entry?.row;
    // Use the uncapped past-events predicate. The generic history predicate caps same-named
    // events to this week's live round (e.g. a current R2 Open must not hide 2017 R3/R4).
    if (!row || !courseFitDistRoundCountsAsActual(row)) continue;
    const year = historyRoundSeasonYear(row);
    if (!Number.isFinite(year) || year > currentYear) continue;
    const sortKey = Math.floor(num(row.sortKey, 0));
    const dateBase = sortKey >= 100000000 ? Math.floor(sortKey / 10) : 0;
    if (Number.isFinite(currentDateBase) && dateBase >= currentDateBase) continue;
    if (!Number.isFinite(currentDateBase) && year >= currentYear) continue;
    const eventId = String(row.event_id || "").trim();
    const eventName = formatEventNameForDisplay(String(row.event_name || "").trim()) || "Event";
    const key = `${year}|${eventId || normCourseNameKey(eventName)}`;
    let group = groups.get(key);
    if (!group) {
      group = { key, year, eventId, eventName, dateBase: 0, entries: [] };
      groups.set(key, group);
    }
    group.dateBase = Math.max(group.dateBase, dateBase);
    group.entries.push(entry);
  }
  const allEvents = [...groups.values()].sort((a, b) => b.dateBase - a.dateBase || b.year - a.year);
  if (!allEvents.length) return null;

  const meanFromRows = (rows, statKey) => {
    const values = rows.map((row) => actualForRoundRow(statKey, row)).filter(Number.isFinite);
    if (!values.length) return { value: NaN, n: 0 };
    return { value: values.reduce((sum, value) => sum + value, 0) / values.length, n: values.length };
  };

  const summarizeEvent = (ev) => {
    const seen = new Set();
    const rows = [];
    const playerIds = new Set();
    for (const entry of ev.entries) {
      const row = entry.row;
      const round = Math.round(num(row.round_num ?? row.round, NaN));
      const player = Math.round(num(entry.dg_id ?? row.dg_id, NaN));
      const dedupe = `${Number.isFinite(player) ? player : entry.player_name}|${round}|${row.sortKey || ""}`;
      if (seen.has(dedupe)) continue;
      seen.add(dedupe);
      rows.push(row);
      if (Number.isFinite(player)) playerIds.add(player);
    }
    return {
      year: ev.year,
      eventId: ev.eventId,
      eventName: ev.eventName,
      dateBase: ev.dateBase,
      rows: rows.length,
      players: playerIds.size,
      score: meanFromRows(rows, "total"),
      birdies: meanFromRows(rows, "birdies"),
      bogeys: meanFromRows(rows, "bogeys"),
      gir: meanFromRows(rows, "gir"),
      fairways: meanFromRows(rows, "fairways"),
      _rows: rows,
    };
  };

  const events = allEvents.map(summarizeEvent);
  const allRows = events.flatMap((e) => e._rows);
  const allPlayerIds = new Set();
  for (const entry of entries || []) {
    const row = entry?.row;
    if (!row || !courseFitDistRoundCountsAsActual(row)) continue;
    const year = historyRoundSeasonYear(row);
    if (!Number.isFinite(year) || year > currentYear) continue;
    const sortKey = Math.floor(num(row.sortKey, 0));
    const dateBase = sortKey >= 100000000 ? Math.floor(sortKey / 10) : 0;
    if (Number.isFinite(currentDateBase) && dateBase >= currentDateBase) continue;
    if (!Number.isFinite(currentDateBase) && year >= currentYear) continue;
    const player = Math.round(num(entry.dg_id ?? row.dg_id, NaN));
    if (Number.isFinite(player)) allPlayerIds.add(player);
  }
  const years = [...new Set(events.map((e) => e.year))].sort((a, b) => a - b);
  const latest = events[0];
  for (const e of events) delete e._rows;

  return {
    // Latest prior event (for "what changed since …" setup notes)
    year: latest.year,
    eventId: latest.eventId,
    eventName: latest.eventName,
    dateBase: latest.dateBase,
    rows: latest.rows,
    players: latest.players,
    score: latest.score,
    birdies: latest.birdies,
    bogeys: latest.bogeys,
    gir: latest.gir,
    fairways: latest.fairways,
    // All archived rounds at this venue (every prior Open / event year)
    allEvents: events,
    years,
    totalRows: allRows.length,
    totalPlayers: allPlayerIds.size,
    allScore: meanFromRows(allRows, "total"),
    allBirdies: meanFromRows(allRows, "birdies"),
    allBogeys: meanFromRows(allRows, "bogeys"),
    allGir: meanFromRows(allRows, "gir"),
    allFairways: meanFromRows(allRows, "fairways"),
  };
}

function courseBreakdownProjectedCountingMean(basis, statKey) {
  const values = Object.values(basis?.field_counting_means_by_round?.[statKey] || {})
    .map((value) => num(value, NaN))
    .filter(Number.isFinite);
  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : NaN;
}

function courseBreakdownPriorEventSection(priorEvent, externalCtx, basis, currentPar) {
  if (!priorEvent) return null;
  const previousSetup = externalCtx?.previous_event || {};
  const bullets = [];
  const years = Array.isArray(priorEvent.years) && priorEvent.years.length
    ? priorEvent.years
    : [priorEvent.year].filter(Number.isFinite);
  const yearLabel =
    years.length > 1 ? `${years[0]}–${years[years.length - 1]}` : String(years[0] || priorEvent.year);

  const nRounds = Math.round(num(priorEvent.totalRows ?? priorEvent.rows, 0));
  const nPlayers = Math.round(num(priorEvent.totalPlayers ?? priorEvent.players, 0));
  if (nRounds > 0) {
    const allScore = priorEvent.allScore?.value ?? priorEvent.score?.value;
    const allBird = priorEvent.allBirdies?.value ?? priorEvent.birdies?.value;
    const allBog = priorEvent.allBogeys?.value ?? priorEvent.bogeys?.value;
    const allGir = priorEvent.allGir?.value ?? priorEvent.gir?.value;
    const bits = [];
    if (Number.isFinite(allScore)) bits.push(`${allScore.toFixed(1)} scoring avg`);
    if (Number.isFinite(allBird)) bits.push(`${allBird.toFixed(2)} birdies`);
    if (Number.isFinite(allBog)) bits.push(`${allBog.toFixed(2)} bogeys`);
    if (Number.isFinite(allGir)) bits.push(`${allGir.toFixed(1)} GIR`);
    bullets.push(
      `All archived rounds here: ${nRounds} rounds across ${years.length} event${years.length === 1 ? "" : "s"} (${yearLabel}${nPlayers ? `; ${nPlayers} players` : ""})${bits.length ? ` — ${bits.join(", ")}` : ""}.`,
    );
  }

  if (Array.isArray(priorEvent.allEvents) && priorEvent.allEvents.length > 1) {
    for (const ev of priorEvent.allEvents) {
      const sc = Number.isFinite(ev.score?.value) ? ev.score.value.toFixed(1) : "—";
      const bird = Number.isFinite(ev.birdies?.value) ? ev.birdies.value.toFixed(2) : "—";
      const bog = Number.isFinite(ev.bogeys?.value) ? ev.bogeys.value.toFixed(2) : "—";
      bullets.push(
        `${ev.year} ${ev.eventName}: ${ev.rows} rounds, field avg ${sc} (birdies ${bird}, bogeys ${bog}).`,
      );
    }
  }

  const setupBits = [];
  const previousPar = Math.round(num(previousSetup.par, NaN));
  if (Number.isFinite(previousPar)) {
    setupBits.push(previousPar === currentPar ? `par ${currentPar} unchanged` : `par ${previousPar} → ${currentPar}`);
  }
  const currentYardage = Math.round(num(externalCtx?.yardage, NaN));
  const previousYardage = Math.round(num(previousSetup.yardage, NaN));
  if (Number.isFinite(currentYardage) && Number.isFinite(previousYardage)) {
    const delta = currentYardage - previousYardage;
    setupBits.push(`${currentYardage.toLocaleString()} yds (${delta >= 0 ? "+" : ""}${delta.toLocaleString()} vs ${previousSetup.year || priorEvent.year})`);
  }
  if (setupBits.length) bullets.push(`Setup vs last visit: ${setupBits.join("; ")}.`);

  for (const change of externalCtx?.changes_since_previous || []) {
    if (change) bullets.push(change);
  }

  // Compare this week to the full venue archive (all prior rounds), not only the latest Open.
  const histScore = num(priorEvent.allScore?.value ?? priorEvent.score?.value, NaN);
  const histBird = num(priorEvent.allBirdies?.value ?? priorEvent.birdies?.value, NaN);
  const histBog = num(priorEvent.allBogeys?.value ?? priorEvent.bogeys?.value, NaN);
  const currentScore = num(
    basis?.event_week_field_avg_score ?? basis?.venue_avg_round_score,
    NaN,
  );
  if (Number.isFinite(currentScore) && Number.isFinite(histScore)) {
    const delta = currentScore - histScore;
    if (Math.abs(delta) >= 0.75) {
      const projBird = courseBreakdownProjectedCountingMean(basis, "birdies");
      const projBog = courseBreakdownProjectedCountingMean(basis, "bogeys");
      const shifts = [];
      if (Number.isFinite(projBird) && Number.isFinite(histBird)) {
        shifts.push(projBird > histBird ? "more birdies" : "fewer birdies");
      }
      if (Number.isFinite(projBog) && Number.isFinite(histBog)) {
        shifts.push(projBog > histBog ? "more bogeys" : "fewer bogeys");
      }
      bullets.push(
        `The model expects a ${delta < 0 ? "softer" : "tougher"} test than this venue's archive (${currentScore.toFixed(1)} projected field average vs ${histScore.toFixed(1)} across ${yearLabel}${shifts.length ? `; ${shifts.join(", ")}` : ""}) — weight current form, weather, and tee wave over raw past results.`,
      );
    } else {
      bullets.push(
        `Projected scoring (${currentScore.toFixed(1)}) sits close to the venue archive (${histScore.toFixed(1)} across ${yearLabel}) — history here should transfer well.`,
      );
    }
  }
  return {
    title: years.length > 1 ? `History at this course (${yearLabel})` : `What changed since ${priorEvent.year}`,
    paragraphs: [
      years.length > 1
        ? `Archived tournaments at this venue: ${years.join(", ")}.`
        : `Last played: ${priorEvent.year} ${priorEvent.eventName}.`,
    ],
    bullets,
  };
}

function courseBreakdownInsightComparePhrase(label, courseVal, tourVal, fmt, higherBetter = true) {
  if (!Number.isFinite(courseVal) || !Number.isFinite(tourVal)) return "";
  const gap = courseVal - tourVal;
  if (Math.abs(gap) < (fmt === "pct" ? 0.8 : 0.08)) {
    return `${label} runs close to tour average`;
  }
  const dir = higherBetter ? (gap > 0 ? "above" : "below") : gap > 0 ? "above" : "below";
  const adj = higherBetter ? (gap > 0 ? "easier" : "tougher") : gap > 0 ? "tougher" : "easier";
  const unit = fmt === "pct" ? `${Math.abs(gap).toFixed(1)} pts` : Math.abs(gap).toFixed(2);
  return `${label} is ${unit} ${dir} tour average (${adj} scoring environment)`;
}

function courseBreakdownPropMarketIdeas(metrics, basis, courseRow, weatherCtx = null) {
  const ideas = [];
  const byKey = Object.fromEntries(metrics.map((m) => [m.benchKey, m]));
  const stp = num(basis.venue_avg_score_to_par, NaN);
  const stpM = byKey["Scoring vs Par"];
  if (Number.isFinite(stp)) {
    const tourStp = Number.isFinite(stpM?.tourDisplay) ? stpM.tourDisplay : 0;
    if (stp > 0.35) {
      ideas.push({
        market: "Total Score",
        angle: "Over",
        reason: `Venue averages +${stp.toFixed(2)} vs par (${tourStp >= 0 ? "+" : ""}${tourStp.toFixed(2)} tour mean). Missed greens and bogey clusters inflate round totals.`,
      });
    } else if (stp < -0.35) {
      ideas.push({
        market: "Total Score",
        angle: "Under",
        reason: `Historical scoring is ${stp.toFixed(2)} vs par. Pars stack up and blow-up holes are less common than tour average.`,
      });
    } else if (Number.isFinite(tourStp) && Math.abs(stp - tourStp) >= 0.12) {
      ideas.push({
        market: "Total Score",
        angle: stp > tourStp ? "Over lean" : "Under lean",
        reason: `Venue scoring (${stp >= 0 ? "+" : ""}${stp.toFixed(2)}) vs tour mean (${tourStp >= 0 ? "+" : ""}${tourStp.toFixed(2)}).`,
      });
    }
  }
  const pushCounting = (benchKey, market, easierSide, harderSide, easierWhy, harderWhy) => {
    const m = byKey[benchKey];
    if (!m) return;
    const gapNote =
      Number.isFinite(m.courseDisplay) && Number.isFinite(m.tourDisplay)
        ? ` (${courseBreakdownFormatDisplay(m.fmt, m.courseDisplay)} here vs ${courseBreakdownFormatDisplay(m.fmt, m.tourDisplay)} tour avg)`
        : "";
    if (m.difficulty === "easier") {
      ideas.push({ market, angle: easierSide, reason: easierWhy + gapNote });
    } else if (m.difficulty === "harder") {
      ideas.push({ market, angle: harderSide, reason: harderWhy + gapNote });
    }
  };
  pushCounting(
    "Birdies",
    "Birdies",
    "Over",
    "Under",
    "Birdie rate ranks above most PGA Tour venues. Aggressive iron play and makeable birdie looks show up often.",
    "Birdie opportunities are scarce here relative to tour courses.",
  );
  pushCounting(
    "Bogeys",
    "Bogeys",
    "Under",
    "Over",
    "Bogeys are harder to come by; clean ball-striking keeps mistakes in check.",
    "Bogey rate runs high. Trouble off the tee and around the greens creates stress pars.",
  );
  pushCounting(
    "GIR",
    "GIR",
    "Over",
    "Under",
    "Greens are more reachable in regulation than at a typical tour stop.",
    "Approach stress is elevated. GIR counts tend to compress.",
  );
  pushCounting(
    "Fairways hit",
    "Fairways Hit",
    "Over",
    "Under",
    "Driving corridors are generous and FIR counts trend high.",
    "Fairways are narrow or penal; missed tee shots are common.",
  );
  const scram = metrics.find((m) => m.benchKey === "Scrambling");
  if (scram?.difficulty === "harder") {
    ideas.push({
      market: "Pars",
      angle: "Under",
      reason: "Scrambling is below tour average. Missed greens turn into bogeys instead of saved pars.",
    });
  }
  if (courseRow && num(courseRow.rgh_diff, 0) > 0.08) {
    ideas.push({
      market: "Bogeys",
      angle: "Over (miss-fit players)",
      reason: "Rough penalty is above tour average. Players who miss fairways bleed strokes quickly.",
    });
  }
  if (courseRow && num(courseRow.putt_sg, 0) > 0.04) {
    ideas.push({
      market: "Birdies",
      angle: "Over (strong putters)",
      reason: "Putting profile is favorable. Lag putting and short putt conversion can unlock birdies without perfect ball-striking.",
    });
  }
  /*
   * Keep the first supported direction for each market. Later conditional signals (rough,
   * putting, weather) may reinforce it, but must never publish the opposite side beside it.
   */
  const seenExact = new Set();
  const directionByMarket = new Map();
  return [...ideas, ...courseBreakdownWeatherPropIdeas(weatherCtx)].filter((idea) => {
    const market = String(idea.market || "").trim().toLowerCase();
    const angle = String(idea.angle || "").trim();
    const exactKey = `${market}|${angle.toLowerCase()}`;
    if (seenExact.has(exactKey)) return false;

    const sideMatch = angle.match(/^(over|under)\b/i);
    const side = sideMatch ? sideMatch[1].toLowerCase() : "";
    const existingSide = directionByMarket.get(market);
    if (side && existingSide && existingSide !== side) return false;

    seenExact.add(exactKey);
    if (side && !existingSide) directionByMarket.set(market, side);
    return true;
  });
}

function courseBreakdownVenueHistoricalWeatherRows(courseName) {
  const vk = normCourseNameKey(courseName);
  const rows = [];
  const map = propsRoundWeatherByKey;
  if (!map?.size || !vk) return rows;
  for (const snap of map.values()) {
    const ck = normCourseNameKey(snap.course_name || "");
    if (ck === vk || courseNameMatchesVenueLoose(snap.course_name, courseName)) rows.push(snap);
  }
  return rows;
}

function courseBreakdownWeatherAggregate(rows) {
  if (!rows?.length) return null;
  const temps = [];
  const winds = [];
  const hums = [];
  /** @type {Record<string, number>} */
  const condCounts = {};
  for (const r of rows) {
    if (Number.isFinite(num(r.tempF, NaN))) temps.push(num(r.tempF, NaN));
    if (Number.isFinite(num(r.windMph, NaN))) winds.push(num(r.windMph, NaN));
    if (Number.isFinite(num(r.humidityPct, NaN))) hums.push(num(r.humidityPct, NaN));
    const c = weatherConditionDisplayLabel(r.condition);
    condCounts[c] = (condCounts[c] || 0) + 1;
  }
  const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : NaN);
  const topConditions = Object.entries(condCounts)
    .sort((a, b) => b[1] - a[1])
    .map(([condition, count]) => ({ condition, count, share: count / rows.length }));
  return {
    n: rows.length,
    avgTemp: mean(temps),
    avgWind: mean(winds),
    avgHumidity: mean(hums),
    topConditions,
  };
}

function courseBreakdownForecastWeatherSlots() {
  hydrateBakedWeatherFromPlayerFields();
  finalizeForecastWaveSummary(null);
  const slots = DATA?.meta?.forecast_wave_slots;
  const morning = slots && typeof slots === "object" ? slots.morning : null;
  const afternoon = slots && typeof slots === "object" ? slots.afternoon : null;
  const round = Math.round(num(DATA?.meta?.forecast_weather_display_round, NaN));
  return {
    morning: morning && Number.isFinite(num(morning.tempF, NaN)) ? morning : null,
    afternoon: afternoon && Number.isFinite(num(afternoon.tempF, NaN)) ? afternoon : null,
    round: Number.isFinite(round) && round >= 1 ? round : effectiveUiModelRoundFromMeta(),
    status: String(DATA?.meta?.forecast_weather_status || ""),
  };
}

function courseBreakdownWeatherComparePhrase(metric, forecastVal, histVal, unit, higherIsNotable = true) {
  if (!Number.isFinite(forecastVal) || !Number.isFinite(histVal)) return "";
  const gap = forecastVal - histVal;
  const thresh = metric === "temp" ? 4 : metric === "wind" ? 3 : 8;
  if (Math.abs(gap) < thresh) {
    return `${unit} is in line with past events here (${histVal.toFixed(1)} historical avg across archived rounds)`;
  }
  const dir = gap > 0 ? "warmer" : "cooler";
  const windDir = gap > 0 ? "windier" : "calmer";
  const humDir = gap > 0 ? "more humid" : "drier";
  if (metric === "temp") return `Temperature runs ${dir} than the ${histVal.toFixed(1)}°F historical average (+${gap.toFixed(1)}°F)`;
  if (metric === "wind") {
    return `Wind looks ${windDir} than typical (${forecastVal.toFixed(1)} mph vs ${histVal.toFixed(1)} mph historical avg)`;
  }
  return `Humidity is ${humDir} than the ${histVal.toFixed(0)}% historical average`;
}

function courseBreakdownVenueWeatherScoringSamples(courseName) {
  const vk = normCourseNameKey(courseName);
  const out = {
    all: [],
    windy: [],
    rain: [],
    calm: [],
  };
  if (!vk || !HISTORY?._ok || !propsRoundWeatherByKey?.size) return out;
  for (const rec of Object.values(HISTORY.byDgId || {})) {
    for (const r of rec.rounds || []) {
      if (!historyRoundCountsAsActual(r)) continue;
      const ck = normCourseNameKey(historyRoundCourseName(r));
      if (ck !== vk && !courseNameMatchesVenueLoose(r.course_name, courseName)) continue;
      const stp = num(r.score_to_par, NaN);
      if (!Number.isFinite(stp)) continue;
      out.all.push(stp);
      const w = propsRoundWeatherByKey.get(historyRoundWeatherLookupKey(r));
      const cond = weatherConditionDisplayLabel(w?.condition);
      const wind = num(w?.windMph, NaN);
      if (cond === "windy" || cond === "storm" || (Number.isFinite(wind) && wind >= 16)) out.windy.push(stp);
      if (cond === "rain") out.rain.push(stp);
      if (cond === "clear" || cond === "cloudy" || cond === "neutral") {
        if (!Number.isFinite(wind) || wind < 14) out.calm.push(stp);
      }
    }
  }
  return out;
}

function courseBreakdownWeatherScoringPhrase(label, samples) {
  if (!samples?.length) return "";
  const avg = samples.reduce((a, b) => a + b, 0) / samples.length;
  const sign = avg >= 0 ? "+" : "";
  return `When conditions were ${label} here historically, rounds averaged ${sign}${avg.toFixed(2)} vs par (${samples.length} archived round${samples.length === 1 ? "" : "s"})`;
}

function courseBreakdownWeatherPropIdeas(weatherCtx) {
  if (!weatherCtx?.hasData) return [];
  const ideas = [];
  const { morning, afternoon, hist, waveDelta } = weatherCtx;
  const snap = afternoon || morning;
  if (!snap) return ideas;
  const wind = num(snap.windMph, NaN);
  const cond = weatherConditionDisplayLabel(snap.condition);
  const diff = weatherDifficultyDeltaFromSnapshot(snap);
  if (Number.isFinite(wind) && wind >= 14) {
    ideas.push({
      market: "Total Score",
      angle: "Over",
      reason: `Forecast wind (${wind.toFixed(1)} mph) is above the venue's historical average. Approach and wedge control get harder.`,
    });
    ideas.push({
      market: "Fairways Hit",
      angle: "Under",
      reason: "Breezy conditions historically compress fairway percentages at this course.",
    });
  }
  if (cond === "rain" || (hist?.topConditions?.[0]?.condition === "rain" && cond === "windy")) {
    ideas.push({
      market: "Birdies",
      angle: "Over (if soft)",
      reason: "Wet rounds here have tended to play softer. Missed approaches can still yield birdie looks if greens hold shots.",
    });
  }
  if (Number.isFinite(diff) && diff > 0.12) {
    ideas.push({
      market: "Bogeys",
      angle: "Over",
      reason: "Model weather difficulty is elevated vs neutral. Stress pars and doubles show up more often.",
    });
  }
  if (Number.isFinite(waveDelta) && Math.abs(waveDelta) >= 0.08) {
    const fav = waveDelta > 0 ? "afternoon" : "morning";
    const disfav = waveDelta > 0 ? "morning" : "afternoon";
    ideas.push({
      market: "Total Score",
      angle: `${fav === "morning" ? "Morning" : "Afternoon"} wave Under`,
      reason: `Tee-wave weather gap: ${disfav} tees face tougher wind/temperature profile than ${fav}. Check wave splits in Round Projections.`,
    });
  }
  const hotAfternoon =
    afternoon &&
    morning &&
    Number.isFinite(num(afternoon.tempF, NaN)) &&
    Number.isFinite(num(morning.tempF, NaN)) &&
    num(afternoon.tempF, NaN) - num(morning.tempF, NaN) >= 6;
  if (hotAfternoon) {
    ideas.push({
      market: "Total Score",
      angle: "Afternoon Over / Morning Under",
      reason: `Afternoon tees are ~${(num(afternoon.tempF, NaN) - num(morning.tempF, NaN)).toFixed(0)}°F warmer. Fatigue and firmer conditions can inflate late scores.`,
    });
  }
  return ideas;
}

function courseBreakdownWeatherInsightSection(weatherCtx) {
  if (!weatherCtx?.hasData) {
    return {
      title: "Weather outlook",
      paragraphs: [
        "Forecast and archived weather are not loaded yet. Open Round Projections or refresh after push:live to pull Open-Meteo tee-time conditions.",
      ],
      bullets: [],
    };
  }
  const { morning, afternoon, hist, forecastRound, scoring, waveDelta } = weatherCtx;
  const paragraphs = [];
  const bullets = [];
  const rndLabel = Number.isFinite(forecastRound) ? `R${forecastRound}` : "this round";
  if (morning && afternoon) {
    paragraphs.push(
      `For ${rndLabel}, morning tees (${formatWeatherSnapshotCompact(morning)}) and afternoon tees (${formatWeatherSnapshotCompact(afternoon)}) diverge. Wave timing matters for round-score props.`,
    );
  } else if (morning || afternoon) {
    paragraphs.push(
      `${rndLabel} forecast at tee time: ${formatWeatherSnapshotCompact(morning || afternoon)}.`,
    );
  }
  if (hist?.n >= 4) {
    const top = hist.topConditions
      .slice(0, 2)
      .map((c) => `${c.condition} (${Math.round(c.share * 100)}% of ${hist.n} archived rounds)`)
      .join(", ");
    paragraphs.push(
      `Historically at this venue (${hist.n} archived PGA rounds): avg ${hist.avgTemp.toFixed(1)}°F, ${hist.avgWind.toFixed(1)} mph wind, ${hist.avgHumidity.toFixed(0)}% humidity. Most common conditions: ${top}.`,
    );
    const snap = afternoon || morning;
    if (snap) {
      const cmp = [
        courseBreakdownWeatherComparePhrase("temp", num(snap.tempF, NaN), hist.avgTemp, "temp"),
        courseBreakdownWeatherComparePhrase("wind", num(snap.windMph, NaN), hist.avgWind, "wind"),
      ].filter(Boolean);
      if (cmp.length) bullets.push(cmp.join("; ") + ".");
    }
  } else if (hist?.n > 0) {
    paragraphs.push(`Limited archived weather at this course (${hist.n} round${hist.n === 1 ? "" : "s"}). Treat historical comparisons as directional.`);
  }
  const windyPhrase = courseBreakdownWeatherScoringPhrase("windy", scoring.windy);
  const rainPhrase = courseBreakdownWeatherScoringPhrase("wet", scoring.rain);
  const calmPhrase = courseBreakdownWeatherScoringPhrase("calmer", scoring.calm);
  if (windyPhrase) bullets.push(windyPhrase + ".");
  if (rainPhrase) bullets.push(rainPhrase + ".");
  if (calmPhrase && !windyPhrase) bullets.push(calmPhrase + ".");
  const leadSnap = afternoon || morning;
  if (leadSnap) {
    const d = weatherDifficultyDeltaFromSnapshot(leadSnap);
    const cond = weatherConditionDisplayLabel(leadSnap.condition);
    if (d > 0.1) {
      bullets.push(
        `Expect a tougher scoring environment than neutral. Wind/heat pushes up total-score and bogey prop baselines${cond === "windy" ? " (wind is the main driver)" : ""}.`,
      );
    } else if (d < -0.08) {
      bullets.push("Soft or mild conditions vs model neutral. Birdie and GIR overs get a small tailwind if course setup stays accessible.");
    }
  }
  if (Number.isFinite(waveDelta) && Math.abs(waveDelta) >= 0.06 && morning && afternoon) {
    const easier = waveDelta > 0 ? "afternoon" : "morning";
    const tougher = waveDelta > 0 ? "morning" : "afternoon";
    bullets.push(
      `Tee-wave edge: ${easier} wave draws the easier weather profile. ${tougher} tees carry ~${Math.abs(waveDelta).toFixed(2)} strokes more weather difficulty in the model.`,
    );
  }
  if (!paragraphs.length && !bullets.length) {
    paragraphs.push("Forecast loaded but comparable historical weather at this venue is thin.");
  }
  return { title: "Weather outlook", paragraphs, bullets };
}

async function courseBreakdownGatherWeatherContext(courseName) {
  await ensurePropsRoundWeatherLoaded();
  hydrateBakedWeatherFromPlayerFields();
  finalizeForecastWaveSummary(null);
  const forecast = courseBreakdownForecastWeatherSlots();
  const histRows = courseBreakdownVenueHistoricalWeatherRows(courseName);
  const hist = courseBreakdownWeatherAggregate(histRows);
  const scoring = courseBreakdownVenueWeatherScoringSamples(courseName);
  const morning = forecast.morning;
  const afternoon = forecast.afternoon;
  let waveDelta = NaN;
  if (morning && afternoon) {
    waveDelta =
      weatherDifficultyDeltaFromSnapshot(afternoon) - weatherDifficultyDeltaFromSnapshot(morning);
  }
  const hasData = Boolean((morning || afternoon) && (hist?.n || scoring.all.length));
  return {
    hasData: Boolean(morning || afternoon || hist?.n),
    morning,
    afternoon,
    hist,
    scoring,
    forecastRound: forecast.round,
    waveDelta,
    hasForecast: Boolean(morning || afternoon),
    hasHistory: Boolean(hist?.n),
  };
}

function courseBreakdownGenerateInsightSections(ctx) {
  const {
    courseName,
    eventName,
    par,
    holePars,
    metrics,
    basis,
    courseRow,
    tourMeans,
    driving,
    approach,
    putting,
    sgImpact,
    approachImpact,
    playerFit,
    weatherCtx,
    externalCtx,
    priorEvent,
    approachBinLeaders,
    asMap,
  } = ctx;

  const p3 = holePars.filter((p) => Math.round(num(p, 4)) === 3).length;
  const p4 = holePars.filter((p) => Math.round(num(p, 4)) === 4).length;
  const p5 = holePars.filter((p) => Math.round(num(p, 4)) === 5).length;
  const fir = metrics.find((m) => m.venueKey === "fir");
  const gir = metrics.find((m) => m.venueKey === "gir");
  const bird = metrics.find((m) => m.venueKey === "birdies");
  const bog = metrics.find((m) => m.venueKey === "bogeys");
  const scram = metrics.find((m) => m.benchKey === "Scrambling");
  const stp = metrics.find((m) => m.venueKey === "stp");

  const profileIntro = [];
  if (holePars.length) {
    profileIntro.push(
      `${courseName} is a par ${par} test (${p3} par 3s, ${p4} par 4s, ${p5} par 5s)`,
    );
  } else {
    profileIntro.push(`${courseName} is a par ${par} venue`);
  }
  if (eventName) profileIntro.push(`hosting the ${eventName}`);

  const skewLines = metrics.map((m) => courseBreakdownMetricGranularLine(m)).filter(Boolean);
  const nearAverage = metrics
    .filter((m) => Number.isFinite(m.courseDisplay) && !COURSE_BREAKDOWN_METRIC_SKILL_NOTES[m.benchKey]?.[m.difficulty])
    .map((m) => m.title.replace(/ per Round|\s\(%\)/g, ""));
  const profileBullets = [...skewLines];
  if (nearAverage.length) {
    profileBullets.push(`${nearAverage.join(", ")}: near tour average — no venue skew worth pricing.`);
  }
  const profile = {
    title: "What this course is like",
    paragraphs: [profileIntro.join("; ") + "."],
    bullets: [...profileBullets, ...courseBreakdownBasisInsightBullets(basis, metrics)],
  };

  const setupSection = courseBreakdownExternalContextSection(externalCtx, eventName, courseRow);
  const terrainSection = courseBreakdownTerrainAndTurfSection(externalCtx);
  const priorEventSection = courseBreakdownPriorEventSection(priorEvent, externalCtx, basis, par);

  const successBullets = [];
  if (sgImpact[0]?.pct >= 15) {
    const second = sgImpact[1]?.pct >= 15 ? sgImpact[1] : null;
    successBullets.push(
      second
        ? `${sgImpact[0].label} and ${second.label} separate this field most (${sgImpact[0].pct.toFixed(0)}% and ${second.pct.toFixed(0)}% of SG spread). Target players elite in both; putting alone won't carry a bad ball-striking week.`
        : `${sgImpact[0].label} separates this field most (${sgImpact[0].pct.toFixed(0)}% of SG spread). Target players with a top-tier ${sgImpact[0].label.toLowerCase()} profile.`,
    );
  } else if (sgImpact.length) {
    successBullets.push("SG spread is balanced across categories — no single skill dominates; look for well-rounded profiles.");
  }
  const topZones = approachImpact.filter((a) => a.pct >= 15).slice(0, 2);
  if (topZones.length) {
    successBullets.push(
      `Most approaches come from ${topZones.map((a) => a.label.toLowerCase()).join(" and ")} (${topZones.map((a) => `${a.pct.toFixed(0)}%`).join(" / ")} of volume) — proximity from these windows is the iron-play skill that matters here.`,
    );
  }
  if (driving) {
    if (driving.bomber >= 7) {
      successBullets.push(
        `Length is an asset (bomber score ${driving.bomber}/10 across ${driving.driverHoles} driver holes) — long hitters can shorten the course faster than the rough punishes them.`,
      );
    } else if (driving.shortPen < -0.35) {
      successBullets.push(
        `Position beats power off the tee: short, out-of-position drives cost about ${Math.abs(driving.shortPen).toFixed(2)} SG per round here, so disciplined club selection is a scoring skill in itself.`,
      );
    }
  }
  successBullets.push(...courseBreakdownModelCoeffBullets(courseRow, tourMeans));
  if (!successBullets.length) {
    successBullets.push("Balanced ball-striking across tee-to-green play. No single skill completely dominates.");
  }

  const problemBullets = [];
  if (fir?.difficulty === "harder") {
    problemBullets.push(
      `Fairways are tight: ${courseBreakdownFormatDisplay("pct", fir.courseDisplay)} FIR vs ${courseBreakdownFormatDisplay("pct", fir.tourDisplay)} tour average${fir.nCourses ? ` (${courseBreakdownMetricTourRankPhrase(fir.benchKey, fir.courseRaw, fir.distRaw)})` : ""}.`,
    );
  }
  if (approach?.rghPen?.some((v) => v >= 0.18)) {
    const maxPen = Math.max(...approach.rghPen);
    const idx = approach.rghPen.indexOf(maxPen);
    const zone = approach?.bins?.[idx]?.label || "approach";
    problemBullets.push(
      `Rough penalty peaks at ${maxPen.toFixed(2)} strokes in the ${zone} window. Missing fairways is expensive.`,
    );
  }
  if (bog && bird && Number.isFinite(bog.courseDisplay) && Number.isFinite(bird.courseDisplay)) {
    const ratio = bog.courseDisplay - bird.courseDisplay;
    if (ratio >= 0.15 || bog.difficulty === "harder") {
      problemBullets.push(
        `Bogeys (${courseBreakdownFormatDisplay("num2", bog.courseDisplay)}/round) come nearly as often as birdies (${courseBreakdownFormatDisplay("num2", bird.courseDisplay)}) — one loose stretch erases an hour of good golf, so favor players who avoid doubles over pure upside.`,
      );
    }
  }
  if (gir?.difficulty === "harder") {
    problemBullets.push(
      `GIR ${courseBreakdownFormatDisplay("pct", gir.courseDisplay)} vs ${courseBreakdownFormatDisplay("pct", gir.tourDisplay)} tour average. Players who cannot hold greens face constant scrambles.`,
    );
  }
  if (scram?.difficulty === "harder") {
    problemBullets.push(
      `Scrambling ${courseBreakdownFormatDisplay("pct", scram.courseDisplay)} vs ${courseBreakdownFormatDisplay("pct", scram.tourDisplay)} tour average. Up-and-down saves are below tour norms.`,
    );
  }
  if (courseRow && num(courseRow.arg_sg, 0) > 0.04) {
    problemBullets.push(
      "Short-game demand is elevated — players with weak chipping or bunker play will leak strokes around these greens.",
    );
  }
  if (courseRow && num(courseRow.miss_fw_pen_frac, 0) > num(tourMeans?.miss_fw_pen_frac, 0) + 0.002) {
    problemBullets.push(
      "Missed fairways are punished more than usual here — crooked drivers face a compounding penalty.",
    );
  }
  if (!problemBullets.length) {
    problemBullets.push("Few extreme penalty spots. Mistakes are more about missed scoring chances than big-number blow-ups.");
  }

  const propIdeas = courseBreakdownPropMarketIdeas(metrics, basis, courseRow, weatherCtx);

  const fitParagraphs = [];
  if (playerFit.emphasis?.length && playerFit.eliteCut) {
    fitParagraphs.push(
      `Among the top ${playerFit.eliteCut} players by SG:Total, who rates best and worst on ${playerFit.emphasis.join(" and ")} — the skills this course rewards most.`,
    );
  } else if (playerFit.emphasis?.length) {
    fitParagraphs.push(
      `Field leaders on ${playerFit.emphasis.join(" and ")} — the skills this course rewards most vs tour average.`,
    );
  } else if (playerFit.fits.length) {
    fitParagraphs.push("Course-table fit blends each player's SG profile with this venue's skill demands.");
  } else {
    fitParagraphs.push("Player fit lists need course-table data. Run npm run build:course-table.");
  }

  const approachLeadersSection = courseBreakdownApproachLeadersSection(approachImpact, approachBinLeaders);
  const successSkillsSection = courseBreakdownSuccessSkillsSection({
    courseRow,
    tourMeans,
    fieldRows: courseBreakdownFieldRows(),
    approachImpact,
    binLeaders: approachBinLeaders,
    driving,
    metrics,
    asMap,
  });

  const sections = [
    profile,
    ...(priorEventSection ? [priorEventSection] : []),
    ...(terrainSection ? [terrainSection] : []),
    ...(setupSection ? [setupSection] : []),
    courseBreakdownWeatherInsightSection(weatherCtx),
    {
      title: "What you need to do well",
      paragraphs: [],
      bullets: successBullets,
    },
    {
      title: "What can cause problems",
      paragraphs: [],
      bullets: problemBullets,
    },
    ...(successSkillsSection ? [successSkillsSection] : []),
    ...(approachLeadersSection ? [approachLeadersSection] : []),
    {
      title: "Who fits vs. who struggles",
      paragraphs: fitParagraphs,
      playerFit: playerFit,
    },
    {
      title: "Prop markets to consider",
      paragraphs:
        propIdeas.length === 0
          ? ["No strong venue skew vs tour benchmarks. Lean on player-specific edges in Round Projections."]
          : [],
      bullets: propIdeas.map((x) => `<strong>${x.market} ${x.angle}</strong>: ${x.reason}`),
    },
  ];
  return sections;
}

function renderCourseBreakdownInsights(sections) {
  const card = document.getElementById("course-breakdown-insights-card");
  const body = document.getElementById("course-breakdown-insights-body");
  if (!card || !body) return;
  if (!sections?.length) {
    card.hidden = true;
    return;
  }
  card.hidden = false;
  body.innerHTML = "";
  for (const sec of sections) {
    const block = document.createElement("section");
    block.className = "course-breakdown-insight-section";
    const h = document.createElement("h4");
    h.textContent = sec.title;
    block.appendChild(h);
    for (const p of sec.paragraphs || []) {
      const el = document.createElement("p");
      el.textContent = p;
      block.appendChild(el);
    }
    if (sec.bullets?.length) {
      const ul = document.createElement("ul");
      ul.className = "course-breakdown-insight-list";
      for (const b of sec.bullets) {
        const li = document.createElement("li");
        if (b.includes("<strong>")) li.innerHTML = b;
        else li.textContent = b;
        ul.appendChild(li);
      }
      block.appendChild(ul);
    }
    if (sec.playerFit && (sec.playerFit.fits.length || sec.playerFit.struggles.length)) {
      const grid = document.createElement("div");
      grid.className = "course-breakdown-insight-players";
      for (const [kind, title] of [
        ["fits", "Best among top field"],
        ["struggles", "Top field — weakest on key skills"],
      ]) {
        const col = document.createElement("div");
        col.className = "course-breakdown-insight-player-col";
        const h5 = document.createElement("h5");
        h5.textContent = title;
        col.appendChild(h5);
        const ul = document.createElement("ul");
        for (const x of sec.playerFit[kind] || []) {
          const li = document.createElement("li");
          const zStr = Number.isFinite(x.skillZ ?? x.fit)
            ? `${(x.skillZ ?? x.fit) >= 0 ? "+" : ""}${(x.skillZ ?? x.fit).toFixed(2)} vs field`
            : "";
          const catStr = x.cat ? ` on ${x.cat}` : "";
          li.innerHTML = `<span class="course-breakdown-insight-player-name">${x.name}</span>${zStr ? `<span class="course-breakdown-insight-player-fit">${zStr}${catStr}</span>` : ""}`;
          ul.appendChild(li);
        }
        col.appendChild(ul);
        grid.appendChild(col);
      }
      block.appendChild(grid);
    }
    if (sec.sources?.length) {
      const src = document.createElement("p");
      src.className = "course-breakdown-insight-sources";
      src.textContent = `Sources: ${sec.sources.join(", ")}`;
      block.appendChild(src);
    }
    body.appendChild(block);
  }
}

async function buildCourseBreakdownInsights(holePars, rows, courseName) {
  await loadCourseTableJson();
  const courseKey = normCourseNameKey(courseName);
  const [eventCtxMap, weatherCtx, courseHistory] = await Promise.all([
    ensureCourseEventContextLoaded(),
    courseBreakdownGatherWeatherContext(courseName),
    ensurePropsCourseIndexForKeyAsync(courseKey),
  ]);
  const courseRow = courseBreakdownActiveCourseRow();
  const tourMeans = COURSE_TABLE_PAYLOAD?.means || {};
  const basis = courseBreakdownBasisRow();
  const metrics = courseBreakdownMetricSnapshots();
  const approachMeans = await courseBreakdownFieldApproachMeans();
  const approach = approachMeans
    ? courseBreakdownScaleApproachRow(approachMeans, courseRow || {}, tourMeans)
    : { bins: [], rghPen: [] };
  const driving = courseRow ? courseBreakdownDrivingModel(courseRow, tourMeans, holePars) : null;
  const putting = courseRow ? courseBreakdownPuttingModel(courseRow, tourMeans) : null;
  const sgImpact = courseBreakdownSgImpactSegments(rows);
  const approachImpact = await courseBreakdownApproachImpactSegments(rows);
  const asMap = await ensureApproachSkillByDgId();
  courseFitSetApproachBinWeights(courseFitVenueApproachBinWeights(approachImpact, courseRow));
  const approachBinLeaders = courseBreakdownApproachBinLeaders(rows, asMap, 3, 15);
  const playerFit = courseBreakdownPlayerFitLists(courseRow, rows);
  const m = DATA?.meta || {};
  const eventName = formatEventNameForDisplay(String(m.event_name || DATA?.event_name || "").trim()) || "";
  const externalCtx = courseBreakdownResolveEventContext(eventCtxMap, courseName, eventName);
  const priorEvent = courseBreakdownPriorEventFromEntries(courseHistory?.entries || []);
  const par =
    Math.round(num(m.course_par_18 ?? DATA?.course_par_18, NaN)) ||
    (holePars.length ? holePars.reduce((s, p) => s + Math.round(num(p, 4)), 0) : 72);
  const sections = courseBreakdownGenerateInsightSections({
    courseName,
    eventName,
    par,
    holePars,
    metrics,
    basis,
    courseRow,
    tourMeans,
    driving,
    approach,
    putting,
    sgImpact,
    approachImpact,
    approachBinLeaders,
    asMap,
    playerFit,
    weatherCtx,
    externalCtx,
    priorEvent,
  });
  renderCourseBreakdownInsights(sections);
}

function buildCourseBreakdownTab() {
  const m = DATA?.meta || {};
  const courseName =
    formatCourseNameForDisplay(String(m.course_used || DATA?.course_used || "").trim()) || "Course";
  const eventName = formatEventNameForDisplay(String(m.event_name || DATA?.event_name || "").trim()) || "";
  const holePars = Array.isArray(m.hole_pars)
    ? m.hole_pars
    : Array.isArray(DATA?.hole_pars)
      ? DATA.hole_pars
      : [];
  const par =
    Math.round(num(m.course_par_18 ?? DATA?.course_par_18, NaN)) ||
    (holePars.length ? holePars.reduce((s, p) => s + Math.round(num(p, 4)), 0) : 72);

  const nameEl = document.getElementById("course-info-name");
  const locEl = document.getElementById("course-info-loc");
  const parEl = document.getElementById("course-info-par");
  if (nameEl) nameEl.textContent = courseName;
  if (locEl) locEl.textContent = eventName;
  if (parEl) {
    if (holePars.length) {
      const p3 = holePars.filter((p) => Math.round(num(p, 4)) === 3).length;
      const p4 = holePars.filter((p) => Math.round(num(p, 4)) === 4).length;
      const p5 = holePars.filter((p) => Math.round(num(p, 4)) === 5).length;
      parEl.textContent = `Par ${par} • ${p3} par 3s · ${p4} par 4s · ${p5} par 5s`;
    } else {
      parEl.textContent = `Par ${par}`;
    }
  }

  const rows = courseBreakdownFieldRows();

  const courseTagSg = document.getElementById("course-sg-impact-course");
  if (courseTagSg) courseTagSg.textContent = `Course: ${courseName}`;
  const courseTagAp = document.getElementById("course-approach-impact-course");
  if (courseTagAp) courseTagAp.textContent = `Course: ${courseName}`;

  renderCourseBreakdownInfo(rows, courseName);
  renderCourseBoxplotGrid();
  void renderCourseBreakdownSkillGrid(holePars);
  renderCourseBreakdownSg(rows);
  void renderCourseBreakdownApproach(rows);
  void buildCourseBreakdownInsights(holePars, rows, courseName);
}

function formatAmericanOddsShort(n) {
  const x = num(n, NaN);
  if (!Number.isFinite(x)) return "—";
  if (x === 0) return "EV";
  return x > 0 ? `+${Math.round(x)}` : `${Math.round(x)}`;
}

/** Prefer DraftKings rows from merged props for O/U display. */
function courseFitFindDraftKingsOuProp(dgId, playerName, market) {
  const props = ouRoundOuPropsForLines();
  const dk = props.filter((r) => String(r.source || "").trim().toLowerCase() === "draftkings");
  const pool = dk.length ? dk : props;
  const pid = Math.round(num(dgId, NaN));
  const want = String(market || "").trim();
  const pk = playerKeyFromName(String(playerName || ""));
  for (const r of pool) {
    if (String(r.market || "").trim() !== want) continue;
    const id = Math.round(num(r.dg_id, NaN));
    if (Number.isFinite(pid) && pid > 0 && id === pid) return r;
  }
  for (const r of pool) {
    if (String(r.market || "").trim() !== want) continue;
    if (playerKeyFromName(String(r.player_name || "")) === pk) return r;
  }
  return null;
}

const COURSE_FIT_DIST_PROPS = Object.freeze([
  { key: "total", label: "Score" },
  { key: "birdies", label: "Birdies or Better" },
  { key: "pars", label: "Pars" },
  { key: "bogeys", label: "Bogeys or Worse" },
  { key: "fairways", label: "Fairways Hit" },
  { key: "gir", label: "Greens in Regulation" },
]);

let courseFitDistRoundFilter = "all";
let courseFitDistPropKey = "total";
/** @type {Set<string>} */
let courseFitDistSelectedEvents = new Set();
let courseFitDistEventsVenueKey = "";
let courseFitDistFiltersBound = false;
let courseFitDistGolferQuery = "";
let courseFitDistGolferDebounce = 0;
/** @type {string[]} */
let courseFitDistGolferLabels = [];
let courseFitDistLoadPromise = null;

function courseFitDistActiveVenueKey(fallbackVk = "") {
  if (courseFitDistEventsVenueKey) return courseFitDistEventsVenueKey;
  const venueRaw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  if (venueRaw) return normCourseNameKey(venueRaw);
  return fallbackVk;
}

function courseFitDistEntryMatchesGolfer(entry, golferQ) {
  const q = String(golferQ || "").trim().toLowerCase();
  if (!q) return true;
  const nm = displayGolferName(String(entry?.playerName || entry?.row?.player_name || ""));
  return golferNameMatchesQuery(nm, q);
}

function courseFitDistGolferLabelsFromEntries(entries) {
  const names = new Set();
  for (const e of entries || []) {
    const nm = displayGolferName(String(e?.playerName || e?.row?.player_name || ""));
    if (nm) names.add(nm);
  }
  return [...names].sort((a, b) => a.localeCompare(b));
}

function setCourseFitDistPanelVisibility(hasData, emptyMessage = "") {
  const emptyEl = document.getElementById("course-fit-dist-empty");
  const chartsEl = document.getElementById("course-fit-dist-charts");
  if (emptyEl) {
    emptyEl.hidden = Boolean(hasData);
    if (!hasData && emptyMessage) emptyEl.textContent = emptyMessage;
  }
  if (chartsEl) chartsEl.hidden = !hasData;
}

function clearCourseFitDistCanvases() {
  for (const id of ["course-fit-dist-avg-canvas", "course-fit-dist-ind-canvas"]) {
    const canvas = document.getElementById(id);
    const ctx = canvas?.getContext?.("2d");
    if (!ctx || !canvas) continue;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  }
}

function courseFitDistPropLabel(statKey) {
  const hit = COURSE_FIT_DIST_PROPS.find((p) => p.key === statKey);
  return hit ? hit.label : "Score";
}

function courseFitDistEventKey(row) {
  if (!row || typeof row !== "object") return "";
  const y = historyRoundSeasonYear(row);
  const ev = String(row.event_name || "").trim();
  if (!ev) return "";
  return `${Number.isFinite(y) ? y : "na"}|${ev}`;
}

function courseFitDistEventDisplayLabel(row) {
  const y = historyRoundSeasonYear(row);
  const ev = formatEventNameForDisplay(String(row?.event_name || "").trim());
  return Number.isFinite(y) ? `${y} ${ev}` : ev;
}

function courseFitDistEventsFromEntries(entries) {
  const map = new Map();
  for (const e of entries || []) {
    const row = e?.row;
    if (!row || !courseFitDistRoundCountsAsActual(row)) continue;
    const key = courseFitDistEventKey(row);
    if (!key || map.has(key)) continue;
    map.set(key, { key, row, label: courseFitDistEventDisplayLabel(row) });
  }
  return [...map.values()].sort((a, b) => {
    const ya = historyRoundSeasonYear(a.row);
    const yb = historyRoundSeasonYear(b.row);
    if (yb !== ya) return yb - ya;
    return String(a.label).localeCompare(String(b.label));
  });
}

function courseFitDistRoundMatches(row, roundFilter) {
  if (roundFilter === "all") return true;
  const want = Math.round(num(roundFilter, NaN));
  const rn = Math.round(num(row?.round_num ?? row?.round, NaN));
  return Number.isFinite(want) && want >= 1 && want <= 4 && rn === want;
}

/** Past-events distributions: include every archived actual; never cap rows to live tournament progress. */
function courseFitDistRoundCountsAsActual(row) {
  if (!row || typeof row !== "object") return false;
  if (!historyRowFromDgHistoricalRoundsApi(row)) return false;
  if (historyRoundIsPlaceholderAllMarketsZero(row)) return false;
  if (historyDateMdYIsFuture(row.event_completed)) return false;
  if (historyRoundChartDateIsFuture(row)) return false;

  if (row._from_live_tournament_stats) {
    const rs = num(row.round_score, NaN);
    if (!Number.isFinite(rs) || rs <= 0) return false;
  }

  if (historyRoundMatchesCurrentEvent(row)) {
    const seasonY = historyRoundSeasonYear(row);
    const currentY = currentEventSeasonYearFromMeta();
    if (Number.isFinite(seasonY) && Number.isFinite(currentY) && seasonY === currentY) {
      if (row._from_pgatour && !pgatourRowBelongsToEvent(row, String(DATA?.meta?.event_name || ""))) return false;
    }
  }
  return true;
}

function courseFitDistFilteredEntries(entries, roundFilter, selectedEvents, golferQ) {
  const out = [];
  for (const e of entries || []) {
    const row = e?.row;
    if (!row || !courseFitDistRoundCountsAsActual(row)) continue;
    const ek = courseFitDistEventKey(row);
    if (selectedEvents.size && !selectedEvents.has(ek)) continue;
    if (!courseFitDistRoundMatches(row, roundFilter)) continue;
    if (!courseFitDistEntryMatchesGolfer(e, golferQ)) continue;
    out.push(e);
  }
  return courseFitDistDedupeEntriesByPlayerEventRound(out);
}

function courseFitDistDedupeEntriesByPlayerEventRound(entries) {
  const map = new Map();
  for (const e of entries || []) {
    const row = e?.row;
    if (!row) continue;
    const ek = courseFitDistEventKey(row);
    const dg = Math.round(num(e.dgId ?? row.dg_id, NaN));
    const rnd = Math.round(num(row?.round_num ?? row?.round, NaN));
    const nameKey = String(e.playerName || row.player_name || "")
      .trim()
      .toLowerCase();
    const pk = `${ek}|${Number.isFinite(dg) && dg > 0 ? dg : nameKey}|${Number.isFinite(rnd) ? rnd : "na"}`;
    const prev = map.get(pk);
    if (!prev) {
      map.set(pk, e);
      continue;
    }
    const sk = num(row.sortKey, 0);
    const psk = num(prev.row?.sortKey, 0);
    if (sk >= psk) map.set(pk, e);
  }
  return [...map.values()];
}

function courseFitDistFilteredGolferDisplayName(entries, golferQ) {
  const q = String(golferQ || "").trim().toLowerCase();
  if (!q) return "";
  for (const e of entries || []) {
    if (!courseFitDistEntryMatchesGolfer(e, q)) continue;
    const nm = displayGolferName(String(e.playerName || e.row?.player_name || ""));
    if (nm) return nm;
  }
  return "";
}

/** Prefer a golfer from this week's field who has history here; otherwise first label A→Z. */
function courseFitDistDefaultGolferName(entries, labels) {
  const names = Array.isArray(labels) && labels.length ? labels : courseFitDistGolferLabelsFromEntries(entries);
  if (!names.length) return "";
  const fieldNames = new Set();
  for (const p of Array.isArray(DATA?.players) ? DATA.players : []) {
    const nm = displayGolferName(String(p?.player_name || ""));
    if (nm) fieldNames.add(nm.toLowerCase());
  }
  if (fieldNames.size) {
    const inField = names.find((nm) => fieldNames.has(String(nm).toLowerCase()));
    if (inField) return inField;
  }
  return names[0];
}

/**
 * Individual-rounds chart always needs one golfer. Resolve a concrete name from the
 * query (or auto-pick), and sync the search input so the UI never shows "All golfers".
 * Does not overwrite the input while the user is mid-edit.
 */
function courseFitDistEnsureGolferSelected(entries) {
  const labels = courseFitDistGolferLabelsFromEntries(entries);
  courseFitDistGolferLabels = labels;
  const gf = document.getElementById("course-fit-dist-golfer");
  const focused = gf instanceof HTMLInputElement && document.activeElement === gf;
  const typed = gf instanceof HTMLInputElement ? String(gf.value || "").trim() : "";
  const q = String(courseFitDistGolferQuery || typed || "")
    .trim()
    .toLowerCase();

  let name = "";
  if (q) {
    name = labels.find((nm) => nm.toLowerCase() === q) || "";
    if (!name) name = courseFitDistFilteredGolferDisplayName(entries, q);
  }
  if (!name) name = courseFitDistDefaultGolferName(entries, labels);

  courseFitDistGolferQuery = name ? name.toLowerCase() : "";
  if (gf instanceof HTMLInputElement && name) {
    if (!focused || !typed) {
      if (String(gf.value || "").trim() !== name) gf.value = name;
    }
  }
  return name;
}

function courseFitDistEventRoundCount(entries, eventKey, roundFilter, golferQ) {
  return courseFitDistFilteredEntries(entries, roundFilter, new Set([eventKey]), golferQ).length;
}

function courseFitDistIndividualValues(entries, statKey, roundFilter, selectedEvents, golferQ = courseFitDistGolferQuery) {
  const out = [];
  for (const e of courseFitDistFilteredEntries(entries, roundFilter, selectedEvents, golferQ)) {
    const v = actualForRoundRow(statKey, e.row);
    if (Number.isFinite(v)) out.push(v);
  }
  return out;
}

function courseFitDistPlayerEventAverages(entries, statKey, roundFilter, selectedEvents, golferQ = courseFitDistGolferQuery) {
  const byPe = new Map();
  for (const e of courseFitDistFilteredEntries(entries, roundFilter, selectedEvents, golferQ)) {
    const row = e.row;
    const ek = courseFitDistEventKey(row);
    const v = actualForRoundRow(statKey, row);
    if (!Number.isFinite(v)) continue;
    const dg = Math.round(num(e.dgId ?? row.dg_id, NaN));
    const pk = `${ek}|${Number.isFinite(dg) ? dg : String(e.playerName || "")}`;
    const hit = byPe.get(pk) || { sum: 0, n: 0 };
    hit.sum += v;
    hit.n += 1;
    byPe.set(pk, hit);
  }
  const out = [];
  for (const hit of byPe.values()) {
    if (hit.n > 0) out.push(hit.sum / hit.n);
  }
  return out;
}

function courseFitDistMeanSd(values) {
  const xs = (values || []).filter((v) => Number.isFinite(v));
  if (!xs.length) return { mean: NaN, sd: NaN, n: 0 };
  const mean = xs.reduce((a, b) => a + b, 0) / xs.length;
  if (xs.length < 2) return { mean, sd: 0, n: xs.length };
  const variance = xs.reduce((a, v) => a + (v - mean) ** 2, 0) / (xs.length - 1);
  return { mean, sd: Math.sqrt(Math.max(variance, 0)), n: xs.length };
}

function courseFitDistFormatStat(v, statKey, halfStep) {
  if (!Number.isFinite(v)) return "—";
  if (statKey === "total") return v.toFixed(2);
  if (halfStep) return v.toFixed(2);
  return Math.abs(v - Math.round(v)) < 1e-6 ? String(Math.round(v)) : v.toFixed(1);
}

function courseFitDistBuildHistogram(values, opts = {}) {
  const xs = (values || []).filter((v) => Number.isFinite(v));
  if (!xs.length) return { bins: [], maxCount: 0 };
  const integerMode = Boolean(opts.integerMode);
  const binWidth = Number.isFinite(opts.binWidth) ? opts.binWidth : integerMode ? 1 : 0.5;
  let minV = Math.min(...xs);
  let maxV = Math.max(...xs);
  if (integerMode) {
    minV = Math.floor(minV);
    maxV = Math.ceil(maxV);
  } else {
    minV = Math.floor(minV / binWidth) * binWidth;
    maxV = Math.ceil(maxV / binWidth) * binWidth;
  }
  const span = Math.max(maxV - minV, binWidth);
  // Integer mode: one bin per integer value, minV..maxV inclusive — a half-open [maxV-1, maxV)
  // last bin would silently drop the max value (e.g. a 5-bogey round vanished from the chart).
  const nBins = integerMode ? Math.round(maxV - minV) + 1 : Math.max(1, Math.round(span / binWidth));
  const bins = [];
  for (let i = 0; i < nBins; i++) {
    const lo = minV + i * binWidth;
    const hi = lo + binWidth;
    const isLast = i === nBins - 1;
    const count = xs.filter(
      (v) => v >= lo - 1e-9 && (isLast ? v <= hi + 1e-9 : v < hi - (integerMode ? 0 : 1e-9)),
    ).length;
    const label = integerMode ? String(Math.round(lo)) : `${lo.toFixed(1)} – ${hi.toFixed(1)}`;
    bins.push({ lo, hi, count, label, mid: lo + binWidth / 2 });
  }
  const maxCount = bins.reduce((m, b) => Math.max(m, b.count), 0);
  return { bins, maxCount, minV, maxV, binWidth };
}

function drawCourseFitDistHistogram(canvas, values, opts = {}) {
  const ctx = canvas?.getContext?.("2d");
  if (!ctx || !canvas) return;
  const statKey = String(opts.statKey || "total");
  const titleMode = String(opts.titleMode || "individual");
  const binWidth = titleMode === "avg" ? 0.5 : 1;
  const integerMode = titleMode === "individual";
  const overlayMean = Number.isFinite(opts.overlayMean) ? opts.overlayMean : NaN;
  const showMeanLine = opts.showMeanLine !== false;
  const showOverlayLabel = Boolean(opts.showOverlayLabel);
  const hist = courseFitDistBuildHistogram(values, { integerMode, binWidth });
  const { mean, sd } = courseFitDistMeanSd(values);

  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const cssW = Math.max(320, canvas.clientWidth || 560);
  const cssH = 300;
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cssW, cssH);

  const pad = { l: 44, r: 16, t: 22, b: 48 };
  const plotW = cssW - pad.l - pad.r;
  const plotH = cssH - pad.t - pad.b;
  const gridColor = "rgba(255,255,255,0.08)";
  const textMuted = getComputedStyle(document.documentElement).getPropertyValue("--golf-text-muted").trim() || "#94a3b8";

  if (!hist.bins.length) {
    ctx.fillStyle = textMuted;
    ctx.font = "600 13px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("No data", cssW / 2, cssH / 2);
    return;
  }

  const maxCount = Math.max(hist.maxCount, 1);
  const yTicks = 5;
  for (let i = 0; i <= yTicks; i++) {
    const y = pad.t + plotH - (i / yTicks) * plotH;
    ctx.strokeStyle = gridColor;
    ctx.beginPath();
    ctx.moveTo(pad.l, y);
    ctx.lineTo(pad.l + plotW, y);
    ctx.stroke();
    ctx.fillStyle = textMuted;
    ctx.font = "500 10px system-ui, sans-serif";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    ctx.fillText(String(Math.round((i / yTicks) * maxCount)), pad.l - 6, y);
  }

  let xMin = hist.minV;
  let xMax = hist.maxV + hist.binWidth;
  // Keep an out-of-range player marker on-plot by expanding the axis.
  if (Number.isFinite(overlayMean)) {
    xMin = Math.min(xMin, overlayMean - hist.binWidth * 0.25);
    xMax = Math.max(xMax, overlayMean + hist.binWidth * 0.25);
  }
  const xSpan = Math.max(xMax - xMin, hist.binWidth);
  const xToPx = (x) => pad.l + ((x - xMin) / xSpan) * plotW;

  if (Number.isFinite(mean) && Number.isFinite(sd) && sd > 0) {
    const bands = [
      { lo: mean - 2 * sd, hi: mean + 2 * sd, fill: "rgba(255,255,255,0.04)" },
      { lo: mean - sd, hi: mean + sd, fill: "rgba(255,255,255,0.07)" },
    ];
    for (const b of bands) {
      const x0 = xToPx(Math.max(b.lo, xMin));
      const x1 = xToPx(Math.min(b.hi, xMax));
      if (x1 > x0) {
        ctx.fillStyle = b.fill;
        ctx.fillRect(x0, pad.t, x1 - x0, plotH);
      }
    }
  }

  const barGap = 2;
  const barW = Math.max(4, plotW / hist.bins.length - barGap);
  for (let i = 0; i < hist.bins.length; i++) {
    const b = hist.bins[i];
    const xCenter = xToPx(b.lo + hist.binWidth / 2);
    const h = (b.count / maxCount) * plotH;
    const x = xCenter - barW / 2;
    const y = pad.t + plotH - h;
    ctx.fillStyle = "#2ecfff";
    ctx.fillRect(x, y, barW, h);
    if (b.count > 0) {
      ctx.fillStyle = "#e8f7ff";
      ctx.font = "700 10px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      ctx.fillText(String(b.count), xCenter, y - 2);
    }
  }

  if (showMeanLine && Number.isFinite(mean)) {
    const mx = xToPx(mean);
    ctx.strokeStyle = "#ef4444";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(mx, pad.t);
    ctx.lineTo(mx, pad.t + plotH);
    ctx.stroke();
  }

  if (Number.isFinite(overlayMean)) {
    const ox = xToPx(overlayMean);
    ctx.strokeStyle = "#f59e0b";
    ctx.lineWidth = 2.5;
    ctx.setLineDash([5, 4]);
    ctx.beginPath();
    ctx.moveTo(ox, pad.t);
    ctx.lineTo(ox, pad.t + plotH);
    ctx.stroke();
    ctx.setLineDash([]);
    if (showOverlayLabel) {
      const overlayLabel = String(opts.overlayLabel || "").trim();
      const tag = overlayLabel
        ? `${overlayLabel} ${courseFitDistFormatStat(overlayMean, statKey, titleMode === "avg")}`
        : courseFitDistFormatStat(overlayMean, statKey, titleMode === "avg");
      ctx.fillStyle = "#f59e0b";
      ctx.font = "700 11px system-ui, sans-serif";
      ctx.textBaseline = "bottom";
      const tw = ctx.measureText(tag).width;
      const tx = Math.max(pad.l + 2, Math.min(pad.l + plotW - tw - 2, ox + 4));
      ctx.textAlign = "left";
      ctx.fillText(tag, tx, pad.t + 14);
    }
  }

  ctx.fillStyle = textMuted;
  ctx.font = "600 11px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  const labelEvery = hist.bins.length > 16 ? 2 : 1;
  for (let i = 0; i < hist.bins.length; i += labelEvery) {
    const b = hist.bins[i];
    const xCenter = xToPx(b.lo + hist.binWidth / 2);
    ctx.save();
    ctx.translate(xCenter, pad.t + plotH + 6);
    ctx.rotate(-0.45);
    ctx.textAlign = "right";
    ctx.fillText(b.label, 0, 0);
    ctx.restore();
  }

  ctx.save();
  ctx.translate(14, pad.t + plotH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.textAlign = "center";
  ctx.fillStyle = textMuted;
  ctx.font = "600 11px system-ui, sans-serif";
  ctx.fillText("Count", 0, 0);
  ctx.restore();

  return { mean, sd, n: values.length, overlayMean };
}

function renderCourseFitDistStats(dl, mean, sd, statKey, halfStep, extra = null) {
  if (!dl) return;
  dl.innerHTML = "";
  const add = (label, value) => {
    const dt = document.createElement("dt");
    dt.textContent = label;
    const dd = document.createElement("dd");
    dd.textContent = value;
    dl.appendChild(dt);
    dl.appendChild(dd);
  };
  add("Mean", courseFitDistFormatStat(mean, statKey, halfStep));
  if (Number.isFinite(mean) && Number.isFinite(sd)) {
    add(
      "±1 SD",
      `${courseFitDistFormatStat(mean - sd, statKey, halfStep)} – ${courseFitDistFormatStat(mean + sd, statKey, halfStep)}`,
    );
    add(
      "±2 SD",
      `${courseFitDistFormatStat(mean - 2 * sd, statKey, halfStep)} – ${courseFitDistFormatStat(mean + 2 * sd, statKey, halfStep)}`,
    );
  }
  if (extra?.playerLabel && Number.isFinite(extra.playerMean)) {
    add(extra.playerLabel, courseFitDistFormatStat(extra.playerMean, statKey, halfStep));
  }
}

function syncCourseFitDistEventCheckboxes(events, venueKey, entries, roundFilter, golferQ) {
  const host = document.getElementById("course-fit-past-events-host");
  if (!host) return;
  if (courseFitDistEventsVenueKey !== venueKey) {
    courseFitDistEventsVenueKey = venueKey;
    courseFitDistSelectedEvents = new Set(events.map((e) => e.key));
  }
  host.innerHTML = "";
  if (!events.length) {
    host.innerHTML = '<p class="text-muted" style="margin:0;font-size:0.82rem">No archived events at this course yet.</p>';
    return;
  }
  const golferActive = Boolean(String(golferQ || "").trim());
  for (const ev of events) {
    const lbl = document.createElement("label");
    lbl.className = "course-fit-dist-event-row";
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.value = ev.key;
    cb.checked = courseFitDistSelectedEvents.has(ev.key);
    cb.addEventListener("change", () => {
      if (cb.checked) courseFitDistSelectedEvents.add(ev.key);
      else courseFitDistSelectedEvents.delete(ev.key);
      buildCourseFitDistributionsPanel(venueKey);
    });
    lbl.appendChild(cb);
    let labelText = ev.label;
    if (golferActive) {
      const n = courseFitDistEventRoundCount(entries, ev.key, roundFilter, golferQ);
      labelText += n > 0 ? ` (${n} round${n === 1 ? "" : "s"})` : " (no rounds for this golfer)";
    }
    lbl.appendChild(document.createTextNode(labelText));
    host.appendChild(lbl);
  }
}

function ensureCourseFitDistFiltersBound() {
  if (courseFitDistFiltersBound) return;
  courseFitDistFiltersBound = true;
  document.querySelectorAll(".course-fit-dist-round-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const v = String(btn.getAttribute("data-cf-round") || "all");
      courseFitDistRoundFilter = v;
      document.querySelectorAll(".course-fit-dist-round-btn").forEach((b) => {
        b.classList.toggle("active", String(b.getAttribute("data-cf-round") || "") === v);
      });
      buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
    });
  });
  document.getElementById("course-fit-dist-prop")?.addEventListener("change", (e) => {
    courseFitDistPropKey = String(/** @type {HTMLSelectElement} */ (e.target).value || "total");
    buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
  });
  const gf = document.getElementById("course-fit-dist-golfer");
  const gfPanel = document.getElementById("course-fit-dist-golfer-suggest");
  if (gf && gf instanceof HTMLInputElement && gfPanel) {
    wireGolferSuggestGlobalDismissOnce();
    const onPick = () => {
      courseFitDistGolferQuery = String(gf.value || "").trim().toLowerCase();
      buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
    };
    const refreshGolferPanel = (showAll = false) => {
      golferSuggestWriteLabels(gfPanel, courseFitDistGolferLabels);
      openGolferSuggestForSearchInput(gf, gfPanel, onPick, { showAll });
    };
    gf.addEventListener("focus", () => {
      // Select current name so typing replaces it; open the full roster (not just the match).
      try {
        gf.select();
      } catch {
        /* ignore */
      }
      refreshGolferPanel(true);
    });
    gf.addEventListener("click", () => {
      if (gfPanel.hidden) refreshGolferPanel(true);
    });
    gf.addEventListener("input", () => {
      if (courseFitDistGolferDebounce) clearTimeout(courseFitDistGolferDebounce);
      courseFitDistGolferDebounce = window.setTimeout(() => {
        courseFitDistGolferDebounce = 0;
        courseFitDistGolferQuery = String(gf.value || "").trim().toLowerCase();
        refreshGolferPanel(false);
        buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
      }, 140);
    });
    gf.addEventListener("change", () => {
      courseFitDistGolferQuery = String(gf.value || "").trim().toLowerCase();
      buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
    });
    gf.addEventListener("blur", () => {
      setTimeout(() => {
        if (gfPanel.contains(document.activeElement)) return;
        gfPanel.hidden = true;
        gfPanel.innerHTML = "";
        courseFitDistGolferQuery = String(gf.value || "").trim().toLowerCase();
        buildCourseFitDistributionsPanel(courseFitDistActiveVenueKey());
      }, 160);
    });
  }
}

function buildCourseFitDistributionsPanel(venueKey) {
  const panel = document.getElementById("course-fit-subpanel-distributions");
  if (!panel || panel.hidden) return;
  ensureCourseFitDistFiltersBound();

  const vk = venueKey || courseFitDistActiveVenueKey();
  const avgCanvas = document.getElementById("course-fit-dist-avg-canvas");
  const indCanvas = document.getElementById("course-fit-dist-ind-canvas");
  const avgTitle = document.getElementById("course-fit-dist-avg-title");
  const indTitle = document.getElementById("course-fit-dist-ind-title");
  const avgStats = document.getElementById("course-fit-dist-avg-stats");
  const indStats = document.getElementById("course-fit-dist-ind-stats");
  const propSel = document.getElementById("course-fit-dist-prop");
  if (propSel && propSel.value !== courseFitDistPropKey) propSel.value = courseFitDistPropKey;

  const statKey = courseFitDistPropKey || "total";
  const propLabel = courseFitDistPropLabel(statKey);

  const bucket = propsGetSingleCourseBucketSync(vk);
  const entries = bucket?.entries || [];
  if (!entries.length) {
    setCourseFitDistPanelVisibility(false, "Loading course history…");
    clearCourseFitDistCanvases();
    if (avgStats) avgStats.innerHTML = "";
    if (indStats) indStats.innerHTML = "";
    void loadCourseFitDistributionsForVenue(vk);
    return;
  }

  const events = courseFitDistEventsFromEntries(entries);
  const roundFilter = courseFitDistRoundFilter || "all";
  // Right chart always needs one golfer; left stays field-wide with that player's average overlaid.
  const golferName = courseFitDistEnsureGolferSelected(entries);
  const golferQ = courseFitDistGolferQuery;
  if (avgTitle) {
    avgTitle.textContent = golferName
      ? `${propLabel} Distribution — Tournament Average (field + ${golferName})`
      : `${propLabel} Distribution — Tournament Average`;
  }
  if (indTitle) {
    indTitle.textContent = golferName
      ? `${propLabel} — Individual Rounds (${golferName})`
      : `${propLabel} — Individual Rounds`;
  }
  syncCourseFitDistEventCheckboxes(events, vk, entries, roundFilter, golferQ);
  const gf = document.getElementById("course-fit-dist-golfer");
  const gfPanel = document.getElementById("course-fit-dist-golfer-suggest");
  if (gf && gf instanceof HTMLInputElement && gfPanel) {
    golferSuggestWriteLabels(gfPanel, courseFitDistGolferLabels);
    reopenGolferSuggestIfSearchFocused(gf, gfPanel, () => {
      courseFitDistGolferQuery = String(gf.value || "").trim().toLowerCase();
      buildCourseFitDistributionsPanel(vk);
    });
  }

  const selected = courseFitDistSelectedEvents.size
    ? courseFitDistSelectedEvents
    : new Set(events.map((e) => e.key));

  // Left: always the full field tournament averages for the selected events/rounds.
  const avgValues = courseFitDistPlayerEventAverages(entries, statKey, roundFilter, selected, "");
  // Right: always the selected golfer's individual rounds.
  const indValues = courseFitDistIndividualValues(entries, statKey, roundFilter, selected, golferQ);
  const playerAvgValues = courseFitDistPlayerEventAverages(entries, statKey, roundFilter, selected, golferQ);
  const playerOverlayMean = (() => {
    if (!playerAvgValues.length) return NaN;
    return playerAvgValues.reduce((a, b) => a + b, 0) / playerAvgValues.length;
  })();
  const hasData = avgValues.length > 0 || indValues.length > 0;

  if (!hasData) {
    const roundLabel = roundFilter === "all" ? "" : ` for R${roundFilter}`;
    const golferLabel = golferName ? ` for ${golferName}` : "";
    setCourseFitDistPanelVisibility(
      false,
      `No data available${roundLabel}${golferLabel} with your chosen filters.`,
    );
    clearCourseFitDistCanvases();
    if (avgStats) avgStats.innerHTML = "";
    if (indStats) indStats.innerHTML = "";
    return;
  }

  setCourseFitDistPanelVisibility(true);
  const avgHit = drawCourseFitDistHistogram(avgCanvas, avgValues, {
    statKey,
    titleMode: "avg",
    overlayMean: playerOverlayMean,
    showOverlayLabel: false,
  });
  const indHit = drawCourseFitDistHistogram(indCanvas, indValues, {
    statKey,
    titleMode: "individual",
    showMeanLine: false,
  });
  renderCourseFitDistStats(avgStats, avgHit?.mean, avgHit?.sd, statKey, true, {
    playerLabel: golferName ? `${golferName} avg` : "",
    playerMean: playerOverlayMean,
  });
  renderCourseFitDistStats(indStats, indHit?.mean, indHit?.sd, statKey, false);
}

async function loadCourseFitDistributionsForVenue(venueKey) {
  const panel = document.getElementById("course-fit-subpanel-distributions");
  if (!panel || panel.hidden || !venueKey) return;
  if (courseFitDistLoadPromise) return courseFitDistLoadPromise;
  const cached = propsGetSingleCourseBucketSync(venueKey);
  if (cached?.entries?.length) {
    buildCourseFitDistributionsPanel(venueKey);
    return;
  }
  setCourseFitDistPanelVisibility(false, "Loading course history…");
  clearCourseFitDistCanvases();
  courseFitDistLoadPromise = ensurePropsCourseIndexForKeyAsync(venueKey)
    .finally(() => {
      courseFitDistLoadPromise = null;
    });
  await courseFitDistLoadPromise;
  if (activeAppTabId() === "course-fit") buildCourseFitDistributionsPanel(venueKey);
}


const COURSE_FIT_TABLE_RADAR_KEYS_DEFAULT = Object.freeze([
  "adj_driving_accuracy",
  "ott_sg",
  "app_sg",
  "arg_sg",
  "putt_sg",
  "adj_driving_distance",
]);

function playerDrivingAccuracyFrac(mrow) {
  const da = num(mrow?.driving_accuracy ?? mrow?.driving_acc, NaN);
  if (!Number.isFinite(da)) return NaN;
  return da > 1 ? da / 100 : da;
}

function playerDrivingDistanceYds(mrow) {
  if (!mrow || typeof mrow !== "object") return NaN;
  const yardCandidates = [
    mrow.driving_distance,
    mrow.avg_driving_distance,
    mrow.adj_driving_distance,
    mrow.average_driving_distance,
    mrow.predicted_driving_distance,
    mrow.predicted_avg_driving_distance,
  ];
  for (const c of yardCandidates) {
    const y = num(c, NaN);
    if (Number.isFinite(y) && y >= 235 && y <= 380) return y;
  }
  const dDist = num(mrow.driving_dist, NaN);
  if (Number.isFinite(dDist) && dDist >= 235 && dDist <= 380) return dDist;
  let rt = num(mrow.driving_distance_rating, NaN);
  if (!Number.isFinite(rt) && Number.isFinite(dDist) && dDist >= -120 && dDist <= 120) rt = dDist;
  if (Number.isFinite(rt) && rt >= -120 && rt <= 120) return 302 + rt;
  return NaN;
}

function courseFitPlayerRadarAxisRaw(mrow, axisIndex) {
  if (axisIndex === 0) return playerDrivingAccuracyFrac(mrow);
  if (axisIndex === 1) return num(mrow?.sg_ott, NaN);
  if (axisIndex === 2) return num(mrow?.sg_app, NaN);
  if (axisIndex === 3) return num(mrow?.sg_arg, NaN);
  if (axisIndex === 4) return num(mrow?.sg_putt, NaN);
  if (axisIndex === 5) return playerDrivingDistanceYds(mrow);
  return NaN;
}

function courseFitRadarKeysFromTable() {
  const k = COURSE_TABLE_PAYLOAD?.radarKeys;
  if (Array.isArray(k) && k.length === 6) return k;
  return [...COURSE_FIT_TABLE_RADAR_KEYS_DEFAULT];
}

function resolveCourseTableRowForNormKey(activeVk) {
  const p = COURSE_TABLE_PAYLOAD;
  if (!p?.byNormKey || !activeVk) return null;
  if (p.byNormKey[activeVk]) return p.byNormKey[activeVk];
  let best = null;
  let bestScore = 0;
  for (const key of Object.keys(p.byNormKey)) {
    let score = 0;
    if (key === activeVk) score = 10000;
    else if (activeVk.length >= 5 && (key.includes(activeVk) || activeVk.includes(key)))
      score = 500 + Math.min(key.length, activeVk.length);
    else {
      const vt = activeVk.split(" ").filter((t) => t.length > 2);
      const kt = key.split(" ").filter((t) => t.length > 2);
      for (const t of vt) {
        if (kt.some((u) => u === t || (t.length >= 4 && (u.startsWith(t) || t.startsWith(u))))) score += 22;
      }
    }
    if (score > bestScore) {
      bestScore = score;
      best = p.byNormKey[key];
    }
  }
  return bestScore >= 22 ? best : null;
}

function courseTableScalarNormTo01(v, col) {
  const r = COURSE_TABLE_PAYLOAD?.ranges?.[col];
  if (!Number.isFinite(v) || !r || !Number.isFinite(r.lo) || !Number.isFinite(r.hi)) return 0.5;
  const span = r.hi - r.lo < 1e-9 ? 1 : r.hi - r.lo;
  return clamp((v - r.lo) / span, 0, 1);
}

/** Iron-play / approach demand (GIR, narrow fairways, distance approach coeffs) — not raw arg subs. */
function courseFitApproachDemandNorm(row) {
  if (!row || typeof row !== "object") return 0.5;
  const gir = courseTableScalarNormTo01(num(row.adj_gir, NaN), "adj_gir");
  const narrow = 1 - courseTableScalarNormTo01(num(row.fw_width, NaN), "fw_width");
  const app = courseTableScalarNormTo01(num(row.app_sg, NaN), "app_sg");
  const g150 = courseTableScalarNormTo01(num(row.greater_150_sg, NaN), "greater_150_sg");
  const l150 = courseTableScalarNormTo01(num(row.less_150_sg, NaN), "less_150_sg");
  return clamp(0.48 * gir + 0.38 * narrow + 0.08 * app + 0.03 * g150 + 0.03 * l150, 0, 1);
}

/** Around-green demand from arg_sg only (fairway/rough/bunker splits inflate ARG on iron layouts). */
function courseFitArgDemandNorm(row) {
  if (!row || typeof row !== "object") return 0.5;
  return courseTableScalarNormTo01(num(row.arg_sg, NaN), "arg_sg") * 0.75;
}

/** Six-axis venue profile for radar + fit (aligned with spoke labels). */
function courseFitVenue5Profile(row) {
  if (!row || typeof row !== "object") return null;
  return [
    courseTableScalarNormTo01(num(row.adj_driving_accuracy, NaN), "adj_driving_accuracy"),
    courseTableScalarNormTo01(num(row.ott_sg, NaN), "ott_sg"),
    courseFitApproachDemandNorm(row),
    courseFitArgDemandNorm(row),
    courseTableScalarNormTo01(num(row.putt_sg, NaN), "putt_sg"),
    courseTableScalarNormTo01(num(row.adj_driving_distance, NaN), "adj_driving_distance"),
  ];
}

/** Tour-average course profile (mean row in course_table) for stress vs typical PGA venue. */
function courseFitTourCourseMean5() {
  const means = COURSE_TABLE_PAYLOAD?.means || {};
  if (!Object.keys(means).length) return COURSE_FIT_RADAR_SPOKE_LABELS.map(() => 0.5);
  const pseudo = { ...means };
  return courseFitVenue5Profile(pseudo) || COURSE_FIT_RADAR_SPOKE_LABELS.map(() => 0.5);
}

/** Current-field average on the same six axes as the radar (true "Field Avg" line). */
function courseFitField5FromRows(rows) {
  const pool = Array.isArray(rows) ? rows : [];
  if (!pool.length) return COURSE_FIT_RADAR_SPOKE_LABELS.map(() => 0.5);
  const sums = COURSE_FIT_RADAR_SPOKE_LABELS.map(() => 0);
  let n = 0;
  for (const r of pool) {
    const p = courseFitPlayerRadarVectorMerged(pool, r);
    if (!p.every(Number.isFinite)) continue;
    for (let i = 0; i < sums.length; i++) sums[i] += p[i];
    n++;
  }
  if (!n) return COURSE_FIT_RADAR_SPOKE_LABELS.map(() => 0.5);
  return sums.map((s) => s / n);
}

/** @deprecated Use courseFitVenue5Profile + courseFitTourCourseMean5 */
function courseFitTour5FromCourseTable() {
  return courseFitTourCourseMean5();
}

/** @deprecated Use courseFitVenue5Profile */
function courseFitVenue5FromCourseTableRow(row) {
  return courseFitVenue5Profile(row) || courseFitTourCourseMean5();
}

function courseFitMergedLoHiForCol(col, fieldSamples) {
  const tr = COURSE_TABLE_PAYLOAD?.ranges?.[col];
  const ff = fieldSamples.filter(Number.isFinite);
  const flo = ff.length ? Math.min(...ff) : NaN;
  const fhi = ff.length ? Math.max(...ff) : NaN;
  if (!tr) {
    if (!Number.isFinite(flo) || !Number.isFinite(fhi)) return { lo: 0, hi: 1 };
    return { lo: flo, hi: fhi <= flo ? flo + 1e-3 : fhi };
  }
  if (!ff.length) return { lo: tr.lo, hi: tr.hi };
  return { lo: Math.min(tr.lo, flo), hi: Math.max(tr.hi, fhi) };
}

/** Player profile on the same axes as `courseFitRadarKeysFromTable()` (merged field + course_table ranges). */
function courseFitPlayerRadarVectorMerged(rows, prow) {
  const keys = courseFitRadarKeysFromTable();
  if (!prow) return keys.map(() => 0.5);
  const prm = mergedPlayerRowForDrivingFields(prow);
  const out = [];
  for (let i = 0; i < keys.length; i++) {
    const col = keys[i];
    const samples = rows
      .map((r) => courseFitPlayerRadarAxisRaw(mergedPlayerRowForDrivingFields(r), i))
      .filter(Number.isFinite);
    const { lo, hi } = courseFitMergedLoHiForCol(col, samples);
    const pv = courseFitPlayerRadarAxisRaw(prm, i);
    if (!Number.isFinite(pv)) {
      out.push(0.5);
      continue;
    }
    const span = hi - lo < 1e-9 ? 1 : hi - lo;
    out.push(clamp((pv - lo) / span, 0, 1));
  }
  return out;
}

function courseFitSimilarCoursesFromCourseTable(activeVk, venueRow) {
  const p = COURSE_TABLE_PAYLOAD;
  if (!p?.rows?.length || !venueRow) return [];
  const ref = courseFitVenue5Profile(venueRow);
  if (!ref || !ref.every(Number.isFinite)) return [];
  const out = [];
  for (const row of p.rows) {
    const nk = row._normKey || normCourseNameKey(String(row.course || ""));
    if (!nk || nk === activeVk) continue;
    const vec = courseFitVenue5Profile(row);
    if (!vec || !vec.every(Number.isFinite)) continue;
    const d = Math.hypot(...vec.map((x, j) => x - ref[j]));
    out.push({ ck: nk, dist: d, sim: 1 / (1 + d) });
  }
  out.sort((a, b) => b.sim - a.sim);
  return out.slice(0, 12);
}

/**
 * One or two axis indices where this venue differs most from tour / field average
 * (|venue − field|); the Who-fits table scores only these so categories stay focused.
 */
function courseFitVenueEmphasisAxisIndices(tour5, venue5) {
  const n = Math.min(tour5?.length || 0, venue5?.length || 0, COURSE_FIT_RADAR_SPOKE_LABELS.length);
  if (n < 1) return [];
  const scored = [];
  for (let i = 0; i < n; i++) {
    const stress = venue5[i] - tour5[i];
    scored.push({ i, abs: Math.abs(stress) });
  }
  scored.sort((a, b) => b.abs - a.abs);
  if (!scored[0]?.abs || scored[0].abs < 1e-6) return [scored[0].i];
  const out = [scored[0].i];
  if (
    scored.length > 1 &&
    scored[1].abs >= scored[0].abs * 0.35
  ) {
    out.push(scored[1].i);
  }
  return out.slice(0, 2);
}

/** Fit sums venue-emphasis axes; category is exactly one of those axes — where this player’s edge is largest (at most two distinct labels in the column). */
function courseFitPlayerCatAndFitOnAxes(tour5, venue5, player5, axisIdxs) {
  if (!player5?.length || !venue5?.length || !tour5?.length || !axisIdxs?.length) {
    return { cat: "—", fit: 0 };
  }
  const contribs = [];
  let fit = 0;
  for (const i of axisIdxs) {
    if (i < 0 || i >= player5.length) continue;
    const stress = venue5[i] - tour5[i];
    const skill = player5[i] - 0.5;
    const c = stress * skill;
    fit += c;
    contribs.push({ i, c });
  }
  if (!contribs.length) return { cat: "—", fit: 0 };
  contribs.sort((a, b) => (b.c !== a.c ? b.c - a.c : a.i - b.i));
  const top = contribs[0];
  if (!top || top.c <= 0) return { cat: "—", fit };
  return { cat: COURSE_FIT_RADAR_SPOKE_LABELS[top.i] || "—", fit };
}

function courseTableStaticDifficultyD() {
  const ev = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  if (!ev) return 0;
  const row = resolveCourseTableRowForNormKey(normCourseNameKey(ev));
  const v = num(row?.adj_score_to_par, NaN);
  const m = num(COURSE_TABLE_PAYLOAD?.means?.adj_score_to_par, NaN);
  if (!Number.isFinite(v) || !Number.isFinite(m)) return 0;
  return clamp(v - m, -3, 5);
}

function buildCourseFitTab() {
  const capEl = document.getElementById("course-fit-radar-caption");
  const legEl = document.getElementById("course-fit-radar-legend");
  const simList = document.getElementById("course-fit-similar-list");
  const simEmpty = document.getElementById("course-fit-similar-empty");
  const sel = document.getElementById("course-fit-player");
  const tbody = document.querySelector("#table-course-fit tbody");
  const theadHeading = document.getElementById("course-fit-table-heading");
  const canvas = document.getElementById("course-fit-radar-canvas");
  if (!tbody || !canvas) return;

  if (!COURSE_TABLE_PAYLOAD?.rows?.length) {
    void loadCourseTableJson().then(() => {
      if (activeAppTabId() === "course-fit") buildCourseFitTab();
    });
    if (capEl) capEl.textContent = "Loading course_table map…";
    if (legEl) legEl.innerHTML = "";
    return;
  }

  // Approach-bin SG (Course Breakdown mix) feeds Course Fit ratings — load once, then rebuild.
  if (!approachSkillByDgIdCache || !courseFitApproachBinWeightsCache) {
    void (async () => {
      await ensureApproachSkillByDgId();
      const pool = courseFitPlayerPool();
      const impact = await courseBreakdownApproachImpactSegments(pool);
      const venueName = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
      const ctRow = resolveCourseTableRowForNormKey(normCourseNameKey(venueName));
      courseFitSetApproachBinWeights(courseFitVenueApproachBinWeights(impact, ctRow));
      if (activeAppTabId() === "course-fit") buildCourseFitTab();
    })();
  }

  const eventVenueName = String(DATA?.meta?.course_used || DATA?.course_used || "this venue").trim() || "this venue";
  const eventVk = normCourseNameKey(eventVenueName);
  if (courseFitVenueEventKeyTracked !== eventVk) {
    courseFitVenueEventKeyTracked = eventVk;
    courseFitVenueFilterKey = null;
    courseFitSimilarSelectedKey = null;
    courseFitGolferDefaultApplied = false;
  }

  let courseKeys = Object.keys(COURSE_TABLE_PAYLOAD.byNormKey || {}).sort((a, b) => a.localeCompare(b));
  if (eventVk && !courseKeys.includes(eventVk)) {
    courseKeys.push(eventVk);
    courseKeys.sort((a, b) => a.localeCompare(b));
  }

  const venueSel = document.getElementById("course-fit-venue");
  if (venueSel) {
    venueSel.innerHTML = "";
    for (const ck of courseKeys) {
      const o = document.createElement("option");
      o.value = ck;
      o.textContent = courseFitPrettyCourseKey(ck);
      venueSel.appendChild(o);
    }
  }

  let activeVk = eventVk;
  if (courseFitVenueFilterKey && courseKeys.includes(courseFitVenueFilterKey)) {
    activeVk = courseFitVenueFilterKey;
  }
  if (venueSel && courseKeys.length) {
    if (courseKeys.includes(activeVk)) venueSel.value = activeVk;
    else {
      activeVk = courseKeys[0];
      venueSel.value = activeVk;
    }
  }

  const venueName = courseFitPrettyCourseKey(activeVk);
  const vk = activeVk;

  const rows = courseFitPlayerPool();
  const ctRow = resolveCourseTableRowForNormKey(vk);
  const tourCourseMean5 = courseFitTourCourseMean5();
  const field5 = courseFitField5FromRows(rows);
  const venue5 = courseFitVenue5Profile(ctRow) || tourCourseMean5;
  const similarRanked = courseFitSimilarCoursesFromCourseTable(vk, ctRow);
  const similarKeys = new Set(similarRanked.map((x) => x.ck));
  if (courseFitSimilarSelectedKey && !similarKeys.has(courseFitSimilarSelectedKey)) {
    courseFitSimilarSelectedKey = null;
  }
  const similarRow =
    courseFitSimilarSelectedKey && COURSE_TABLE_PAYLOAD?.byNormKey?.[courseFitSimilarSelectedKey]
      ? COURSE_TABLE_PAYLOAD.byNormKey[courseFitSimilarSelectedKey]
      : null;
  const similar5 = similarRow ? courseFitVenue5Profile(similarRow) : null;

  const similarDisplayName = courseFitSimilarSelectedKey
    ? courseFitPrettyCourseKey(courseFitSimilarSelectedKey)
    : "";

  if (capEl) capEl.textContent = venueName;

  if (sel) {
    const prev = sel.value;
    sel.innerHTML = "";
    const opt0 = document.createElement("option");
    opt0.value = "";
    opt0.textContent = "— None —";
    sel.appendChild(opt0);
    for (const r of rows) {
      const id = Math.round(num(r.dg_id, NaN));
      if (!Number.isFinite(id)) continue;
      const o = document.createElement("option");
      o.value = String(id);
      o.textContent = displayGolferName(String(r.player_name || ""));
      sel.appendChild(o);
    }
    if (prev && [...sel.options].some((x) => x.value === prev)) {
      sel.value = prev;
    } else if (!courseFitGolferDefaultApplied) {
      courseFitGolferDefaultApplied = true;
      const wantTf = (o) =>
        String(o.textContent || "")
          .trim()
          .toLowerCase()
          .includes("tommy fleetwood");
      const tfOpt = [...sel.options].find(wantTf);
      if (tfOpt) sel.value = tfOpt.value;
    }
    refreshGolferComboboxFromSelect("course-fit-player");
  }

  const dgSel = Math.round(num(sel?.value, NaN));
  const prow = rows.find((r) => Math.round(num(r.dg_id, NaN)) === dgSel);
  const player5 = courseFitPlayerRadarVectorMerged(rows, prow);

  if (legEl) {
    const selectedGolferName =
      (prow && displayGolferName(String(prow.player_name || ""))) || "Selected golfer";
    let html =
      '<span class="course-fit-leg-item"><span class="course-fit-leg-dash"></span> Field Avg</span>' +
      `<span class="course-fit-leg-item"><span class="course-fit-leg-green"></span> ${escapeHtml(venueName)}</span>`;
    if (similar5 && similarDisplayName) {
      html +=
        `<span class="course-fit-leg-item"><span class="course-fit-leg-blue" aria-hidden="true"></span> ${escapeHtml(similarDisplayName)}</span>`;
    }
    html += `<span class="course-fit-leg-item"><span class="course-fit-leg-gold"></span> ${escapeHtml(selectedGolferName)}</span>`;
    legEl.innerHTML = html;
  }

  drawCourseFitRadar(canvas, field5, venue5, player5, similar5);

  if (!courseFitRadarResizeBound && typeof window !== "undefined") {
    courseFitRadarResizeBound = true;
    window.addEventListener("resize", () => {
      if (activeAppTabId() === "course-fit") buildCourseFitTab();
    });
  }

  if (simList && simEmpty) {
    simList.innerHTML = "";
    if (!similarRanked.length) {
      simEmpty.hidden = false;
      courseFitSimilarSelectedKey = null;
    } else {
      simEmpty.hidden = true;
      let rank = 1;
      for (const s of similarRanked) {
        const li = document.createElement("li");
        li.className = "course-fit-similar-li";
        li.setAttribute("data-course-fit-ck", s.ck);
        li.setAttribute("role", "button");
        li.setAttribute("tabindex", "0");
        li.setAttribute(
          "aria-pressed",
          courseFitSimilarSelectedKey === s.ck ? "true" : "false",
        );
        if (courseFitSimilarSelectedKey === s.ck) li.classList.add("course-fit-similar-li-selected");
        li.innerHTML = `<span class="course-fit-sim-rank">${rank++}.</span><span class="course-fit-sim-name">${escapeHtml(
          courseFitPrettyCourseKey(s.ck),
        )}</span><span class="course-fit-sim-score">${(s.sim * 100).toFixed(0)}</span>`;
        simList.appendChild(li);
      }
    }
  }

  ensureCourseFitTableHead();

  const search = String(document.getElementById("course-fit-search")?.value || "")
    .trim()
    .toLowerCase();
  const archetypeRows = courseFitArchetypeTableRows(rows, tourCourseMean5, venue5, ctRow);

  tbody.innerHTML = "";
  if (theadHeading) {
    theadHeading.textContent = `Course ratings — ${venueName}`;
  }

  const marketKeys = ["win", "top_5", "top_10", "top_20"];
  const displayRows = [];
  for (const row of archetypeRows) {
    const nm = displayGolferName(String(row.r.player_name || ""));
    if (search && !nm.toLowerCase().includes(search)) continue;
    const dgId = Math.round(num(row.r.dg_id, NaN));
    const odds = {};
    for (const mk of marketKeys) odds[mk] = courseFitOutrightBestPriceOdds(mk, dgId);
    displayRows.push({ ...row, nm, dgId, odds });
  }

  let sortKey = String(courseFitTableSort.key || "rating");
  if (sortKey === "fit" || sortKey === "category" || sortKey === "archetype") sortKey = "rating";
  const sortDir = courseFitTableSort.dir > 0 ? 1 : -1;
  const axisSortMatch = /^axis_(\d+)$/.exec(sortKey);
  displayRows.sort((a, b) => {
    if (sortKey === "golfer") {
      const c = a.nm.localeCompare(b.nm);
      return c * sortDir || (b.archetypeZ - a.archetypeZ) * sortDir;
    }
    if (axisSortMatch) {
      const j = parseInt(axisSortMatch[1], 10);
      const av = a.axisZ[j];
      const bv = b.axisZ[j];
      const af = Number.isFinite(av);
      const bf = Number.isFinite(bv);
      if (af !== bf) return af ? -1 : 1;
      if (af && av !== bv) return (av - bv) * sortDir;
      return (b.archetypeZ - a.archetypeZ) || a.nm.localeCompare(b.nm);
    }
    if (sortKey === "rating") {
      const az = a.archetypeZ;
      const bz = b.archetypeZ;
      if (Number.isFinite(az) && Number.isFinite(bz) && az !== bz) return (az - bz) * sortDir;
      return (a.archetypeFit - b.archetypeFit) * sortDir || a.nm.localeCompare(b.nm);
    }
    if (marketKeys.includes(sortKey)) {
      const av = a.odds?.[sortKey]?.am;
      const bv = b.odds?.[sortKey]?.am;
      const af = Number.isFinite(av);
      const bf = Number.isFinite(bv);
      if (af !== bf) return af ? -1 : 1;
      if (af && av !== bv) return (av - bv) * sortDir;
      return (b.archetypeZ - a.archetypeZ) || a.nm.localeCompare(b.nm);
    }
    return (b.archetypeZ - a.archetypeZ) || a.nm.localeCompare(b.nm);
  });

  if (!displayRows.length) {
    const tr = document.createElement("tr");
    const td = document.createElement("td");
    td.colSpan = courseFitTableHeadColSpan();
    td.className = "text-muted";
    td.textContent = rows.length
      ? "No players match this search."
      : "No players in the field for this round.";
    tr.appendChild(td);
    tbody.appendChild(tr);
  } else {
    for (const row of displayRows) {
      const tr = document.createElement("tr");
      const tdN = document.createElement("td");
      tdN.className = "course-fit-col-golfer";
      tdN.textContent = row.nm;
      tr.appendChild(tdN);
      for (let j = 0; j < COURSE_FIT_RADAR_SPOKE_LABELS.length; j++) {
        const tdZ = document.createElement("td");
        const cell = formatCourseFitZCell(row.axisZ[j]);
        tdZ.className = cell.cls;
        tdZ.textContent = cell.text;
        tdZ.title = `${COURSE_FIT_RADAR_SPOKE_LABELS[j]} — skill vs field (green = above-average on this spoke)`;
        tr.appendChild(tdZ);
      }
      const tdA = document.createElement("td");
      const archCell = formatCourseFitZCell(row.archetypeZ);
      tdA.className = archCell.cls;
      tdA.title = `Venue-weighted fit ${row.archetypeFit >= 0 ? "+" : ""}${row.archetypeFit.toFixed(2)} (Σ spoke z × venue demand; matches radar emphasis)`;
      tdA.textContent = archCell.text;
      tr.appendChild(tdA);
      for (const mk of marketKeys) {
        const tdO = document.createElement("td");
        tdO.className = "num course-fit-out-td";
        const ob = row.odds?.[mk] || { html: "—" };
        tdO.innerHTML = ob.html;
        tr.appendChild(tdO);
      }
      tbody.appendChild(tr);
    }
  }
  updateCourseFitTableSortIndicators();

  const distPanel = document.getElementById("course-fit-subpanel-distributions");
  if (distPanel && !distPanel.hidden) {
    const bucket = propsGetSingleCourseBucketSync(vk);
    if (bucket?.entries?.length) buildCourseFitDistributionsPanel(vk);
    else void loadCourseFitDistributionsForVenue(vk);
  }
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function buildMatchupsTable() {
  const tbody = document.querySelector("#table-matchups tbody");
  const note = document.getElementById("matchups-source-note");
  if (!tbody) return;
  tbody.innerHTML = "";
  const msel = document.getElementById("matchups-market");
  const key = msel ? msel.value : "round_matchups";
  const pack = DATA.matchups && DATA.matchups[key];
  const list = pack && pack.match_list;
  if (typeof list === "string") {
    if (note) {
      note.hidden = true;
      note.textContent = "";
    }
    return;
  }
  if (note) note.hidden = true;
  if (!Array.isArray(list) || !list.length) {
    return;
  }
  const r = getModelRoundForEv();
  const elim = dgIdsEliminatedFromEventPostCut();
  for (const m of list) {
    const id1 = Math.round(num(m.p1_dg_id, NaN));
    const id2 = Math.round(num(m.p2_dg_id, NaN));
    const id3 = Math.round(num(m.p3_dg_id, NaN));
    const row1 = projectionPlayerRowForModelByIdOrName(id1, m.p1_player_name, r);
    const row2 = projectionPlayerRowForModelByIdOrName(id2, m.p2_player_name, r);
    const row3 = projectionPlayerRowForModelByIdOrName(id3, m.p3_player_name, r);
    const mu1 = effectiveMuSg(row1, id1, key);
    const mu2 = effectiveMuSg(row2, id2, key);
    const mu3 = effectiveMuSg(row3, id3, key);
    const odds = m.odds || {};
    const b1 = bestBookDecimalForSide(odds, "p1", { allowDatagolf: true });
    const b2 = bestBookDecimalForSide(odds, "p2", { allowDatagolf: true });
    const b3 = bestBookDecimalForSide(odds, "p3", { allowDatagolf: true });
    const isThree = key === "3_balls" && Number.isFinite(id3) && id3 > 0;
    if (elim.size && (elim.has(id1) || elim.has(id2) || (isThree && elim.has(id3)))) continue;
    const label = isThree
      ? `${m.p1_player_name || ""} / ${m.p2_player_name || ""} / ${m.p3_player_name || ""}`
      : `${m.p1_player_name || ""} vs ${m.p2_player_name || ""}`;
    const span = isThree ? 3 : 2;
    function row(side, name, modelPct, ev, bb) {
      const tr = document.createElement("tr");
      const td0 = document.createElement("td");
      if (side === 1) {
        td0.rowSpan = span;
        td0.textContent = label;
      }
      const td1 = document.createElement("td");
      td1.textContent = String(name || "");
      const td2 = document.createElement("td");
      td2.className = "num";
      td2.textContent = Number.isFinite(modelPct) ? `${(modelPct * 100).toFixed(1)}%` : "—";
      const td3 = document.createElement("td");
      td3.className = "num";
      if (Number.isFinite(ev)) {
        td3.textContent = `${(ev * 100).toFixed(1)}%`;
        td3.classList.add(ev >= 0 ? "ev-pos" : "ev-neg");
      } else td3.textContent = "—";
      const td4 = document.createElement("td");
      td4.className = "num best-book-td";
      if (bb.book && Number.isFinite(bb.dec)) {
        td4.innerHTML = `${bookBadgeHtml(bb.book)} <span class="best-book-odds">${bb.dec.toFixed(2)}</span>`;
      } else td4.textContent = "—";
      if (side === 1) tr.appendChild(td0);
      tr.appendChild(td1);
      tr.appendChild(td2);
      tr.appendChild(td3);
      tr.appendChild(td4);
      tbody.appendChild(tr);
    }
    if (isThree) {
      const [tp1, tp2, tp3] = threeBallModelProbsLiveBlended(mu1, mu2, mu3, row1, row2, row3);
      const ev1 = Number.isFinite(b1.dec) ? tp1 * b1.dec - 1 : NaN;
      const ev2 = Number.isFinite(b2.dec) ? tp2 * b2.dec - 1 : NaN;
      const ev3 = Number.isFinite(b3.dec) ? tp3 * b3.dec - 1 : NaN;
      row(1, m.p1_player_name, tp1, ev1, b1);
      row(2, m.p2_player_name, tp2, ev2, b2);
      row(3, m.p3_player_name, tp3, ev3, b3);
    } else {
      const p1m = matchupWinProbLiveBlended(mu1, mu2, key, row1, row2);
      const ev1 = Number.isFinite(b1.dec) ? p1m * b1.dec - 1 : NaN;
      const ev2 = Number.isFinite(b2.dec) ? (1 - p1m) * b2.dec - 1 : NaN;
      row(1, m.p1_player_name, p1m, ev1, b1);
      row(2, m.p2_player_name, 1 - p1m, ev2, b2);
    }
  }
}

function impliedPctFromBookField(v) {
  const p = bookImpliedProb01(v);
  if (!Number.isFinite(p) || p <= 0 || p >= 1) return NaN;
  return p * 100;
}

function impliedPctFromOutrightBookField(v) {
  const x = num(v, NaN);
  if (!Number.isFinite(x) || x <= 0) return NaN;
  if (x > 0 && x < 100) return x;
  if (x === 100) return NaN;
  return impliedPctFromBookField(x);
}

/**
 * DataGolf feeds sometimes substitute ~10% implied (~+900) on FanDuel/Betway/SkyBet win markets when a book has no real price (same float across much of the field). Skip those for ladder / best-book picks so Caesars-only junk does not dominate.
 */
function outrightFeedPlaceholderProbNaN(p01, marketKey, bookRaw) {
  if (!Number.isFinite(p01) || p01 <= 0 || p01 >= 1) return NaN;
  const mk = String(marketKey || "");
  const bk = normalizeEvSportsbookKey(bookRaw);
  if (mk === "win" && (bk === "fanduel" || bk === "betway" || bk === "skybet")) {
    if (p01 >= 0.098 && p01 <= 0.102) return NaN;
  }
  return p01;
}

function impliedProbFromOutrightRowBook(row, bk, marketKey) {
  if (!row || !bk) return NaN;
  const bkNorm = normalizeEvSportsbookKey(bk);
  const pct = impliedPctFromOutrightBookField(row[bk] ?? row[bkNorm]);
  if (!Number.isFinite(pct)) return NaN;
  let p01 = pct / 100;
  p01 = outrightFeedPlaceholderProbNaN(p01, marketKey, bk);
  return Number.isFinite(p01) ? p01 : NaN;
}

function outrightFinishRowsByMarketDg(dgId) {
  const markets = ["win", "top_5", "top_10", "top_20"];
  const id = Math.round(num(dgId, NaN));
  /** @type {Record<string, object | null>} */
  const rowsByM = Object.create(null);
  if (!Number.isFinite(id)) return rowsByM;
  for (const mk of markets) {
    const pack = DATA.outrights?.[mk];
    const row = Array.isArray(pack?.rows) ? pack.rows.find((r) => Math.round(num(r.dg_id, NaN)) === id) : null;
    rowsByM[mk] = row;
  }
  return rowsByM;
}

/**
 * Pick one book per player so finish-market cells share the same sportsbook.
 * Maximizes sum of per-market EV across the four ladders under the existing EV ratio caps.
 */
function outrightFinishLadderBestBookBundle(dgId, opts) {
  const markets = ["win", "top_5", "top_10", "top_20"];
  const rowsByM = outrightFinishRowsByMarketDg(dgId);
  /** @type {Record<string, number>} */
  const modelPs = Object.create(null);
  for (const mk of markets) {
    modelPs[mk] = modelProbOutrightFromRowOrProjections(rowsByM[mk] || {}, mk, opts);
  }
  const bookSet = new Set();
  for (const mk of markets) {
    const pack = DATA.outrights?.[mk];
    const bks = Array.isArray(pack?.bookKeys) ? pack.bookKeys : [];
    for (const k of bks) {
      if (k && k !== "datagolf" && outrightLadderSportsbookAllowed(k)) bookSet.add(normalizeEvSportsbookKey(k));
    }
  }
  const books = [...bookSet].sort((a, b) => a.localeCompare(b));
  let best = null;
  let bestScore = -Infinity;
  for (const bk of books) {
    const raw = markets.map((mk) => impliedProbFromOutrightRowBook(rowsByM[mk], bk, mk));
    let sumEv = 0;
    let nOk = 0;
    for (let i = 0; i < 4; i++) {
      const mk = markets[i];
      const pBook = raw[i];
      const modelP = modelPs[mk];
      if (!Number.isFinite(pBook) || !Number.isFinite(modelP) || modelP <= 0) continue;
      const ev = outrightEvFromModelAndBook(modelP, pBook, mk);
      if (!Number.isFinite(ev)) continue;
      sumEv += ev;
      nOk++;
    }
    if (nOk === 0) continue;
    const better =
      !best ||
      sumEv > bestScore + 1e-9 ||
      (Math.abs(sumEv - bestScore) <= 1e-9 && best && bk.localeCompare(best.book) < 0);
    if (better) {
      bestScore = sumEv;
      best = { book: bk, raw, modelPs, rowsByM };
    }
  }
  return best;
}

function outrightLogit(p) {
  const x = clamp(p, 1e-9, 1 - 1e-9);
  return Math.log(x / (1 - x));
}

function outrightInvlogit(t) {
  return 1 / (1 + Math.exp(-t));
}

/** Mean/std of tournament `current_score` (lower = better vs par) for outright nudging. */
function outrightFieldCurrentScoreStats() {
  const seen = new Set();
  const vals = [];
  for (const p of DATA.players || []) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id) || seen.has(id)) continue;
    const s = num(p.current_score, NaN);
    if (!Number.isFinite(s)) continue;
    seen.add(id);
    vals.push(s);
  }
  if (vals.length < 5) return null;
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  let v = 0;
  for (const s of vals) v += (s - mean) ** 2;
  const std = Math.sqrt(v / vals.length);
  if (!Number.isFinite(std) || std < 0.25) return null;
  return { mean, std, n: vals.length };
}

function outrightLiveTournamentContext() {
  const m = DATA?.meta || {};
  if (Number.isFinite(num(m.datagolf_live_current_round, NaN))) return true;
  return Boolean(String(m.datagolf_live_last_update || "").trim());
}

/**
 * Softmax win shares from field `current_score` (lower = better vs par). Used to blend with DG win
 * so model prices move with the live board even when placement API is slow.
 */
function outrightFieldScoreSoftmaxWinMap() {
  const byId = new Map();
  for (const p of DATA.players || []) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id) || byId.has(id)) continue;
    const s = num(p.current_score, NaN);
    if (!Number.isFinite(s)) continue;
    byId.set(id, s);
  }
  if (byId.size < 5) return new Map();
  const arr = [...byId.entries()];
  const scores = arr.map(([, s]) => s);
  const minS = Math.min(...scores);
  const maxS = Math.max(...scores);
  const spread = Math.max(0.5, maxS - minS);
  const T = spread * 0.42 + 0.85;
  let sum = 0;
  const wts = [];
  for (const [id, s] of arr) {
    const w = Math.exp(-(s - minS) / T);
    wts.push([id, w]);
    sum += w;
  }
  const out = new Map();
  for (const [id, w] of wts) out.set(id, w / sum);
  return out;
}

/** +EV only: optional score-driven probs when `meta.outright_ev_live_leaderboard_model` is true. */
function outrightEvLiveLeaderboardModelEnabled() {
  if (!outrightLiveTournamentContext()) return false;
  return DATA?.meta?.outright_ev_live_leaderboard_model === true;
}

let outrightEvLbProbCache = {
  sig: "",
  /** @type {Map<number, number>} */
  win: new Map(),
  /** @type {Map<number, number>} */
  top5: new Map(),
  /** @type {Map<number, number>} */
  top10: new Map(),
  /** @type {Map<number, number>} */
  top20: new Map(),
};

function randStdNormal() {
  let u = 0;
  let v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

function outrightEvLiveLeaderboardCacheSig() {
  const sigma = num(DATA?.meta?.outright_ev_live_leaderboard_sigma, NaN);
  const strokeNoise = Number.isFinite(sigma) && sigma > 0 ? sigma : 2.25;
  const nSimsRaw = Math.round(num(DATA?.meta?.outright_ev_live_leaderboard_mc_sims, NaN));
  const nSims = Number.isFinite(nSimsRaw) && nSimsRaw >= 100 ? Math.min(2500, nSimsRaw) : 420;
  const parts = [];
  for (const p of DATA.players || []) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id)) continue;
    const s = num(p.current_score, NaN);
    if (!Number.isFinite(s)) continue;
    parts.push(`${id}:${s}`);
  }
  parts.sort();
  return `${DATA.meta?.datagolf_live_last_update}|${strokeNoise}|${nSims}|${parts.join(";")}`;
}

/** Builds Maps dg_id -> P(market) for win (softmax on scores) and top_K (noisy rank MC). Safe to call repeatedly; keyed by score fingerprint. */
function ensureOutrightEvLiveLeaderboardProbCache() {
  const sig = outrightEvLiveLeaderboardCacheSig();
  if (outrightEvLbProbCache.sig === sig && outrightEvLbProbCache.win.size >= 5) return;

  const scoresById = new Map();
  for (const p of DATA.players || []) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id) || scoresById.has(id)) continue;
    const s = num(p.current_score, NaN);
    if (!Number.isFinite(s)) continue;
    scoresById.set(id, s);
  }
  if (scoresById.size < 5) {
    outrightEvLbProbCache = {
      sig: "",
      win: new Map(),
      top5: new Map(),
      top10: new Map(),
      top20: new Map(),
    };
    return;
  }

  outrightEvLbProbCache = {
    sig,
    win: new Map(),
    top5: new Map(),
    top10: new Map(),
    top20: new Map(),
  };

  const winSm = outrightFieldScoreSoftmaxWinMap();
  for (const [id, pw] of winSm) outrightEvLbProbCache.win.set(id, pw);

  const sigma = num(DATA?.meta?.outright_ev_live_leaderboard_sigma, NaN);
  const strokeNoise = Number.isFinite(sigma) && sigma > 0 ? sigma : 2.25;
  const nSimsRaw = Math.round(num(DATA?.meta?.outright_ev_live_leaderboard_mc_sims, NaN));
  const nSims = Number.isFinite(nSimsRaw) && nSimsRaw >= 100 ? Math.min(2500, nSimsRaw) : 420;

  const ids = [...scoresById.keys()];
  /** @type {Map<number, number>} */
  const mkCounts = () => {
    const m = new Map();
    for (const id of ids) m.set(id, 0);
    return m;
  };
  const c5 = mkCounts();
  const c10 = mkCounts();
  const c20 = mkCounts();

  for (let rep = 0; rep < nSims; rep++) {
    const perf = ids.map((id) => ({
      id,
      key: scoresById.get(id) + randStdNormal() * strokeNoise,
    }));
    perf.sort((a, b) => a.key - b.key);
    const n = perf.length;
    for (let i = 0; i < Math.min(5, n); i++) {
      const id = perf[i].id;
      c5.set(id, c5.get(id) + 1);
    }
    for (let i = 0; i < Math.min(10, n); i++) {
      const id = perf[i].id;
      c10.set(id, c10.get(id) + 1);
    }
    for (let i = 0; i < Math.min(20, n); i++) {
      const id = perf[i].id;
      c20.set(id, c20.get(id) + 1);
    }
  }

  for (const id of ids) {
    outrightEvLbProbCache.top5.set(id, c5.get(id) / nSims);
    outrightEvLbProbCache.top10.set(id, c10.get(id) / nSims);
    outrightEvLbProbCache.top20.set(id, c20.get(id) / nSims);
  }
}

/** Alpha Caddie outright probs from composite ratings + tournament MC (not DG placement / dg_model). */
const TOURNAMENT_MC_MU_MULT = [1.0, 0.99, 0.97, 0.95];
const TOURNAMENT_MC_SD_MULT = [1.0, 1.01, 1.03, 1.05];
const TOURNAMENT_MC_FORM_SD = 0.25;

let outrightAlphaModelProbCache = {
  sig: "",
  win: new Map(),
  top5: new Map(),
  top10: new Map(),
  top20: new Map(),
  make_cut: new Map(),
  frl: new Map(),
};

function tournamentMcLognSdlog() {
  const raw = num(DATA?.meta?.outright_model_mc_logn_sdlog, 0.45);
  return clamp(Number.isFinite(raw) ? raw : 0.45, 0.05, 1.5);
}

function drawShiftedLognormal(meanX, sdX, sdlogOpt) {
  const sdlog = sdlogOpt != null ? sdlogOpt : tournamentMcLognSdlog();
  let mx = num(meanX, 0);
  const sx = num(sdX, NaN);
  if (!Number.isFinite(sx) || sx <= 0) return mx;
  if (!Number.isFinite(sdlog) || sdlog <= 0) return mx + randStdNormal() * sx;
  const cv = Math.sqrt(Math.exp(sdlog * sdlog) - 1);
  if (!Number.isFinite(cv) || cv <= 0) return mx + randStdNormal() * sx;
  const meanY = sx / cv;
  if (!Number.isFinite(meanY) || meanY <= 0) return mx + randStdNormal() * sx;
  const ml = Math.log(meanY) - 0.5 * sdlog * sdlog;
  const eps = Math.exp(ml + sdlog * randStdNormal()) - meanY;
  return mx + eps;
}

function tournamentScoringBasisFromData() {
  const par = coursePar18FromData();
  const basis = DATA?.meta?.projection_course_basis || {};
  const baseline = num(basis.venue_avg_round_score, NaN);
  const avgStp = num(basis.venue_avg_score_to_par, NaN);
  return {
    par,
    baseline: Number.isFinite(baseline) ? baseline : par + 3.2,
    avgStp: Number.isFinite(avgStp) ? avgStp : 3.2,
  };
}

/** Per-round composite rating for tournament MC (μ_SG + round_sd, all projection layers). */
function tournamentMcRatingFromRow(row, dgId) {
  const base = weatherAdjustedMuSg(row);
  if (!Number.isFinite(base)) return null;
  let muSg = base + pricingModeMuSgBonus(dgId) + priorRoundCourseMuSgDelta(row);
  if (outrightLiveTournamentContext() && liveRowMatchesDgLiveRound(row)) {
    muSg += liveCurrentRoundMuSgDelta(row);
  }
  const roundSd = clamp(num(row?.round_sd, 2.75), 2.0, 3.5);
  return { muSg: clamp(muSg, -4, 4), roundSd };
}

function tournamentMcLiveRoundPartialStp(row) {
  const thru = Math.round(num(row?.dg_live_thru, NaN));
  const today = num(row?.dg_live_today, NaN);
  if (!Number.isFinite(thru) || thru < 1 || thru >= 18) return 0;
  if (!Number.isFinite(today)) return 0;
  return today;
}

function simPlayerTournamentStpForMc(entry, formShock, ctx) {
  const { baseline, avgStp, par, liveR, hasLive, lognSdlog } = ctx;
  const { id, currentScore, ratings } = entry;

  if (!hasLive || !Number.isFinite(currentScore)) {
    let totalStp = 0;
    let r1Stp = NaN;
    for (let r = 1; r <= 4; r++) {
      const rt = ratings[r - 1];
      if (!rt) return null;
      const sg = drawShiftedLognormal(
        rt.muSg * TOURNAMENT_MC_MU_MULT[r - 1] + formShock,
        rt.roundSd * TOURNAMENT_MC_SD_MULT[r - 1],
        lognSdlog,
      );
      const roundStp = avgStp - sg;
      if (r === 1) r1Stp = roundStp;
      totalStp += roundStp;
    }
    return { totalStp, r1Stp };
  }

  let totalStp = currentScore;
  let r1Stp = NaN;
  const startR = Math.max(1, Math.min(4, liveR));

  for (let r = startR; r <= 4; r++) {
    const rt = ratings[r - 1];
    if (!rt) return null;
    const sg = drawShiftedLognormal(
      rt.muSg * TOURNAMENT_MC_MU_MULT[r - 1] + formShock,
      rt.roundSd * TOURNAMENT_MC_SD_MULT[r - 1],
      lognSdlog,
    );
    const roundStp = avgStp - sg;
    if (r === 1 && startR === 1) r1Stp = roundStp;

    if (r === startR) {
      const liveRow = projectionPlayerRowForModel(id, r);
      const partial = liveRow ? tournamentMcLiveRoundPartialStp(liveRow) : 0;
      totalStp += roundStp - partial;
    } else {
      totalStp += roundStp;
      if (r === 1) r1Stp = roundStp;
    }
  }
  return { totalStp, r1Stp };
}

/** Cheap key for pre-baked outright sim cache (no per-player rating scan). */
function outrightAlphaModelBakeCacheKey() {
  const bake = DATA?.meta?.outright_sim_probs;
  return [
    `rev${projectionsDataRev}`,
    `ba${bake?.baked_at || ""}`,
    `lt${bake?.live_through || ""}`,
    `lu${DATA?.meta?.datagolf_live_last_update || ""}`,
  ].join("|");
}

function outrightAlphaModelBrowserMcAllowed() {
  if (DATA?.meta?.outright_model_mc_in_browser === true) return true;
  if (DATA?.meta?.outright_model_mc_in_browser === false) return false;
  const bake = DATA?.meta?.outright_sim_probs?.by_dg;
  return !(bake && typeof bake === "object" && Object.keys(bake).length >= 5);
}

function loadOutrightAlphaModelCacheFromBaked(cacheKey) {
  const bake = DATA?.meta?.outright_sim_probs;
  const byDg = bake?.by_dg;
  if (!byDg || typeof byDg !== "object") return false;

  const liveLu = String(DATA?.meta?.datagolf_live_last_update || "");
  const bakeLive = String(bake.live_through || "");
  if (bakeLive) {
    if (!liveLu || bakeLive !== liveLu) return false;
  } else if (outrightLiveTournamentContext() && liveLu) {
    return false;
  }

  const next = {
    sig: cacheKey,
    win: new Map(),
    top5: new Map(),
    top10: new Map(),
    top20: new Map(),
    make_cut: new Map(),
    frl: new Map(),
  };
  for (const [idStr, probs] of Object.entries(byDg)) {
    const id = Math.round(num(idStr, NaN));
    if (!Number.isFinite(id) || !probs || typeof probs !== "object") continue;
    if (Number.isFinite(num(probs.win, NaN))) next.win.set(id, num(probs.win));
    if (Number.isFinite(num(probs.top_5, NaN))) next.top5.set(id, num(probs.top_5));
    if (Number.isFinite(num(probs.top_10, NaN))) next.top10.set(id, num(probs.top_10));
    if (Number.isFinite(num(probs.top_20, NaN))) next.top20.set(id, num(probs.top_20));
    if (Number.isFinite(num(probs.make_cut, NaN))) next.make_cut.set(id, num(probs.make_cut));
    if (Number.isFinite(num(probs.frl, NaN))) next.frl.set(id, num(probs.frl));
  }
  if (next.win.size < 5) return false;
  outrightAlphaModelProbCache = next;
  return true;
}

function hydrateOutrightAlphaModelProbCacheFromPayload() {
  const key = outrightAlphaModelBakeCacheKey();
  if (!loadOutrightAlphaModelCacheFromBaked(key)) {
    outrightAlphaModelProbCache = {
      sig: "",
      win: new Map(),
      top5: new Map(),
      top10: new Map(),
      top20: new Map(),
      make_cut: new Map(),
      frl: new Map(),
    };
  }
}

function tournamentMcSimsForBrowser() {
  const capRaw = Math.round(num(DATA?.meta?.outright_model_mc_sims_browser, 280));
  const browserCap = Number.isFinite(capRaw) && capRaw >= 80 ? Math.min(400, capRaw) : 280;
  const nSimsRaw = Math.round(num(DATA?.meta?.outright_model_mc_sims, NaN));
  if (Number.isFinite(nSimsRaw) && nSimsRaw >= 100) {
    return Math.min(browserCap, Math.min(2500, nSimsRaw));
  }
  return browserCap;
}

/** Monte Carlo tournament outcomes from composite μ_SG ratings (shifted log-normal rounds). */
function ensureOutrightAlphaModelProbCache() {
  const cacheKey = outrightAlphaModelBakeCacheKey();
  if (outrightAlphaModelProbCache.sig === cacheKey && outrightAlphaModelProbCache.win.size >= 5) return;
  if (loadOutrightAlphaModelCacheFromBaked(cacheKey)) return;
  if (!outrightAlphaModelBrowserMcAllowed()) return;

  const scoring = tournamentScoringBasisFromData();
  const nSims = tournamentMcSimsForBrowser();
  const liveR = Math.max(1, Math.min(4, Math.round(num(DATA?.meta?.datagolf_live_current_round, NaN)) || 1));
  const hasLive = outrightLiveTournamentContext();
  const lognSdlog = tournamentMcLognSdlog();

  const scoreByDg = new Map();
  for (const pr of DATA.players || []) {
    const dg = Math.round(num(pr.dg_id, NaN));
    const s = num(pr.current_score, NaN);
    if (Number.isFinite(dg) && Number.isFinite(s) && !scoreByDg.has(dg)) scoreByDg.set(dg, s);
  }

  const field = [];
  const seen = new Set();
  for (const p of DATA.players || []) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id) || seen.has(id)) continue;
    if (!samePlayerRound(p, 1)) continue;
    seen.add(id);

    const ratings = [];
    let ok = true;
    for (let rnd = 1; rnd <= 4; rnd++) {
      const row = projectionPlayerRowForModel(id, rnd);
      const rt = row ? tournamentMcRatingFromRow(row, id) : null;
      if (!rt) {
        ok = false;
        break;
      }
      ratings.push(rt);
    }
    if (!ok) continue;

    const currentScore = scoreByDg.get(id) ?? NaN;
    field.push({ id, ratings, currentScore });
  }

  if (field.length < 5) {
    outrightAlphaModelProbCache = {
      sig: "",
      win: new Map(),
      top5: new Map(),
      top10: new Map(),
      top20: new Map(),
      make_cut: new Map(),
      frl: new Map(),
    };
    return;
  }

  const cutLine = Math.min(65, Math.max(10, Math.floor(field.length * 0.42)));
  const mkCounts = () => {
    const m = new Map();
    for (const f of field) m.set(f.id, 0);
    return m;
  };
  const winC = mkCounts();
  const c5 = mkCounts();
  const c10 = mkCounts();
  const c20 = mkCounts();
  const cCut = mkCounts();
  const cFrl = mkCounts();

  const ctx = { ...scoring, liveR, hasLive, lognSdlog };

  for (let rep = 0; rep < nSims; rep++) {
    const formShocks = field.map(() => drawShiftedLognormal(0, TOURNAMENT_MC_FORM_SD, lognSdlog));
    const perf = [];
    for (let i = 0; i < field.length; i++) {
      const sim = simPlayerTournamentStpForMc(field[i], formShocks[i], ctx);
      if (!sim) continue;
      perf.push({ id: field[i].id, totalStp: sim.totalStp, r1Stp: sim.r1Stp });
    }
    if (perf.length < 5) continue;

    perf.sort((a, b) => {
      const d = a.totalStp - b.totalStp;
      if (d !== 0) return d;
      return Math.random() - 0.5;
    });
    winC.set(perf[0].id, winC.get(perf[0].id) + 1);
    const n = perf.length;
    for (let i = 0; i < Math.min(5, n); i++) c5.set(perf[i].id, c5.get(perf[i].id) + 1);
    for (let i = 0; i < Math.min(10, n); i++) c10.set(perf[i].id, c10.get(perf[i].id) + 1);
    for (let i = 0; i < Math.min(20, n); i++) c20.set(perf[i].id, c20.get(perf[i].id) + 1);
    for (let i = 0; i < Math.min(cutLine, n); i++) cCut.set(perf[i].id, cCut.get(perf[i].id) + 1);
    perf.sort((a, b) => {
      const d = a.r1Stp - b.r1Stp;
      if (d !== 0) return d;
      return Math.random() - 0.5;
    });
    cFrl.set(perf[0].id, cFrl.get(perf[0].id) + 1);
  }

  const clampProb = (p) => clamp(p, 0.001, 0.95);
  const next = {
    sig: cacheKey,
    win: new Map(),
    top5: new Map(),
    top10: new Map(),
    top20: new Map(),
    make_cut: new Map(),
    frl: new Map(),
  };
  for (const f of field) {
    const id = f.id;
    next.win.set(id, clampProb(winC.get(id) / nSims));
    next.top5.set(id, clampProb(c5.get(id) / nSims));
    next.top10.set(id, clampProb(c10.get(id) / nSims));
    next.top20.set(id, clampProb(c20.get(id) / nSims));
    next.make_cut.set(id, clampProb(cCut.get(id) / nSims));
    next.frl.set(id, clampProb(cFrl.get(id) / nSims));
  }
  outrightAlphaModelProbCache = next;
}

function modelProbOutrightAlphaModelLookup(outrightRow, marketKey) {
  const id = Math.round(num(outrightRow?.dg_id, NaN));
  if (!Number.isFinite(id)) return NaN;
  ensureOutrightAlphaModelProbCache();
  if (!outrightAlphaModelProbCache.sig || outrightAlphaModelProbCache.win.size < 5) return NaN;
  const mk = String(marketKey || "");
  let m = null;
  if (mk === "win") m = outrightAlphaModelProbCache.win;
  else if (mk === "top_5") m = outrightAlphaModelProbCache.top5;
  else if (mk === "top_10") m = outrightAlphaModelProbCache.top10;
  else if (mk === "top_20") m = outrightAlphaModelProbCache.top20;
  else if (mk === "make_cut") m = outrightAlphaModelProbCache.make_cut;
  else if (mk === "frl") m = outrightAlphaModelProbCache.frl;
  else if (mk === "mc") {
    const pCut = outrightAlphaModelProbCache.make_cut.get(id);
    if (!Number.isFinite(pCut)) return NaN;
    return clamp(1 - pCut, 1e-6, 1 - 1e-6);
  } else return NaN;
  const p = m.get(id);
  if (!Number.isFinite(p) || p <= 0 || p >= 1) return NaN;
  return clamp(p, 1e-6, 1 - 1e-6);
}

function outrightUseDgPlacementProbs() {
  return DATA?.meta?.outright_use_dg_placement_probs === true;
}

/** Legacy DataGolf preds/pre-tournament placement on projection rows (opt-in only). */
function modelProbOutrightFromDgPlacement(rowPlayer, marketKey) {
  const col =
    marketKey === "win"
      ? "win"
      : marketKey === "top_5"
        ? "top_5"
        : marketKey === "top_10"
          ? "top_10"
          : marketKey === "top_20"
            ? "top_20"
            : marketKey === "make_cut" || marketKey === "mc"
              ? "make_cut"
              : "win";
  const rawVal = rowPlayer ? rowPlayer[col] : undefined;
  if (rawVal == null || rawVal === "") return NaN;
  let baseP = datagolfModelProb01(rawVal);
  if (!Number.isFinite(baseP) || baseP <= 0) return NaN;
  if (marketKey === "mc") return clamp(1 - baseP, 1e-6, 1 - 1e-6);
  return clamp(baseP, 1e-6, 1 - 1e-6);
}

function finalizeOutrightModelProb(rowPlayer, marketKey, baseP) {
  if (!Number.isFinite(baseP) || baseP <= 0 || baseP >= 1) return NaN;
  if (marketKey === "mc") {
    let pCut = outrightProbWithLiveScoreNudge(rowPlayer, "make_cut", baseP);
    pCut = outrightProbWithPricingModeNudge(rowPlayer, "make_cut", pCut);
    return clamp(1 - pCut, 1e-6, 1 - 1e-6);
  }
  let p = outrightProbWithLiveScoreNudge(rowPlayer, marketKey, baseP);
  p = outrightProbWithPricingModeNudge(rowPlayer, marketKey, p);
  return clamp(p, 1e-6, 1 - 1e-6);
}

/** Lookup +EV live leaderboard model prob for one outright row + market (win | top_5 | top_10 | top_20). */
function modelProbOutrightLiveLeaderboardEvLookup(outrightRow, marketKey) {
  const id = Math.round(num(outrightRow?.dg_id, NaN));
  if (!Number.isFinite(id)) return NaN;
  ensureOutrightEvLiveLeaderboardProbCache();
  if (!outrightEvLbProbCache.sig || outrightEvLbProbCache.win.size < 5) return NaN;
  const mk = String(marketKey || "");
  let m = null;
  if (mk === "win") m = outrightEvLbProbCache.win;
  else if (mk === "top_5") m = outrightEvLbProbCache.top5;
  else if (mk === "top_10") m = outrightEvLbProbCache.top10;
  else if (mk === "top_20") m = outrightEvLbProbCache.top20;
  else return NaN;
  const p = m.get(id);
  if (!Number.isFinite(p) || p <= 0 || p >= 1) return NaN;
  return clamp(p, 1e-6, 1 - 1e-6);
}

/**
 * Nudge placement probs using leaderboard `current_score` vs the field (DataGolf: lower = better).
 * Scaled down when preds/in-play already supplied placement so we do not double-count DG's model.
 * Off by default — +EV uses raw export placement unless meta.outright_live_score_placement_nudge is true.
 */
function outrightProbWithLiveScoreNudge(rowPlayer, marketKey, baseP) {
  if (!Number.isFinite(baseP) || baseP <= 0 || baseP >= 1) return baseP;
  if (DATA?.meta?.outright_live_score_placement_nudge !== true) return baseP;
  if (!outrightLiveTournamentContext()) return baseP;
  const fs = outrightFieldCurrentScoreStats();
  if (!fs) return baseP;
  const s = num(rowPlayer?.current_score, NaN);
  if (!Number.isFinite(s)) return baseP;
  const zAdv = (fs.mean - s) / fs.std;
  if (!Number.isFinite(zAdv)) return baseP;
  const fromApi = Boolean(rowPlayer?.dg_live_placement_from_api);
  const apiScale = fromApi ? 0.82 : 1;
  const k =
    marketKey === "win"
      ? 0.42
      : marketKey === "top_5"
        ? 0.3
        : marketKey === "top_10"
          ? 0.22
            : marketKey === "top_20"
            ? 0.15
            : marketKey === "make_cut"
              ? 0.24
              : 0;
  const t = outrightLogit(baseP) + apiScale * k * clamp(zAdv, -2.8, 2.8);
  return clamp(outrightInvlogit(t), 1e-6, 1 - 1e-6);
}

/** +EV / model American: tilt placement probs using the same μ_SG bonus as O/U (pricing mode + skill). */
function outrightProbWithPricingModeNudge(rowPlayer, marketKey, baseP) {
  if (!Number.isFinite(baseP) || baseP <= 0 || baseP >= 1) return baseP;
  const id = Math.round(num(rowPlayer?.dg_id, NaN));
  if (!Number.isFinite(id)) return baseP;
  const b = pricingModeMuSgBonus(id);
  if (!Number.isFinite(b) || Math.abs(b) < 1e-10) return baseP;
  const mk = String(marketKey || "");
  const k =
    mk === "win"
      ? 0.52
      : mk === "top_5"
        ? 0.36
        : mk === "top_10"
          ? 0.26
          : mk === "top_20"
            ? 0.18
            : mk === "make_cut" || mk === "mc"
              ? 0.22
              : mk === "frl"
                ? 0.42
                : 0.3;
  const t = outrightLogit(baseP) + k * b;
  return clamp(outrightInvlogit(t), 1e-6, 1 - 1e-6);
}

function modelProbOutrightMarket(rowPlayer, marketKey) {
  const id = Math.round(num(rowPlayer?.dg_id, NaN));
  const pAlpha = Number.isFinite(id) ? modelProbOutrightAlphaModelLookup({ dg_id: id }, marketKey) : NaN;
  if (Number.isFinite(pAlpha) && pAlpha > 0) {
    return finalizeOutrightModelProb(rowPlayer, marketKey, pAlpha);
  }
  if (!outrightUseDgPlacementProbs()) return NaN;
  const pDg = modelProbOutrightFromDgPlacement(rowPlayer, marketKey);
  if (!Number.isFinite(pDg) || pDg <= 0) return NaN;
  return finalizeOutrightModelProb(rowPlayer, marketKey, pDg);
}

/**
 * Outrights "Model" fair price: Alpha Caddie projection MC first; DataGolf placement only when
 * `meta.outright_use_dg_placement_probs` is true. Optional `opts.evLiveLeaderboard` for score-only board.
 */
function modelProbOutrightFromRowOrProjections(outrightRow, marketKey, opts) {
  const id = Math.round(num(outrightRow?.dg_id, NaN));
  const evLb = opts && opts.evLiveLeaderboard === true && outrightEvLiveLeaderboardModelEnabled();
  if (evLb) {
    const pLb = modelProbOutrightLiveLeaderboardEvLookup(outrightRow, marketKey);
    if (Number.isFinite(pLb) && pLb > 0) {
      let prowLb = Number.isFinite(id) ? projectionRowWithPlacementMerged(id) : null;
      if (!prowLb && outrightRow?.player_name) {
        prowLb = projectionPlayerRowForModelByIdOrName(NaN, outrightRow.player_name, getModelRoundForEv());
      }
      return finalizeOutrightModelProb(prowLb || {}, marketKey, pLb);
    }
  }

  let prow = Number.isFinite(id) ? projectionRowWithPlacementMerged(id) : null;
  if (!prow && outrightRow?.player_name) {
    prow = projectionPlayerRowForModelByIdOrName(NaN, outrightRow.player_name, getModelRoundForEv());
  }

  const pAlpha = modelProbOutrightAlphaModelLookup(outrightRow, marketKey);
  if (Number.isFinite(pAlpha) && pAlpha > 0) {
    return finalizeOutrightModelProb(prow || {}, marketKey, pAlpha);
  }

  if (!outrightUseDgPlacementProbs()) return NaN;

  const scrapedModelPct = num(outrightRow?.dg_model, NaN);
  if (Number.isFinite(scrapedModelPct) && scrapedModelPct > 0 && scrapedModelPct < 100) {
    const p0 = clamp(scrapedModelPct / 100, 1e-6, 1 - 1e-6);
    return finalizeOutrightModelProb(prow || {}, marketKey, p0);
  }

  const fromDg = modelProbOutrightFromDgPlacement(prow || {}, marketKey);
  if (Number.isFinite(fromDg) && fromDg > 0) {
    return finalizeOutrightModelProb(prow || {}, marketKey, fromDg);
  }

  return NaN;
}

let outrightSort = { key: "player", dir: 1 };

function buildOutrightsTableBodyOnly() {
  const table = document.getElementById("table-outrights");
  if (!table) return;
  const msel = document.getElementById("outright-market");
  const mk = msel ? msel.value : "win";
  const pack = DATA.outrights && DATA.outrights[mk];
  const tbody = table.querySelector("tbody");
  if (!tbody || !pack || !Array.isArray(pack.rows)) return;
  const bookKeys = Array.isArray(pack.bookKeys) ? pack.bookKeys.filter((k) => k && k !== "datagolf") : [];
  const elim = dgIdsEliminatedFromEventPostCut();
  const outrightRowOk =
    mk === "make_cut" || mk === "mc"
      ? () => true
      : (row) => !elim.has(Math.round(num(row.dg_id, NaN)));
  const finishMk = mk === "win" || mk === "top_5" || mk === "top_10" || mk === "top_20";
  const rows = pack.rows.filter(outrightRowOk).map((row) => {
    const id = Math.round(num(row.dg_id, NaN));
    if (finishMk) {
      const bundle = outrightFinishLadderBestBookBundle(id);
      if (bundle) {
        const idx = ["win", "top_5", "top_10", "top_20"].indexOf(mk);
        const pBook = bundle.raw[idx];
        const mp = bundle.modelPs[mk];
        if (Number.isFinite(pBook) && Number.isFinite(mp) && mp > 0) {
          const ev = outrightEvFromModelAndBook(mp, pBook, mk);
          if (Number.isFinite(ev)) {
            return {
              row,
              modelP: mp,
              bestBook: bundle.book,
              bestAm: americanFromImpliedProb(pBook),
              bestEv: ev,
            };
          }
        }
      }
    }
    let modelP = modelProbOutrightFromRowOrProjections(row, mk);
    let bestBook = "";
    let bestAm = NaN;
    let bestEv = NaN;
    for (const bk of bookKeys) {
      const pct = impliedPctFromOutrightBookField(row[bk]);
      if (!Number.isFinite(pct) || pct <= 0) continue;
      let pBook = pct / 100;
      pBook = outrightFeedPlaceholderProbNaN(pBook, mk, bk);
      if (!Number.isFinite(pBook) || pBook <= 0 || pBook >= 1) continue;
      if (!Number.isFinite(modelP) || modelP <= 0) continue;
      const ev = outrightEvFromModelAndBook(modelP, pBook, mk);
      if (!Number.isFinite(ev)) continue;
      const am = americanFromImpliedProb(pBook);
      if (!Number.isFinite(bestEv) || ev > bestEv) {
        bestEv = ev;
        bestBook = bk;
        bestAm = am;
      }
    }
    return {
      row,
      modelP,
      bestBook,
      bestAm: Number.isFinite(bestAm) ? Math.round(bestAm) : bestAm,
      bestEv,
    };
  });

  function sortVal(item, key) {
    if (key === "player") return String(item.row.player_name || "").toLowerCase();
    if (key === "model") return num(item.modelP, -1);
    if (key === "ev") return num(item.bestEv, -1e9);
    if (key === "best") return num(item.bestAm, 0);
    const pct = impliedPctFromBookField(item.row[key]);
    return num(pct, -1);
  }

  const sk = outrightSort.key;
  const sd = outrightSort.dir;
  rows.sort((a, b) => {
    const va = sortVal(a, sk);
    const vb = sortVal(b, sk);
    if (va < vb) return -sd;
    if (va > vb) return sd;
    return 0;
  });

  tbody.innerHTML = "";
  let i = 0;
  for (const it of rows) {
    const tr = document.createElement("tr");
    tr.className = "outrights-data-row" + (i % 2 ? " outrights-row-alt" : "");
    const nameTd = document.createElement("td");
    nameTd.textContent = String(it.row.player_name || "");
    tr.appendChild(nameTd);
    for (const bk of bookKeys) {
      const td = document.createElement("td");
      td.className = "num";
      const pct = impliedPctFromBookField(it.row[bk]);
      td.textContent = Number.isFinite(pct) ? `${pct.toFixed(1)}%` : "—";
      tr.appendChild(td);
    }
    const mTd = document.createElement("td");
    mTd.className = "num";
    mTd.textContent = Number.isFinite(it.modelP) ? `${(it.modelP * 100).toFixed(1)}%` : "—";
    tr.appendChild(mTd);
    const evTd = document.createElement("td");
    evTd.className = "num";
    if (Number.isFinite(it.bestEv)) {
      evTd.textContent = `${(it.bestEv * 100).toFixed(1)}%`;
      evTd.classList.add(it.bestEv >= 0 ? "ev-pos" : "ev-neg");
    } else evTd.textContent = "—";
    tr.appendChild(evTd);
    const bbTd = document.createElement("td");
    bbTd.className = "num best-book-td";
    if (it.bestBook && Number.isFinite(it.bestAm)) {
      bbTd.innerHTML = `${bookBadgeHtml(it.bestBook)} <span class="best-book-odds">${formatAmerican(it.bestAm)}</span>`;
    } else bbTd.textContent = "—";
    tr.appendChild(bbTd);
    tbody.appendChild(tr);
    i++;
  }
}

function buildOutrightsTable() {
  const table = document.getElementById("table-outrights");
  if (!table) return;
  const msel = document.getElementById("outright-market");
  const mk = msel ? msel.value : "win";
  const pack = DATA.outrights && DATA.outrights[mk];
  const thead = table.querySelector("thead");
  const tbody = table.querySelector("tbody");
  if (!thead || !tbody) return;
  const bookKeys = pack && Array.isArray(pack.bookKeys) ? pack.bookKeys.filter((k) => k && k !== "datagolf") : [];
  const trh = document.createElement("tr");
  const thPlayer = document.createElement("th");
  thPlayer.className = "sortable";
  thPlayer.dataset.sortKey = "player";
  thPlayer.innerHTML = `Player<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`;
  trh.appendChild(thPlayer);
  for (const bk of bookKeys) {
    const th = document.createElement("th");
    th.className = "num book-col-th sortable";
    th.dataset.sortKey = bk;
    th.innerHTML = `<span class="book-th-inner"><span class="book-badge-inline" title="${bk}">${bk.slice(0, 3).toUpperCase()}</span></span><span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`;
    trh.appendChild(th);
  }
  const thM = document.createElement("th");
  thM.className = "num sortable";
  thM.dataset.sortKey = "model";
  thM.innerHTML = `Model<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`;
  trh.appendChild(thM);
  const thE = document.createElement("th");
  thE.className = "num sortable";
  thE.dataset.sortKey = "ev";
  thE.innerHTML = `EV<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`;
  trh.appendChild(thE);
  const thB = document.createElement("th");
  thB.className = "num sortable";
  thB.dataset.sortKey = "best";
  thB.innerHTML = `Best Book<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span>`;
  trh.appendChild(thB);
  thead.innerHTML = "";
  thead.appendChild(trh);
  buildOutrightsTableBodyOnly();
  updateOutrightsSortIndicators();
}

function updateOutrightsSortIndicators() {
  const table = document.getElementById("table-outrights");
  if (!table) return;
  const ths = table.querySelectorAll("thead th.sortable");
  ths.forEach((th) => {
    const key = th.dataset.sortKey;
    const up = th.querySelector(".sort-up");
    const dn = th.querySelector(".sort-down");
    if (up) up.classList.toggle("active", key === outrightSort.key && outrightSort.dir > 0);
    if (dn) dn.classList.toggle("active", key === outrightSort.key && outrightSort.dir < 0);
  });
}

let outrightsSortInited = false;

function initOutrightsTableSortOnce() {
  if (outrightsSortInited) return;
  const table = document.getElementById("table-outrights");
  if (!table) return;
  outrightsSortInited = true;
  table.querySelector("thead")?.addEventListener("click", (ev) => {
    const th = ev.target.closest("th.sortable");
    if (!th || !table.contains(th)) return;
    const key = th.dataset.sortKey;
    if (!key) return;
    if (outrightSort.key === key) outrightSort.dir *= -1;
    else {
      outrightSort.key = key;
      outrightSort.dir = key === "player" ? 1 : -1;
    }
    buildOutrightsTableBodyOnly();
    updateOutrightsSortIndicators();
  });
}

function playerKeyFromName(full) {
  const s = String(full || "").trim();
  const i = s.indexOf(",");
  if (i > 0) {
    const last = s.slice(0, i).trim().toLowerCase();
    const first = (s.slice(i + 1).trim().split(/\s+/)[0] || "").toLowerCase();
    return `${last}|${first}`;
  }
  const tok = s.toLowerCase().split(/\s+/).filter(Boolean);
  if (tok.length >= 2) return `${tok[tok.length - 1]}|${tok[0]}`;
  return s.toLowerCase().replace(/\s+/g, "");
}

function normEvtNameKey(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function parseRoundNumFromRLabel(rlab) {
  const m = String(rlab || "").match(/(\d+)/);
  return m ? parseInt(m[1], 10) : NaN;
}

/** Match hole-card round key to player_shots_web.json round uid (tournament_name\tR{n}). */
function findShotsRoundUid(byRound, wantUid) {
  if (!byRound || !wantUid) return null;
  if (byRound[wantUid]) return wantUid;
  const parts = String(wantUid).split("\t");
  const evRaw = (parts[0] || "").trim();
  const rlab = (parts[1] || "").trim();
  const rn = parseRoundNumFromRLabel(rlab);
  const wantEv = normEvtNameKey(evRaw);
  for (const k of Object.keys(byRound)) {
    const kp = String(k).split("\t");
    const e2 = (kp[0] || "").trim();
    const r2 = (kp[1] || "").trim();
    const rn2 = parseRoundNumFromRLabel(r2);
    if (Number.isFinite(rn) && Number.isFinite(rn2) && rn !== rn2) continue;
    if (normEvtNameKey(e2) === wantEv) return k;
  }
  return null;
}

function renderPropsShotsForSelection(dg, fullKey) {
  const wrap = document.getElementById("props-shot-wrap");
  const metaEl = document.getElementById("props-shot-meta");
  const tbody = document.querySelector("#props-shots-table tbody");
  if (!wrap || !tbody) return;
  if (!SHOTS._ok || !fullKey) {
    wrap.hidden = true;
    tbody.innerHTML = "";
    if (metaEl) metaEl.textContent = "";
    return;
  }
  const byRound = SHOTS.byDgId && SHOTS.byDgId[String(dg)];
  const uid = findShotsRoundUid(byRound, fullKey);
  if (!uid || !byRound || !byRound[uid]) {
    wrap.hidden = true;
    tbody.innerHTML = "";
    if (metaEl) metaEl.textContent = "";
    return;
  }
  const holesObj = byRound[uid];
  const holeNums = Object.keys(holesObj)
    .map((h) => parseInt(h, 10))
    .filter((n) => Number.isFinite(n) && n >= 1 && n <= 18)
    .sort((a, b) => a - b);
  const rows = [];
  for (const hn of holeNums) {
    const arr = holesObj[String(hn)] || [];
    for (const s of arr) {
      rows.push({ hole: hn, ...s });
    }
  }
  if (!rows.length) {
    wrap.hidden = true;
    tbody.innerHTML = "";
    if (metaEl) metaEl.textContent = "";
    return;
  }
  wrap.hidden = false;
  if (metaEl) {
    const m = SHOTS.meta || {};
    metaEl.textContent = `Source: ${m.source_csv || "shots"} · ${m.min_shot_season_year || "2022"}+ · last ${m.shot_round_tail ?? "—"} rounds/player · ${(m.rows_used || 0).toLocaleString()} shot rows in bundle`;
  }
  tbody.innerHTML = "";
  for (const s of rows) {
    const tr = document.createElement("tr");
    const t0 = document.createElement("td");
    t0.textContent = String(s.hole);
    const t1 = document.createElement("td");
    t1.className = "num";
    t1.textContent = String(s.sn);
    const t2 = document.createElement("td");
    t2.textContent = s.f || "—";
    const t3 = document.createElement("td");
    t3.textContent = s.t || "—";
    const t4 = document.createElement("td");
    t4.className = "num";
    t4.textContent = Number.isFinite(s.d) ? String(s.d) : "—";
    const t5 = document.createElement("td");
    let pbp = String(s.p || "").trim();
    if (s.fin) pbp = pbp ? `${pbp} · final` : "final";
    t5.textContent = pbp;
    t5.className = "props-shot-pbp";
    tr.appendChild(t0);
    tr.appendChild(t1);
    tr.appendChild(t2);
    tr.appendChild(t3);
    tr.appendChild(t4);
    tr.appendChild(t5);
    tbody.appendChild(tr);
  }
}

function embeddedRoundHistoryPayload() {
  if (
    typeof window === "undefined" ||
    !window.__ALPHA_CADDIE_EMBEDDED_ROUND_HISTORY__ ||
    typeof window.__ALPHA_CADDIE_EMBEDDED_ROUND_HISTORY__ !== "object" ||
    !window.__ALPHA_CADDIE_EMBEDDED_ROUND_HISTORY__.byDgId
  ) {
    return null;
  }
  return window.__ALPHA_CADDIE_EMBEDDED_ROUND_HISTORY__;
}

function loadEmbeddedRoundHistoryScript() {
  if (embeddedRoundHistoryPayload()) return Promise.resolve();
  if (typeof document === "undefined") return Promise.resolve();
  if (embeddedRoundHistoryScriptPromise) return embeddedRoundHistoryScriptPromise;
  embeddedRoundHistoryScriptPromise = new Promise((resolve) => {
    const s = document.createElement("script");
    s.src = isFileProtocol() ? "embedded-player-round-history.js" : cacheBustFetchUrl("embedded-player-round-history.js");
    s.async = true;
    s.onload = () => resolve();
    s.onerror = () => resolve();
    document.body.appendChild(s);
  });
  return embeddedRoundHistoryScriptPromise;
}

function historyDateMdYIsFuture(s) {
  const raw = String(s || "").trim();
  let y = NaN;
  let mo = NaN;
  let d = NaN;
  const mdy = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (mdy) {
    mo = Number(mdy[1]);
    d = Number(mdy[2]);
    y = Number(mdy[3]);
  } else if (iso) {
    y = Number(iso[1]);
    mo = Number(iso[2]);
    d = Number(iso[3]);
  } else {
    return false;
  }
  const t = Date.UTC(y, mo - 1, d);
  const now = new Date();
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return Number.isFinite(t) && t > today;
}

/** PGA/LIV stroke events: DG CSV uses event_completed = last day; spread rounds backward (R4 on that day). */
function historyEventStrokeRoundCap(row) {
  const t = String(row?.tour || "").toLowerCase();
  return t === "liv" ? 3 : 4;
}

function historyMdyFromChronoBase(chronoBase, dayOffset) {
  if (!Number.isFinite(chronoBase) || chronoBase <= 0) return "";
  const y = Math.floor(chronoBase / 10000);
  const mo = Math.floor((chronoBase % 10000) / 100);
  const d = chronoBase % 100;
  const ms = Date.UTC(y, mo - 1, d) + Math.round(Number(dayOffset) || 0) * 86400000;
  const dt = new Date(ms);
  return `${dt.getUTCMonth() + 1}/${dt.getUTCDate()}/${dt.getUTCFullYear()}`;
}

function historyRowUsesEventEndAnchor(row) {
  if (!row || typeof row !== "object") return false;
  if (row._from_live_tournament_stats || row._from_pgatour || row._from_live_in_play) return false;
  if (row._from_dg_historical_rounds) return false;
  const ec = String(row.event_completed || "").trim();
  if (!ec) return false;
  const sk = Math.round(num(row.sortKey, NaN));
  if (Number.isFinite(sk) && sk > 9_999_999) {
    const skBase = Math.floor(sk / 10);
    const ecBase = parseEventCompletedChronoBase(ec);
    return ecBase > 0 && skBase === ecBase;
  }
  return true;
}

function historyRoundDayOffsetFromEventAnchor(row) {
  const rnd = Math.round(num(row?.round_num, NaN));
  if (!Number.isFinite(rnd) || rnd < 1) return 0;
  if (!historyRowUsesEventEndAnchor(row)) return 0;
  const cap = historyEventStrokeRoundCap(row);
  return -(Math.max(0, cap - rnd));
}

/** Play date M/D/YYYY for Historical Trends chart + date filters. */
function historyRoundPlayMdY(row) {
  if (!row || typeof row !== "object") return "";
  const ec = String(row.event_completed || "").trim();
  const offset = historyRoundDayOffsetFromEventAnchor(row);
  if (offset !== 0 && ec) {
    const base = parseEventCompletedChronoBase(ec);
    if (base > 0) return historyMdyFromChronoBase(base, offset);
  }
  return ec;
}

/** Calendar day shown on the trends chart, as UTC midnight ms. */
function historyRoundChartDateUtcMs(row) {
  const iso = String(row?.chart_session_iso || "").trim();
  const isoM = iso.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoM) return Date.UTC(+isoM[1], +isoM[2] - 1, +isoM[3]);
  const mdy = historyRoundPlayMdY(row);
  const base = parseEventCompletedChronoBase(mdy);
  if (!base) return NaN;
  const y = Math.floor(base / 10000);
  const mo = Math.floor((base % 10000) / 100);
  const d = base % 100;
  return Date.UTC(y, mo - 1, d);
}

function historyRoundChartDateIsFuture(row) {
  if (row && typeof row === "object") {
    const rnd = Math.round(num(row.round_num, NaN));
    const cap = currentTournamentProgressRoundCap();
    if (historyRoundMatchesCurrentEvent(row) && Number.isFinite(rnd) && Number.isFinite(cap) && rnd <= cap) {
      const ms = historyRoundChartDateUtcMs(row);
      if (Number.isFinite(ms)) {
        const now = new Date();
        const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
        if (ms <= today) return false;
      }
    }
  }
  const ms = historyRoundChartDateUtcMs(row);
  if (!Number.isFinite(ms)) return historyDateMdYIsFuture(row?.event_completed);
  const now = new Date();
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return ms > today;
}

function sanitizePlayerHistoryPayload(payload) {
  if (!payload || typeof payload !== "object" || !payload.byDgId || typeof payload.byDgId !== "object") return payload;
  normalizeHistoryCourseNamesInPayload(payload);
  let removed = 0;
  let liveRowsRemoved = 0;
  for (const bucket of Object.values(payload.byDgId)) {
    if (!bucket || !Array.isArray(bucket.rounds)) continue;
    const before = bucket.rounds.length;
    bucket.rounds = bucket.rounds.filter((r) => {
      if (r?._from_live_in_play && !r?._from_live_tournament_stats) {
        liveRowsRemoved += 1;
        return false;
      }
      return !historyDateMdYIsFuture(r?.event_completed) && !historyRoundChartDateIsFuture(r);
    });
    removed += before - bucket.rounds.length;
  }
  if (removed > 0 || liveRowsRemoved > 0) {
    payload.meta = {
      ...(payload.meta || {}),
      ...(removed > 0 ? { future_rounds_filtered: removed } : {}),
      ...(liveRowsRemoved > 0 ? { live_in_play_rows_stripped: liveRowsRemoved } : {}),
    };
  }
  return payload;
}

/**
 * Historical Trends actuals: historical-raw-data/rounds (CSV) or preds/live-tournament-stats during the live week.
 */
function historyRowFromDgHistoricalRoundsApi(row) {
  if (!row || typeof row !== "object") return false;
  if (row._from_live_tournament_stats || row._from_pgatour) return true;
  return !row._from_live_in_play;
}

function applyPlayerHistoryPayload(payload, opts = {}) {
  const clean = sanitizePlayerHistoryPayload(payload);
  if (clean?.byDgId && typeof clean.byDgId === "object") {
    for (const bucket of Object.values(clean.byDgId)) {
      if (!bucket?.rounds) continue;
      bucket.rounds = bucket.rounds.map((r) => scrubLivePlaceholderCountingOnRow(r));
    }
  }
  HISTORY = { ...clean, _ok: true, _loading: false, _partial: Boolean(opts.partial) };
  HISTORY_ROUNDS_CHRONO_CACHE.clear();
  PRICING_MU_BONUS_CACHE.clear();
  if (DATA?.meta?.event_name) scrubNonActualRoundsFromHistoryBuckets();
  bumpHistoryMutationEpoch();
  void ensurePropsDgIdNameManifestLoaded();
  if (!opts.partial && activeAppTabId() === "ou") {
    requestAnimationFrame(() => buildOuTable());
  }
}

function normalizeHistoryShardPayload(payload) {
  if (!payload || typeof payload !== "object") return null;
  if (payload.byDgId && typeof payload.byDgId === "object") return payload;
  const dg = Math.round(num(payload.dg_id, NaN));
  if (!Number.isFinite(dg) || !Array.isArray(payload.rounds)) return null;
  return {
    meta: payload.meta && typeof payload.meta === "object" ? payload.meta : {},
    byDgId: {
      [String(dg)]: {
        dg_id: dg,
        player_name: String(payload.player_name || "").trim(),
        rounds: payload.rounds,
      },
    },
    holesByPlayerKey: {},
  };
}

function mergePlayerHistoryPartialPayload(payload) {
  const normalized = normalizeHistoryShardPayload(payload);
  const clean = sanitizePlayerHistoryPayload(normalized || payload);
  if (!clean || !clean.byDgId || typeof clean.byDgId !== "object") return false;
  const mergedByDgId = { ...(HISTORY.byDgId || {}), ...clean.byDgId };
  HISTORY = {
    meta: { ...(HISTORY.meta || {}), ...(clean.meta || {}) },
    byDgId: mergedByDgId,
    holesByPlayerKey: { ...(HISTORY.holesByPlayerKey || {}), ...(clean.holesByPlayerKey || {}) },
    _ok: true,
    _loading: false,
    _partial: Object.keys(mergedByDgId).length < 20,
  };
  for (const k of Object.keys(clean.byDgId)) {
    const id = Math.round(num(k, NaN));
    if (Number.isFinite(id)) HISTORY_ROUNDS_CHRONO_CACHE.delete(id);
  }
  PRICING_MU_BONUS_CACHE.clear();
  bumpHistoryMutationEpoch();
  if (activeAppTabId() === "ou") scheduleOuTableRebuildAfterHistory();
  return true;
}

function historyBucketLoaded(dgId) {
  const id = Math.round(num(dgId, NaN));
  const bucket = HISTORY.byDgId?.[String(id)];
  return (
    Number.isFinite(id) &&
    Boolean(bucket && Array.isArray(bucket.rounds) && bucket.rounds.length > 0)
  );
}

function historyBucketIsSeasonSliceOnly(dgId) {
  const id = Math.round(num(dgId, NaN));
  const bucket = HISTORY.byDgId?.[String(id)];
  return Boolean(bucket && Number.isFinite(bucket._propsSeasonSlice));
}

async function ensurePlayerCareerHistoryLoaded(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return false;
  if (historyBucketLoaded(id) && !historyBucketIsSeasonSliceOnly(id)) return true;
  return loadPlayerHistoryBucket(id);
}

function historyBucketResolved(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return false;
  return historyBucketLoaded(id) || playerHistoryAbsentDgIds.has(id);
}

function markPlayerHistoryAbsent(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return;
  playerHistoryAbsentDgIds.add(id);
}

async function extractHistoryBucketFromEmbedded(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return false;
  try {
    await loadEmbeddedRoundHistoryScript();
    const emb = embeddedRoundHistoryPayload();
    const bucket = emb?.byDgId?.[String(id)];
    if (!bucket || !Array.isArray(bucket.rounds) || !bucket.rounds.length) return false;
    return mergePlayerHistoryPartialPayload({
      meta: emb.meta || {},
      byDgId: { [String(id)]: bucket },
      holesByPlayerKey: {},
    });
  } catch (_) {
    return false;
  }
}

function historyBucketLoading(dgId) {
  const id = Math.round(num(dgId, NaN));
  return Number.isFinite(id) && playerHistoryBucketLoadPromises.has(id);
}

async function loadPlayerHistoryBucket(dgId, opts = {}) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return false;
  const seasonYear = Number.isFinite(num(opts.seasonYear, NaN)) ? Math.round(num(opts.seasonYear, NaN)) : NaN;
  const existing = HISTORY.byDgId?.[String(id)];
  const wantsCareer = !Number.isFinite(seasonYear);
  if (existing) {
    if (wantsCareer && historyBucketLoaded(id) && !historyBucketIsSeasonSliceOnly(id)) return true;
    if (!wantsCareer && historyBucketReadyForFieldSeason(id, seasonYear)) return true;
  }
  if (isFileProtocol()) {
    await loadPlayerHistory();
    return historyBucketLoaded(id);
  }
  if (playerHistoryBucketLoadPromises.has(id)) return playerHistoryBucketLoadPromises.get(id);
  const p = (async () => {
    const url = cacheBustFetchUrl(`player-history/by-dg/${id}.json`);
    const fetchOpts = { cache: "no-store" };
    if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
      fetchOpts.signal = AbortSignal.timeout(12000);
    }
    try {
      const res = await fetch(url, fetchOpts);
      if (res.ok) {
        const raw = await res.json();
        if (Number.isFinite(seasonYear)) {
          const dgKey = String(id);
          let rounds = Array.isArray(raw?.rounds) ? raw.rounds : raw?.byDgId?.[dgKey]?.rounds;
          if (!Array.isArray(rounds)) rounds = [];
          rounds = rounds.filter((r) => historyRoundSeasonYear(r) === seasonYear);
          const playerName = String(
            raw?.player_name || raw?.byDgId?.[dgKey]?.player_name || "",
          ).trim();
          const sliced = {
            meta: raw?.meta && typeof raw.meta === "object" ? raw.meta : {},
            byDgId: {
              [dgKey]: {
                dg_id: id,
                player_name: playerName,
                rounds,
                _propsSeasonSlice: seasonYear,
                _propsSeasonEmpty: rounds.length === 0,
              },
            },
            holesByPlayerKey: {},
          };
          const ok = mergePlayerHistoryPartialPayload(sliced);
          if (ok) return true;
        } else {
          const rawRounds = Array.isArray(raw?.rounds)
            ? raw.rounds
            : raw?.byDgId?.[String(id)]?.rounds;
          if (Array.isArray(rawRounds) && !rawRounds.length) {
            markPlayerHistoryAbsent(id);
            return false;
          }
          const ok = mergePlayerHistoryPartialPayload(raw);
          if (ok && historyBucketLoaded(id)) return true;
        }
      }
    } catch (_) {
      /* shard missing, timeout, or parse error */
    }
    if (await extractHistoryBucketFromEmbedded(id)) {
      if (Number.isFinite(seasonYear)) {
        const bucket = HISTORY.byDgId?.[String(id)];
        if (bucket?.rounds) {
          bucket.rounds = bucket.rounds.filter((r) => historyRoundSeasonYear(r) === seasonYear);
          bucket._propsSeasonSlice = seasonYear;
          bucket._propsSeasonEmpty = bucket.rounds.length === 0;
        }
      }
      return historyBucketLoaded(id);
    }
    return false;
  })();
  playerHistoryBucketLoadPromises.set(id, p);
  try {
    return await p;
  } finally {
    playerHistoryBucketLoadPromises.delete(id);
  }
}

/**
 * Prefer player_round_history.json (npm run build:history from historical_rounds_all.csv) when served
 * over HTTP; use embedded script as fallback or for file:// demos.
 */
async function loadPlayerHistory() {
  if (HISTORY._ok && !HISTORY._partial) return;
  const selDg = selectedDgId();
  if (Number.isFinite(selDg) && historyBucketLoaded(selDg)) return;
  if (playerHistoryLoadPromise) return playerHistoryLoadPromise;
  HISTORY = { ...HISTORY, _loading: true };
  playerHistoryLoadPromise = (async () => {
    if (isFileProtocol()) {
      await loadEmbeddedRoundHistoryScript();
      const emb = embeddedRoundHistoryPayload();
      if (emb) {
        applyPlayerHistoryPayload(emb, { partial: false });
        return;
      }
      HISTORY = { meta: {}, byDgId: {}, holesByPlayerKey: {}, _ok: false, _loading: false };
      HISTORY_ROUNDS_CHRONO_CACHE.clear();
      PRICING_MU_BONUS_CACHE.clear();
      return;
    }
    try {
      const fetchOpts = { cache: "no-store" };
      if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
        fetchOpts.signal = AbortSignal.timeout(90000);
      }
      const res = await fetch(cacheBustFetchUrl("player_round_history.json"), fetchOpts);
      if (res.ok) {
        applyPlayerHistoryPayload(await res.json(), { partial: false });
        return;
      }
    } catch (_) {}
    await loadEmbeddedRoundHistoryScript();
    const emb = embeddedRoundHistoryPayload();
    if (emb) {
      applyPlayerHistoryPayload(emb, { partial: false });
      return;
    }
    HISTORY = { meta: {}, byDgId: {}, holesByPlayerKey: {}, _ok: false, _loading: false };
    HISTORY_ROUNDS_CHRONO_CACHE.clear();
    PRICING_MU_BONUS_CACHE.clear();
  })();
  try {
    await playerHistoryLoadPromise;
  } finally {
    playerHistoryLoadPromise = null;
    if (HISTORY && typeof HISTORY === "object") HISTORY._loading = false;
  }
}

async function loadPlayerShots() {
  if (isFileProtocol()) {
    SHOTS = { meta: {}, byDgId: {}, _ok: false };
    return;
  }
  try {
    const res = await fetch("player_shots_web.json", { cache: "no-store" });
    if (!res.ok) throw new Error(String(res.status));
    SHOTS = { ...(await res.json()), _ok: true };
  } catch (_) {
    SHOTS = { meta: {}, byDgId: {}, _ok: false };
  }
}

function defaultPropGolferDgId() {
  const nm = (s) => String(s || "").toLowerCase();
  for (const p of DATA.players) {
    if (!samePlayerRound(p, 1)) continue;
    if (tournamentPostCutListPhase() && isPlayerEliminatedFromEvent(p)) continue;
    const n = nm(p.player_name);
    if (n.includes("scheffler") && n.includes("scottie")) return Math.round(num(p.dg_id, NaN));
  }
  return NaN;
}

/** Case-insensitive match on DataGolf name and display name; all query tokens must match somewhere. */
function golferNameMatchesQuery(nameRaw, qLower) {
  const q = String(qLower || "").trim().toLowerCase();
  if (!q) return true;
  const raw = String(nameRaw || "").toLowerCase();
  const disp = displayGolferName(String(nameRaw || "")).toLowerCase();
  if (disp.includes(q) || raw.includes(q)) return true;
  const parts = q.split(/\s+/).filter(Boolean);
  return parts.every((t) => disp.includes(t) || raw.includes(t));
}

/** Match full matchup label (`A vs B` / 3-ball) or either side for combobox search. */
function matchupRowLabelMatchesQuery(labelRaw, qLower) {
  const q = String(qLower || "").trim().toLowerCase();
  if (!q) return false;
  const label = String(labelRaw || "").trim();
  if (!label) return false;
  if (golferNameMatchesQuery(label, q)) return true;
  const disp = displayGolferName(label).trim().toLowerCase();
  if (disp === q || disp.includes(q)) return true;
  const segs = disp.split(/\s+vs\s+|\s*\/\s*/).map((s) => s.trim()).filter(Boolean);
  const toks = q.split(/\s+/).filter((t) => t.length >= 2);
  if (segs.length >= 2 && toks.length) {
    if (segs.some((seg) => toks.every((t) => seg.includes(t)))) return true;
  }
  return false;
}

/** Themed custom list (native `<datalist>` popups cannot match dark UI). */
const GOLFER_SUGGEST_PANEL_MAX = 80;

function golferSuggestReadLabels(panel) {
  if (!panel) return [];
  const raw = /** @type {{ _golferSuggestLabels?: string[] }} */ (/** @type {unknown} */ (panel))._golferSuggestLabels;
  return Array.isArray(raw) ? raw : [];
}

function golferSuggestWriteLabels(panel, labels) {
  if (!panel) return;
  /** @type {{ _golferSuggestLabels?: string[] }} */ (/** @type {unknown} */ (panel))._golferSuggestLabels = labels;
}

function filterGolferSuggestLabels(names, qRaw) {
  const q = String(qRaw || "").trim().toLowerCase();
  if (!q) return names.slice(0, GOLFER_SUGGEST_PANEL_MAX);
  const useMatchup = names.some((n) => /\s+vs\s+|\s+\/\s+/.test(String(n)));
  const out = [];
  for (const name of names) {
    const ok = useMatchup ? matchupRowLabelMatchesQuery(name, q) : golferNameMatchesQuery(name, q);
    if (ok) out.push(name);
    if (out.length >= GOLFER_SUGGEST_PANEL_MAX) break;
  }
  return out;
}

function hideOpenGolferSuggestPanels() {
  document.querySelectorAll(".golfer-suggest-panel").forEach((p) => {
    p.hidden = true;
    p.innerHTML = "";
  });
}

function renderOpenGolferSuggestPanel(panel, labels, onPick) {
  if (!panel) return;
  panel.innerHTML = "";
  if (!labels.length) {
    panel.hidden = true;
    return;
  }
  for (const lab of labels) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "golfer-suggest-item";
    b.setAttribute("role", "option");
    b.textContent = lab;
    b.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      onPick(lab);
    });
    panel.appendChild(b);
  }
  panel.hidden = false;
}

let golferSuggestGlobalPointerWired = false;
function wireGolferSuggestGlobalDismissOnce() {
  if (golferSuggestGlobalPointerWired) return;
  golferSuggestGlobalPointerWired = true;
  document.addEventListener(
    "pointerdown",
    (ev) => {
      const t = ev.target;
      if (!(t instanceof Element)) return;
      if (t.closest(".golfer-suggest-panel") || t.closest(".golfer-suggest-anchor")) return;
      hideOpenGolferSuggestPanels();
    },
    true,
  );
}

function openGolferSuggestForSearchInput(search, panel, onPickFromList, opts = {}) {
  const labels = golferSuggestReadLabels(panel);
  // showAll: focus/open should list every golfer; typing still filters.
  const q = opts.showAll ? "" : String(search.value || "");
  const picked = filterGolferSuggestLabels(labels, q);
  renderOpenGolferSuggestPanel(panel, picked, (lab) => {
    search.value = lab;
    hideOpenGolferSuggestPanels();
    onPickFromList(lab);
  });
}

/** After label cache updates: keep the panel open if the user is still typing (table/select refresh must not wipe it). */
function reopenGolferSuggestIfSearchFocused(search, panel, onPickFromList, opts = {}) {
  if (!panel) return;
  if (!search || document.activeElement !== search) {
    panel.innerHTML = "";
    panel.hidden = true;
    return;
  }
  const labels = golferSuggestReadLabels(panel);
  const v = String(search.value || "").trim().toLowerCase();
  const exact = Boolean(v) && labels.some((l) => String(l).toLowerCase() === v);
  // Exact full name selected → show the full roster so the user can pick someone else.
  openGolferSuggestForSearchInput(search, panel, onPickFromList, {
    showAll: Boolean(opts.showAll) || (opts.showAllIfExact !== false && exact),
  });
}

function wireOuPlayerFilterSuggestOnce() {
  const search = document.getElementById("ou-player-filter");
  const panel = document.getElementById("ou-player-filter-suggest");
  if (!search || !panel || !(search instanceof HTMLInputElement) || search.dataset.golferSuggestWired === "1") return;
  search.dataset.golferSuggestWired = "1";
  wireGolferSuggestGlobalDismissOnce();
  const refreshPanel = () =>
    openGolferSuggestForSearchInput(search, panel, () => {
      ouProjExpandedKey = "";
      scheduleBuildOuTable(true);
    });
  search.addEventListener("focus", refreshPanel);
  search.addEventListener("input", refreshPanel);
  search.addEventListener("blur", () => {
    setTimeout(() => {
      if (panel.contains(document.activeElement)) return;
      panel.hidden = true;
      panel.innerHTML = "";
    }, 160);
  });
}

function wireGolferSuggestComboOnce(selectId) {
  const search = document.getElementById(`${selectId}-search`);
  const panel = document.getElementById(`${selectId}-suggest`);
  const sel = document.getElementById(selectId);
  if (!search || !panel || !sel || search.dataset.golferSuggestWired === "1") return;
  search.dataset.golferSuggestWired = "1";
  wireGolferSuggestGlobalDismissOnce();
  const refreshPanel = () =>
    openGolferSuggestForSearchInput(search, panel, () => {
      commitGolferComboSearchToSelect(selectId);
      sel.dispatchEvent(new Event("change", { bubbles: true }));
    });
  // Matchup Analysis: do not open the suggestion list on focus alone (avoids a second “dropdown” feel); click or typing opens it.
  const openSuggestOnFocusOnly = selectId !== "analysis-matchup-select";
  if (openSuggestOnFocusOnly) search.addEventListener("focus", refreshPanel);
  else search.addEventListener("click", refreshPanel);
  search.addEventListener("input", refreshPanel);
  search.addEventListener("blur", () => {
    setTimeout(() => {
      if (panel.contains(document.activeElement)) return;
      panel.hidden = true;
      panel.innerHTML = "";
    }, 160);
  });
}

/** `select` + `#${id}-search` + `#${id}-suggest` panel — wire once after DOM. */
const GOLFER_COMBO_SELECT_IDS = [
  "prop-golfer",
  "live-prop-golfer",
  "course-fit-player",
  "ev-filter-golfer",
  "analysis-matchup-select",
];

function syncGolferComboSearchFromSelect(selectId) {
  const sel = document.getElementById(selectId);
  const search = document.getElementById(`${selectId}-search`);
  if (!sel || !search) return;
  const opt = sel.selectedOptions[0];
  if (!opt || String(opt.value || "") === "") {
    search.value = "";
    return;
  }
  search.value = opt ? String(opt.textContent || "").trim() : "";
}

function commitGolferComboSearchToSelect(selectId) {
  const sel = /** @type {HTMLSelectElement | null} */ (document.getElementById(selectId));
  const search = document.getElementById(`${selectId}-search`);
  if (!sel || !search) return;
  const q = String(search.value || "").trim();
  const qLow = q.toLowerCase();
  if (!q) {
    const empty = [...sel.options].find((o) => String(o.value || "") === "");
    if (empty) sel.value = "";
    else if (sel.options.length) sel.selectedIndex = 0;
    return;
  }
  let hit = [...sel.options].find((o) => String(o.textContent || "").trim().toLowerCase() === qLow);
  if (!hit) hit = [...sel.options].find((o) => String(o.textContent || "").toLowerCase().includes(qLow));
  if (!hit) hit = [...sel.options].find((o) => String(o.value || "") === q);
  if (!hit && selectId === "analysis-matchup-select" && matchupAnalysisRowsCache.length) {
    const row = matchupAnalysisRowsCache.find((r) => matchupRowLabelMatchesQuery(r.matchup, qLow));
    if (row) {
      selectMatchupAnalysisMatchup(row.key);
      return;
    }
  }
  if (hit) {
    sel.value = String(hit.value);
    search.value = String(hit.value || "") === "" ? "" : String(hit.textContent || "").trim();
  } else {
    syncGolferComboSearchFromSelect(selectId);
  }
}

function refreshGolferComboboxFromSelect(selectId) {
  const sel = document.getElementById(selectId);
  const panel = document.getElementById(`${selectId}-suggest`);
  const search = document.getElementById(`${selectId}-search`);
  if (!sel || !panel) return;
  let labels;
  if (selectId === "analysis-matchup-select" && matchupAnalysisRowsCache.length) {
    labels = matchupAnalysisRowsCache.map((r) => String(r.matchup || "").trim()).filter(Boolean);
  } else {
    labels = [...sel.querySelectorAll("option")]
      .filter((o) => String(o.value || "") !== "")
      .map((o) => String(o.textContent || "").trim())
      .filter(Boolean);
  }
  golferSuggestWriteLabels(panel, labels);
  reopenGolferSuggestIfSearchFocused(search, panel, () => {
    commitGolferComboSearchToSelect(selectId);
    sel.dispatchEvent(new Event("change", { bubbles: true }));
  });
  if (!search || document.activeElement !== search) syncGolferComboSearchFromSelect(selectId);
}

function wireGolferSearchCombo(selectId) {
  const search = document.getElementById(`${selectId}-search`);
  const sel = document.getElementById(selectId);
  if (!search || !sel || search.dataset.golferComboWired === "1") return;
  search.dataset.golferComboWired = "1";
  const commit = () => {
    commitGolferComboSearchToSelect(selectId);
    sel.dispatchEvent(new Event("change", { bubbles: true }));
  };
  search.addEventListener("change", commit);
  search.addEventListener("blur", commit);
  sel.addEventListener("change", () => syncGolferComboSearchFromSelect(selectId));
}

function wireAllGolferSearchCombosOnce() {
  wireGolferSuggestGlobalDismissOnce();
  for (const id of GOLFER_COMBO_SELECT_IDS) {
    wireGolferSearchCombo(id);
    wireGolferSuggestComboOnce(id);
  }
}

function ouResolveSinglePlayerRowFromFilter(allRows, qTrim) {
  const q = String(qTrim || "").trim().toLowerCase();
  if (!q) return null;
  const m = allRows.filter((p) => golferNameMatchesQuery(String(p.player_name || ""), q));
  if (m.length === 1) return m[0];
  const exact = allRows.find((p) => String(p.player_name || "").trim().toLowerCase() === q);
  if (exact) return exact;
  return allRows.find((p) => displayGolferName(String(p.player_name || "")).trim().toLowerCase() === q) || null;
}

function ouResolveSinglePlayerNameForToolbar(allRows, qTrim) {
  const row = ouResolveSinglePlayerRowFromFilter(allRows, qTrim);
  return row ? String(row.player_name || "").trim() : "";
}

function fillFieldGolferSelect(selId, pickDefaultIdFn) {
  const sel = document.getElementById(selId);
  if (!sel) return;
  const prevVal = String(sel.value || "");
  const seen = new Set();
  const opts = [];
  for (const p of DATA.players) {
    if (!samePlayerRound(p, 1)) continue;
    if (tournamentPostCutListPhase() && isPlayerEliminatedFromEvent(p)) continue;
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id) || seen.has(id)) continue;
    seen.add(id);
    opts.push({ id, name: String(p.player_name || "") });
  }
  opts.sort((a, b) => displayGolferName(a.name).localeCompare(displayGolferName(b.name)));
  sel.innerHTML = "";
  for (const o of opts) {
    const op = document.createElement("option");
    op.value = String(o.id);
    op.textContent = displayGolferName(o.name);
    sel.appendChild(op);
  }
  const defaultId = pickDefaultIdFn ? pickDefaultIdFn() : NaN;
  let nextVal = "";
  if (prevVal && [...sel.options].some((o) => o.value === prevVal)) nextVal = prevVal;
  else if (Number.isFinite(defaultId) && [...sel.options].some((o) => o.value === String(defaultId))) nextVal = String(defaultId);
  else if (sel.options.length) nextVal = sel.options[0].value;

  sel.value = nextVal;
  const changed = prevVal !== String(sel.value || "");
  if (GOLFER_COMBO_SELECT_IDS.includes(selId)) refreshGolferComboboxFromSelect(selId);
  if (changed && (selId === "live-prop-golfer" || selId === "prop-golfer")) {
    sel.dispatchEvent(new Event("change", { bubbles: true }));
  }
}

function fillPropGolferSelect() {
  fillFieldGolferSelect("prop-golfer", defaultPropGolferDgId);
}

function fillLivePropGolferSelect() {
  fillFieldGolferSelect("live-prop-golfer", defaultLivePropGolferDgId);
}

function defaultLivePropGolferDgId() {
  const nm = (s) => String(s || "").toLowerCase();
  for (const p of DATA.players) {
    if (!samePlayerRound(p, 1)) continue;
    if (tournamentPostCutListPhase() && isPlayerEliminatedFromEvent(p)) continue;
    const n = nm(p.player_name);
    if (n.includes("cameron") && n.includes("young")) return Math.round(num(p.dg_id, NaN));
  }
  return defaultPropGolferDgId();
}

/** Strip DG live partial-round fields so remainder math uses full-round priors + user-entered “so far”. */
function rowWithoutLivePartialFields(row) {
  if (!row || typeof row !== "object") return row;
  const out = { ...row };
  delete out.dg_live_thru;
  delete out.dg_live_today;
  delete out.dg_live_birdies_so_far;
  delete out.dg_live_bogeys_so_far;
  delete out.dg_live_pars_so_far;
  delete out.dg_live_eagles_so_far;
  delete out.dg_live_placement_from_api;
  return out;
}

function livePropSampleMeanStd(xs) {
  const n = xs.length;
  if (!n) return { mean: NaN, std: NaN, n: 0 };
  const mean = xs.reduce((s, x) => s + x, 0) / n;
  if (n < 2) return { mean, std: NaN, n };
  let v = 0;
  for (const x of xs) v += (x - mean) ** 2;
  return { mean, std: Math.sqrt(v / (n - 1)), n };
}

/** Shotgun / split tees: playing order from `startHole` (1–18), wrapping (e.g. 10 → … → 18 → 1 → … → 9). */
function livePropPlayOrder(startHole) {
  const s = Math.round(num(startHole, NaN));
  const start = Number.isFinite(s) && s >= 1 && s <= 18 ? s : 1;
  const out = [];
  for (let i = 0; i < 18; i++) {
    let h = start + i;
    if (h > 18) h -= 18;
    out.push(h);
  }
  return out;
}

function livePropHoleParFromCard(holePars, holeNum1) {
  const hn = Math.round(num(holeNum1, NaN));
  if (!Array.isArray(holePars) || holePars.length < 18 || hn < 1 || hn > 18) return NaN;
  return num(holePars[hn - 1], NaN);
}

/** Sum par for the first N holes completed in `playOrder` using `meta.hole_pars` (hole numbers 1–18 on the card). */
function courseParSumPlayOrderThru(holePars, playOrder, nCompleted) {
  const n = Math.min(18, Math.max(0, Math.floor(num(nCompleted, NaN))));
  if (!n) return 0;
  if (!Array.isArray(holePars) || holePars.length < 18 || !Array.isArray(playOrder) || playOrder.length < 18) return NaN;
  let s = 0;
  for (let i = 0; i < n; i++) {
    const p = livePropHoleParFromCard(holePars, playOrder[i]);
    if (!Number.isFinite(p)) return NaN;
    s += p;
  }
  return s;
}

/** Fairway-eligible holes on the card (excludes par 3s) using current course `hole_pars`. */
function livePropFairwayOppFullFromPars(holePars) {
  if (!Array.isArray(holePars) || holePars.length < 18) return NaN;
  let c = 0;
  for (let i = 0; i < 18; i++) {
    const p = num(holePars[i], NaN);
    if (!Number.isFinite(p)) return NaN;
    if (p !== 3) c += 1;
  }
  return c;
}

/** Fairway opportunities in the first `nCompleted` holes of `playOrder` (par 3s excluded). */
function livePropFairwayOppPlayedThru(holePars, playOrder, nCompleted) {
  const n = Math.min(18, Math.max(0, Math.floor(num(nCompleted, NaN))));
  if (!n) return 0;
  if (!Array.isArray(holePars) || holePars.length < 18 || !Array.isArray(playOrder) || playOrder.length < 18) return NaN;
  let c = 0;
  for (let i = 0; i < n; i++) {
    const p = livePropHoleParFromCard(holePars, playOrder[i]);
    if (!Number.isFinite(p)) return NaN;
    if (p !== 3) c += 1;
  }
  return c;
}

function livePropDedupeHolesSorted(holes) {
  const byHole = new Map();
  if (!Array.isArray(holes)) return [];
  for (const h of holes) {
    const hn = Math.round(num(h.hole, NaN));
    if (!Number.isFinite(hn) || hn < 1 || hn > 18) continue;
    byHole.set(hn, h);
  }
  return [...byHole.entries()].sort((a, b) => a[0] - b[0]).map(([, h]) => h);
}

function livePropHolesForRound(pkey, r) {
  const hm = HISTORY.holesByPlayerKey[pkey];
  if (!hm || !r) return null;
  const rn = Math.round(num(r.round_num, NaN));
  if (!Number.isFinite(rn) || rn < 1) return null;
  const suf = `\tR${rn}`;
  const evN = normEvtNameKey(String(r.event_name || ""));
  let fuzzy = null;
  for (const k of Object.keys(hm)) {
    if (!k.endsWith(suf)) continue;
    const pref = k.slice(0, k.length - suf.length).trim();
    if (normEvtNameKey(pref) === evN) return hm[k];
    fuzzy ??= hm[k];
  }
  return fuzzy;
}

function livePropHolesCoverCompleted(holes, playOrder, completedHoles) {
  const deduped = livePropDedupeHolesSorted(holes);
  if (!deduped.length || completedHoles < 1) return false;
  if (!Array.isArray(playOrder) || playOrder.length < 18) return false;
  const have = new Set();
  for (const h of deduped) {
    const hn = Math.round(num(h.hole, NaN));
    if (Number.isFinite(hn)) have.add(hn);
  }
  const n = Math.min(18, Math.max(0, Math.round(completedHoles)));
  for (let i = 0; i < n; i++) {
    if (!have.has(playOrder[i])) return false;
  }
  return true;
}

function livePropCumulativeFromHoles(holes, playOrder, completedHoles, statKey) {
  if (!Array.isArray(holes) || !Array.isArray(playOrder) || playOrder.length < 18 || completedHoles < 1) return NaN;
  const byHole = new Map();
  for (const h of holes) {
    const hn = Math.round(num(h.hole, NaN));
    if (!Number.isFinite(hn) || hn < 1 || hn > 18) continue;
    byHole.set(hn, h);
  }
  const n = Math.min(18, Math.max(0, Math.round(completedHoles)));
  let strokes = 0;
  let birdies = 0;
  let pars = 0;
  let bogeys = 0;
  for (let i = 0; i < n; i++) {
    const hn = playOrder[i];
    const h = byHole.get(hn);
    if (!h) return NaN;
    const par = num(h.par, NaN);
    const sc = num(h.score, NaN);
    if (!Number.isFinite(sc) || !Number.isFinite(par)) continue;
    strokes += sc;
    const rel = sc - par;
    if (rel <= -1) birdies += 1;
    if (rel === 0) pars += 1;
    if (rel >= 1) bogeys += 1;
  }
  if (statKey === "total") return strokes;
  if (statKey === "birdies") return birdies;
  if (statKey === "pars") return pars;
  if (statKey === "bogeys") return bogeys;
  return NaN;
}

/** Full-round counting stats from 18 scored holes (overrides projection placeholders on merged live rows when hole JSON exists). */
function historyFullRoundCountingStatFromHoles(statKey, holes) {
  if (!Array.isArray(holes) || holes.length < 1) return NaN;
  const deduped = livePropDedupeHolesSorted(holes);
  if (deduped.length !== 18) return NaN;
  let strokes = 0;
  let birdies = 0;
  let pars = 0;
  let bogeys = 0;
  for (const h of deduped) {
    const par = num(h.par, NaN);
    const sc = num(h.score, NaN);
    if (!Number.isFinite(sc) || !Number.isFinite(par)) return NaN;
    strokes += sc;
    const rel = sc - par;
    if (rel <= -1) birdies += 1;
    if (rel === 0) pars += 1;
    if (rel >= 1) bogeys += 1;
  }
  if (statKey === "total") return strokes;
  if (statKey === "birdies") return birdies;
  if (statKey === "pars") return pars;
  if (statKey === "bogeys") return bogeys;
  return NaN;
}

function historyTrendRowHoleArray(row) {
  if (!row || typeof row !== "object") return null;
  const dg = Math.round(num(row.dg_id, NaN));
  if (!Number.isFinite(dg)) return null;
  const rec = HISTORY.byDgId && HISTORY.byDgId[String(dg)];
  const pname = String(rec?.player_name || "").trim();
  if (!pname) return null;
  const pkey = playerKeyFromName(pname);
  return livePropHolesForRound(pkey, row);
}

function livePropHistoricalRemainders(dgId, statKey, completedHoles, maxRounds, playOrder) {
  const samples = [];
  let holeBacked = 0;
  const rec = HISTORY.byDgId && HISTORY.byDgId[String(dgId)];
  if (!rec || !Array.isArray(rec.rounds)) return { samples, holeBacked, n: 0 };
  const pname = String(rec.player_name || "").trim();
  const pkey = playerKeyFromName(pname);
  const rounds = rec.rounds.slice().sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
  const cap =
    Number.isFinite(maxRounds) && maxRounds > 0 ? Math.min(maxRounds, rounds.length) : rounds.length;
  const ord = Array.isArray(playOrder) && playOrder.length >= 18 ? playOrder : livePropPlayOrder(1);
  for (let i = 0; i < cap; i++) {
    const r = rounds[i];
    const fin = actualForRoundRow(statKey, r);
    if (!Number.isFinite(fin)) continue;
    let cum = NaN;
    let usedHoleBack = false;
    const holes = livePropHolesForRound(pkey, r);
    if (
      completedHoles >= 1 &&
      holes &&
      livePropHolesCoverCompleted(holes, ord, completedHoles) &&
      (statKey === "total" || statKey === "birdies" || statKey === "pars" || statKey === "bogeys")
    ) {
      cum = livePropCumulativeFromHoles(holes, ord, completedHoles, statKey);
      if (Number.isFinite(cum)) usedHoleBack = true;
    }
    if (!Number.isFinite(cum)) {
      const c = completedHoles;
      cum = c > 0 ? fin * (c / 18) : 0;
    }
    if (usedHoleBack) holeBacked++;
    samples.push(fin - cum);
  }
  return { samples, holeBacked, n: samples.length };
}

function livePropModelRemainderSigma(marketLabel, rowClean, statKey, completedHoles, opts = {}) {
  const playOrder = Array.isArray(opts.playOrder) && opts.playOrder.length >= 18 ? opts.playOrder : livePropPlayOrder(1);
  const holePars = opts.holePars;
  const remHoles = clamp(18 - completedHoles, 0, 18);
  const muFull = ouProjectedMean(marketLabel, rowClean);
  const sigFull = sigmaForOu(marketLabel, rowClean);
  if (!Number.isFinite(muFull) || !Number.isFinite(sigFull)) return { muRem: NaN, sigRem: NaN };

  if (statKey === "fairways") {
    let fullFair = NaN;
    let playedFair = 0;
    if (Array.isArray(holePars) && holePars.length >= 18) {
      fullFair = livePropFairwayOppFullFromPars(holePars);
      playedFair = livePropFairwayOppPlayedThru(holePars, playOrder, completedHoles);
    }
    if (!Number.isFinite(fullFair) || fullFair < 1) {
      if (remHoles <= 0) return { muRem: 0, sigRem: Math.max(0.08, sigFull * 0.06) };
      const denom = fairwayHolesModeledFromData();
      const remU = Math.max(1, Math.round((denom / 18) * remHoles));
      return {
        muRem: (muFull / denom) * remU,
        sigRem: Math.max(0.2, sigFull * Math.sqrt(remU / denom)),
      };
    }
    const remFair = Math.max(0, fullFair - playedFair);
    if (remFair <= 0) return { muRem: 0, sigRem: Math.max(0.08, sigFull * 0.06) };
    return {
      muRem: (muFull / fullFair) * remFair,
      sigRem: Math.max(0.2, sigFull * Math.sqrt(remFair / fullFair)),
    };
  }

  if (remHoles <= 0) return { muRem: 0, sigRem: Math.max(0.08, sigFull * 0.06) };
  if (statKey === "gir" || statKey === "putts") {
    const denom = 18;
    return {
      muRem: (muFull / denom) * remHoles,
      sigRem: Math.max(0.25, sigFull * Math.sqrt(remHoles / denom)),
    };
  }
  return {
    muRem: muFull * (remHoles / 18),
    sigRem: Math.max(0.15, sigFull * Math.sqrt(remHoles / 18)),
  };
}

function renderLivePropPredictor() {
  const root = document.getElementById("live-prop-results");
  if (!root) return;

  const dg = Math.round(num(document.getElementById("live-prop-golfer")?.value, NaN));
  const statKey = String(document.getElementById("live-prop-market")?.value || "total");
  const startHoleRaw = Math.round(num(document.getElementById("live-prop-start-hole")?.value, NaN));
  const startHole = Number.isFinite(startHoleRaw) && startHoleRaw >= 1 && startHoleRaw <= 18 ? startHoleRaw : 1;
  const playOrder = livePropPlayOrder(startHole);
  const throughHoles = Math.round(num(document.getElementById("live-prop-through-holes")?.value, NaN));
  const curRaw = num(document.getElementById("live-prop-current")?.value, NaN);
  const lineRaw = num(document.getElementById("live-prop-line")?.value, NaN);
  const line = clampPropLineForMarket(statKey, enforceHalfLine(lineRaw));
  const oAm = num(document.getElementById("live-prop-over-am")?.value, NaN);
  const uAm = num(document.getElementById("live-prop-under-am")?.value, NaN);

  const completed = Number.isFinite(throughHoles) ? clamp(throughHoles, 0, 18) : NaN;
  const isRoundScoreMarket = statKey === "total";
  const par18 = num(DATA?.meta?.course_par_18, NaN);
  const holePars = DATA?.meta?.hole_pars;
  let parThru = courseParSumPlayOrderThru(holePars, playOrder, completed);
  if (!Number.isFinite(parThru)) {
    parThru = Number.isFinite(par18) && Number.isFinite(completed) ? (par18 / 18) * completed : NaN;
  }
  const currentForProjection = isRoundScoreMarket && Number.isFinite(parThru) ? parThru + curRaw : curRaw;
  const marketLabel = ouMarketKeyFromStatKey(statKey);
  const rEv = getModelRoundForEv();
  const rowRaw =
    projectionPlayerRowForModel(dg, rEv) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg && samePlayerRound(p, rEv)) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg);
  const rowClean = rowRaw ? rowWithoutLivePartialFields(rowRaw) : null;

  const histOk = Boolean(HISTORY._ok);

  if (
    !Number.isFinite(dg) ||
    !Number.isFinite(throughHoles) ||
    throughHoles < 0 ||
    throughHoles > 18 ||
    !Number.isFinite(curRaw) ||
    (!isRoundScoreMarket && curRaw < 0) ||
    (isRoundScoreMarket && !Number.isFinite(parThru)) ||
    !Number.isFinite(line)
  ) {
    root.innerHTML = `<p class="live-prop-placeholder">Complete the form to see projection and edge.</p>`;
    return;
  }

  if (!rowClean) {
    root.innerHTML = `<p class="text-warn">No projection row for this golfer — refresh projections.</p>`;
    return;
  }

  let muRem;
  let sigRem;

  if (statKey === "gir" || statKey === "fairways" || statKey === "putts") {
    const m = livePropModelRemainderSigma(marketLabel, rowClean, statKey, completed, { playOrder, holePars });
    muRem = m.muRem;
    sigRem = m.sigRem;
  } else {
    const { samples } = livePropHistoricalRemainders(dg, statKey, completed, undefined, playOrder);
    const mMod = livePropModelRemainderSigma(marketLabel, rowClean, statKey, completed, { playOrder, holePars });
    const { mean: muHist, std: sigHist, n: nEff } = livePropSampleMeanStd(samples);
    const w = Math.min(1, nEff / 26);
    if (histOk && nEff >= 6 && Number.isFinite(muHist) && Number.isFinite(sigHist)) {
      muRem = w * muHist + (1 - w) * mMod.muRem;
      sigRem = Math.max(0.25, w * sigHist + (1 - w) * mMod.sigRem);
    } else {
      muRem = mMod.muRem;
      sigRem = mMod.sigRem;
    }
  }

  if (!Number.isFinite(muRem) || !Number.isFinite(sigRem)) {
    root.innerHTML = `<p class="text-warn">Could not build remainder distribution for this market.</p>`;
    return;
  }

  const predFinal = currentForProjection + muRem;
  const sigF = Math.max(0.22, sigRem);
  const z = (line - predFinal) / sigF;
  const pOver = clampProb01(1 - normalCdf(z));
  const pUnder = clampProb01(1 - pOver);

  const dO = decimalFromAmerican(oAm);
  const dU = decimalFromAmerican(uAm);
  const evO = Number.isFinite(dO) && dO > 1 ? pOver * dO - 1 : NaN;
  const evU = Number.isFinite(dU) && dU > 1 ? pUnder * dU - 1 : NaN;

  const LIVE_PROP_MODEL_VIG = 0.075;
  const vigOverProb = clampProb01(pOver * (1 + LIVE_PROP_MODEL_VIG));
  const vigUnderProb = clampProb01(pUnder * (1 + LIVE_PROP_MODEL_VIG));
  const fairOverAm = americanFromImpliedProb(vigOverProb);
  const fairUnderAm = americanFromImpliedProb(vigUnderProb);
  const fmtFair = (am) => (Number.isFinite(am) ? formatAmerican(am) : "—");
  const fmtEv = (x) =>
    Number.isFinite(x)
      ? `<span class="${x >= 0 ? "ev-pos" : "ev-neg"}">${(x * 100).toFixed(1)}%</span>`
      : "—";

  const prec = statKey === "total" ? 2 : 1;
  root.innerHTML = `
    <div class="live-prop-result-grid">
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">Projected</span>
        <span class="live-prop-metric-val">${predFinal.toFixed(prec)}</span>
      </div>
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">Standard deviation</span>
        <span class="live-prop-metric-val">${sigF.toFixed(2)}</span>
      </div>
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">Over fair price</span>
        <span class="live-prop-metric-val">${fmtFair(fairOverAm)}</span>
      </div>
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">Under fair price</span>
        <span class="live-prop-metric-val">${fmtFair(fairUnderAm)}</span>
      </div>
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">EV Over</span>
        <span class="live-prop-metric-val">${fmtEv(evO)}</span>
      </div>
      <div class="live-prop-metric">
        <span class="live-prop-metric-label">EV Under</span>
        <span class="live-prop-metric-val">${fmtEv(evU)}</span>
      </div>
    </div>`;
}

/** DraftKings round props in DATA.props (from fetch:dk-ou / fetch:book-odds): fill line + American odds when available for golfer + market. */
function syncLivePropBookLineAndOddsFromDk() {
  const statKey = String(document.getElementById("live-prop-market")?.value || "total");
  const dg = Math.round(num(document.getElementById("live-prop-golfer")?.value, NaN));
  const lineEl = document.getElementById("live-prop-line");
  const oEl = document.getElementById("live-prop-over-am");
  const uEl = document.getElementById("live-prop-under-am");
  if (!lineEl || !oEl || !uEl) return;

  const fallbackLineAndOdds = () => {
    const d = defaultPropLineForStat(statKey);
    lineEl.value = formatPropLineValueForInput(clampPropLineForMarket(statKey, d));
    oEl.value = formatAmericanOddsInput(OU_DEFAULT_ODDS_AM);
    uEl.value = formatAmericanOddsInput(OU_DEFAULT_ODDS_AM);
  };

  if (!Number.isFinite(dg) || dg <= 0) {
    fallbackLineAndOdds();
    return;
  }

  const marketLabel = ouMarketKeyFromStatKey(statKey);
  const rEv = getModelRoundForEv();
  const rowRaw =
    projectionPlayerRowForModel(dg, rEv) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg && samePlayerRound(p, rEv)) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg);
  const rowClean = rowRaw ? rowWithoutLivePartialFields(rowRaw) : null;

  if (!rowClean) {
    fallbackLineAndOdds();
    return;
  }

  const mu = ouProjectedMean(marketLabel, rowClean);
  const pick = chooseOuPropLineForProjection(marketLabel, rowClean, mu);
  if (pick && Number.isFinite(pick.line)) {
    lineEl.value = formatPropLineValueForInput(clampPropLineForMarket(statKey, pick.line));
    oEl.value = formatAmericanOddsInput(pick.over);
    uEl.value = formatAmericanOddsInput(pick.under);
    return;
  }

  fallbackLineAndOdds();
}

function syncLivePropCurrentInputLabel() {
  const statKey = String(document.getElementById("live-prop-market")?.value || "total");
  const through = Math.round(num(document.getElementById("live-prop-through-holes")?.value, NaN));
  const startHoleRaw = Math.round(num(document.getElementById("live-prop-start-hole")?.value, NaN));
  const startHole = Number.isFinite(startHoleRaw) && startHoleRaw >= 1 && startHoleRaw <= 18 ? startHoleRaw : 1;
  const playOrder = livePropPlayOrder(startHole);
  const labelEl = document.getElementById("live-prop-current-label");
  const inputEl = document.getElementById("live-prop-current");
  if (!labelEl || !inputEl) return;
  if (statKey === "total") {
    const par18 = num(DATA?.meta?.course_par_18, NaN);
    const holePars = DATA?.meta?.hole_pars;
    let parThru = courseParSumPlayOrderThru(holePars, playOrder, through);
    if (!Number.isFinite(parThru) && Number.isFinite(par18) && Number.isFinite(through)) {
      parThru = (par18 / 18) * clamp(through, 0, 18);
    }
    labelEl.textContent = "Current to par";
    inputEl.min = "-18";
    inputEl.step = "1";
    inputEl.placeholder = "0";
  } else {
    labelEl.textContent = "Current total";
    inputEl.min = "0";
    inputEl.step = "0.1";
    inputEl.placeholder = "0";
  }
}

function initLivePropPredictorUi() {
  const marketEl = document.getElementById("live-prop-market");
  if (marketEl && [...marketEl.options].some((o) => o.value === "birdies")) marketEl.value = "birdies";
  const throughEl = document.getElementById("live-prop-through-holes");
  if (throughEl) throughEl.value = "6";
  const startHoleEl = document.getElementById("live-prop-start-hole");
  if (startHoleEl) startHoleEl.value = "1";
  const currentEl = document.getElementById("live-prop-current");
  if (currentEl) currentEl.value = "2";
  const lineEl = document.getElementById("live-prop-line");
  if (lineEl) lineEl.value = "4.5";
  syncLivePropCurrentInputLabel();
  const ids = [
    "live-prop-golfer",
    "live-prop-market",
    "live-prop-start-hole",
    "live-prop-through-holes",
    "live-prop-current",
    "live-prop-line",
    "live-prop-over-am",
    "live-prop-under-am",
  ];
  for (const id of ids) {
    document.getElementById(id)?.addEventListener("change", () => {
      if (id === "live-prop-market" || id === "live-prop-golfer") syncLivePropBookLineAndOddsFromDk();
      if (id === "live-prop-market" || id === "live-prop-through-holes" || id === "live-prop-start-hole") {
        syncLivePropCurrentInputLabel();
      }
      renderLivePropPredictor();
    });
    document.getElementById(id)?.addEventListener("input", () => {
      if (id === "live-prop-market" || id === "live-prop-through-holes" || id === "live-prop-start-hole") {
        syncLivePropCurrentInputLabel();
      }
      renderLivePropPredictor();
    });
  }
  fillLivePropGolferSelect();
  syncLivePropBookLineAndOddsFromDk();
  renderLivePropPredictor();
}

