function selectedPropsWeatherConditionKeys() {
  const keys = [];
  if (document.getElementById("props-filter-cond-clear")?.checked) keys.push("clear");
  if (document.getElementById("props-filter-cond-cloudy")?.checked) keys.push("cloudy");
  if (document.getElementById("props-filter-cond-rainy")?.checked) keys.push("rain", "storm");
  if (document.getElementById("props-filter-cond-windy")?.checked) keys.push("windy");
  return keys;
}

function propsWeatherConditionFilterActive() {
  const clear = Boolean(document.getElementById("props-filter-cond-clear")?.checked);
  const cloudy = Boolean(document.getElementById("props-filter-cond-cloudy")?.checked);
  const rainy = Boolean(document.getElementById("props-filter-cond-rainy")?.checked);
  const windy = Boolean(document.getElementById("props-filter-cond-windy")?.checked);
  return !(clear && cloudy && rainy && windy);
}

function historyRoundMatchesWeatherConditions(row, allowedKeys) {
  if (!allowedKeys?.length) return true;
  const key = propsConditionKeyFromRow(row);
  if (!key) return false;
  if (allowedKeys.includes(key)) return true;
  if (key === "storm" && allowedKeys.includes("rainy")) return true;
  return false;
}

function filterHistoryRoundsByWeatherConditions(list) {
  if (!propsWeatherConditionFilterActive()) return list;
  const allowed = selectedPropsWeatherConditionKeys();
  if (!allowed.length) return [];
  return list.filter((r) => historyRoundMatchesWeatherConditions(r, allowed));
}

function parseHistoryRowTeetimeMinutes(row) {
  const raw = String(row?.teetime ?? row?.pga_meta_teetime ?? row?.dg_teetime_local ?? "").trim();
  if (!raw) return NaN;
  const iso = parseDgTeetimeParts(raw);
  if (iso) return iso.hh * 60 + iso.mm;
  const m = raw.match(/^(\d{1,2}):(\d{2})\s*(am|pm)?/i);
  if (m) {
    let h = parseInt(m[1], 10);
    const mm = parseInt(m[2], 10);
    const ap = String(m[3] || "").toLowerCase();
    if (ap === "pm" && h < 12) h += 12;
    if (ap === "am" && h === 12) h = 0;
    if (!ap && h >= 1 && h <= 7) h += 12;
    return h * 60 + mm;
  }
  return NaN;
}

function normalizedTeeWave(row) {
  const w = String(row?.dg_tee_wave ?? "").trim().toLowerCase();
  if (w.includes("morning") || w === "am" || w === "a" || w === "early" || w.includes("early")) return "morning";
  if (w.includes("afternoon") || w === "pm" || w === "p" || w === "late" || w.includes("late")) return "afternoon";
  const min = parseHistoryRowTeetimeMinutes(row);
  if (!Number.isFinite(min)) return "";
  return min < 13 * 60 ? "morning" : "afternoon";
}

function historyRoundTeeWave(row) {
  return normalizedTeeWave(row);
}

function selectedPropsTeeWaveFilter() {
  return String(document.getElementById("props-filter-tee-wave")?.value || "").trim().toLowerCase();
}

function selectedOuTeeWaveFilter() {
  return String(document.getElementById("ou-tee-wave-filter")?.value || "").trim().toLowerCase();
}

function playerMatchesTeeWaveFilter(player, waveFilter) {
  if (!waveFilter) return true;
  const norm = normalizedTeeWave(player);
  if (!norm) return false;
  return norm === waveFilter;
}

function filterHistoryRoundsByTeeWave(list) {
  const wave = selectedPropsTeeWaveFilter();
  if (!wave) return list;
  return list.filter((r) => historyRoundTeeWave(r) === wave);
}

function selectedPropsRoundNumsFilter() {
  const out = [];
  for (let rn = 1; rn <= 4; rn++) {
    if (document.getElementById(`props-filter-round-${rn}`)?.checked) out.push(rn);
  }
  return out;
}

function propsRoundNumFilterActive() {
  const sel = selectedPropsRoundNumsFilter();
  return sel.length > 0 && sel.length < 4;
}

function filterHistoryRoundsByRoundNum(list) {
  const sel = selectedPropsRoundNumsFilter();
  if (!sel.length || sel.length >= 4) return list;
  const set = new Set(sel);
  return list.filter((r) => {
    const rn = Math.round(num(r?.round_num, NaN));
    return set.has(rn);
  });
}

function selectedPropsYearFilter() {
  const raw = String(document.getElementById("props-filter-year")?.value || "").trim();
  if (!raw) return NaN;
  const y = Math.round(num(raw, NaN));
  return y >= 1990 && y <= 2100 ? y : NaN;
}

function propsYearFilterActive() {
  if (propsFilterDraftKingsOnlyOn() && propsCourseWindowModeOn()) return false;
  return Number.isFinite(selectedPropsYearFilter());
}

function applyPropsWindowTailToRows(rows, statKey, winN, opts = {}) {
  const wn = clamp(
    Math.round(num(winN, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX,
  );
  const list = Array.isArray(rows) ? rows : [];
  const mode = selectedPropsTailMode();
  if (mode === "recent") {
    const sorted = [...list].sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
    return sorted.slice(0, wn).sort((a, b) => historyRoundChronoKey(a) - historyRoundChronoKey(b));
  }
  const lowerBetter = propsStatLowerIsBetter(statKey);
  const scored = [];
  for (const r of list) {
    const a = opts.courseWindow
      ? chartActualForCourseWindowEntry(statKey, { row: r })
      : actualForRoundRow(statKey, r);
    if (Number.isFinite(a)) scored.push({ r, a });
  }
  if (mode === "best") scored.sort((a, b) => (lowerBetter ? a.a - b.a : b.a - a.a));
  else scored.sort((a, b) => (lowerBetter ? b.a - a.a : a.a - b.a));
  return scored
    .slice(0, wn)
    .map((x) => x.r)
    .sort((a, b) => historyRoundChronoKey(a) - historyRoundChronoKey(b));
}

function applyPropsWindowTailToCourseEntries(entries, statKey, winN) {
  const byDg = new Map();
  for (const e of entries || []) {
    const id = Math.round(num(e?.dgId, NaN));
    if (!Number.isFinite(id)) continue;
    if (!byDg.has(id)) byDg.set(id, []);
    byDg.get(id).push(e);
  }
  const out = [];
  for (const list of byDg.values()) {
    const rows = list.map((e) => e.row);
    const picked = new Set(applyPropsWindowTailToRows(rows, statKey, winN, { courseWindow: true }));
    for (const e of list) {
      if (picked.has(e.row)) out.push(e);
    }
  }
  out.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  return out;
}

/** Field view: per-golfer round window (same tail logic as single-player course mode). */
function propsCourseWindowEntriesAfterWindow(entries, statKey, winN) {
  return applyPropsWindowTailToCourseEntries(entries, statKey, winN);
}

function propsAverageModeOn() {
  return Boolean(document.getElementById("props-filter-average")?.checked);
}

function propsFieldAverageChartActive() {
  return propsCourseWindowModeOn() && propsAverageModeOn();
}

function selectedPropsFieldAverageSort() {
  const v = String(document.getElementById("props-filter-avg-sort")?.value || "desc").trim().toLowerCase();
  return v === "asc" ? "asc" : "desc";
}

function propsWindowNMax() {
  return PROPS_HISTORY_ROUND_MAX;
}

function propsFieldSortControlVisible() {
  if (propsAverageModeOn()) return true;
  if (propsCourseWindowModeOn()) return true;
  const tail = selectedPropsTailMode();
  return tail === "best" || tail === "worst";
}

function syncPropsAverageUiState() {
  const fieldOn = propsCourseWindowModeOn();
  const avgOn = propsAverageModeOn();
  const sortWrap = document.getElementById("props-filter-avg-sort-wrap");
  if (sortWrap) sortWrap.hidden = !propsFieldSortControlVisible();
  const topRoundsLabel = document.querySelector(".props-trends-top-rounds .props-sidebar-label");
  if (topRoundsLabel) topRoundsLabel.textContent = fieldOn && avgOn ? "Players" : "Rounds";
  const winEl = document.getElementById("props-window-n");
  if (winEl) {
    winEl.max = String(propsWindowNMax());
    const v = clamp(Math.round(num(winEl.value, PROPS_HISTORY_ROUND_DEFAULT)), PROPS_HISTORY_ROUND_MIN, propsWindowNMax());
    if (String(v) !== winEl.value) winEl.value = String(v);
  }
}

function propsSuggestedWindowN() {
  if (propsCourseWindowModeActive()) {
    if (propsAverageModeOn()) return PROPS_FIELD_GOLFER_HORIZONTAL_MAX;
    const tail = selectedPropsTailMode();
    if (tail === "best" || tail === "worst") {
      return PROPS_FIELD_GOLFER_HORIZONTAL_MAX;
    }
    const sel = selectedPropsRoundNumsFilter();
    if (sel.length && sel.length < 4) return sel.length;
    return PROPS_HISTORY_ROUND_DEFAULT;
  }
  const dg = selectedDgId();
  if (!Number.isFinite(dg)) return PROPS_HISTORY_ROUND_DEFAULT;
  const n = filteredHistoryRounds(dg).length;
  return n > 0 ? Math.min(n, PROPS_HISTORY_ROUND_DEFAULT) : PROPS_HISTORY_ROUND_DEFAULT;
}

function syncPropsWindowNDefault(force = false) {
  if (propsWindowNUserOverride && !force) return;
  const el = document.getElementById("props-window-n");
  if (!el) return;
  const suggested = propsSuggestedWindowN();
  el.value = String(suggested);
}

function filterHistoryRoundsByYear(list) {
  const y = selectedPropsYearFilter();
  if (!Number.isFinite(y)) return list;
  return list.filter((r) => historyRoundSeasonYear(r) === y);
}

function selectedPropsTailMode() {
  const v = String(document.getElementById("props-filter-tail-mode")?.value || "recent").trim().toLowerCase();
  return v === "best" || v === "worst" ? v : "recent";
}

function propsSidebarFiltersContextKey() {
  return [
    propsTrendTempContextKey(),
    propsTrendWindContextKey(),
    propsTrendHumidityContextKey(),
    selectedPropsWeatherConditionKeys().join(","),
    selectedPropsTeeWaveFilter() || "all",
    selectedPropsRoundNumsFilter().join(","),
    Number.isFinite(selectedPropsYearFilter()) ? String(selectedPropsYearFilter()) : "all",
    propsRoundWeatherByKey?.size ?? 0,
  ].join("|");
}

function applyPropsSidebarFiltersToRounds(list, dgIdOpt) {
  let out = enrichHistoryRoundsForTrendsFilters(list, dgIdOpt);
  out = filterHistoryRoundsByTempRange(out);
  out = filterHistoryRoundsByWindRange(out);
  out = filterHistoryRoundsByHumidityRange(out);
  out = filterHistoryRoundsByWeatherConditions(out);
  out = filterHistoryRoundsByTeeWave(out);
  out = filterHistoryRoundsByRoundNum(out);
  out = filterHistoryRoundsByYear(out);
  return out;
}

function historyRoundWeatherLookupKey(row) {
  const eid = Math.round(num(row?.event_id, NaN));
  const yr = historyRoundSeasonYear(row);
  const rnd = Math.round(num(row?.round_num, NaN));
  if (!Number.isFinite(eid) || !Number.isFinite(yr) || !Number.isFinite(rnd)) return "";
  return `${eid}|${yr}|${rnd}`;
}

function playerDgTeetimeForRound(player) {
  const raw = String(player?.dg_teetime_local || "").trim();
  if (raw) return raw;
  const dg = Math.round(num(player?.dg_id, NaN));
  const rnd = Math.round(num(player?.round, NaN));
  const tt = fieldUpdatesTeetimeForDgRound(dg, rnd);
  return tt?.teetime ? String(tt.teetime).trim() : "";
}

function fieldUpdatesTeetimeForDgRound(dgId, roundNum) {
  const fu = lastLiveInPlayBundleForHistory?.field_updates;
  if (!fu || typeof fu !== "object") return null;
  const flist = fu.field ?? fu.field_updates ?? fu.players ?? fu.data;
  if (!Array.isArray(flist)) return null;
  const id = Math.round(num(dgId, NaN));
  const rnd = Math.round(num(roundNum, NaN));
  if (!Number.isFinite(id) || !Number.isFinite(rnd)) return null;
  const fp = flist.find((p) => Math.round(num(p?.dg_id ?? p?.dgId, NaN)) === id);
  const slots = Array.isArray(fp?.teetimes) ? fp.teetimes : [];
  const slot = slots.find((t) => Math.round(num(t?.round_num ?? t?.round, NaN)) === rnd);
  if (!slot?.teetime || !String(slot.teetime).trim()) return null;
  return {
    teetime: String(slot.teetime).trim(),
    wave: String(slot.wave || "").trim(),
  };
}

function enrichHistoryRowForTrendsFilters(row, dgIdOpt) {
  if (!row || typeof row !== "object") return row;
  const out = { ...row };
  const dg = Math.round(num(dgIdOpt ?? row?.dg_id, NaN));
  const rnd = Math.round(num(out.round_num, NaN));

  const wKey = historyRoundWeatherLookupKey(out);
  const snap = propsRoundWeatherByKey?.get?.(wKey);
  if (snap && Number.isFinite(num(snap.tempF, NaN))) {
    out.weather_temp_f = snap.tempF;
    if (Number.isFinite(num(snap.windMph, NaN))) out.weather_wind_mph = snap.windMph;
    if (Number.isFinite(num(snap.humidityPct, NaN))) out.weather_humidity = snap.humidityPct;
    if (snap.condition) out.weather_condition = String(snap.condition).toLowerCase();
    out.weather_source = "open_meteo_archive";
  } else if (!Number.isFinite(parseWeatherNumber(out.weather_temp_f))) {
    const p =
      projectionPlayerRowForModel(dg, rnd) ||
      DATA.players?.find((pl) => Math.round(num(pl.dg_id, NaN)) === dg && samePlayerRound(pl, rnd));
    if (p) {
      if (Number.isFinite(num(p.weather_temp_f, NaN))) out.weather_temp_f = p.weather_temp_f;
      if (Number.isFinite(num(p.weather_wind_mph, NaN))) out.weather_wind_mph = p.weather_wind_mph;
      if (Number.isFinite(num(p.weather_humidity, NaN))) out.weather_humidity = p.weather_humidity;
      if (p.weather_condition) out.weather_condition = String(p.weather_condition).toLowerCase();
    }
  }

  if (!String(out.teetime ?? "").trim()) {
    const tt = fieldUpdatesTeetimeForDgRound(dg, rnd);
    if (tt?.teetime) {
      out.teetime = tt.teetime;
      if (tt.wave) out.dg_tee_wave = tt.wave;
    }
  }
  if (!String(out.teetime ?? "").trim() && Number.isFinite(dg) && Number.isFinite(rnd)) {
    const p =
      projectionPlayerRowForModel(dg, rnd) ||
      DATA.players?.find((pl) => Math.round(num(pl.dg_id, NaN)) === dg && samePlayerRound(pl, rnd));
    if (p?.dg_teetime_local) {
      out.teetime = String(p.dg_teetime_local).trim();
      if (p.dg_tee_wave) out.dg_tee_wave = String(p.dg_tee_wave).trim();
    }
  }
  return out;
}

function enrichHistoryRoundsForTrendsFilters(list, dgIdOpt) {
  if (!Array.isArray(list) || !list.length) return list || [];
  return list.map((r) => enrichHistoryRowForTrendsFilters(r, dgIdOpt ?? r?.dg_id));
}

function enrichCourseWindowEntry(entry) {
  if (!entry?.row) return entry;
  const dgId = courseWindowEntryDgId(entry);
  const playerName =
    String(entry.playerName || entry.player_name || "").trim() ||
    resolveGolferDisplayNameForDg(dgId, entry.player_name);
  return {
    ...entry,
    dgId: Number.isFinite(dgId) ? dgId : entry.dgId,
    playerName,
    row: enrichHistoryRowForTrendsFilters(entry.row, dgId),
  };
}

async function ensurePropsRoundWeatherLoaded() {
  if (propsRoundWeatherByKey) return propsRoundWeatherByKey;
  if (propsRoundWeatherLoadPromise) return propsRoundWeatherLoadPromise;
  propsRoundWeatherLoadPromise = (async () => {
    if (isFileProtocol()) {
      propsRoundWeatherByKey = new Map();
      return propsRoundWeatherByKey;
    }
    try {
      const res = await fetch(cacheBustFetchUrl("data/historical_round_weather.json"), { cache: "no-store" });
      if (res.ok) {
        const j = await res.json();
        const map = new Map();
        for (const [k, v] of Object.entries(j?.byKey || {})) map.set(k, v);
        propsRoundWeatherByKey = map;
        return map;
      }
    } catch (_) {
      /* optional bundle */
    }
    propsRoundWeatherByKey = new Map();
    return propsRoundWeatherByKey;
  })();
  return propsRoundWeatherLoadPromise;
}

function ensurePropsRoundWeatherLoadedForTrends() {
  void ensurePropsRoundWeatherLoaded().then((map) => {
    if (!map?.size || propsRoundWeatherLoadedOnce) return;
    propsRoundWeatherLoadedOnce = true;
    invalidateCourseWindowRoundEntriesCache();
    if (activeAppTabId() === "props") scheduleRenderPropsTrends(0);
  });
}

function isoCalendarDayBefore(isoRaw) {
  const m = String(isoRaw || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return "";
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  d.setUTCDate(d.getUTCDate() - 1);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
}

/** Earliest chart day at venue → default From is the calendar day before first round. */
function propsCourseWindowDefaultFromIso(courseKey) {
  const days = distinctCompletedRoundDatesAtCourse(courseKey);
  if (!days.length) return "";
  const sorted = [...days].sort((a, b) => a.localeCompare(b));
  return isoCalendarDayBefore(sorted[0]);
}

function propsTrendTempContextKey() {
  const { minF, maxF } = propsTempBoundsFromDom();
  if (!Number.isFinite(minF) && !Number.isFinite(maxF)) return "all";
  const a = Number.isFinite(minF) ? String(minF) : "";
  const b = Number.isFinite(maxF) ? String(maxF) : "";
  return `${a}:${b}`;
}


function selectedPropsCourseFilter() {
  const raw = String(document.getElementById("props-filter-course")?.value || "").trim();
  if (!raw) return "";
  return normCourseNameKey(raw);
}

/** Event venue key for Historical Trends course window (projections meta). */
function propsEventVenueCourseKey() {
  const metaVenue = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  return metaVenue ? normCourseNameKey(metaVenue) : "";
}

/** In field mode: Course dropdown (empty = all courses) or Current course only. Single-player: current-course checkbox. */
function propsEffectiveCourseKey() {
  if (courseFilterOn()) return propsEventVenueCourseKey();
  const sel = selectedPropsCourseFilter();
  if (propsCourseWindowModeOn()) return sel;
  return sel;
}

/** Keep only entries whose row course_name matches the active course key. */
function filterCourseWindowEntriesToCourseKey(entries, courseKey) {
  const ck = String(courseKey || "").trim();
  if (!ck) return entries || [];
  return (entries || []).filter((e) => normCourseNameKey(e?.row?.course_name) === ck);
}

/** Label for chart tooltip / hit regions (row course_name, else active venue filter). */
function propsChartHitCourseLabel(hist) {
  const fromRow = hist ? propsCourseNameFromRow(hist) : "";
  if (fromRow) return fromRow;
  const ck = propsEffectiveCourseKey() || propsEventVenueCourseKey();
  return ck ? courseFitPrettyCourseKey(ck) : "";
}

/** This week's projection field. */
function propsFieldPlayerDgIds() {
  const ids = new Set();
  for (const p of roundProjectionPlayersForOuRound()) {
    const id = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(id)) continue;
    ids.add(id);
  }
  return ids;
}

function courseWindowEntryDgId(entry) {
  return Math.round(num(entry?.dgId ?? entry?.dg_id, NaN));
}

/** Keep only this week's field (and DK subset when that filter is on). */
function restrictCourseWindowEntriesToField(entries, statKey) {
  const fieldIds = new Set(
    [...propsFieldPlayerDgIds()].map((id) => Math.round(num(id, NaN))).filter((x) => Number.isFinite(x)),
  );
  if (!fieldIds.size) return propsCourseWindowModeOn() ? [] : entries || [];
  return (entries || []).filter((e) => fieldIds.has(courseWindowEntryDgId(e)));
}

/** Load per-player history shards for field view (season-sliced when possible). */
async function ensurePropsFieldPlayerHistoryLoaded(opts = {}) {
  const gen = opts.gen ?? propsFieldHistoryLoadGen;
  const seasonYear = Number.isFinite(num(opts.seasonYear, NaN))
    ? Math.round(num(opts.seasonYear, NaN))
    : propsFieldEffectiveSeasonYear();
  const ids = opts.ids ? [...opts.ids] : [...propsFieldPlayerDgIds()];
  if (!ids.length) return 0;
  const bucketReady = (id) =>
    Number.isFinite(seasonYear) ? historyBucketReadyForFieldSeason(id, seasonYear) : historyBucketLoaded(id);
  const missing = ids.filter((id) => !bucketReady(id));
  if (!missing.length) return 0;

  if (Number.isFinite(seasonYear)) {
    const bundled = await loadFieldSeasonHistoryBundle(seasonYear, { gen });
    if (gen !== propsFieldHistoryLoadGen) return 0;
    if (bundled) {
      opts.onBatch?.(ids.length, ids.length);
      return ids.length;
    }
  }

  const stillMissing = ids.filter((id) => !bucketReady(id));
  if (!stillMissing.length) return ids.length - missing.length;

  const loadOpts = Number.isFinite(seasonYear) ? { seasonYear } : {};
  const batch = 28;
  let loaded = ids.length - stillMissing.length;
  for (let i = 0; i < stillMissing.length; i += batch) {
    if (gen !== propsFieldHistoryLoadGen) return loaded;
    await Promise.all(stillMissing.slice(i, i + batch).map((id) => loadPlayerHistoryBucket(id, loadOpts)));
    loaded += Math.min(batch, stillMissing.length - i);
    opts.onBatch?.(loaded, ids.length);
  }
  return loaded;
}

function ensurePropsCourseSelectedForWindow(opts = {}) {
  if (!propsCourseWindowModeOn()) return false;
  const courseSel = document.getElementById("props-filter-course");
  if (!courseSel) return false;
  const prefer = propsEventVenueCourseKey();
  if (!prefer) return false;
  if (![...courseSel.options].some((o) => o.value === prefer)) {
    const op = document.createElement("option");
    op.value = prefer;
    op.textContent = courseFitPrettyCourseKey(prefer);
    courseSel.appendChild(op);
  }
  const cur = selectedPropsCourseFilter();
  const force = Boolean(opts.force);
  if (!force && (propsFieldCourseUserPicked || cur)) return false;
  if (courseSel.value !== prefer) {
    courseSel.value = prefer;
    return true;
  }
  return false;
}

/** UTC calendar day of the trends chart timestamp for one round row → `YYYY-MM-DD`. */
function historyRoundChartUtcIsoDay(row) {
  const ms = historyRoundChartDateUtcMs(row);
  if (!Number.isFinite(ms)) return "";
  const d = new Date(ms);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
}

/** Safe filename for `player-history/by-course/*.json` (must match build-player-history.mjs). */
function propsCourseShardFileName(courseKey) {
  const safe = String(courseKey || "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 96);
  return `${safe || "unknown"}.json`;
}

function propsStoreSingleCourseBucket(courseKey, bucket) {
  propsSingleCourseIndexSig = `${historyMutationEpoch}|${courseKey}`;
  propsSingleCourseIndexCache = bucket;
  propsCourseRoundIndex.set(courseKey, bucket);
  const ep = historyMutationEpoch;
  distinctCourseSessionDatesCache.set(courseKey, { epoch: ep, days: bucket.days });
}

function propsGetSingleCourseBucketSync(courseKey) {
  if (!courseKey) return null;
  const sig = `${historyMutationEpoch}|${courseKey}`;
  if (propsSingleCourseIndexSig === sig && propsSingleCourseIndexCache) {
    if (propsCourseWindowModeOn() && !propsSingleCourseIndexCache._fromCourseShard) return null;
    return propsSingleCourseIndexCache;
  }
  // Field mode must use the full by-course shard — not the partial index built from whichever
  // player histories happen to be in memory (often only the golfer selected in the search box).
  if (propsCourseWindowModeOn()) return null;
  const fromMap = propsCourseRoundIndex.get(courseKey);
  if (fromMap) return fromMap;
  return null;
}

/** Calendar year for the active field week (from datagolf_field_date_start). */
function currentEventSeasonYearFromMeta() {
  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4})-/);
  if (!ds) return NaN;
  const y = parseInt(ds[1], 10);
  return Number.isFinite(y) ? y : NaN;
}

/** Default season year for This week's field (current event year, else display season). */
function propsFieldDefaultSeasonYear() {
  const y = currentEventSeasonYearFromMeta();
  return Number.isFinite(y) ? y : PROPS_TREND_DISPLAY_SEASON_YEAR;
}

/** Active season year in field view — only when Year filter is set (default: all years). */
function propsFieldEffectiveSeasonYear() {
  return selectedPropsYearFilter();
}

function historyBucketReadyForFieldSeason(dgId, seasonYear) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return false;
  const bucket = HISTORY.byDgId?.[String(id)];
  if (!bucket || !Array.isArray(bucket.rounds)) return false;
  if (bucket._propsSeasonEmpty === true && bucket._propsSeasonSlice === seasonYear) return true;
  if (!bucket.rounds.length) return false;
  if (!Number.isFinite(seasonYear)) return true;
  if (bucket._propsSeasonSlice === seasonYear) return true;
  if (!Number.isFinite(bucket._propsSeasonSlice)) {
    return bucket.rounds.some((r) => historyRoundSeasonYear(r) === seasonYear);
  }
  return false;
}

/** Mark field players with no season rows so we do not re-fetch their career shards. */
function stampEmptyFieldSeasonBuckets(seasonYear, dgIds) {
  if (!Number.isFinite(seasonYear) || !dgIds?.length) return;
  const patch = {};
  for (const dgId of dgIds) {
    const id = Math.round(num(dgId, NaN));
    if (!Number.isFinite(id)) continue;
    if (historyBucketReadyForFieldSeason(id, seasonYear)) continue;
    const key = String(id);
    patch[key] = {
      dg_id: id,
      player_name: String(HISTORY.byDgId?.[key]?.player_name || "").trim(),
      rounds: [],
      _propsSeasonSlice: seasonYear,
      _propsSeasonEmpty: true,
    };
  }
  if (Object.keys(patch).length) mergePlayerHistoryPartialPayload({ byDgId: patch, holesByPlayerKey: {} });
}

/** Single prebuilt bundle: all field players' rounds for one season (~one HTTP request). */
async function loadFieldSeasonHistoryBundle(seasonYear, opts = {}) {
  const y = Math.round(num(seasonYear, NaN));
  if (!Number.isFinite(y)) return false;
  const gen = opts.gen ?? propsFieldHistoryLoadGen;
  const fieldIds = [...propsFieldPlayerDgIds()];
  if (!fieldIds.length) return true;
  if (fieldIds.every((id) => historyBucketReadyForFieldSeason(id, y))) return true;
  if (isFileProtocol()) return false;

  if (fieldSeasonHistoryLoadPromises.has(y)) return fieldSeasonHistoryLoadPromises.get(y);

  const p = (async () => {
    const url = cacheBustFetchUrl(`player-history/field-${y}.json`);
    const fetchOpts = { cache: "no-store" };
    if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
      fetchOpts.signal = AbortSignal.timeout(30000);
    }
    try {
      const res = await fetch(url, fetchOpts);
      if (gen !== propsFieldHistoryLoadGen) return false;
      if (res.ok) {
        const raw = await res.json();
        if (gen !== propsFieldHistoryLoadGen) return false;
        const byDgId = raw?.byDgId && typeof raw.byDgId === "object" ? raw.byDgId : {};
        for (const bucket of Object.values(byDgId)) {
          if (!bucket || typeof bucket !== "object") continue;
          bucket._propsSeasonSlice = y;
          bucket._propsSeasonEmpty = !Array.isArray(bucket.rounds) || bucket.rounds.length === 0;
        }
        const ok = mergePlayerHistoryPartialPayload({
          meta: raw?.meta || {},
          byDgId,
          holesByPlayerKey: raw?.holesByPlayerKey || {},
        });
        if (gen !== propsFieldHistoryLoadGen) return false;
        if (ok) {
          stampEmptyFieldSeasonBuckets(y, fieldIds);
          return fieldIds.every((id) => historyBucketReadyForFieldSeason(id, y));
        }
      }
    } catch (_) {
      /* bundle missing or timeout — fall back to per-player shards */
    }
    return false;
  })();

  fieldSeasonHistoryLoadPromises.set(y, p);
  try {
    return await p;
  } finally {
    fieldSeasonHistoryLoadPromises.delete(y);
  }
}

function ensurePropsFieldYearDefault(force = false) {
  if (!propsCourseWindowModeOn()) {
    propsFieldYearDefaultApplied = false;
    return;
  }
  const yearSel = document.getElementById("props-filter-year");
  if (!yearSel) return;
  if (force || !propsFieldYearDefaultApplied) {
    yearSel.value = "";
    propsFieldYearDefaultApplied = true;
  }
}

/** Chart play date M/D/YYYY from tournament week start + round_num (DK field-by-course). */
function propsTrendChartDateFromFieldRound(row) {
  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/);
  const rnd = Math.round(num(row?.round_num, NaN));
  if (!ds || !Number.isFinite(rnd)) return "";
  const iso = propsIsoFromFieldDateStartAndRound(ds[0], rnd);
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return "";
  return `${Number(m[2])}/${Number(m[3])}/${m[1]}`;
}

/** ISO YYYY-MM-DD for tournament round N from field week start (R1 = date_start). */
function propsIsoFromFieldDateStartAndRound(dateStartIso, roundNum) {
  const m = String(dateStartIso || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return "";
  const rn = Math.round(num(roundNum, NaN));
  if (!Number.isFinite(rn) || rn < 1 || rn > 4) return m[0];
  const t = Date.UTC(+m[1], +m[2] - 1, +m[3]) + (rn - 1) * 86400000;
  const d = new Date(t);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
}

/** Default session date from projections (current round when in play). */
function propsDefaultSessionIsoFromMeta() {
  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/);
  const cr = Math.round(num(DATA?.meta?.datagolf_field_current_round ?? DATA?.meta?.display_round, NaN));
  if (ds && Number.isFinite(cr) && cr >= 1 && cr <= 4) {
    return propsIsoFromFieldDateStartAndRound(ds[0], cr);
  }
  if (ds) return ds[1];
  const upd = String(DATA?.meta?.updated_at || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (upd && Number.isFinite(cr) && cr >= 1 && cr <= 4) {
    const t = Date.UTC(+upd[1], +upd[2] - 1, +upd[3]) - (cr - 1) * 86400000;
    const d = new Date(t);
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
  }
  return "";
}

function ensurePropsCourseWindowDateDefaultsFromMeta() {
  if (!propsCourseWindowModeOn()) return;
  const fromEl = document.getElementById("props-filter-date-from");
  const toEl = document.getElementById("props-filter-date-to");
  if (!fromEl || !toEl) return;
  if (String(fromEl.value || "").trim() || String(toEl.value || "").trim()) return;
  const courseKey = propsEffectiveCourseKey();
  if (!courseKey) return;
  const fromIso = propsCourseWindowDefaultFromIso(courseKey);
  if (fromIso) fromEl.value = fromIso;
}

async function loadPropsCoursesManifest() {
  if (propsCoursesManifestCache) return propsCoursesManifestCache;
  if (propsCoursesManifestPromise) return propsCoursesManifestPromise;
  propsCoursesManifestPromise = (async () => {
    if (isFileProtocol()) return { courses: [] };
    try {
      const res = await fetch(cacheBustFetchUrl("player-history/courses-manifest.json"), { cache: "no-store" });
      if (res.ok) {
        propsCoursesManifestCache = await res.json();
        return propsCoursesManifestCache;
      }
    } catch (_) {
      /* manifest optional */
    }
    propsCoursesManifestCache = { courses: [] };
    return propsCoursesManifestCache;
  })().finally(() => {
    propsCoursesManifestPromise = null;
  });
  return propsCoursesManifestPromise;
}

function propsCourseShardFilesToTry(courseKey) {
  const files = new Set();
  if (courseKey) files.add(propsCourseShardFileName(courseKey));
  for (const c of propsCoursesManifestCache?.courses || []) {
    const ck = String(c.course_key || "").trim();
    const file = String(c.file || "").trim();
    if (!file) continue;
    if (ck && normCourseNameKey(ck) === courseKey) files.add(file);
  }
  return [...files];
}

function parsePropsCourseShardPayload(j) {
  const entries = [];
  for (const e of j.entries || []) {
    const row = e.row && typeof e.row === "object" ? e.row : e;
    formatHistoryRoundCourseNameInPlace(row);
    const dgId = Math.round(num(e.dg_id ?? row?.dg_id, NaN));
    if (!Number.isFinite(dgId)) continue;
    entries.push({
      row,
      dgId,
      playerName: resolveGolferDisplayNameForDg(dgId, e.player_name || row?.player_name),
    });
  }
  const days = Array.isArray(j.days) ? j.days.map(String) : [];
  return { days, entries };
}

function propsCourseWindowEntryDedupeKey(e) {
  const r = e?.row;
  const sk = Math.round(num(r?.sortKey, NaN));
  if (Number.isFinite(sk) && sk > 0) return `${e.dgId}|${sk}`;
  const yr = Math.round(num(r?.year, NaN));
  const rn = Math.round(num(r?.round_num, NaN));
  const ev = String(r?.event_name || "").trim().toLowerCase();
  return `${e.dgId}|${yr}|${rn}|${ev}`;
}

/** Supplement prebuilt course shard with live-week rows from in-memory HISTORY (not yet in shard file). */
function mergeMemoryCourseEntriesIntoBucket(bucket, courseKey) {
  if (!bucket || !courseKey || !HISTORY?.byDgId) return bucket;
  const ep = historyMutationEpoch;
  if (bucket._memoryMergeEpoch === ep) return bucket;
  const seen = new Set((bucket.entries || []).map(propsCourseWindowEntryDedupeKey));
  const dateSet = new Set(Array.isArray(bucket.days) ? bucket.days : []);
  const nameByDg = buildPropsGolferDisplayNameMap();
  const dgIds = new Set();
  if (Array.isArray(DATA?.players)) {
    for (const p of DATA.players) {
      const id = Math.round(num(p.dg_id, NaN));
      if (Number.isFinite(id)) dgIds.add(id);
    }
  }
  const scanAll = propsHistorySmallEnoughForMemoryCourseIndex();
  const sources = scanAll
    ? Object.entries(HISTORY.byDgId)
    : [...dgIds].map((id) => [String(id), HISTORY.byDgId[String(id)]]);
  for (const [dgStr, rec] of sources) {
    const dgId = Math.round(num(dgStr, NaN));
    if (!Number.isFinite(dgId) || !rec || !Array.isArray(rec.rounds)) continue;
    const playerName = resolveGolferDisplayNameForDg(dgId, nameByDg.get(dgId), nameByDg);
    for (const r of rec.rounds) {
      if (!historyRoundCountsAsActual(r)) continue;
      if (normCourseNameKey(r.course_name) !== courseKey) continue;
  const entry = {
    row: enrichHistoryRowForTrendsFilters(enrichHistoryRowFromLiveActuals(r), dgId),
    dgId,
    playerName,
  };
      const key = propsCourseWindowEntryDedupeKey(entry);
      if (seen.has(key)) continue;
      seen.add(key);
      bucket.entries.push(entry);
      const iso = historyRoundChartUtcIsoDay(r);
      if (iso) dateSet.add(iso);
    }
  }
  bucket.days = [...dateSet].sort((a, b) => b.localeCompare(a));
  bucket._memoryMergeEpoch = ep;
  return bucket;
}

async function fetchPropsCourseHistoryShard(courseKey) {
  if (!courseKey || isFileProtocol()) return null;
  await loadPropsCoursesManifest();
  const files = propsCourseShardFilesToTry(courseKey);
  for (const file of files) {
    try {
      const res = await fetch(cacheBustFetchUrl(`player-history/by-course/${file}`), { cache: "no-store" });
      if (!res.ok) continue;
      const parsed = parsePropsCourseShardPayload(await res.json());
      if (parsed.entries.length) return parsed;
    } catch (_) {
      /* try next alias file */
    }
  }
  return null;
}

/** True when in-memory scan is small enough not to freeze the tab. */
function propsHistorySmallEnoughForMemoryCourseIndex() {
  const by = HISTORY?.byDgId;
  if (!by) return true;
  const keys = Object.keys(by);
  if (keys.length > 24) return false;
  let rounds = 0;
  for (const k of keys) {
    rounds += by[k]?.rounds?.length || 0;
    if (rounds > 4000) return false;
  }
  return true;
}

/** Scan in-memory history for one venue only, yielding so the tab stays responsive. */
async function buildPropsSingleCourseIndexFromMemory(courseKey) {
  const dateSet = new Set();
  const entries = [];
  if (!courseKey || !HISTORY?.byDgId) return { days: [], entries };
  const nameByDg = buildPropsGolferDisplayNameMap();
  const dgEntries = Object.entries(HISTORY.byDgId);
  for (let i = 0; i < dgEntries.length; i += PROPS_COURSE_INDEX_PLAYER_CHUNK) {
    for (const [dgStr, rec] of dgEntries.slice(i, i + PROPS_COURSE_INDEX_PLAYER_CHUNK)) {
      const dgId = Math.round(num(dgStr, NaN));
      if (!Number.isFinite(dgId) || !rec || !Array.isArray(rec.rounds)) continue;
      const playerName = resolveGolferDisplayNameForDg(dgId, nameByDg.get(dgId), nameByDg);
      for (const r of rec.rounds) {
        if (!historyRoundCountsAsActual(r)) continue;
        if (normCourseNameKey(r.course_name) !== courseKey) continue;
        entries.push({ row: r, dgId, playerName });
        const iso = historyRoundChartUtcIsoDay(r);
        if (iso) dateSet.add(iso);
      }
    }
    if (i + PROPS_COURSE_INDEX_PLAYER_CHUNK < dgEntries.length) await yieldToMain();
  }
  return { days: [...dateSet].sort((a, b) => b.localeCompare(a)), entries };
}

/**
 * Field-by-course: prefer prebuilt `player-history/by-course/*.json`, else chunked in-memory scan.
 * Never builds the all-courses index (that was freezing the tab).
 */
async function ensurePropsCourseIndexForKeyAsync(courseKey) {
  if (!courseKey) return { days: [], entries: [] };
  const cached = propsGetSingleCourseBucketSync(courseKey);
  if (cached) return cached;
  if (propsSingleCourseIndexPromise && propsSingleCourseIndexCourseKey === courseKey) {
    return propsSingleCourseIndexPromise;
  }
  propsSingleCourseIndexCourseKey = courseKey;
  propsSingleCourseIndexPromise = (async () => {
    const shard = await fetchPropsCourseHistoryShard(courseKey);
    if (shard?.entries?.length) {
      mergeMemoryCourseEntriesIntoBucket(shard, courseKey);
      shard._fromCourseShard = true;
      propsStoreSingleCourseBucket(courseKey, shard);
      return shard;
    }
    if (!propsCourseWindowModeOn() && propsHistorySmallEnoughForMemoryCourseIndex()) {
      const built = await buildPropsSingleCourseIndexFromMemory(courseKey);
      propsStoreSingleCourseBucket(courseKey, built);
      return built;
    }
    const iso = propsDefaultSessionIsoFromMeta();
    return {
      days: iso ? [iso] : [],
      entries: [],
      shardMissing: true,
    };
  })().finally(() => {
    propsSingleCourseIndexPromise = null;
  });
  return propsSingleCourseIndexPromise;
}

/**
 * Build full course dropdown list only (single-player mode). Field-by-course skips this scan.
 */
function rebuildPropsCourseRoundIndex() {
  const sig = String(historyMutationEpoch);
  if (propsCourseRoundIndexSig === sig && propsCourseRoundIndex.size > 0) return;
  propsCourseRoundIndexSig = sig;
  propsCourseRoundIndex.clear();
  if (!HISTORY?.byDgId) return;
  const nameByDg = buildPropsGolferDisplayNameMap();
  const tmp = new Map();
  for (const [dgStr, rec] of Object.entries(HISTORY.byDgId)) {
    const dgId = Math.round(num(dgStr, NaN));
    if (!Number.isFinite(dgId) || !rec || !Array.isArray(rec.rounds)) continue;
    const playerName = resolveGolferDisplayNameForDg(dgId, nameByDg.get(dgId), nameByDg);
    for (const r of rec.rounds) {
      if (!historyRoundCountsAsActual(r)) continue;
      const ck = normCourseNameKey(r.course_name);
      if (!ck) continue;
      let bucket = tmp.get(ck);
      if (!bucket) {
        bucket = { dateSet: new Set(), entries: [] };
        tmp.set(ck, bucket);
      }
      bucket.entries.push({ row: r, dgId, playerName });
      const iso = historyRoundChartUtcIsoDay(r);
      if (iso) bucket.dateSet.add(iso);
    }
  }
  for (const [ck, bucket] of tmp) {
    propsCourseRoundIndex.set(ck, {
      days: [...bucket.dateSet].sort((a, b) => b.localeCompare(a)),
      entries: bucket.entries,
    });
  }
}

function distinctCompletedRoundDatesAtCourse(courseKey) {
  if (!courseKey || !HISTORY?.byDgId) return [];
  const bucket = propsGetSingleCourseBucketSync(courseKey);
  if (bucket) return bucket.days;
  const ep = historyMutationEpoch;
  const hit = distinctCourseSessionDatesCache.get(courseKey);
  if (hit && hit.epoch === ep) return hit.days;
  return [];
}

function formatPropsCourseSessionDateLabel(isoRaw) {
  const m = String(isoRaw || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return String(isoRaw || "").trim() || "—";
  const mo = Number(m[2]);
  const d = Number(m[3]);
  const y = Number(m[1]);
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return `${months[mo - 1]} ${d}, ${y}`;
}

/** Prefer this week's round day from meta when it appears in course history. */
function propsEventPreferredSessionDateIso(sortedDescDays) {
  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/);
  const cr = Math.round(num(DATA?.meta?.datagolf_field_current_round ?? DATA?.meta?.display_round, NaN));
  if (ds && Number.isFinite(cr) && cr >= 1 && cr <= 4) {
    const s = propsIsoFromFieldDateStartAndRound(ds[0], cr);
    if (s && sortedDescDays.includes(s)) return s;
  }
  if (ds) {
    const s = ds[1];
    if (sortedDescDays.includes(s)) return s;
  }
  const upd = String(DATA?.meta?.updated_at || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (upd && Number.isFinite(cr) && cr >= 1 && cr <= 4) {
    const t = Date.UTC(+upd[1], +upd[2] - 1, +upd[3]) - (cr - 1) * 86400000;
    const d = new Date(t);
    const s = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
    if (sortedDescDays.includes(s)) return s;
  }
  return "";
}

/** Match old session dropdown: pick defaults when entering field-by-course or changing course while dates are unset. */
function ensurePropsCourseWindowDateDefaults() {
  if (!propsCourseWindowModeOn()) {
    propsCourseWindowDateDefaultsCourseTracked = "";
    return;
  }
  const courseKey = propsEffectiveCourseKey();
  const fromEl = document.getElementById("props-filter-date-from");
  const toEl = document.getElementById("props-filter-date-to");
  if (!fromEl || !toEl || !HISTORY?._ok) return;
  if (!courseKey) return;

  const applyDefaultRange = () => {
    const fromIso = propsCourseWindowDefaultFromIso(courseKey);
    if (fromIso) fromEl.value = fromIso;
    else fromEl.value = "";
    toEl.value = "";
  };

  let days = distinctCompletedRoundDatesAtCourse(courseKey);
  if (!days.length) {
    const iso = propsDefaultSessionIsoFromMeta();
    if (iso) days = [iso];
  }

  const bumpedCourse = courseKey !== propsCourseWindowDateDefaultsCourseTracked;
  propsCourseWindowDateDefaultsCourseTracked = courseKey;

  const fromRaw = String(fromEl.value || "").trim();
  const toRaw = String(toEl.value || "").trim();

  if (!bumpedCourse) {
    if (!fromRaw && !toRaw) applyDefaultRange();
    return;
  }

  applyDefaultRange();
}

function propsCourseWindowModeOn() {
  return Boolean(document.getElementById("props-filter-course-window")?.checked);
}

/** Field view: this week's projection field (all courses/years unless filtered). */
function propsCourseWindowModeActive() {
  return propsCourseWindowModeOn();
}

/** Removed DraftKings-only field filter — always full projection field. */
function propsFilterDraftKingsOnlyOn() {
  return false;
}

/** Field-by-course + DK: default From/To to R1–R4 only when both dates are blank (never overwrite user range). */
function propsEnsureDkTournamentDateRange() {
  if (!propsCourseWindowModeOn() || !propsFilterDraftKingsOnlyOn()) return;
  const fromEl = document.getElementById("props-filter-date-from");
  const toEl = document.getElementById("props-filter-date-to");
  if (!fromEl || !toEl) return;
  const fromRaw = String(fromEl.value || "").trim();
  const toRaw = String(toEl.value || "").trim();
  if (fromRaw || toRaw) return;
  const ds = String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/);
  if (!ds) return;
  const fromIso = propsIsoFromFieldDateStartAndRound(ds[0], 1);
  const toIso = propsIsoFromFieldDateStartAndRound(ds[0], 4);
  if (fromIso) fromEl.value = fromIso;
  if (toIso) toEl.value = toIso;
}

/** Drop future-only From dates in all-courses field view (stale tournament defaults). */
function propsSanitizeFieldDateFilters() {
  if (!propsCourseWindowModeOn() || propsEffectiveCourseKey()) return;
  const fromEl = document.getElementById("props-filter-date-from");
  if (!fromEl) return;
  const fromRaw = String(fromEl.value || "").trim();
  if (!fromRaw) return;
  const fromMs = propsCourseWindowDateInputToUtcMs(fromRaw, false);
  if (Number.isFinite(fromMs) && fromMs > Date.now() + 86400000) fromEl.value = "";
}

function propsTrendPlayerHasDraftKingsLine(dgId, playerName, statKey) {
  if (!draftKingsTournamentPropsAvailable()) return false;
  const market = ouMarketKeyFromStatKey(statKey);
  const canon = ouPropsCanonicalMarket(market);
  const id = Math.round(num(dgId, NaN));
  if (Number.isFinite(id) && dkAuditPropsLineKeys?.size) {
    for (const key of dkAuditPropsLineKeys) {
      if (key.startsWith(`${id}|`) && key.endsWith(`|${canon}`)) return true;
    }
  }
  const row = { dg_id: dgId, player_name: playerName };
  if (ouPropsRowsForMarketPlayer(market, row, { dkOnly: true, allDkRounds: true }).length) return true;
  return Boolean(courseFitFindDraftKingsOuProp(dgId, playerName, market));
}

function propsTrendPlayerHasDraftKingsLineForRound(dgId, playerName, statKey, roundNum) {
  const rnd = Math.round(num(roundNum, NaN));
  if (!Number.isFinite(rnd)) return false;
  const market = ouMarketKeyFromStatKey(statKey);
  const canon = ouPropsCanonicalMarket(market);
  const id = Math.round(num(dgId, NaN));
  if (Number.isFinite(id) && dkAuditPropsLineKeys?.has(`${id}|${rnd}|${canon}`)) return true;
  const row = { dg_id: dgId, player_name: playerName };
  return ouPropsRowsForMarketPlayer(market, row, { dkOnly: true, allDkRounds: true, roundNum: rnd }).length > 0;
}

function filterCourseWindowEntriesForDraftKings(entries, statKey) {
  if (!propsFilterDraftKingsOnlyOn()) return entries || [];
  return (entries || []).filter((e) => propsTrendPlayerHasDraftKingsLine(e.dgId, e.playerName, statKey));
}

/** Round projections tab field (same sort as Model O/U projection grid). */
function roundProjectionPlayersForOuRound() {
  const r = Math.round(getOuRound());
  let rows = ouSortedPlayerRowsProjection(r);
  if (!rows.length) {
    const alt = Math.round(effectiveUiModelRoundFromMeta());
    if (Number.isFinite(alt) && alt !== r) rows = ouSortedPlayerRowsProjection(alt);
  }
  return rows;
}

function propsTrendIndexCourseEntriesByDg(bucket, courseKey, fieldDgIds) {
  const byDg = new Map();
  const add = (e) => {
    const id = e.dgId;
    if (!Number.isFinite(id)) return;
    if (!byDg.has(id)) byDg.set(id, []);
    byDg.get(id).push(e);
  };
  for (const e of bucket?.entries || []) add(e);
  if (!courseKey || !HISTORY?.byDgId || !fieldDgIds?.size) return byDg;
  const nameByDg = buildPropsGolferDisplayNameMap();
  for (const id of fieldDgIds) {
    const rec = HISTORY.byDgId[String(id)];
    if (!rec || !Array.isArray(rec.rounds)) continue;
    const playerName = resolveGolferDisplayNameForDg(id, rec.player_name, nameByDg);
    for (const r of rec.rounds) {
      if (courseKey && normCourseNameKey(r.course_name) !== courseKey) continue;
      if (!historyRoundCountsAsActual(r)) continue;
      add({ row: r, dgId: id, playerName });
    }
  }
  return byDg;
}

function pickCourseWindowEntriesForPlayer(entries, fromMs, toMs) {
  const list = entries || [];
  let inWin = list.filter((e) => historyRoundInCourseDateWindow(e.row, fromMs, toMs));
  if (!inWin.length && list.length) {
    const sorted = [...list].sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
    inWin = [sorted[sorted.length - 1]];
  }
  return inWin;
}

function applyChartActualToHistoryRow(statKey, row, chartActual) {
  if (!row || typeof row !== "object" || !Number.isFinite(chartActual)) return row;
  const out = { ...row, _from_dg_historical_rounds: true };
  if (statKey === "total") out.round_score = chartActual;
  else if (statKey === "birdies") out.birdies = chartActual;
  else if (statKey === "pars") out.pars = chartActual;
  else if (statKey === "bogeys") out.bogies = chartActual;
  else if (statKey === "gir") out.gir = chartActual;
  else if (statKey === "fairways") out.fairways = chartActual;
  else if (statKey === "putts") out.putts = chartActual;
  return out;
}

/** One chart value per DK golfer: venue history when chartable, else round projection mean. */
function chartActualForDraftKingsCourseWindow(statKey, entry, playerRow) {
  const market = ouMarketKeyFromStatKey(statKey);
  if (Number.isFinite(entry?.chartActual)) return entry.chartActual;
  if (entry?.row && !entry.row._from_projection_chart) {
    let actual = actualForRoundRow(statKey, entry.row);
    if (!Number.isFinite(actual)) actual = actualForFieldVenueKpiRow(statKey, entry.row);
    if (Number.isFinite(actual)) return actual;
  }
  if (playerRow) return ouProjectedMean(market, playerRow);
  return NaN;
}

function propsCourseWindowDateBoundsMs() {
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  if (!fromRaw && !toRaw) return { ok: false, fromMs: NaN, toMs: NaN };
  let fromMs = propsCourseWindowDateInputToUtcMs(fromRaw, false);
  let toMs = propsCourseWindowDateInputToUtcMs(toRaw, true);
  if (Number.isFinite(fromMs) && Number.isFinite(toMs) && fromMs > toMs) {
    const swap = fromMs;
    fromMs = toMs;
    toMs = swap;
  }
  return { ok: true, fromMs, toMs };
}

/**
 * Field-by-course + DraftKings: one bar per golfer per tournament round with a DK line, chartable actual,
 * and play date inside the From/To filter.
 */
function collectCourseWindowDraftKingsProjectionEntries(bucket, statKey, opts = {}) {
  const courseKey = propsEffectiveCourseKey();
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  const hasDateFilter = Boolean(fromRaw || toRaw);
  const bounds = hasDateFilter ? propsCourseWindowDateBoundsMs() : { ok: false, fromMs: NaN, toMs: NaN };

  const nameByDg = buildPropsGolferDisplayNameMap();
  const fieldPlayers = roundProjectionPlayersForOuRound();
  const fieldDgIds = new Set(
    fieldPlayers.map((p) => Math.round(num(p.dg_id, NaN))).filter((id) => Number.isFinite(id)),
  );
  const byDg = propsTrendIndexCourseEntriesByDg(bucket, courseKey, fieldDgIds);
  const cap = currentTournamentProgressRoundCap();

  const raw = [];
  const seen = new Set();
  for (const p of fieldPlayers) {
    const dgId = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(dgId)) continue;
    const playerName = resolveGolferDisplayNameForDg(dgId, p.player_name, nameByDg);
    if (!propsTrendPlayerHasDraftKingsLine(dgId, playerName, statKey)) continue;
    const histAll = (byDg.get(dgId) || []).filter((e) => {
      if (!historyRoundCountsAsActual(e.row)) return false;
      const rnd = Math.round(num(e.row?.round_num, NaN));
      if (Number.isFinite(cap) && Number.isFinite(rnd) && rnd > cap) return false;
      if (propsRoundNumFilterActive()) {
        const sel = new Set(selectedPropsRoundNumsFilter());
        if (!sel.has(rnd)) return false;
      }
      return true;
    });
    histAll.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));

    for (const pick of histAll) {
      const rnd = Math.round(num(pick.row?.round_num, NaN));
      if (!Number.isFinite(rnd)) continue;
      const dedupe = `${dgId}|${rnd}|${historyRoundChronoKey(pick.row)}`;
      if (seen.has(dedupe)) continue;
      seen.add(dedupe);

      const chartActual = chartActualForDraftKingsCourseWindow(statKey, pick, p);
      if (!Number.isFinite(chartActual)) continue;

      let row = enrichHistoryRowForTrendsFilters({ ...pick.row }, dgId);
      if (!Number.isFinite(actualForRoundRow(statKey, row))) {
        row = applyChartActualToHistoryRow(statKey, row, chartActual);
      }
      const playIso = propsIsoFromFieldDateStartAndRound(
        String(DATA?.meta?.datagolf_field_date_start || "").match(/^(\d{4}-\d{2}-\d{2})/)?.[0] || "",
        rnd,
      );
      if (playIso && historyRoundMatchesCurrentEvent(row)) row.chart_session_iso = playIso;

      if (bounds.ok && !historyRoundInCourseDateWindow(row, bounds.fromMs, bounds.toMs)) continue;

      raw.push({
        row,
        dgId,
        playerName: playerName || pick.playerName,
        chartActual,
      });
    }
  }

  return opts.applySidebarFilters === false ? raw : filterCourseWindowEntriesBySidebarFilters(raw);
}

function propsCourseWindowDateInputToUtcMs(raw, endOfDay) {
  const s = String(raw || "").trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return NaN;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (!Number.isFinite(y) || !Number.isFinite(mo) || !Number.isFinite(d)) return NaN;
  return endOfDay ? Date.UTC(y, mo - 1, d, 23, 59, 59, 999) : Date.UTC(y, mo - 1, d);
}

function propsCourseWindowDateRangeLabel() {
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  if (!fromRaw && !toRaw) return "";
  const f = formatPropsCourseSessionDateLabel;
  if (fromRaw && toRaw && fromRaw === toRaw) return f(fromRaw);
  if (fromRaw && !toRaw) return `${f(fromRaw)} → …`;
  if (!fromRaw && toRaw) return `… → ${f(toRaw)}`;
  return `${f(fromRaw)} – ${f(toRaw)}`;
}

function historyRoundMatchesCourseKey(row, courseKey) {
  if (!row || !courseKey) return false;
  return normCourseNameKey(row.course_name) === courseKey;
}

function historyRoundInCourseDateWindow(row, fromMs, toMs) {
  const ms = historyRoundChartDateUtcMs(row);
  if (!Number.isFinite(ms)) return true;
  if (Number.isFinite(fromMs) && ms < fromMs) return false;
  if (Number.isFinite(toMs) && ms > toMs) return false;
  return true;
}

function propsIsoDayDistanceMs(isoA, isoB) {
  const ta = Date.parse(`${isoA}T12:00:00Z`);
  const tb = Date.parse(`${isoB}T12:00:00Z`);
  if (!Number.isFinite(ta) || !Number.isFinite(tb)) return Infinity;
  return Math.abs(ta - tb);
}

/** Nearest completed session at venue when the picked calendar day has no rows yet. */
function propsPickNearestCourseSessionDay(bucket, fromRaw, toRaw) {
  const days = Array.isArray(bucket?.days) ? bucket.days.filter(Boolean) : [];
  if (!days.length || !fromRaw || !toRaw || fromRaw !== toRaw) return "";
  if (days.includes(fromRaw)) return "";
  let best = days[0];
  let dist = propsIsoDayDistanceMs(fromRaw, best);
  for (const d of days) {
    const dd = propsIsoDayDistanceMs(fromRaw, d);
    if (dd < dist) {
      dist = dd;
      best = d;
    }
  }
  return best || "";
}

function historyRoundFilterKey(row) {
  const dg = Math.round(num(row?.dg_id ?? row?.dgId, NaN));
  const eid = Math.round(num(row?.event_id, NaN));
  const yr = historyRoundSeasonYear(row);
  const rnd = Math.round(num(row?.round_num, NaN));
  if (Number.isFinite(dg) && Number.isFinite(eid) && Number.isFinite(yr) && Number.isFinite(rnd)) {
    return `${dg}|${eid}|${yr}|${rnd}`;
  }
  return `${dg}|${historyRoundChronoKey(row)}`;
}

function filterCourseWindowEntriesBySidebarFilters(entries) {
  if (!entries?.length) return entries || [];
  const rows = entries.map((e) => enrichHistoryRowForTrendsFilters(e.row, e.dgId));
  const filtered = applyPropsSidebarFiltersToRounds(rows, undefined);
  const keep = new Set(filtered.map(historyRoundFilterKey));
  return entries.filter((e, i) => keep.has(historyRoundFilterKey(rows[i])));
}

function filterCourseWindowEntriesByDateMs(bucket, fromMs, toMs) {
  const raw = [];
  for (const e of bucket.entries || []) {
    const enriched = enrichCourseWindowEntry(e);
    if (!historyRoundInCourseDateWindow(enriched.row, fromMs, toMs)) continue;
    raw.push(enriched);
  }
  raw.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  return filterCourseWindowEntriesBySidebarFilters(raw);
}

/** Chart + window KPI actual (field venue rules for totals; DK entries may carry chartActual). */
function chartActualForCourseWindowEntry(statKey, entry) {
  if (Number.isFinite(entry?.chartActual)) return entry.chartActual;
  const row = entry?.row;
  if (!row) return NaN;
  let actual = actualForRoundRow(statKey, row);
  if (!Number.isFinite(actual)) actual = actualForFieldVenueKpiRow(statKey, row);
  return actual;
}

function applyPropsSidebarWeatherFiltersToRounds(list) {
  return applyPropsSidebarFiltersToRounds(list);
}

/** All field-player rounds (optional course + date filters) from per-player history. */
function collectFieldRoundEntriesFromPlayerHistory(opts = {}) {
  if (!HISTORY?.byDgId) return [];
  const courseKey = propsEffectiveCourseKey();
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  const hasDateFilter = Boolean(fromRaw || toRaw);
  const skipDateFilter = Boolean(opts.skipDateFilter);
  const applyDateBounds = hasDateFilter && !skipDateFilter && Boolean(courseKey);
  const bounds = applyDateBounds ? propsCourseWindowDateBoundsMs() : { ok: false, fromMs: NaN, toMs: NaN };
  const nameByDg = buildPropsGolferDisplayNameMap();
  const fieldIds = propsFieldPlayerDgIds();
  const seasonYear = selectedPropsYearFilter();
  const raw = [];
  for (const id of fieldIds) {
    const rec = HISTORY.byDgId[String(id)];
    if (!rec || !Array.isArray(rec.rounds)) continue;
    const playerName = resolveGolferDisplayNameForDg(id, rec.player_name, nameByDg);
    for (const r of rec.rounds) {
      if (!historyRoundCountsAsActual(r)) continue;
      if (Number.isFinite(seasonYear) && historyRoundSeasonYear(r) !== seasonYear) continue;
      if (courseKey && normCourseNameKey(r.course_name) !== courseKey) continue;
      if (bounds.ok && !historyRoundInCourseDateWindow(r, bounds.fromMs, bounds.toMs)) continue;
      raw.push(enrichCourseWindowEntry({ row: r, dgId: id, playerName }));
    }
  }
  raw.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  return opts.applySidebarFilters === false ? raw : filterCourseWindowEntriesBySidebarFilters(raw);
}

/** DK field: tournament-week rows when live, plus full history for round-projection DK golfers. */
function collectDkFieldPlayerRoundEntries(statKey, bucketOpt, opts = {}) {
  const courseKey = propsEffectiveCourseKey();
  const merged = [];
  const seen = new Set();
  const add = (list) => {
    for (const e of list || []) {
      const key = `${e.dgId}|${Math.round(num(e.row?.round_num, NaN))}|${historyRoundChronoKey(e.row)}`;
      if (seen.has(key)) continue;
      seen.add(key);
      merged.push(e);
    }
  };
  const dkOpts = opts.applySidebarFilters === false ? { applySidebarFilters: false } : {};
  if (courseKey) {
    const bucket = bucketOpt || propsGetSingleCourseBucketSync(courseKey);
    if (bucket) {
      mergeMemoryCourseEntriesIntoBucket(bucket, courseKey);
      add(collectCourseWindowDraftKingsProjectionEntries(bucket, statKey, dkOpts));
    }
  } else {
    add(collectCourseWindowDraftKingsProjectionEntries(null, statKey, dkOpts));
  }
  let hist = collectFieldRoundEntriesFromPlayerHistory({ skipDateFilter: true, applySidebarFilters: false });
  hist = filterCourseWindowEntriesForDraftKings(hist, statKey);
  add(hist);
  merged.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  return opts.applySidebarFilters === false ? merged : filterCourseWindowEntriesBySidebarFilters(merged);
}

function propsCourseWindowRawEntriesCacheSig(bucketOpt) {
  const courseKey = propsEffectiveCourseKey();
  const statKey = statKeyFromPropSelect();
  const dkProj = propsFilterDraftKingsOnlyOn();
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  const fieldFp = propsCourseWindowModeOn()
    ? `field|${playerDgFingerprint(roundProjectionPlayersForOuRound())}`
    : "";
  return [
    historyMutationEpoch,
    courseKey || "all",
    fromRaw,
    toRaw,
    Number.isFinite(propsFieldEffectiveSeasonYear()) ? String(propsFieldEffectiveSeasonYear()) : "all",
    fieldFp,
    dkProj ? `dkproj|${statKey}|${dkAuditPropsCacheSig}|${dkAuditPropsLineKeys?.size ?? 0}|${draftKingsRoundPropsOnly(true).length}` : "",
    bucketOpt ? "bucket" : "",
  ].join("|");
}

function collectCourseWindowEntriesFromBucket(bucket, courseKey) {
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  const entries = filterCourseWindowEntriesToCourseKey(bucket?.entries || [], courseKey);
  if (!fromRaw && !toRaw) {
    return entries
      .map((e) => enrichCourseWindowEntry(e))
      .sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  }
  const bounds = propsCourseWindowDateBoundsMs();
  let { fromMs, toMs } = bounds;
  let out = [];
  for (const e of entries) {
    const enriched = enrichCourseWindowEntry(e);
    if (!historyRoundInCourseDateWindow(enriched.row, fromMs, toMs)) continue;
    out.push(enriched);
  }
  out.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
  if (!out.length && entries.length && fromRaw && toRaw && fromRaw === toRaw) {
    const near = propsPickNearestCourseSessionDay(bucket, fromRaw, toRaw);
    if (near) {
      propsCourseWindowDateFallbackIso = near;
      fromMs = propsCourseWindowDateInputToUtcMs(near, false);
      toMs = propsCourseWindowDateInputToUtcMs(near, true);
      out = [];
      for (const e of entries) {
        const enriched = enrichCourseWindowEntry(e);
        if (!historyRoundInCourseDateWindow(enriched.row, fromMs, toMs)) continue;
        out.push(enriched);
      }
      out.sort((a, b) => historyRoundChronoKey(a.row) - historyRoundChronoKey(b.row));
    }
  }
  return out;
}

/** Heavy scan: field rounds before sidebar weather/round/year filters. */
function collectCourseWindowRoundEntriesRaw(bucketOpt) {
  const courseKey = propsEffectiveCourseKey();
  if (!HISTORY?.byDgId) return [];
  const statKey = statKeyFromPropSelect();
  const sig = propsCourseWindowRawEntriesCacheSig(bucketOpt);
  if (sig === courseWindowRoundEntriesRawCacheSig && courseWindowRoundEntriesRawCache) {
    return courseWindowRoundEntriesRawCache;
  }

  propsCourseWindowDateFallbackIso = "";
  const rawOpts = { applySidebarFilters: false };
  let out;
  if (!courseKey) {
    // "Current course only" with unknown venue must not fall back to all-course field history.
    out = courseFilterOn() ? [] : collectFieldRoundEntriesFromPlayerHistory(rawOpts);
  } else {
    const bucket = (bucketOpt?.entries?.length ? bucketOpt : null) || propsGetSingleCourseBucketSync(courseKey);
    if (!bucket) {
      out = [];
    } else {
      mergeMemoryCourseEntriesIntoBucket(bucket, courseKey);
      out = collectCourseWindowEntriesFromBucket(bucket, courseKey);
    }
  }
  if (propsCourseWindowModeOn()) {
    out = restrictCourseWindowEntriesToField(out, statKey);
  }

  courseWindowRoundEntriesRawCacheSig = sig;
  courseWindowRoundEntriesRawCache = out;
  return out;
}

/** All player-round rows for field view (one course, all courses, optional date window). */
function collectCourseWindowRoundEntriesFixed(bucketOpt) {
  const sidebarSig = propsSidebarFiltersContextKey();
  const sig = `${propsCourseWindowRawEntriesCacheSig(bucketOpt)}|sf|${sidebarSig}`;
  if (sig === courseWindowRoundEntriesCacheSig && courseWindowRoundEntriesCache) {
    return courseWindowRoundEntriesCache;
  }
  const out = filterCourseWindowEntriesBySidebarFilters(collectCourseWindowRoundEntriesRaw(bucketOpt));
  courseWindowRoundEntriesCacheSig = sig;
  courseWindowRoundEntriesCache = out;
  return out;
}

function propsCourseWindowEntriesForChart(winN, statKeyOpt) {
  const statKey = statKeyOpt || statKeyFromPropSelect();
  const list = collectCourseWindowRoundEntriesFixed();
  const wn = clamp(
    Math.round(num(winN, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX,
  );
  if (propsCourseWindowModeActive()) {
    return propsCourseWindowEntriesAfterWindow(list, statKey, wn);
  }
  if (list.length > wn) return list.slice(-wn);
  return list;
}

/** When the date window has more bars than we paint, sample evenly (not slice(-N) which drops early days). */
function sampleCourseWindowChartEntriesEvenly(entries, cap) {
  if (!entries?.length || entries.length <= cap) return entries || [];
  const out = [];
  const n = entries.length;
  for (let i = 0; i < cap; i++) {
    const idx = cap <= 1 ? 0 : Math.round((i * (n - 1)) / (cap - 1));
    out.push(entries[idx]);
  }
  return out;
}

function propsFullHitStatsFromRoundList(statKey, line, rounds, opts = {}) {
  if (!Number.isFinite(line)) return { valid: 0, over: 0, under: 0, overRate: NaN, underRate: NaN };
  let valid = 0;
  let over = 0;
  let under = 0;
  for (const r of rounds) {
    const a = opts.courseWindow ? chartActualForCourseWindowEntry(statKey, { row: r }) : actualForRoundRow(statKey, r);
    if (!Number.isFinite(a)) continue;
    valid++;
    if (a > line) over++;
    else if (a < line) under++;
  }
  return {
    valid,
    over,
    under,
    overRate: valid > 0 ? over / valid : NaN,
    underRate: valid > 0 ? under / valid : NaN,
  };
}

function propsCourseWindowFieldHitStats(statKey, line, winN) {
  const rounds = propsCourseWindowEntriesForChart(winN, statKey).map((e) => e.row);
  return propsFullHitStatsFromRoundList(statKey, line, rounds, { courseWindow: true });
}

function refreshPropsCourseFilterOptionsAllPlayers() {
  const courseSel = document.getElementById("props-filter-course");
  if (!courseSel) return;
  const prev = courseSel.value;
  const windowOn = propsCourseWindowModeOn();
  const metaVenue = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  const mkVenue = metaVenue ? normCourseNameKey(metaVenue) : "";
  const manifestN = propsCoursesManifestCache?.courses?.length ?? 0;
  const optsCacheKey = `${historyMutationEpoch}|${windowOn ? 1 : 0}|${mkVenue}|${manifestN}|${propsFilterDraftKingsOnlyOn() ? 1 : 0}`;
  let sortedEntries = propsAllPlayersCourseOptsEntries;
  if (propsAllPlayersCourseOptsCacheKey !== optsCacheKey || !sortedEntries) {
    const byKey = new Map();
    if (windowOn) {
      for (const c of propsCoursesManifestCache?.courses || []) {
        const k = normCourseNameKey(c.course_key);
        if (k) byKey.set(k, courseFitPrettyCourseKey(k));
      }
      for (const id of propsFieldPlayerDgIds()) {
        const rec = HISTORY.byDgId?.[String(id)];
        if (!rec?.rounds) continue;
        for (const r of rec.rounds) {
          if (historyRoundIsPlaceholderAllMarketsZero(r)) continue;
          const k = normCourseNameKey(r.course_name);
          if (!k) continue;
          if (!byKey.has(k)) byKey.set(k, courseFitPrettyCourseKey(k));
        }
      }
      if (mkVenue && !byKey.has(mkVenue)) byKey.set(mkVenue, courseFitPrettyCourseKey(mkVenue));
      sortedEntries = [...byKey.entries()].sort((a, b) => {
        if (mkVenue && a[0] === mkVenue) return -1;
        if (mkVenue && b[0] === mkVenue) return 1;
        return a[0].localeCompare(b[0]);
      });
      if (!propsCoursesManifestCache && !isFileProtocol()) {
        void loadPropsCoursesManifest().then((manifest) => {
          if (!manifest?.courses?.length || !propsCourseWindowModeOn()) return;
          propsAllPlayersCourseOptsCacheKey = "";
          refreshPropsCourseFilterOptionsAllPlayers();
          scheduleRenderPropsTrends(0);
        });
      }
    } else {
      rebuildPropsCourseRoundIndex();
      for (const k of propsCourseRoundIndex.keys()) {
        byKey.set(k, courseFitPrettyCourseKey(k));
      }
      if (metaVenue && mkVenue && !byKey.has(mkVenue)) byKey.set(mkVenue, courseFitPrettyCourseKey(mkVenue));
      sortedEntries = [...byKey.entries()].sort((a, b) => a[0].localeCompare(b[0]));
    }
    propsAllPlayersCourseOptsCacheKey = optsCacheKey;
    propsAllPlayersCourseOptsEntries = sortedEntries;
  }
  courseSel.disabled = false;
  courseSel.innerHTML = windowOn
    ? '<option value="">All courses</option>'
    : '<option value="">All</option>';
  for (const [k, label] of sortedEntries) {
    const op = document.createElement("option");
    op.value = k;
    op.textContent = label;
    courseSel.appendChild(op);
  }
  const prevK = prev ? normCourseNameKey(prev) : "";
  if (prevK && [...courseSel.options].some((o) => o.value === prevK)) courseSel.value = prevK;
  else if (windowOn && !propsFieldCourseUserPicked) ensurePropsCourseSelectedForWindow();
  refreshPropsYearFilterOptions(selectedDgId());
}

function defaultLineForCourseWindow(statKey, entries) {
  const vals = entries.map((e) => chartActualForCourseWindowEntry(statKey, e)).filter((x) => Number.isFinite(x));
  if (vals.length) {
    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
    return clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, mean));
  }
  return clampPropLineForMarket(statKey, defaultPropLineForStat(statKey));
}

/** KPI scope for field charts: match visible bars (capped player count), not the full filtered pool. */
function propsCourseWindowChartKpiScope(graphSeries, entriesAll) {
  const series = graphSeries || [];
  if (!series.length) {
    return { players: 0, rounds: 0, roundRows: [], fieldEntries: [] };
  }
  const dgIds = new Set();
  for (const s of series) {
    const id = Math.round(num(s.dgId, NaN));
    if (Number.isFinite(id)) dgIds.add(id);
  }
  const fieldEntries = (entriesAll || []).filter((e) => dgIds.has(e.dgId));
  const aggregateSeries = series.every((s) => s._aggregate);
  let rounds = 0;
  if (aggregateSeries) {
    for (const s of series) {
      const n = Math.round(num(s._golferAvgRounds, NaN));
      rounds += Number.isFinite(n) && n > 0 ? n : 1;
    }
  } else {
    rounds = series.length;
  }
  let roundRows;
  if (aggregateSeries && propsAverageModeOn()) {
    roundRows = fieldEntries.map((e) => e.row);
  } else {
    roundRows = series.map((s) => s._hist).filter(Boolean);
  }
  return { players: dgIds.size, rounds, roundRows, fieldEntries };
}

function paintPropsTrendKpiRowCourseWindow(statKey, hitSt, graphSeries, entries) {
  const el = document.getElementById("props-trends-kpis");
  if (!el) return;
  if (!propsFieldVenueShardCache.ready && propsEventVenueCourseKey()) {
    el.replaceChildren();
    const wait = document.createElement("p");
    wait.className = "text-muted";
    wait.textContent = "Loading course history for venue KPIs…";
    el.appendChild(wait);
    ensurePropsFieldVenueHistoryLoaded();
    return;
  }
  el.replaceChildren();
  const scope = propsCourseWindowChartKpiScope(graphSeries, entries);
  const rounds = scope.roundRows;
  const playerCount = scope.players;
  const vals = (graphSeries || []).map((s) => s.actual).filter((x) => Number.isFinite(x));
  const graphMean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  const fieldVals = scope.fieldEntries
    .map((e) => chartActualForCourseWindowEntry(statKey, e))
    .filter((x) => Number.isFinite(x));
  const fieldMean = fieldVals.length
    ? fieldVals.reduce((a, b) => a + b, 0) / fieldVals.length
    : propsTrendMeanFieldVenueActual(statKey, rounds);
  const dkOnly = propsFilterDraftKingsOnlyOn();

  const addKpi = (label, val, cls, rawCount = false) => {
    const wrap = document.createElement("div");
    wrap.className = "props-trends-kpi";
    const lab = document.createElement("span");
    lab.className = "props-trends-kpi-lab";
    lab.textContent = label;
    const v = document.createElement("span");
    v.className = "props-trends-kpi-val" + (cls ? ` ${cls}` : "");
    v.textContent =
      rawCount && Number.isFinite(val) ? String(Math.round(val)) : formatPropsTrendKpiValue(statKey, val);
    wrap.appendChild(lab);
    wrap.appendChild(v);
    el.appendChild(wrap);
  };

  addKpi(dkOnly ? "DK field avg (window)" : "Field avg (window)", fieldMean);
  addKpi(dkOnly ? "DK graph avg" : "Graph avg", graphMean);
  ensurePropsFieldVenueHistoryLoaded();
  const atVenueSeason = roundsMatchingCurrentCourseOnlyFieldSeason();
  const atVenueAll = roundsMatchingCurrentCourseOnlyFieldAllTime();
  addKpi(
    `${PROPS_TREND_DISPLAY_SEASON_YEAR} course avg`,
    propsTrendSeasonCourseKpiValue(statKey, atVenueSeason),
  );
  addKpi(
    "All-time course avg",
    propsTrendFieldVenueKpiValue(statKey, atVenueAll, { allowMetaFallback: false }),
  );
  addKpi("Rounds", scope.rounds, "", true);
  addKpi("Players", playerCount, "", true);

  if (hitSt && hitSt.valid > 0) {
    const lowerBetter = propsStatLowerIsBetter(statKey);
    const addRateKpi = (label, rate, wins, total, side) => {
      const wrap = document.createElement("div");
      wrap.className = "props-trends-kpi";
      const lab = document.createElement("span");
      lab.className = "props-trends-kpi-lab";
      lab.textContent = label;
      const val = document.createElement("span");
      val.className = "props-trends-kpi-val";
      val.textContent = Number.isFinite(rate) ? `${(rate * 100).toFixed(1)}% (${wins}/${total})` : "—";
      const isUnderSide = side === "under";
      const greenSide = lowerBetter ? isUnderSide : !isUnderSide;
      val.classList.add(greenSide ? "ev-pos" : "ev-neg");
      wrap.appendChild(lab);
      wrap.appendChild(val);
      el.appendChild(wrap);
    };
    addRateKpi("Over hit rate", hitSt.overRate, hitSt.over, hitSt.valid, "over");
    addRateKpi("Under hit rate", hitSt.underRate, hitSt.under, hitSt.valid, "under");
  }
}

function parseWeatherNumber(v) {
  const n = num(v, NaN);
  if (Number.isFinite(n)) return n;
  const cleaned = String(v ?? "").replace(/[^0-9.-]+/g, "");
  const m = parseFloat(cleaned);
  return Number.isFinite(m) ? m : NaN;
}

function weatherRangeMatch(kind, bucket, value) {
  if (!bucket) return true;
  if (!Number.isFinite(value)) return false;
  if (kind === "temp") {
    if (bucket === "lt60") return value < 60;
    if (bucket === "60_69") return value >= 60 && value <= 69.999;
    if (bucket === "70_79") return value >= 70 && value <= 79.999;
    if (bucket === "80_89") return value >= 80 && value <= 89.999;
    if (bucket === "gte90") return value >= 90;
  }
  if (kind === "wind") {
    if (bucket === "0_5") return value >= 0 && value <= 5.999;
    if (bucket === "6_10") return value >= 6 && value <= 10.999;
    if (bucket === "11_15") return value >= 11 && value <= 15.999;
    if (bucket === "16_20") return value >= 16 && value <= 20.999;
    if (bucket === "gte21") return value >= 21;
  }
  if (kind === "humidity") {
    if (bucket === "lt40") return value < 40;
    if (bucket === "40_59") return value >= 40 && value <= 59.999;
    if (bucket === "60_79") return value >= 60 && value <= 79.999;
    if (bucket === "gte80") return value >= 80;
  }
  return true;
}

function propsConditionKeyFromRow(r) {
  const raw = String(
    r?.pga_meta_weather_condition ?? r?.weather_condition ?? r?.condition ?? ""
  )
    .trim()
    .toLowerCase();
  if (!raw) return "";
  if (raw.includes("storm") || raw.includes("thunder")) return "storm";
  if (raw.includes("rain") || raw.includes("shower") || raw.includes("drizzle")) return "rain";
  if (raw.includes("wind")) return "windy";
  if (raw.includes("cloud") || raw.includes("overcast")) return "cloudy";
  if (raw.includes("sun") || raw.includes("clear")) return "clear";
  return raw;
}

function propsConditionLabel(key) {
  if (!key) return "";
  if (key === "clear") return "Clear";
  if (key === "cloudy") return "Cloudy";
  if (key === "windy") return "Windy";
  if (key === "rain") return "Rain";
  if (key === "storm") return "Storm";
  return key
    .split(/[\s_]+/)
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function refreshPropsYearFilterOptions(dgId) {
  const yearSel = document.getElementById("props-filter-year");
  if (!yearSel) return;
  const prev = String(yearSel.value || "").trim();
  const years = new Set();
  if (propsCourseWindowModeOn()) {
    years.add(propsFieldDefaultSeasonYear());
    const courseKey = propsEffectiveCourseKey();
    if (courseKey) {
      const bucket = courseKey ? propsGetSingleCourseBucketSync(courseKey) : null;
      for (const e of bucket?.entries || []) {
        const y = historyRoundSeasonYear(e.row);
        if (Number.isFinite(y)) years.add(y);
      }
    }
    for (const id of propsFieldPlayerDgIds()) {
      const rec = HISTORY.byDgId?.[String(id)];
      if (!rec?.rounds) continue;
      for (const r of rec.rounds) {
        if (historyRoundIsPlaceholderAllMarketsZero(r)) continue;
        if (courseKey && normCourseNameKey(r.course_name) !== courseKey) continue;
        const y = historyRoundSeasonYear(r);
        if (Number.isFinite(y)) years.add(y);
      }
    }
  } else {
    const id = Math.round(num(dgId, NaN));
    if (Number.isFinite(id)) {
      for (const r of historyRoundsForDg(id)) {
        if (historyRoundIsPlaceholderAllMarketsZero(r)) continue;
        const y = historyRoundSeasonYear(r);
        if (Number.isFinite(y)) years.add(y);
      }
    }
  }
  yearSel.innerHTML = '<option value="">All years</option>';
  [...years]
    .sort((a, b) => b - a)
    .forEach((y) => {
      const op = document.createElement("option");
      op.value = String(y);
      op.textContent = String(y);
      yearSel.appendChild(op);
    });
  if (prev && [...yearSel.options].some((o) => o.value === prev)) yearSel.value = prev;
  else if (propsCourseWindowModeOn() && propsFieldYearDefaultApplied) yearSel.value = "";
}

function refreshPropsFilterOptionsForGolfer(dgId) {
  if (propsCourseWindowModeOn()) {
    refreshPropsCourseFilterOptionsAllPlayers();
    refreshPropsYearFilterOptions(dgId);
    return;
  }
  const courseSel = document.getElementById("props-filter-course");
  if (!courseSel) return;
  const rounds = historyRoundsForDg(dgId).filter((r) => !historyRoundIsPlaceholderAllMarketsZero(r));
  if (courseSel) {
    const prev = courseSel.value;
    /** @type {Map<string, string>} canonical key → pretty label */
    const byKey = new Map();
    for (const r of rounds) {
      const cn = String(r?.course_name || "").trim();
      if (!cn) continue;
      const k = normCourseNameKey(cn);
      if (!k) continue;
      if (!byKey.has(k)) byKey.set(k, courseFitPrettyCourseKey(k));
    }
    const metaVenue = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
    if (metaVenue) {
      const mk = normCourseNameKey(metaVenue);
      if (mk && !byKey.has(mk)) byKey.set(mk, courseFitPrettyCourseKey(mk));
    }
    courseSel.innerHTML = '<option value="">All</option>';
    [...byKey.entries()]
      .sort((a, b) => a[0].localeCompare(b[0]))
      .forEach(([k, label]) => {
        const op = document.createElement("option");
        op.value = k;
        op.textContent = label;
        courseSel.appendChild(op);
      });
    const prevK = prev ? normCourseNameKey(prev) : "";
    if (prevK && [...courseSel.options].some((o) => o.value === prevK)) courseSel.value = prevK;
  }
  refreshPropsYearFilterOptions(dgId);
}

const PROPS_SG_STAT_KEYS = Object.freeze([
  "sg_total",
  "sg_ott",
  "sg_app",
  "sg_arg",
  "sg_putt",
  "sg_t2g",
  // Approach SG by distance/lie (from shot traces)
  "sg_50_100_fw",
  "sg_100_150_fw",
  "sg_150_200_fw",
  "sg_over_200_fw",
  "sg_under_150_rgh",
  "sg_over_150_rgh",
  "sg_app_dist_total",
  // Putting SG by start distance (feet)
  "sg_putt_0_5ft",
  "sg_putt_5_10ft",
  "sg_putt_10_15ft",
  "sg_putt_15_25ft",
  "sg_putt_25plus_ft",
  "sg_putt_dist_total",
]);
const PROPS_PCT_STAT_KEYS = Object.freeze(["gir_pct", "fairways_pct"]);

function propsStatIsSg(statKey) {
  return PROPS_SG_STAT_KEYS.includes(statKey);
}

function propsStatIsPct(statKey) {
  return PROPS_PCT_STAT_KEYS.includes(statKey);
}

function propsStatUsesTenthLineStep(statKey) {
  return propsStatIsSg(statKey) || propsStatIsPct(statKey);
}

/** Birdies / pars / GIR / fairways / SG / %: higher is better. Round score / bogeys / putts: higher is worse. */
function propsMarketHigherIsBetter(statKey) {
  return (
    statKey === "birdies" ||
    statKey === "pars" ||
    statKey === "gir" ||
    statKey === "fairways" ||
    propsStatIsSg(statKey) ||
    propsStatIsPct(statKey)
  );
}

/** Round score / bogeys / putts: lower actual is better for O/U coloring (over line = red). */
function propsStatLowerIsBetter(statKey) {
  return !propsMarketHigherIsBetter(statKey);
}

/** Order chart bars left-to-right by stat value (Sort: low→high or high→low). */
function sortPropsFieldByCourseSeriesChart(statKey, series) {
  if (!series || series.length < 2) return;
  const sortAsc = selectedPropsFieldAverageSort() === "asc";
  series.sort((a, b) => {
    const va = num(a.actual, NaN);
    const vb = num(b.actual, NaN);
    const fa = Number.isFinite(va);
    const fb = Number.isFinite(vb);
    if (fa && fb && va !== vb) return sortAsc ? va - vb : vb - va;
    if (fa !== fb) return fa ? -1 : 1;
    const pa = String(a.playerName || "").localeCompare(String(b.playerName || ""));
    if (pa !== 0) return pa;
    return String(a.date || "").localeCompare(String(b.date || ""));
  });
}

function courseWindowEntryChartActual(statKey, e, dkOnly) {
  if (dkOnly && Number.isFinite(e.chartActual)) return e.chartActual;
  if (dkOnly) {
    return chartActualForDraftKingsCourseWindow(
      statKey,
      e,
      projectionPlayerRowForModel(e.dgId, getOuRound()) ||
        DATA.players?.find((p) => Math.round(num(p.dg_id, NaN)) === e.dgId),
    );
  }
  return chartActualForCourseWindowEntry(statKey, e);
}

/** One chart point per golfer (mean / best / worst / most-recent round in the filtered set). */
function buildFieldGolferAggregateSeries(entries, statKey) {
  const dkOnly = propsFilterDraftKingsOnlyOn();
  const avgOn = propsAverageModeOn();
  const tail = selectedPropsTailMode();
  const byDg = new Map();
  for (const e of entries || []) {
    const id = Math.round(num(e?.dgId, NaN));
    if (!Number.isFinite(id)) continue;
    const actual = courseWindowEntryChartActual(statKey, e, dkOnly);
    if (!Number.isFinite(actual)) continue;
    if (!byDg.has(id)) byDg.set(id, { dgId: id, playerName: e.playerName, picks: [] });
    byDg.get(id).picks.push({ actual, entry: e });
  }
  const nameByDg = buildPropsGolferDisplayNameMap();
  const series = [];
  const lowerBetter = propsStatLowerIsBetter(statKey);
  for (const [, g] of byDg) {
    const dgId = g.dgId;
    let picks = [...g.picks];
    let actual = NaN;
    if (avgOn) {
      const nums = picks.map((p) => p.actual).filter((x) => Number.isFinite(x));
      if (nums.length < PROPS_FIELD_AVERAGE_MIN_ROUNDS) continue;
      actual = nums.reduce((a, b) => a + b, 0) / nums.length;
    } else if (tail === "recent") {
      picks.sort((a, b) => historyRoundChronoKey(b.entry.row) - historyRoundChronoKey(a.entry.row));
      actual = picks[0]?.actual;
    } else {
      picks.sort((a, b) => (lowerBetter ? a.actual - b.actual : b.actual - a.actual));
      if (tail === "worst") picks.reverse();
      actual = picks[0]?.actual;
    }
    if (!Number.isFinite(actual)) continue;
    const pick = picks[0]?.entry;
    const playerName = resolveGolferDisplayNameForDg(dgId, g.playerName, nameByDg);
    const aggRows = picks.map((p) => p.entry?.row).filter(Boolean);
    series.push({
      actual,
      playerName,
      dgId,
      roundNum: Math.round(num(pick?.row?.round_num, NaN)),
      date: "",
      _hist: pick?.row,
      _aggregate: true,
      _golferAvgRounds: avgOn ? picks.map((p) => p.actual).filter((x) => Number.isFinite(x)).length : 1,
      _yearLabel: propsChartYearLabelFromRows(aggRows),
    });
  }
  return series;
}

function fieldGolferHorizontalCap(winN) {
  return clamp(
    Math.min(
      PROPS_FIELD_GOLFER_HORIZONTAL_MAX,
      Math.round(num(winN, PROPS_FIELD_GOLFER_HORIZONTAL_MAX)),
    ),
    1,
    PROPS_FIELD_GOLFER_HORIZONTAL_MAX,
  );
}

function fieldGolferDisplayCap(winN) {
  return clamp(
    Math.round(num(winN, PROPS_FIELD_GOLFER_HORIZONTAL_MAX)),
    1,
    PROPS_HISTORY_ROUND_MAX,
  );
}

/** In field average mode the stepper is a player count; use all filtered rounds per golfer for the mean. */
function propsFieldRoundWindowN(winN) {
  if (propsFieldAverageChartActive()) return PROPS_HISTORY_ROUND_MAX;
  return winN;
}

function propsFieldPlayerCapOnlyIntent() {
  if (!propsCourseWindowModeOn() || !propsAverageModeOn()) return false;
  if (!propsFieldUncappedAggregateSeries?.length || !propsFieldUncappedEntriesAll) return false;
  return propsFieldPlayerCapOnlyRender;
}

/** Y order for field average chart (low→high or high→low). */
function sortFieldAverageSeries(statKey, series) {
  if (!series?.length) return;
  const sortAsc = selectedPropsFieldAverageSort() === "asc";
  series.sort((a, b) => {
    const va = num(a.actual, NaN);
    const vb = num(b.actual, NaN);
    if (Number.isFinite(va) && Number.isFinite(vb) && va !== vb) {
      return sortAsc ? va - vb : vb - va;
    }
    return String(a.playerName || "").localeCompare(String(b.playerName || ""));
  });
}

/**
 * Keep the top-N golfers by Sample (best / worst / recent), then order bars by Sort.
 * winN is the player count in field average mode, not rounds per golfer.
 */
function capFieldGolferSeriesForDisplay(statKey, series, winN) {
  if (!series?.length) return series || [];
  const cap = propsAverageModeOn() ? fieldGolferDisplayCap(winN) : fieldGolferHorizontalCap(winN);
  const ranked = [...series];
  sortGolferHorizontalSeries(statKey, ranked);
  let picked = ranked.length > cap ? ranked.slice(0, cap) : ranked;
  if (propsAverageModeOn()) sortFieldAverageSeries(statKey, picked);
  return picked;
}

/** Y order for horizontal field chart: worst = worst→best; best/recent = best→worst. */
function sortGolferHorizontalSeries(statKey, series, tailOpt) {
  if (!series?.length) return;
  const tail = tailOpt || selectedPropsTailMode();
  const hi = propsMarketHigherIsBetter(statKey);
  const worstFirst = tail === "worst";
  series.sort((a, b) => {
    const va = num(a.actual, NaN);
    const vb = num(b.actual, NaN);
    if (Number.isFinite(va) && Number.isFinite(vb) && va !== vb) {
      if (worstFirst) return hi ? va - vb : vb - va;
      return hi ? vb - va : va - vb;
    }
    return String(a.playerName || "").localeCompare(String(b.playerName || ""));
  });
}

/** Field view: one bar per golfer — only when Average is on. */
function propsFieldUseGolferAggregateChart(entriesAll, winN) {
  return propsCourseWindowModeOn() && propsAverageModeOn();
}

function propsChartGolferLabelShort(name) {
  const s = String(name || "").trim();
  if (!s) return "—";
  if (s.includes(",")) {
    const i = s.indexOf(",");
    const last = s.slice(0, i).trim();
    const first = (s.slice(i + 1).trim().split(/\s+/)[0] || "").trim();
    const out = first ? `${first} ${last}` : last;
    return out.length > 20 ? `${out.slice(0, 18)}…` : out;
  }
  return s.length > 20 ? `${s.slice(0, 18)}…` : s;
}

/**
 * Placeholder / bad rows: all counting markets are 0 and no real total — drop from chart & hit stats.
 */
function historyRoundIsPlaceholderAllMarketsZero(row) {
  if (!row || typeof row !== "object") return true;
  const t = num(row.round_score, NaN);
  const hasRealTotal = Number.isFinite(t) && t > 0;
  if (hasRealTotal && Number.isFinite(num(row.sg_total, NaN))) return false;
  const b = num(row.birdies, 0);
  const p = num(row.pars, 0);
  const bg = num(row.bogies ?? row.bogeys, 0);
  const g = num(row.gir, 0);
  const f = num(row.fairways, 0);
  const pt = num(row.putts, 0);
  const countsAllZero = b === 0 && p === 0 && bg === 0 && g === 0 && f === 0 && pt === 0;
  const noRealTotal = !hasRealTotal;
  return countsAllZero && noRealTotal;
}

/**
 * Historical Trends / hit-rate: only rounds that have actually been completed (not scheduled future days,
 * not in-progress live projections, not round_num ahead of the live tournament).
 */
function historyRoundCountsAsActual(row) {
  if (!row || typeof row !== "object") return false;
  if (!historyRowFromDgHistoricalRoundsApi(row)) return false;
  if (historyRoundIsPlaceholderAllMarketsZero(row)) return false;
  if (historyDateMdYIsFuture(row.event_completed)) return false;
  if (historyRoundChartDateIsFuture(row)) return false;

  if (row._from_live_tournament_stats) {
    const rs = num(row.round_score, NaN);
    if (!Number.isFinite(rs) || rs <= 0) return false;
  }

  if (historyRoundMatchesCurrentEvent(row)) {
    const rnd = Math.round(num(row.round_num, NaN));
    const cap = currentTournamentProgressRoundCap();
    if (Number.isFinite(rnd) && Number.isFinite(cap) && rnd > cap) return false;
    if (row._from_pgatour && !pgatourRowBelongsToEvent(row, String(DATA?.meta?.event_name || ""))) return false;
  }
  return true;
}

function scrubNonActualRoundsFromHistoryBuckets() {
  if (!HISTORY?.byDgId || typeof HISTORY.byDgId !== "object") return 0;
  let removed = 0;
  for (const bucket of Object.values(HISTORY.byDgId)) {
    if (!bucket || !Array.isArray(bucket.rounds)) continue;
    const before = bucket.rounds.length;
    bucket.rounds = bucket.rounds.filter((r) => historyRoundCountsAsActual(r));
    removed += before - bucket.rounds.length;
  }
  if (removed > 0) {
    HISTORY_ROUNDS_CHRONO_CACHE.clear();
    PRICING_MU_BONUS_CACHE.clear();
    bumpHistoryMutationEpoch();
  }
  return removed;
}

/** Loose match for schedule titles (e.g. “THE MASTERS” vs “Masters Tournament”). */
function scheduleNameMatchesMeta(histNameRaw, metaNameRaw) {
  const meta = String(metaNameRaw || "").trim();
  const hist = String(histNameRaw || "").trim();
  if (!meta || !hist) return false;
  if (courseNameMatchesVenue(hist, meta)) return true;
  const strip = (s) =>
    s
      .toLowerCase()
      .replace(/\b(the|pga|liv\s*golf|dp\s*world)\b/g, " ")
      .replace(/\b(championship|tournament|invitational|classic|open)\b/g, " ")
      .replace(/[^a-z0-9]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  const h = strip(hist);
  const m = strip(meta);
  if (!h || !m) return false;
  if (h.includes(m) || m.includes(h)) return true;
  const tokens = (s) => s.split(" ").filter((t) => t.length >= 4);
  const ht = tokens(h);
  const mt = tokens(m);
  for (const t of mt) {
    if (ht.some((x) => x.includes(t) || t.includes(x))) return true;
  }
  return false;
}

/**
 * Extra course matching for API vs CSV naming:
 * short venue strings from DataGolf vs longer course_name in history.
 */
function courseNameMatchesVenueLoose(courseNameRaw, venueRaw) {
  if (courseNameMatchesVenue(courseNameRaw, venueRaw)) return true;
  const c = String(courseNameRaw || "").trim().toLowerCase();
  const needle = String(venueRaw || "").trim().toLowerCase();
  if (!c || !needle) return false;
  const headC = Math.min(10, c.length);
  const headN = Math.min(10, needle.length);
  if (headC >= 3 && needle.includes(c.slice(0, headC))) return true;
  if (headN >= 3 && c.includes(needle.slice(0, headN))) return true;
  return false;
}

/**
 * Known duplicate venue labels in feeds/history (after internal normalization) → one canonical key.
 * Keys must match the post-normalization lowercase string from `normCourseNameKey` pipeline.
 */
const COURSE_NAME_CANONICAL_KEYS = Object.freeze({
  albany: "albany golf club",
  "albany bahamas": "albany golf club",
  "sea island resort": "sea island golf club",
  "royal birkdale": "royal birkdale golf club",
  "royal birkdale gc": "royal birkdale golf club",
});

/** Pull North/South course side before stripping parentheses (must match course-name-key.mjs). */
function extractCourseSideToken(s) {
  const t = String(s || "").toLowerCase();
  const inParen = t.match(/\(\s*(north|south|east|west)\s*(course)?\s*\)/i);
  if (inParen) return `${inParen[1].toLowerCase()} course`;
  const outside = t.match(/\b(north|south|east|west)\s+course\b/i);
  if (outside) return `${outside[1].toLowerCase()} course`;
  const shortParen = t.match(/\(\s*(north|south|east|west)\s*\)/i);
  if (shortParen) return `${shortParen[1].toLowerCase()} course`;
  return "";
}

/** Course-name canonical key for filters/matching (e.g. "Trump National Doral" vs "(Blue Monster)"). */
function normCourseNameKey(raw) {
  let s = String(raw || "").trim().toLowerCase();
  const side = extractCourseSideToken(s);
  s = s.replace(/\([^)]*\)/g, " ");
  s = s.replace(/\b(blue monster|stadium course|championship course|club de golf)\b/g, " ");
  s = s.replace(/&/g, " and ");
  /* Venue / feed variants (TPC Sawgrass "The Players", Harbour Town Gl vs Golf Links, etc.). */
  s = s.replace(/\bthe players\b/gi, " ");
  /* Unify "… Gc" / "… Cc" / "… Gl" / dotted forms (DataGolf vs CSV vs history). */
  s = s.replace(/\bc\.?\s*c\.?\b/gi, "country club");
  s = s.replace(/\bg\.?\s*c\.?\b/gi, "golf club");
  s = s.replace(/\bg\.?\s*l\.?\b/gi, "golf links");
  s = s.replace(/\bgolf club(\s+golf club)+\b/gi, "golf club");
  s = s.replace(/\bcountry club(\s+country club)+\b/gi, "country club");
  s = s.replace(/\bgolf links(\s+golf links)+\b/gi, "golf links");
  s = s.replace(/\b(north|south|east|west)\s+course\b/g, " ");
  s = s.replace(/[^a-z0-9]+/g, " ");
  s = s.replace(/\s+/g, " ").trim();
  if (side) s = `${s} ${side}`.replace(/\s+/g, " ").trim();
  const alias = COURSE_NAME_CANONICAL_KEYS[s];
  return alias || s;
}

function formatCourseNameForDisplay(raw) {
  const k = normCourseNameKey(raw);
  if (!k) return enforceCourseDisplayAcronyms(String(raw || "").trim());
  return courseFitPrettyCourseKey(k);
}

function formatHistoryRoundCourseNameInPlace(r) {
  if (!r || typeof r !== "object") return r;
  const cn = String(r.course_name ?? "").trim();
  if (!cn) return r;
  const pretty = formatCourseNameForDisplay(cn);
  if (pretty && pretty !== cn) r.course_name = pretty;
  return r;
}

function normalizeHistoryCourseNamesInPayload(payload) {
  if (!payload?.byDgId || typeof payload.byDgId !== "object") return;
  for (const bucket of Object.values(payload.byDgId)) {
    if (!bucket?.rounds) continue;
    for (const r of bucket.rounds) formatHistoryRoundCourseNameInPlace(r);
  }
}

function normalizeStoredCourseUsedLabels() {
  const m = DATA.meta;
  if (m && m.course_used) m.course_used = formatCourseNameForDisplay(m.course_used);
  for (const p of DATA.players || []) {
    if (p && p.course_used) p.course_used = formatCourseNameForDisplay(p.course_used);
  }
}

/** Schedule title match + prefix / normalized fallbacks (sponsor-heavy titles vs short CSV names). */
function eventNameMatchesCurrentSchedule(histNameRaw, metaNameRaw) {
  if (scheduleNameMatchesMeta(histNameRaw, metaNameRaw)) return true;
  const en = String(histNameRaw || "").trim().toLowerCase();
  const evN = String(metaNameRaw || "").trim().toLowerCase();
  if (!en || !evN) return false;
  if (en.includes(evN.slice(0, 14)) || evN.includes(en.slice(0, 10))) return true;
  const a = normEvtNameKey(histNameRaw);
  const b = normEvtNameKey(metaNameRaw);
  if (a && b && (a === b || a.includes(b) || b.includes(a))) return true;
  return false;
}

/** Current tournament context match for history rows.
 * If venue is known, require a strict normalized course-key match (no loose substring leaks).
 * Event-name fallback is used only when venue is unavailable.
 */
function currentTournamentContextMatchesRound(r) {
  const vn = venueCourseName();
  const metaEvent = String(DATA.meta.event_name || "").trim();
  if (vn) {
    const rk = normCourseNameKey(r?.course_name);
    const vk = normCourseNameKey(vn);
    return Boolean(rk && vk && rk === vk);
  }
  if (metaEvent) return eventNameMatchesCurrentSchedule(r.event_name, metaEvent);
  return false;
}

function filteredHistoryRoundsMemoSig() {
  return [
    historyMutationEpoch,
    courseFilterOn() ? 1 : 0,
    venueCourseName(),
    String(DATA?.meta?.event_name || ""),
    propsCourseWindowModeActive() ? propsEffectiveCourseKey() || "" : "",
    propsSidebarFiltersContextKey(),
    propsFieldVenueShardCache.ready ? propsFieldVenueShardCacheSig : "venue-shard-pending",
    propsSingleCourseIndexSig || "course-index-pending",
  ].join("\x1f");
}

/** Rounds for one player from by-course history shard (full venue archive). */
function playerRoundsFromCourseHistoryShards(dgId, courseKey) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id) || !courseKey) return [];
  const bucket = propsGetSingleCourseBucketSync(courseKey);
  const rows = [];
  for (const e of bucket?.entries || []) {
    if (Math.round(num(e.dgId, NaN)) !== id) continue;
    if (e.row) rows.push(e.row);
  }
  return rows;
}

/** Merge partial player bucket with by-course shard when filtering by venue. */
function playerHistoryRoundsAugmentedForCourseFilter(dgId) {
  const base = historyRoundsForDg(dgId).filter((r) => !historyRoundIsPlaceholderAllMarketsZero(r));
  if (!propsTrendCourseFilterActive()) return base;
  const venueRaw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  const courseKey =
    propsEffectiveCourseKey() || (courseFilterOn() && venueRaw ? normCourseNameKey(venueRaw) : "");
  const extra = playerRoundsFromCourseHistoryShards(dgId, courseKey);
  if (!extra.length) return base;
  return mergePropsVenueRoundRowsUnique(base, extra);
}

function ensurePropsCourseHistoryForTrendsChart(dgId) {
  if (!propsTrendCourseFilterActive()) return;
  ensurePropsFieldVenueHistoryLoaded();
  const courseKey = propsEffectiveCourseKey() || propsEventVenueCourseKey();
  if (courseKey) {
    void ensurePropsCourseIndexForKeyAsync(courseKey).then(() => {
      if (activeAppTabId() === "props") scheduleRenderPropsTrends(0);
    });
  }
  const id = Math.round(num(dgId, NaN));
  if (Number.isFinite(id) && !isFileProtocol()) void loadPlayerHistoryBucket(id);
}

function filteredHistoryRounds(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return [];
  const ms = filteredHistoryRoundsMemoSig();
  if (ms !== filteredHistoryRoundsMemoSigStored) {
    filteredHistoryRoundsMemoSigStored = ms;
    filteredHistoryRoundsMemoByDgId.clear();
  }
  const memoHit = filteredHistoryRoundsMemoByDgId.get(id);
  if (memoHit) return memoHit;

  let list = propsTrendCourseFilterActive()
    ? playerHistoryRoundsAugmentedForCourseFilter(id)
    : historyRoundsForDg(id);
  if (courseFilterOn()) {
    const venueKey = propsEventVenueCourseKey();
    if (venueKey) {
      list = list.filter((r) => normCourseNameKey(r.course_name) === venueKey);
    } else {
      const metaEvent = String(DATA.meta.event_name || "").trim();
      if (metaEvent) list = list.filter((r) => currentTournamentContextMatchesRound(r));
    }
  }
  const courseFilter = propsCourseWindowModeActive() || courseFilterOn() ? propsEffectiveCourseKey() : "";
  if (courseFilter) {
    list = list.filter((r) => normCourseNameKey(r.course_name) === normCourseNameKey(courseFilter));
  }
  list = applyPropsSidebarFiltersToRounds(list, id);
  list = list.filter((r) => !historyRoundIsPlaceholderAllMarketsZero(r));
  /* Current-course filter can yield zero rows (rookies, first-time venue) — never fall back to other courses. */
  if (courseFilterOn() && !list.length) {
    filteredHistoryRoundsMemoByDgId.set(id, list);
    return list;
  }
  list.sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
  filteredHistoryRoundsMemoByDgId.set(id, list);
  return list;
}

/** Newest-first rounds for chart + hit stats (respects Rounds stepper, including current-course filter). */
function propsFilteredRoundsNewestFirst(dgId, winN) {
  const list = filteredHistoryRounds(dgId);
  const wn = clamp(
    Math.round(num(winN, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX
  );
  const mode = selectedPropsTailMode();
  if (mode === "recent") return list.slice(0, wn);
  if (mode === "average") {
    const sorted = [...list].sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
    return sorted.slice(0, wn).sort((a, b) => historyRoundChronoKey(a) - historyRoundChronoKey(b));
  }
  const statKey = statKeyFromPropSelect();
  const lowerBetter = propsStatLowerIsBetter(statKey);
  const scored = [];
  for (const r of list) {
    const a = actualForRoundRow(statKey, r);
    if (Number.isFinite(a)) scored.push({ r, a });
  }
  if (mode === "best") scored.sort((a, b) => (lowerBetter ? a.a - b.a : b.a - a.a));
  else scored.sort((a, b) => (lowerBetter ? b.a - a.a : a.a - b.a));
  const picked = scored.slice(0, wn).map((x) => x.r);
  return picked.sort((a, b) => historyRoundChronoKey(a) - historyRoundChronoKey(b));
}

function historyRoundsChronoNewestFirst(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (Number.isFinite(id)) {
    const cached = HISTORY_ROUNDS_CHRONO_CACHE.get(id);
    if (cached) return cached;
  }
  const list = historyRoundsForDg(dgId).filter((r) => !historyRoundIsPlaceholderAllMarketsZero(r));
  const sorted = list.sort((a, b) => historyRoundChronoKey(b) - historyRoundChronoKey(a));
  if (Number.isFinite(id)) HISTORY_ROUNDS_CHRONO_CACHE.set(id, sorted);
  return sorted;
}

function meanNumFromRounds(rounds, key) {
  const vals = [];
  for (const r of rounds) {
    const v = num(r[key], NaN);
    if (Number.isFinite(v)) vals.push(v);
  }
  if (!vals.length) return NaN;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

/** Newest-first rounds; index 0 = most recent (decay 0.86^i). */
function meanNumFromRoundsRecencyWeighted(rounds, key, decay = 0.86) {
  if (!rounds?.length) return NaN;
  let sum = 0;
  let wsum = 0;
  for (let i = 0; i < rounds.length; i++) {
    const v = num(rounds[i][key], NaN);
    if (!Number.isFinite(v)) continue;
    const w = decay ** i;
    sum += v * w;
    wsum += w;
  }
  return wsum > 0 ? sum / wsum : NaN;
}

function meanNumFromRoundsRecencyWeightedStat(rounds, statKey, decay = 0.86) {
  if (!rounds?.length) return NaN;
  let sum = 0;
  let wsum = 0;
  for (let i = 0; i < rounds.length; i++) {
    const v = actualForFieldVenueKpiRow(statKey, rounds[i]);
    if (!Number.isFinite(v)) continue;
    const w = decay ** i;
    sum += v * w;
    wsum += w;
  }
  return wsum > 0 ? sum / wsum : NaN;
}

/** Map pricing UI skill value to projection / history SG column (e.g. `sg_putt`). */
function pricingSkillColumnKeyFromRaw(skillRaw) {
  const skRaw = String(skillRaw || "sg_total").toLowerCase();
  return skRaw === "default" ? "sg_total" : PRICING_SKILL_COLUMNS.includes(skRaw) ? skRaw : "sg_total";
}

/**
 * Skill-focus fallback when round history is short or lacks the chosen pillar: player SG vs field median
 * on the active model round so +EV Model odds respond to the Skill dropdown (Outright Win, matchups, O/U).
 */
function projectionSkillFocusNudgeFromField(dgId, skillKey) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id) || !PRICING_SKILL_COLUMNS.includes(skillKey)) return 0;
  const prRound = getModelRoundForEv();
  const row = projectionPlayerRowForModel(id, prRound);
  if (!row) return 0;
  const v = num(row[skillKey], NaN);
  if (!Number.isFinite(v)) return 0;
  const vals = [];
  for (const p of DATA.players || []) {
    const pid = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(pid)) continue;
    const pr = projectionPlayerRowForModel(pid, prRound);
    if (!pr) continue;
    const x = num(pr[skillKey], NaN);
    if (Number.isFinite(x)) vals.push(x);
  }
  if (vals.length < 8) return 0;
  vals.sort((a, b) => a - b);
  const mid = Math.floor(vals.length / 2);
  const median = vals.length % 2 === 1 ? vals[mid] : (vals[mid - 1] + vals[mid]) / 2;
  const delta = v - median;
  return clamp(delta * 0.32, -0.35, 0.35);
}

function courseNameMatchesVenue(courseNameRaw, venueRaw) {
  const c = String(courseNameRaw || "").trim().toLowerCase();
  const v = String(venueRaw || "").trim().toLowerCase();
  if (!c || !v) return false;
  if (c.includes(v) || v.includes(c)) return true;
  const ck = normCourseNameKey(c);
  const vk = normCourseNameKey(v);
  if (!ck || !vk) return false;
  return ck.includes(vk) || vk.includes(ck);
}

function pricingModeMuSgBonus(dgId) {
  return pricingModeMuSgBonusForMode(dgId, PRICING_STATE.mode, PRICING_STATE.skill);
}

function pricingModeMuSgBonusForMode(dgId, modeRaw, skillRaw = PRICING_STATE.skill) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return 0;
  const mode = ["default", "recent", "course", "skill"].includes(String(modeRaw || "").toLowerCase())
    ? String(modeRaw || "").toLowerCase()
    : "default";
  const skillKey = String(skillRaw || "default").toLowerCase();
  const venueKey = mode === "course" ? normCourseNameKey(venueCourseName()) : "";
  const cacheKey = `${id}|${mode}|${skillKey}|${venueKey}`;
  if (PRICING_MU_BONUS_CACHE.has(cacheKey)) return PRICING_MU_BONUS_CACHE.get(cacheKey) || 0;
  if (mode === "default" || mode === "adaptive") {
    const rounds = historyRoundsChronoNewestFirst(id);
    const vk = normCourseNameKey(venueCourseName());
    const ctRow = resolveCourseTableRowForNormKey(vk);
    const modelRound = Math.round(num(DATA?.display_round ?? DATA?.meta?.display_round, 1)) || 1;
    let recent = 0;
    let course = 0;
    let skill = 0;
    let venueRounds = 0;
    if (rounds.length >= 4) {
      recent = recentFormMuBonusAdaptive(rounds);
      const ch = courseHistoryMuBonusAdaptive(rounds, venueCourseName());
      course = ch.bonus;
      venueRounds = ch.venueRounds;
      skill = courseWeightedSkillFormBonus(rounds, ctRow, id, modelRound);
    } else {
      skill = courseWeightedSkillFormBonus([], ctRow, id, modelRound);
    }
    const out = blendAdaptiveMuSgBonus(recent, course, skill, venueRounds);
    PRICING_MU_BONUS_CACHE.set(cacheKey, out);
    return out;
  }

  const rounds = historyRoundsChronoNewestFirst(id);
  if (rounds.length < 4) {
    if (mode === "skill") {
      const sk0 = pricingSkillColumnKeyFromRaw(skillRaw);
      const fb0 = projectionSkillFocusNudgeFromField(id, sk0);
      PRICING_MU_BONUS_CACHE.set(cacheKey, fb0);
      return fb0;
    }
    PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
    return 0;
  }

  if (mode === "recent") {
    const nRec = Math.min(6, Math.max(3, Math.floor(rounds.length / 2)));
    const recent = rounds.slice(0, nRec);
    const older = rounds.slice(nRec, Math.min(rounds.length, nRec + 18));
    let rMean = meanNumFromRounds(recent, "sg_total");
    let oMean = meanNumFromRounds(older, "sg_total");
    if (Number.isFinite(rMean) && Number.isFinite(oMean)) {
      const out = clamp((rMean - oMean) * 0.9, -0.35, 0.35);
      PRICING_MU_BONUS_CACHE.set(cacheKey, out);
      return out;
    }
    rMean = meanNumFromRounds(recent, "round_score");
    oMean = meanNumFromRounds(older, "round_score");
    if (Number.isFinite(rMean) && Number.isFinite(oMean)) {
      const out = clamp(((oMean - rMean) / 6) * 0.85, -0.35, 0.35);
      PRICING_MU_BONUS_CACHE.set(cacheKey, out);
      return out;
    }
    PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
    return 0;
  }

  if (mode === "course") {
    const vn = venueCourseName();
    if (!vn) {
      PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
      return 0;
    }
    const here = rounds.filter((r) => courseNameMatchesVenue(r.course_name, vn));
    if (here.length < 2) {
      PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
      return 0;
    }
    const other = rounds.filter((r) => !courseNameMatchesVenue(r.course_name, vn));
    const hMean = meanNumFromRoundsRecencyWeighted(here, "sg_total", 0.84);
    const oMean = meanNumFromRoundsRecencyWeighted(other.length ? other : rounds, "sg_total", 0.9);
    if (Number.isFinite(hMean) && Number.isFinite(oMean)) {
      const out = clamp((hMean - oMean) * 1.05, -0.42, 0.42);
      PRICING_MU_BONUS_CACHE.set(cacheKey, out);
      return out;
    }
    const hSc = meanNumFromRoundsRecencyWeighted(here, "round_score", 0.84);
    const oSc = meanNumFromRoundsRecencyWeighted(other.length ? other : rounds, "round_score", 0.9);
    if (Number.isFinite(hSc) && Number.isFinite(oSc)) {
      const out = clamp(((oSc - hSc) / 6) * 0.95, -0.42, 0.42);
      PRICING_MU_BONUS_CACHE.set(cacheKey, out);
      return out;
    }
    PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
    return 0;
  }

  if (mode === "skill") {
    const sk = pricingSkillColumnKeyFromRaw(skillRaw);
    const nRec = Math.min(8, Math.max(3, Math.floor(rounds.length / 2)));
    const recent = rounds.slice(0, nRec);
    const older = rounds.slice(nRec, Math.min(rounds.length, nRec + 24));
    const rMean = meanNumFromRounds(recent, sk);
    const oMean = meanNumFromRounds(older, sk);
    if (Number.isFinite(rMean) && Number.isFinite(oMean)) {
      const out = clamp((rMean - oMean) * 0.75, -0.35, 0.35);
      PRICING_MU_BONUS_CACHE.set(cacheKey, out);
      return out;
    }
    const fb = projectionSkillFocusNudgeFromField(id, sk);
    PRICING_MU_BONUS_CACHE.set(cacheKey, fb);
    return fb;
  }

  PRICING_MU_BONUS_CACHE.set(cacheKey, 0);
  return 0;
}

/** Live thru/today → SG delta for matchups; skipped for round_matchups / 3_balls unless `in_play_affects_round_odds`. */
function liveMuSgDeltaForMatchupRow(row, matchupMarketKind) {
  if (!inPlayAffectsRoundOdds()) return 0;
  if (matchupMarketKind === "round_matchups" || matchupMarketKind === "3_balls") return 0;
  return liveCurrentRoundMuSgDelta(row);
}

function effectiveMuSg(row, dgIdOpt, matchupMarketKind) {
  const base = weatherAdjustedMuSg(row);
  const id = Number.isFinite(dgIdOpt) ? Math.round(dgIdOpt) : Math.round(num(row?.dg_id, NaN));
  if (!Number.isFinite(base) || !Number.isFinite(id)) return base;
  return (
    base +
    pricingModeMuSgBonus(id) +
    priorRoundCourseMuSgDelta(row) +
    liveMuSgDeltaForMatchupRow(row, matchupMarketKind)
  );
}

function pricingCourseVenueStatMuNudge(market, dgId) {
  const mode = String(PRICING_STATE.mode || "default").toLowerCase();
  if (mode !== "default" && mode !== "adaptive" && mode !== "course") return 0;
  const strength = mode === "course" ? 1 : 0.62;
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return 0;
  const vn = venueCourseName();
  if (!vn) return 0;
  const rounds = historyRoundsChronoNewestFirst(id);
  const here = rounds.filter((r) => courseNameMatchesVenue(r.course_name, vn));
  if (here.length < 2) return 0;
  const mKey = ouModelMarketKey(market) || "Total score";
  const statKey = ouMarketRatingHistoryStatKey(mKey);
  const venueAvg = meanNumFromRoundsRecencyWeightedStat(here, statKey, 0.82);
  const broadAvg = meanNumFromRoundsRecencyWeightedStat(rounds, statKey, 0.9);
  if (!Number.isFinite(venueAvg) || !Number.isFinite(broadAvg)) return 0;
  const delta = venueAvg - broadAvg;
  if (mKey === "Total score") return clamp(-delta * 0.55 * strength, -2.8, 2.8);
  if (mKey === "Bogeys") return clamp(delta * 0.42 * strength, -1.8, 1.8);
  if (mKey === "Birdies") return clamp(delta * 0.48 * strength, -1.8, 1.8);
  if (mKey === "Pars") return clamp(delta * 0.12 * strength, -1.2, 1.2);
  if (mKey === "GIR") return clamp(delta * 3.2 * strength, -2.2, 2.2);
  if (mKey === "Fairways hit") return clamp(delta * 2.4 * strength, -2.2, 2.2);
  if (mKey === "Putts") return clamp(-delta * 0.38 * strength, -2.2, 2.2);
  return 0;
}

function pricingStatMuAdjustment(market, dgId) {
  const b = pricingModeMuSgBonus(dgId);
  let out = 0;
  if (Number.isFinite(b) && b !== 0) {
    if (market === "Total score") out = -1.05 * b;
    else if (market === "Bogeys") out = -0.45 * b;
    else if (market === "Birdies") out = 0.5 * b;
    else if (market === "Pars") out = 0.08 * b;
    else if (market === "GIR") out = 0.35 * b;
    else if (market === "Fairways hit") out = 0.22 * b;
    else if (market === "Putts") out = -0.32 * b;
  }
  return out + pricingCourseVenueStatMuNudge(market, dgId) + courseWeightedMarketMuNudge(market, dgId);
}

function pricingModelHistoryNudge(statKey, dgId) {
  const b = pricingModeMuSgBonus(dgId);
  if (!Number.isFinite(b) || b === 0) return 0;
  if (statKey === "total") return -1.02 * b;
  if (statKey === "bogeys") return -0.42 * b;
  if (statKey === "birdies") return 0.48 * b;
  if (statKey === "gir") return 0.38 * b;
  if (statKey === "fairways") return 0.24 * b;
  if (statKey === "pars") return 0.06 * b;
  if (statKey === "putts") return -0.3 * b;
  return 0;
}

function propsTrendLineSidebarFiltersContextKey() {
  return [
    propsTrendTempContextKey(),
    propsTrendWindContextKey(),
    propsTrendHumidityContextKey(),
    selectedPropsWeatherConditionKeys().join(","),
    selectedPropsTeeWaveFilter() || "all",
    selectedPropsRoundNumsFilter().join(","),
    Number.isFinite(selectedPropsYearFilter()) ? String(selectedPropsYearFilter()) : "all",
  ].join("|");
}

function propsLineStepForStat(statKey) {
  if (propsStatUsesTenthLineStep(statKey)) return 0.1;
  if (statKey === "total") return 1;
  return 0.5;
}

function syncPropsLineStep() {
  const lineEl = document.getElementById("prop-line");
  if (!lineEl) return;
  const sk = statKeyFromPropSelect();
  if (propsStatUsesTenthLineStep(sk)) {
    lineEl.step = "0.1";
    if (propsStatIsSg(sk)) {
      lineEl.min = "-6";
      lineEl.max = "6";
    } else {
      lineEl.min = "0";
      lineEl.max = "100";
    }
  } else {
    lineEl.step = "0.5";
    lineEl.min = "0";
    lineEl.removeAttribute("max");
  }
}

function bumpPropsTrendLine(delta) {
  syncPropsLineStep();
  const lineInp = document.getElementById("prop-line");
  const sk = statKeyFromPropSelect();
  const cur = clampPropLineForMarket(sk, snapPropLineForMarket(sk, lineInp?.value));
  const base = Number.isFinite(cur) ? cur : defaultPropLineForStat(sk);
  const step = propsLineStepForStat(sk);
  const v = clampPropLineForMarket(sk, base + delta * step);
  if (lineInp) lineInp.value = formatPropLineValueForInput(v);
  propsTrendLineUserOverride = true;
  lockPropsTrendLineContextToCurrentFilter();
  renderPropsTrendsNow();
}

function propsTrendLineContextKeyFromDom() {
  const dg = selectedDgId();
  const sk = statKeyFromPropSelect();
  const winN = clamp(
    Math.round(num(document.getElementById("props-window-n")?.value, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX
  );
  const winNKey = String(winN);
  const temp = propsTrendTempContextKey();
  const side = propsTrendLineSidebarFiltersContextKey();
  const course = propsEffectiveCourseKey() || "all";
  const pm = PRICING_STATE.mode || "default";
  const ps = PRICING_STATE.skill === "default" ? "default" : pricingSkillHistoryKey();
  const cw = propsCourseWindowModeActive() ? 1 : 0;
  const dk = propsFilterDraftKingsOnlyOn() ? 1 : 0;
  const winDates = cw
    ? `${String(document.getElementById("props-filter-date-from")?.value || "")}|${String(document.getElementById("props-filter-date-to")?.value || "")}`
    : "";
  return `${dg}|${sk}|${courseFilterOn() ? 1 : 0}|${winNKey}|${temp}|${side}|${course}|${pm}|${ps}|${cw}|${winDates}|${dk}`;
}

/** After user changes line or steppers so projection logic does not overwrite the input. */
function lockPropsTrendLineContextToCurrentFilter() {
  propsTrendsLineContextKey = propsTrendLineContextKeyFromDom();
}

/**
 * Min rounds to list a player in the trends table. Full-field default is high for stability;
 * any narrow filter (this event’s course, field-by-course window + venue, or weather buckets)
 * uses 1 so you still see the whole field when sample sizes are small per player.
 */
function propsTopHitMinRoundsForFilter() {
  if (propsCourseWindowModeActive()) return 1;
  if (courseFilterOn()) return 1;
  if (propsTempFilterActive()) return 1;
  if (propsWindFilterActive()) return 1;
  if (propsHumidityFilterActive()) return 1;
  if (propsWeatherConditionFilterActive()) return 1;
  if (selectedPropsTeeWaveFilter()) return 1;
  if (propsRoundNumFilterActive()) return 1;
  if (propsYearFilterActive()) return 1;
  return PROPS_TOP_HIT_MIN_ROUNDS;
}

function propsPlayerMeetsFireSide(statKey, row) {
  if (!row || !row.valid) return false;
  const hi = propsMarketHigherIsBetter(statKey);
  if (hi) return row.overRate >= 0.5;
  return row.underRate >= 0.5;
}

function propsPlayerMeetsIceSide(statKey, row) {
  if (!row || !row.valid) return false;
  const hi = propsMarketHigherIsBetter(statKey);
  if (hi) return row.underRate >= 0.5;
  return row.overRate >= 0.5;
}

/**
 * History JSON uses `null` for missing stats; `Number(null) === 0` would fake zeros on charts / hit rates.
 * GIR / fairways from CSV are sometimes fractions in (0,1] (share of holes) — convert to counts like build-player-history.
 */
function historyScalarOrNaN(v) {
  if (v == null || v === "") return NaN;
  const n = Number(v);
  return Number.isFinite(n) ? n : NaN;
}

/** Birdies O/U and trends: eagles (and eagles_or_better) count toward birdies, same as sportsbook markets. */
function birdiesPlusEaglesFromRow(row) {
  if (!row || typeof row !== "object") return NaN;
  const b = historyScalarOrNaN(row.birdies);
  const eob = historyScalarOrNaN(row.eagles_or_better);
  const eg = historyScalarOrNaN(row.eagles);
  if (!Number.isFinite(b)) {
    if (Number.isFinite(eob) && eob > 0) return eob;
    if (Number.isFinite(eg) && eg > 0) return eg;
    return NaN;
  }
  const eagleAdd =
    Number.isFinite(eob) && eob > 0 ? eob : Number.isFinite(eg) && eg > 0 ? eg : 0;
  return b + eagleAdd;
}

/** Bogeys O/U: doubles_or_worse count toward bogeys (DraftKings / PrizePicks “Bogeys or Worse”). */
function bogeysPlusDoublesFromRow(row) {
  if (!row || typeof row !== "object") return NaN;
  const bg = historyScalarOrNaN(row.bogeys ?? row.bogies);
  const dow = historyScalarOrNaN(row.doubles_or_worse);
  const dbl = historyScalarOrNaN(row.doubles);
  if (!Number.isFinite(bg)) {
    if (Number.isFinite(dow) && dow > 0) return dow;
    if (Number.isFinite(dbl) && dbl > 0) return dbl;
    return NaN;
  }
  const dblAdd =
    Number.isFinite(dow) && dow > 0 ? dow : Number.isFinite(dbl) && dbl > 0 ? dbl : 0;
  return bg + dblAdd;
}

/**
 * GIR / fairways: values in (0, 1] are share-of-holes (e.g. 0.72 → integer hole counts); values in (1, holes]
 * are expected counts from history or projections — keep fractional scale (do not `Math.round` to whole holes;
 * that turned 9.91 fairways / 11.88 GIR into 10 / 12 for O-U means).
 */
function girFairwaysCountFromRawForOu(v, holes) {
  const n = historyScalarOrNaN(v);
  if (!Number.isFinite(n)) return NaN;
  if (n > 0 && n <= 1.0001) return Math.min(holes, Math.max(0, Math.round(n * holes)));
  if (n > 1.0001 && n <= holes + 1e-6) return Math.min(holes, Math.max(0, n));
  return Math.min(holes, Math.max(0, Math.round(n)));
}

function historyGirOrFairwaysCount(v, holes) {
  return girFairwaysCountFromRawForOu(v, holes);
}

/** Fallback μ when `ouMeanCountingStat` is NaN — must not use `num(null)` (Number(null) is 0). */
function ouFallbackScalarForProjectedMean(mKey, row, rec) {
  if (mKey === "Birdies") return birdiesPlusEaglesFromRow(row);
  if (mKey === "Bogeys") return bogeysPlusDoublesFromRow(row);
  const v = historyScalarOrNaN(row?.[rec.field]);
  if (mKey === "GIR") return girFairwaysCountFromRawForOu(v, 18);
  if (mKey === "Fairways hit") return girFairwaysCountFromRawForOu(v, fairwayHolesModeledFromData());
  return v;
}

/** Mean for O/U +EV: GIR / fairways as hole counts when projections store rates. */
function ouMeanCountingStat(market, row) {
  const mKey = ouModelMarketKey(market) || "Total score";
  const rec = ouStatRec(mKey);
  if (mKey === "Birdies") return birdiesPlusEaglesFromRow(row);
  if (mKey === "Bogeys") return bogeysPlusDoublesFromRow(row);
  const raw = historyScalarOrNaN(row?.[rec.field]);
  if (!Number.isFinite(raw)) return NaN;
  if (mKey === "GIR") return girFairwaysCountFromRawForOu(raw, 18);
  if (mKey === "Fairways hit") return girFairwaysCountFromRawForOu(raw, fairwayHolesModeledFromData());
  return raw;
}

/** Field-wide course KPI means: completed rounds only; total uses any posted gross (incl. live week). */
function actualForFieldVenueKpiRow(statKey, row) {
  if (!row || typeof row !== "object" || !historyRoundCountsAsActual(row)) return NaN;
  if (statKey === "total") {
    const rs = historyScalarOrNaN(row.round_score);
    return Number.isFinite(rs) && rs > 0 ? rs : NaN;
  }
  return actualForRoundRow(statKey, row);
}

function actualForRoundRow(statKey, row) {
  if (!row || typeof row !== "object") return NaN;
  if (statKey === "total" || statKey === "birdies" || statKey === "pars" || statKey === "bogeys") {
    if (!historyRowFromDgHistoricalRoundsApi(row)) return NaN;
    const enriched = enrichHistoryRowFromLiveActuals(row);
    if (statKey === "total") return historyScalarOrNaN(enriched.round_score);
    const cp = num(enriched.course_par, NaN) || num(DATA?.meta?.course_par_18, NaN);
    const rec = reconcileHoleCountsFromScoreRuntime(
      {
        birdies: enriched.birdies,
        pars: enriched.pars,
        bogeys: enriched.bogeys ?? enriched.bogies,
        round_score: enriched.round_score ?? enriched.score,
        eagles_or_better: enriched.eagles_or_better,
        doubles_or_worse: enriched.doubles_or_worse,
      },
      cp,
    );
    if (!historyLiveCountingTrusted(enriched) && !Number.isFinite(rec.birdies) && !Number.isFinite(rec.bogeys))
      return NaN;
    if (statKey === "birdies") {
      const b = num(rec.birdies, NaN);
      if (Number.isFinite(b)) return b + Math.max(0, num(rec.eagles ?? enriched.eagles_or_better, 0));
      return birdiesPlusEaglesFromRow(enriched);
    }
    if (statKey === "pars") return historyScalarOrNaN(rec.pars ?? enriched.pars);
    return bogeysPlusDoublesFromRow({
      bogeys: rec.bogeys ?? enriched.bogeys ?? enriched.bogies,
      doubles: enriched.doubles,
      doubles_or_worse: enriched.doubles_or_worse ?? rec.doubles,
    });
  }
  if (statKey === "gir") {
    const enriched = enrichHistoryRowFromLiveActuals(row);
    let v = historyGirOrFairwaysCount(enriched.gir, 18);
    if (!Number.isFinite(v) || v === 0 || v === 1) {
      const liveV = liveRoundActualStatForDgRound(
        enriched.dg_id ?? row.dg_id,
        enriched.round_num ?? enriched.round ?? row.round_num ?? row.round,
        "gir",
      );
      if (Number.isFinite(liveV) && liveV > 1) v = liveV;
    }
    if (!Number.isFinite(v) || v === 0 || v === 1) return NaN;
    return v;
  }
  if (statKey === "fairways") {
    const enriched = enrichHistoryRowFromLiveActuals(row);
    let v = historyGirOrFairwaysCount(enriched.fairways, fairwayHolesModeledFromData());
    if (!Number.isFinite(v) || v === 0 || v === 1) {
      const liveV = liveRoundActualStatForDgRound(row.dg_id, row.round_num ?? row.round, "fairways");
      if (Number.isFinite(liveV) && liveV >= 0) v = liveV;
    }
    return Number.isFinite(v) && v >= 0 ? v : NaN;
  }
  if (statKey === "putts") {
    const enriched = enrichHistoryRowFromLiveActuals(row);
    let v = historyScalarOrNaN(enriched.putts);
    if (!Number.isFinite(v) || v === 0 || v === 1) {
      const liveV = liveRoundActualStatForDgRound(row.dg_id, row.round_num ?? row.round, "putts");
      if (Number.isFinite(liveV) && liveV > 1) v = liveV;
    }
    return v === 0 || v === 1 ? NaN : v;
  }
  if (propsStatIsSg(statKey)) {
    return historyScalarOrNaN(row[statKey]);
  }
  if (statKey === "gir_pct") {
    const enriched = enrichHistoryRowFromLiveActuals(row);
    const scrubbed = scrubLivePlaceholderCountingOnRow(enriched);
    let count = historyGirOrFairwaysCount(scrubbed.gir, 18);
    if (!Number.isFinite(count) || count === 0 || count === 1) {
      const liveV = liveRoundActualStatForDgRound(row.dg_id, row.round_num ?? row.round, "gir");
      if (Number.isFinite(liveV) && liveV > 1) count = liveV;
    }
    if (!Number.isFinite(count) || count === 0 || count === 1) return NaN;
    return (count / 18) * 100;
  }
  if (statKey === "fairways_pct") {
    const nFw = fairwayHolesModeledFromData();
    if (!Number.isFinite(nFw) || nFw <= 0) return NaN;
    const enriched = enrichHistoryRowFromLiveActuals(row);
    let count = historyGirOrFairwaysCount(enriched.fairways, nFw);
    if (!Number.isFinite(count) || count === 0 || count === 1) {
      const liveV = liveRoundActualStatForDgRound(row.dg_id, row.round_num ?? row.round, "fairways");
      if (Number.isFinite(liveV) && liveV > 1) count = liveV;
    }
    if (!Number.isFinite(count) || count === 0 || count === 1) return NaN;
    return (count / nFw) * 100;
  }
  return NaN;
}

/** Lines are only *.5 (never whole numbers): … 69.5, 70.5, 71.5 … */
function snapPropLineToDotFive(x) {
  const v = num(x, NaN);
  if (!Number.isFinite(v)) return NaN;
  return Math.round(v - 0.5) + 0.5;
}

function snapPropLineForMarket(statKey, line) {
  const v = num(line, NaN);
  if (!Number.isFinite(v)) return NaN;
  if (propsStatUsesTenthLineStep(statKey)) return Math.round(v * 10) / 10;
  return snapPropLineToDotFive(v);
}

function formatPropLineValueForInput(line, statKeyOpt) {
  const sk = statKeyOpt || statKeyFromPropSelect();
  const s = snapPropLineForMarket(sk, line);
  if (!Number.isFinite(s)) return "";
  return s.toFixed(1);
}

function formatPropsTrendLineLabel(statKey, line) {
  const s = snapPropLineForMarket(statKey, line);
  if (!Number.isFinite(s)) return "—";
  if (propsStatIsPct(statKey)) return `${s.toFixed(1)}%`;
  if (propsStatIsSg(statKey)) return s >= 0 ? `+${s.toFixed(1)}` : s.toFixed(1);
  return s.toFixed(1);
}

function formatPropLineChartLabel(statKey, line) {
  const s = clampPropLineForMarket(statKey, line);
  if (!Number.isFinite(s)) return "";
  if (propsStatIsPct(statKey)) return `${s.toFixed(1)}%`;
  if (propsStatIsSg(statKey)) return s >= 0 ? `+${s.toFixed(1)}` : s.toFixed(1);
  return s.toFixed(1);
}

function clampPropLineForMarket(statKey, line) {
  const s = snapPropLineForMarket(statKey, line);
  if (!Number.isFinite(s)) return NaN;
  if (propsStatIsSg(statKey)) return clamp(s, -6, 6);
  if (statKey === "gir_pct") return clamp(s, 15, 95);
  if (statKey === "fairways_pct") return clamp(s, 15, 95);
  if (statKey === "total") return clamp(s, 50.5, 99.5);
  if (statKey === "gir") return clamp(s, 4.5, 16.5);
  if (statKey === "fairways") {
    const nFw = fairwayHolesModeledFromData();
    const hi = Number.isFinite(nFw) && nFw >= 1 ? nFw - 0.5 : 13.5;
    return clamp(s, 0.5, hi);
  }
  if (statKey === "putts") return clamp(s, 22.5, 36.5);
  return clamp(s, 0.5, 29.5);
}

/** Default O/U line when projections or inputs do not supply one (prefer venue historical means). */
function defaultPropLineForStat(statKey) {
  const b = DATA?.meta?.projection_course_basis;
  if (b && typeof b === "object") {
    if (statKey === "total" && Number.isFinite(num(b.venue_avg_round_score, NaN))) {
      return enforceHalfLine(num(b.venue_avg_round_score, NaN));
    }
    if (statKey === "birdies" && Number.isFinite(num(b.venue_avg_birdies, NaN))) {
      return enforceHalfLine(num(b.venue_avg_birdies, NaN));
    }
    if (statKey === "pars" && Number.isFinite(num(b.venue_avg_pars, NaN))) {
      return enforceHalfLine(num(b.venue_avg_pars, NaN));
    }
    if (statKey === "bogeys" && Number.isFinite(num(b.venue_avg_bogeys, NaN))) {
      return enforceHalfLine(num(b.venue_avg_bogeys, NaN));
    }
    if (statKey === "gir" && Number.isFinite(num(b.venue_avg_gir, NaN))) {
      return enforceHalfLine(num(b.venue_avg_gir, NaN));
    }
    if (statKey === "fairways" && Number.isFinite(num(b.venue_avg_fairways, NaN))) {
      return enforceHalfLine(num(b.venue_avg_fairways, NaN));
    }
    if (statKey === "putts" && Number.isFinite(num(b.venue_avg_putts, NaN))) {
      return enforceHalfLine(num(b.venue_avg_putts, NaN));
    }
  }
  if (propsStatIsSg(statKey)) return 0;
  if (statKey === "gir_pct") {
    const avgGir = num(b?.venue_avg_gir, NaN);
    if (Number.isFinite(avgGir)) return snapPropLineForMarket(statKey, (avgGir / 18) * 100);
    return 65;
  }
  if (statKey === "fairways_pct") {
    const avgFw = num(b?.venue_avg_fairways, NaN);
    const nFw = fairwayHolesModeledFromData();
    if (Number.isFinite(avgFw) && Number.isFinite(nFw) && nFw > 0) {
      return snapPropLineForMarket(statKey, (avgFw / nFw) * 100);
    }
    return 58;
  }
  if (statKey === "total") return 70.5;
  if (statKey === "gir") return 11.5;
  if (statKey === "fairways") return 8.5;
  if (statKey === "putts") return 29.5;
  return 3.5;
}

/** Label for prop-stat / history market (toolbar + hit-rate copy). */
function propMarketLabelFromKey(statKey) {
  if (statKey === "total") return "Round score";
  if (statKey === "birdies") return "Birdies";
  if (statKey === "pars") return "Pars";
  if (statKey === "bogeys") return "Bogeys";
  if (statKey === "gir") return "GIR";
  if (statKey === "fairways") return "Fairways hit";
  if (statKey === "putts") return "Putts";
  if (statKey === "sg_total") return "SG: Total";
  if (statKey === "sg_ott") return "SG: Off the tee";
  if (statKey === "sg_app") return "SG: Approach";
  if (statKey === "sg_arg") return "SG: Around the green";
  if (statKey === "sg_putt") return "SG: Putting";
  if (statKey === "sg_t2g") return "SG: Tee to green";
  if (statKey === "sg_50_100_fw") return "SG: App 50–100 (FW)";
  if (statKey === "sg_100_150_fw") return "SG: App 100–150 (FW)";
  if (statKey === "sg_150_200_fw") return "SG: App 150–200 (FW)";
  if (statKey === "sg_over_200_fw") return "SG: App 200+ (FW)";
  if (statKey === "sg_under_150_rgh") return "SG: App <150 (RGH)";
  if (statKey === "sg_over_150_rgh") return "SG: App 150+ (RGH)";
  if (statKey === "sg_app_dist_total") return "SG: App distance total";
  if (statKey === "sg_putt_0_5ft") return "SG: Putt 0–5 ft";
  if (statKey === "sg_putt_5_10ft") return "SG: Putt 5–10 ft";
  if (statKey === "sg_putt_10_15ft") return "SG: Putt 10–15 ft";
  if (statKey === "sg_putt_15_25ft") return "SG: Putt 15–25 ft";
  if (statKey === "sg_putt_25plus_ft") return "SG: Putt 25+ ft";
  if (statKey === "sg_putt_dist_total") return "SG: Putt distance total";
  if (statKey === "gir_pct") return "GIR %";
  if (statKey === "fairways_pct") return "Fairways %";
  return String(statKey || "");
}

/**
 * Over / under vs line (strict; pushes excluded from both counts).
 * Selected golfer: same window as chart (`propsFilteredRoundsNewestFirst`).
 * Leaderboard table: all rounds matching filters (ignore Rounds stepper).
 */
function propsFullHitStatsForDg(dgId, statKey, line, winN, forLeaderboardTable = false) {
  if (!Number.isFinite(line)) return { valid: 0, over: 0, under: 0, overRate: NaN, underRate: NaN };
  const newestFirst = forLeaderboardTable
    ? filteredHistoryRounds(dgId)
    : propsFilteredRoundsNewestFirst(dgId, winN);
  let valid = 0;
  let over = 0;
  let under = 0;
  for (const r of newestFirst) {
    const a = actualForRoundRow(statKey, r);
    if (!Number.isFinite(a)) continue;
    valid++;
    if (a > line) over++;
    else if (a < line) under++;
  }
  return {
    valid,
    over,
    under,
    overRate: valid > 0 ? over / valid : NaN,
    underRate: valid > 0 ? under / valid : NaN,
  };
}

function ensurePropsDgIdNameManifestLoaded() {
  if (propsDgIdNameById) return Promise.resolve(propsDgIdNameById);
  if (propsDgIdNameManifestPromise) return propsDgIdNameManifestPromise;
  propsDgIdNameManifestPromise = (async () => {
    if (isFileProtocol()) {
      propsDgIdNameById = new Map();
      return propsDgIdNameById;
    }
    try {
      const res = await fetch(cacheBustFetchUrl("player-history/manifest.json"), { cache: "no-store" });
      if (res.ok) {
        const j = await res.json();
        const m = new Map();
        for (const p of j.players || []) {
          const id = Math.round(num(p.dg_id, NaN));
          const nm = normalizeGolferDisplayName(p.player_name);
          if (Number.isFinite(id) && nm) m.set(id, nm);
        }
        propsDgIdNameById = m;
        propsHistoryManifestDgIds = new Set(m.keys());
        return m;
      }
    } catch (_) {
      /* manifest optional */
    }
    propsDgIdNameById = new Map();
    propsHistoryManifestDgIds = new Set();
    return propsDgIdNameById;
  })().finally(() => {
    propsDgIdNameManifestPromise = null;
  });
  return propsDgIdNameManifestPromise;
}

function golferDisplayNameFromHistoryBucket(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id) || !HISTORY?.byDgId) return "";
  const rec = HISTORY.byDgId[String(id)];
  if (!rec) return "";
  const bucketNm = normalizeGolferDisplayName(rec.player_name);
  if (bucketNm) return bucketNm;
  const rounds = Array.isArray(rec.rounds) ? rec.rounds : [];
  for (let i = rounds.length - 1; i >= 0; i--) {
    const rn = normalizeGolferDisplayName(rounds[i]?.player_name);
    if (rn) return rn;
  }
  return "";
}

/**
 * Resolve a golfer label for Historical Trends / field-by-course (never `DG {id}`).
 * @param {number} dgId
 * @param {string} [hintName] — shard row / entry hint
 * @param {Map<number, string>} [nameByDgOpt]
 */
function resolveGolferDisplayNameForDg(dgId, hintName = "", nameByDgOpt = null) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return "";
  const hint = normalizeGolferDisplayName(hintName);
  if (hint) return hint;
  const map = nameByDgOpt || buildPropsGolferDisplayNameMap();
  const fromMap = map.get(id);
  if (fromMap) return fromMap;
  const fromHist = golferDisplayNameFromHistoryBucket(id);
  if (fromHist) return fromHist;
  if (propsDgIdNameById?.has(id)) return propsDgIdNameById.get(id) || "";
  return "";
}

function propsPlayerDisplayNameForDg(dgId, hintName = "") {
  return resolveGolferDisplayNameForDg(dgId, hintName) || "—";
}

/** O(players + history + manifest) lookup for leaderboard rows. */
function buildPropsGolferDisplayNameMap() {
  const sig = `${historyMutationEpoch}|${DATA.players?.length ?? 0}|${propsDgIdNameById?.size ?? 0}|${Object.keys(HISTORY?.byDgId || {}).length}`;
  if (propsGolferDisplayNameMapCache && sig === propsGolferDisplayNameMapCacheSig) {
    return propsGolferDisplayNameMapCache;
  }
  const m = new Map();
  const players = DATA.players || [];
  for (const p of players) {
    const pid = Math.round(num(p.dg_id, NaN));
    if (!Number.isFinite(pid)) continue;
    const nm = normalizeGolferDisplayName(p.player_name);
    if (nm) m.set(pid, nm);
  }
  if (HISTORY?.byDgId) {
    for (const [dgStr, rec] of Object.entries(HISTORY.byDgId)) {
      const pid = Math.round(num(dgStr, NaN));
      if (!Number.isFinite(pid) || m.has(pid)) continue;
      const nm = golferDisplayNameFromHistoryBucket(pid);
      if (nm) m.set(pid, nm);
    }
  }
  if (propsDgIdNameById?.size) {
    for (const [pid, nm] of propsDgIdNameById) {
      if (!m.has(pid) && nm) m.set(pid, nm);
    }
  }
  propsGolferDisplayNameMapCache = m;
  propsGolferDisplayNameMapCacheSig = sig;
  return m;
}

/** Max rows that could count toward O/U (finite actual on this market); filters only remove rounds. Used to prune leaderboard work. */
function propsMaxFiniteMarketRoundsUpperBound(dgId, statKey, minRoundsNeeded = 1) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return 0;
  const need = Math.max(1, Math.round(num(minRoundsNeeded, 1)));
  let n = 0;
  for (const r of historyRoundsForDg(id)) {
    if (historyRoundIsPlaceholderAllMarketsZero(r)) continue;
    if (!Number.isFinite(actualForRoundRow(statKey, r))) continue;
    n++;
    if (n >= need) return n;
  }
  return n;
}

const FIRE3 = String.fromCodePoint(0x1f525).repeat(3);
const ICE3 = String.fromCodePoint(0x1f9ca).repeat(3);

function paintPropsTopHitsHeadUi(statKey, line) {
  const em = document.getElementById("props-top-hits-emoji");
  if (em) em.textContent = propsTopHitsFitMode === "fire" ? FIRE3 : ICE3;
  const mk = document.getElementById("props-top-hits-market");
  if (mk) mk.textContent = propMarketLabelFromKey(statKey);
  const ln = document.getElementById("props-top-hits-line-text");
  if (ln) {
    ln.textContent = Number.isFinite(line) ? `Line ${formatPropsTrendLineLabel(statKey, line)}` : "Line —";
  }
  const toggle = document.getElementById("props-top-hits-emoji-toggle");
  if (toggle) {
    toggle.setAttribute(
      "aria-label",
      propsTopHitsFitMode === "fire"
        ? "Prioritize fire-side fits — click to prioritize ice-side fits"
        : "Prioritize ice-side fits — click to prioritize fire-side fits"
    );
  }
}

function propsTopTableSortInPlace(rows, statKey) {
  const fitFirst =
    propsTopHitsFitMode === "fire"
      ? (r) => propsPlayerMeetsFireSide(statKey, r)
      : (r) => propsPlayerMeetsIceSide(statKey, r);
  const { key, dir } = propsTopTableSort;
  rows.sort((a, b) => {
    const fa = fitFirst(a) ? 0 : 1;
    const fb = fitFirst(b) ? 0 : 1;
    if (fa !== fb) return fa - fb;
    let cmp = 0;
    if (key === "name") cmp = String(a.name).localeCompare(String(b.name));
    else if (key === "overRate") cmp = a.overRate - b.overRate;
    else if (key === "underRate") cmp = a.underRate - b.underRate;
    else if (key === "over") cmp = a.over - b.over;
    else if (key === "under") cmp = a.under - b.under;
    if (cmp !== 0) return dir === 1 ? cmp : -cmp;
    if (b.valid !== a.valid) return b.valid - a.valid;
    return String(a.name).localeCompare(String(b.name));
  });
}

/** Calendar year on a history row (`year` field or parsed `event_completed`). */
function historyRoundSeasonYear(r) {
  if (!r || typeof r !== "object") return NaN;
  const y = num(r.year, NaN);
  if (Number.isFinite(y) && y >= 1990 && y <= 2100) return Math.round(y);
  const base = parseEventCompletedChronoBase(r.event_completed);
  const yy = Math.floor(base / 10000);
  return yy >= 1990 && yy <= 2100 ? yy : NaN;
}

const PROPS_TREND_DISPLAY_SEASON_YEAR = 2026;

function propsTrendHistoryBaselineRounds(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return [];
  return historyRoundsForDg(id).filter((r) => !historyRoundIsPlaceholderAllMarketsZero(r));
}

function propsTrendMeanActual(statKey, rounds) {
  let sum = 0;
  let n = 0;
  for (const r of rounds) {
    const a = actualForRoundRow(statKey, r);
    if (!Number.isFinite(a)) continue;
    sum += a;
    n++;
  }
  return n > 0 ? sum / n : NaN;
}

function propsTrendMeanFieldVenueActual(statKey, rounds) {
  let sum = 0;
  let n = 0;
  for (const r of rounds) {
    const a = actualForFieldVenueKpiRow(statKey, r);
    if (!Number.isFinite(a)) continue;
    sum += a;
    n++;
  }
  return n > 0 ? sum / n : NaN;
}

/** Baked venue means from projections when field history is not loaded yet. */
function propsTrendFieldVenueKpiFallback(statKey) {
  const b = DATA?.meta?.projection_course_basis;
  if (!b || typeof b !== "object") return NaN;
  if (statKey === "total") return num(b.venue_avg_round_score, NaN);
  if (statKey === "birdies") return num(b.venue_avg_birdies, NaN);
  if (statKey === "pars") return num(b.venue_avg_pars, NaN);
  if (statKey === "bogeys") return num(b.venue_avg_bogeys, NaN);
  if (statKey === "gir") return num(b.venue_avg_gir, NaN);
  if (statKey === "fairways") return num(b.venue_avg_fairways, NaN);
  if (statKey === "putts") return num(b.venue_avg_putts, NaN);
  return NaN;
}

function propsTrendFieldVenueKpiValue(statKey, rounds, opts = {}) {
  const mean = propsTrendMeanFieldVenueActual(statKey, rounds);
  if (Number.isFinite(mean)) return mean;
  if (opts.allowMetaFallback === false) return NaN;
  return propsTrendFieldVenueKpiFallback(statKey);
}

function propsVenueRoundDedupeKey(row) {
  const dg = Math.round(num(row?.dg_id, NaN));
  const sk = Math.round(num(row?.sortKey, NaN));
  if (Number.isFinite(sk) && sk > 0) return `${dg}|${sk}`;
  const yr = historyRoundSeasonYear(row);
  const rn = Math.round(num(row?.round_num, NaN));
  const ev = String(row?.event_name || "").trim().toLowerCase();
  return `${dg}|${yr}|${rn}|${ev}`;
}

function mergePropsVenueRoundRowsUnique(primary, extra) {
  const out = [...(primary || [])];
  const seen = new Set(out.map(propsVenueRoundDedupeKey));
  for (const r of extra || []) {
    const k = propsVenueRoundDedupeKey(r);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(r);
  }
  return out;
}

/** Season course avg: only from completed rounds at this venue in the display year (no projection fallback). */
function propsTrendSeasonCourseKpiValue(statKey, seasonRoundsAtVenue) {
  if (!seasonRoundsAtVenue?.length) return NaN;
  return propsTrendMeanFieldVenueActual(statKey, seasonRoundsAtVenue);
}

function propsTrendCourseFilterActive() {
  return Boolean(courseFilterOn() || (propsCourseWindowModeActive() && propsEffectiveCourseKey()));
}

/** Course-only slice of career history (“Current course only” and/or Course dropdown while field-by-course window is on); ignores weather & graph window. */
function roundsMatchingCourseSelectionOnly(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return [];
  if (!propsTrendCourseFilterActive()) return [];
  let list = playerHistoryRoundsAugmentedForCourseFilter(id);
  if (courseFilterOn()) {
    const venueKey = propsEventVenueCourseKey();
    if (venueKey) list = list.filter((r) => normCourseNameKey(r.course_name) === venueKey);
    else {
      const metaEvent = String(DATA.meta?.event_name || "").trim();
      if (metaEvent) list = list.filter((r) => currentTournamentContextMatchesRound(r));
    }
  }
  const courseSel = propsCourseWindowModeActive() || courseFilterOn() ? propsEffectiveCourseKey() : "";
  if (courseSel) list = list.filter((r) => normCourseNameKey(r.course_name) === normCourseNameKey(courseSel));
  return list;
}

/** Current tournament venue-only slice (independent of filters), used for KPI context. */
function roundsMatchingCurrentCourseOnly(dgId) {
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return [];
  const vn = venueCourseName();
  const metaEvent = String(DATA.meta.event_name || "").trim();
  if (!vn && !metaEvent) return [];
  let list = propsTrendHistoryBaselineRounds(id);
  list = list.filter((r) => currentTournamentContextMatchesRound(r));
  // "Current course avg" should reflect this season only, not prior-year starts at the same venue.
  list = list.filter((r) => historyRoundSeasonYear(r) === PROPS_TREND_DISPLAY_SEASON_YEAR);
  return list;
}

/** True when enough player buckets are loaded to run full-field KPI / top-10 scans safely. */
function propsFieldLeaderboardEnabled() {
  if (!HISTORY._ok || HISTORY._partial) return false;
  return Object.keys(HISTORY.byDgId || {}).length >= 20;
}

/** Field course KPIs can use partial history; leaderboard still needs propsFieldLeaderboardEnabled(). */
function propsFieldVenueKpisEnabled() {
  const venueRaw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  if (!venueRaw || !HISTORY._ok) return false;
  return Object.keys(HISTORY.byDgId || {}).length >= 1;
}

/** In-memory field rounds at venue (partial on live week) — supplements season KPI after shard load. */
function rebuildPropsFieldVenueMemorySupplement() {
  const venueRaw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  const sig = `${historyMutationEpoch}|${normCourseNameKey(venueRaw)}`;
  if (!venueRaw || !propsFieldVenueKpisEnabled()) {
    propsFieldVenueRoundsCacheSig = sig;
    propsFieldVenueRoundsCache = { season: [], all: [] };
    return;
  }
  if (propsFieldVenueRoundsCacheSig === sig) return;
  const season = [];
  const all = [];
  for (const rec of Object.values(HISTORY.byDgId || {})) {
    if (!rec || !Array.isArray(rec.rounds)) continue;
    for (const r of rec.rounds) {
      if (historyRoundIsPlaceholderAllMarketsZero(r)) continue;
      if (normCourseNameKey(r.course_name) !== normCourseNameKey(venueRaw)) continue;
      all.push(r);
      if (historyRoundSeasonYear(r) === PROPS_TREND_DISPLAY_SEASON_YEAR) season.push(r);
    }
  }
  propsFieldVenueRoundsCacheSig = sig;
  propsFieldVenueRoundsCache = { season, all };
}

/**
 * True all-time + season field venue KPIs from prebuilt by-course history (not partial in-memory field load).
 */
async function ensurePropsFieldVenueShardRoundsLoaded() {
  const venueRaw = String(DATA?.meta?.course_used || DATA?.course_used || "").trim();
  const courseKey = normCourseNameKey(venueRaw);
  const sig = `${historyMutationEpoch}|${courseKey}`;
  if (!courseKey || !propsFieldVenueKpisEnabled()) {
    propsFieldVenueShardCacheSig = sig;
    propsFieldVenueShardCache = { season: [], all: [], ready: true };
    return propsFieldVenueShardCache;
  }
  if (propsFieldVenueShardCacheSig === sig && propsFieldVenueShardCache.ready) {
    return propsFieldVenueShardCache;
  }
  if (propsFieldVenueShardPromise) return propsFieldVenueShardPromise;

  propsFieldVenueShardPromise = (async () => {
    rebuildPropsFieldVenueMemorySupplement();
    const bucket = await ensurePropsCourseIndexForKeyAsync(courseKey);
    const allShard = [];
    for (const e of bucket.entries || []) {
      const r = e.row;
      if (!r || historyRoundIsPlaceholderAllMarketsZero(r)) continue;
      if (!historyRoundCountsAsActual(r)) continue;
      allShard.push(r);
    }
    const all = mergePropsVenueRoundRowsUnique(allShard, propsFieldVenueRoundsCache.all);
    const seasonShard = allShard.filter(
      (r) => historyRoundSeasonYear(r) === PROPS_TREND_DISPLAY_SEASON_YEAR,
    );
    const season = mergePropsVenueRoundRowsUnique(seasonShard, propsFieldVenueRoundsCache.season);
    propsFieldVenueShardCache = { season, all, ready: true };
    propsFieldVenueShardCacheSig = sig;
    return propsFieldVenueShardCache;
  })().finally(() => {
    propsFieldVenueShardPromise = null;
  });
  return propsFieldVenueShardPromise;
}

/** Load venue shard + optional full player history for field leaderboard. */
function ensurePropsFieldVenueHistoryLoaded() {
  if (isFileProtocol()) return;
  void ensurePropsFieldVenueShardRoundsLoaded().then(() => {
    if (activeAppTabId() === "props") scheduleRenderPropsTrends(0);
  });
  if (propsFieldLeaderboardEnabled() || playerHistoryLoadPromise || HISTORY._loading) return;
  void loadPlayerHistory().then(() => {
    if (activeAppTabId() === "props") scheduleRenderPropsTrends(0);
  });
}

/** Field-wide current-course rounds (all players) for this season KPI. */
function roundsMatchingCurrentCourseOnlyFieldSeason() {
  if (propsFieldVenueShardCache.ready) return propsFieldVenueShardCache.season;
  rebuildPropsFieldVenueMemorySupplement();
  return propsFieldVenueRoundsCache.season;
}

/** Field-wide rounds at this venue across all seasons (by-course shard). */
function roundsMatchingCurrentCourseOnlyFieldAllTime() {
  if (propsFieldVenueShardCache.ready) return propsFieldVenueShardCache.all;
  rebuildPropsFieldVenueMemorySupplement();
  return propsFieldVenueRoundsCache.all;
}

function formatPropsTrendKpiValue(statKey, v) {
  if (!Number.isFinite(v)) return "—";
  if (propsStatIsPct(statKey)) return `${v.toFixed(1)}%`;
  if (propsStatIsSg(statKey)) return v >= 0 ? `+${v.toFixed(2)}` : v.toFixed(2);
  if (Math.abs(v - Math.round(v)) < 1e-9) return String(Math.round(v));
  return v.toFixed(1);
}

function propMarketTrendBookLabel(statKey) {
  if (statKey === "total") return "Score";
  return propMarketLabelFromKey(statKey);
}

/**
 * Posted O/U for a sportsbook (`fanduel` | `draftkings`) nearest the chart line.
 */
function propsTrendPickQuoteForBook(playerRow, marketLabel, hintLine, bookSlug) {
  const canon = ouPropsCanonicalMarket(marketLabel);
  const want = String(bookSlug || "").trim().toLowerCase();
  if (!want || !playerRow) return null;
  const props = Array.isArray(DATA.props) ? DATA.props : [];
  /** @type {{ line: number, over: number, under: number }[]} */
  const cand = [];
  for (const r of props) {
    const src = String(r.source || "").trim().toLowerCase();
    if (src !== want) continue;
    if (String(r.market || "").trim() !== canon) continue;
    const L = enforceHalfLine(num(r.line, NaN));
    const o = Math.round(num(r.over_odds, NaN));
    const u = Math.round(num(r.under_odds, NaN));
    if (!Number.isFinite(L) || !Number.isFinite(o) || !Number.isFinite(u) || o === 0 || u === 0) continue;
    const rid = Math.round(num(r.dg_id, NaN));
    const wantId = Math.round(num(playerRow.dg_id, NaN));
    const rRaw = ouPropPlayerKeyRaw(r.player_name || "");
    const rDisp = ouPropPlayerKeyDisplay(r.player_name || "");
    const wantRaw = ouPropPlayerKeyRaw(playerRow.player_name || "");
    const wantDisp = ouPropPlayerKeyDisplay(playerRow.player_name || "");
    const sameById = Number.isFinite(wantId) && wantId > 0 && rid === wantId;
    const sameByName =
      (wantRaw && rRaw && wantRaw === rRaw) || (wantDisp && rDisp && wantDisp === rDisp);
    if (!sameById && !sameByName) continue;
    cand.push({ line: L, over: o, under: u });
  }
  if (!cand.length) return null;
  const h = enforceHalfLine(hintLine);
  if (!Number.isFinite(h)) return cand.slice().sort((a, b) => a.line - b.line)[0];
  let best = cand[0];
  let bd = Math.abs(best.line - h);
  for (let i = 1; i < cand.length; i++) {
    const d = Math.abs(cand[i].line - h);
    if (d < bd) {
      best = cand[i];
      bd = d;
    }
  }
  return best;
}

function paintPropsTrendBookRows(playerRow, statKey, lineHint, hitSt) {
  const wrap = document.getElementById("props-trends-book-lines");
  if (!wrap) return;
  wrap.replaceChildren();
  if (!playerRow) return;

  const marketLbl = ouMarketKeyFromStatKey(statKey);
  const mShort = propMarketTrendBookLabel(statKey);
  const fd = propsTrendPickQuoteForBook(playerRow, marketLbl, lineHint, "fanduel");
  const dk = propsTrendPickQuoteForBook(playerRow, marketLbl, lineHint, "draftkings");

  const mkRow = (bookKey, pick) => {
    if (!pick) return;
    const meta = SPORTSBOOK_META[bookKey];
    if (!meta) return;
    const row = document.createElement("div");
    row.className = `props-trends-book-row${propsStatLowerIsBetter(statKey) ? " props-ou-lower-is-better" : ""}`;
    const logoWrap = document.createElement("span");
    logoWrap.className = "props-trends-book-logo-wrap";
    const img = document.createElement("img");
    img.className = "props-trends-book-logo-img";
    img.alt = meta.label;
    img.loading = "lazy";
    const fb = document.createElement("span");
    fb.className = "props-trends-book-logo-fallback";
    fb.textContent = meta.short || bookKey.slice(0, 2).toUpperCase();
    fb.style.display = "none";
    logoWrap.appendChild(img);
    logoWrap.appendChild(fb);
    row.appendChild(logoWrap);
    attachBookLogoWithFallback(img, fb, meta.domain);

    const main = document.createElement("span");
    main.className = "props-trends-book-main";
    main.appendChild(document.createTextNode(`${formatPropLineValueForInput(pick.line)} `));
    const mkt = document.createElement("span");
    mkt.className = "props-trends-book-mkt";
    mkt.textContent = mShort;
    main.appendChild(mkt);
    row.appendChild(main);

    const ou = document.createElement("span");
    ou.className = "props-trends-book-ou";
    const oSp = document.createElement("span");
    oSp.className = "props-trends-book-ou-over";
    oSp.textContent = `O ${formatAmerican(pick.over)}`;
    const uSp = document.createElement("span");
    uSp.className = "props-trends-book-ou-under";
    uSp.textContent = `U ${formatAmerican(pick.under)}`;
    ou.appendChild(oSp);
    ou.appendChild(uSp);
    row.appendChild(ou);
    wrap.appendChild(row);
  };

  mkRow("fanduel", fd);
  mkRow("draftkings", dk);

  if (!fd && !dk && Number.isFinite(lineHint)) {
    const lowerBetter = propsStatLowerIsBetter(statKey);
    const lineTxt = formatPropsTrendLineLabel(statKey, lineHint);
    const market = propMarketLabelFromKey(statKey);
    const underPct =
      hitSt && hitSt.valid > 0 && Number.isFinite(hitSt.underRate) ? Math.round(hitSt.underRate * 100) : NaN;
    const overPct =
      hitSt && hitSt.valid > 0 && Number.isFinite(hitSt.overRate) ? Math.round(hitSt.overRate * 100) : NaN;
    const underTxt =
      hitSt && hitSt.valid > 0 && Number.isFinite(underPct) ? `${hitSt.under}/${hitSt.valid} (${underPct}%)` : "—";
    const overTxt =
      hitSt && hitSt.valid > 0 && Number.isFinite(overPct) ? `${hitSt.over}/${hitSt.valid} (${overPct}%)` : "—";
    const fbRow = document.createElement("div");
    fbRow.className = `props-trends-inline-meta${lowerBetter ? " props-ou-lower-is-better" : ""}`;
    fbRow.innerHTML = `<span class="props-trends-inline-line">Line ${lineTxt}</span><span class="props-trends-inline-market">${market}</span><span class="props-trends-inline-under">U ${underTxt}</span><span class="props-trends-inline-over">O ${overTxt}</span>`;
    wrap.appendChild(fbRow);
  }
}

function paintPropsTrendKpiRow(statKey, hitSt, graphSeries, dgId) {
  const el = document.getElementById("props-trends-kpis");
  if (!el) return;
  if (!propsFieldVenueShardCache.ready && propsFieldVenueKpisEnabled()) {
    el.replaceChildren();
    const wait = document.createElement("p");
    wait.className = "text-muted";
    wait.textContent = "Loading course history for venue KPIs…";
    el.appendChild(wait);
    ensurePropsFieldVenueHistoryLoaded();
    return;
  }
  el.replaceChildren();
  const id = Math.round(num(dgId, NaN));
  if (!Number.isFinite(id)) return;

  const pool = propsTrendHistoryBaselineRounds(id);
  const allMean = propsTrendMeanActual(statKey, pool);
  const seasonRounds = pool.filter((r) => historyRoundSeasonYear(r) === PROPS_TREND_DISPLAY_SEASON_YEAR);
  const seasonMean = propsTrendMeanActual(statKey, seasonRounds);

  const vals = (graphSeries || []).map((s) => s.actual).filter((x) => Number.isFinite(x));
  const graphMean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;

  const addKpi = (label, val) => {
    const wrap = document.createElement("div");
    wrap.className = "props-trends-kpi";
    const lab = document.createElement("span");
    lab.className = "props-trends-kpi-lab";
    lab.textContent = label;
    const v = document.createElement("span");
    v.className = "props-trends-kpi-val";
    v.textContent = formatPropsTrendKpiValue(statKey, val);
    wrap.appendChild(lab);
    wrap.appendChild(v);
    el.appendChild(wrap);
  };

  addKpi("All-time avg", allMean);
  addKpi("Season avg", seasonMean);
  addKpi("Graph avg", graphMean);
  ensurePropsFieldVenueHistoryLoaded();
  const atVenueSeason = roundsMatchingCurrentCourseOnlyFieldSeason();
  const atVenueAll = roundsMatchingCurrentCourseOnlyFieldAllTime();
  addKpi(
    `${PROPS_TREND_DISPLAY_SEASON_YEAR} course avg`,
    propsTrendSeasonCourseKpiValue(statKey, atVenueSeason),
  );
  addKpi(
    "All-time course avg",
    propsTrendFieldVenueKpiValue(statKey, atVenueAll, { allowMetaFallback: false }),
  );

  if (hitSt && hitSt.valid > 0) {
    const lowerBetter = propsStatLowerIsBetter(statKey);
    const addRateKpi = (label, rate, wins, total, side) => {
      const wrap = document.createElement("div");
      wrap.className = "props-trends-kpi";
      const lab = document.createElement("span");
      lab.className = "props-trends-kpi-lab";
      lab.textContent = label;
      const val = document.createElement("span");
      val.className = "props-trends-kpi-val";
      val.textContent = Number.isFinite(rate) ? `${(rate * 100).toFixed(1)}% (${wins}/${total})` : "—";
      const isUnderSide = side === "under";
      const greenSide = lowerBetter ? isUnderSide : !isUnderSide;
      val.classList.add(greenSide ? "ev-pos" : "ev-neg");
      wrap.appendChild(lab);
      wrap.appendChild(val);
      el.appendChild(wrap);
    };
    addRateKpi("Over hit rate", hitSt.overRate, hitSt.over, hitSt.valid, "over");
    addRateKpi("Under hit rate", hitSt.underRate, hitSt.under, hitSt.valid, "under");
  }

}

function paintPropsTrendsInsightHeader(playerRow, statKey, line, hitSt, graphSeries, dgId) {
  paintPropsTrendBookRows(playerRow, statKey, line, hitSt);
  paintPropsTrendKpiRow(statKey, hitSt, graphSeries, dgId);
}

function paintPropsTopTableSortHeaders() {
  document.querySelectorAll("#table-props-top-hits thead th[data-props-sort]").forEach((th) => {
    const k = th.getAttribute("data-props-sort");
    const active = k === propsTopTableSort.key;
    th.setAttribute("aria-sort", active ? (propsTopTableSort.dir === -1 ? "descending" : "ascending") : "none");
    const up = th.querySelector(".sort-up");
    const dn = th.querySelector(".sort-down");
    if (up && dn) {
      up.classList.toggle("active", active && propsTopTableSort.dir === -1);
      dn.classList.toggle("active", active && propsTopTableSort.dir === 1);
    }
  });
}

let propsTopTableSortListenerBound = false;
function initPropsTopTableSortOnce() {
  if (propsTopTableSortListenerBound) return;
  const thead = document.querySelector("#table-props-top-hits thead");
  if (!thead) return;
  propsTopTableSortListenerBound = true;
  thead.addEventListener("click", (ev) => {
    const th = ev.target.closest("th[data-props-sort]");
    if (!th) return;
    const key = th.getAttribute("data-props-sort");
    if (!key || !["name", "overRate", "over", "underRate", "under"].includes(key)) return;
    if (propsTopTableSort.key === key) {
      propsTopTableSort = { key, dir: /** @type {-1 | 1} */ (-propsTopTableSort.dir) };
    } else {
      const defaultDir = key === "name" ? 1 : -1;
      propsTopTableSort = { key, dir: defaultDir };
    }
    renderPropsTrendsNow();
  });
}

function renderPropsHitRateAndTopTable(statKey, line, winN, courseWindowEntriesOpt) {
  initPropsTopTableSortOnce();
  paintPropsTopHitsHeadUi(statKey, line);
  const block = document.getElementById("props-hit-rate-block");
  const underEl = document.getElementById("props-hit-under-val");
  const overEl = document.getElementById("props-hit-over-val");
  const tbody = document.querySelector("#table-props-top-hits tbody");
  if (!HISTORY._ok) {
    if (block) {
      block.hidden = true;
      block.classList.remove("props-ou-lower-is-better");
    }
    if (underEl) underEl.textContent = "—";
    if (overEl) overEl.textContent = "—";
    if (tbody) tbody.innerHTML = "";
    paintPropsTopTableSortHeaders();
    return;
  }
  const wn = clamp(
    Math.round(num(winN, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX
  );
  const dg = selectedDgId();
  const windowEntriesList =
    propsCourseWindowModeActive() && courseWindowEntriesOpt
      ? propsCourseWindowEntriesAfterWindow(courseWindowEntriesOpt, statKey, wn)
      : null;
  const st = propsCourseWindowModeActive()
    ? windowEntriesList
      ? propsFullHitStatsFromRoundList(statKey, line, windowEntriesList.map((e) => e.row), { courseWindow: true })
      : propsCourseWindowFieldHitStats(statKey, line, wn)
    : propsFullHitStatsForDg(dg, statKey, line, wn);
  if (block) {
    block.hidden = false;
    block.classList.toggle("props-ou-lower-is-better", propsStatLowerIsBetter(statKey));
  }
  if (underEl) {
    if (st.valid > 0) {
      const pct = Math.round(st.underRate * 100);
      underEl.textContent = `${st.under}/${st.valid} (${pct}%)`;
    } else {
      underEl.textContent = "—";
    }
  }
  if (overEl) {
    if (st.valid > 0) {
      const pct = Math.round(st.overRate * 100);
      overEl.textContent = `${st.over}/${st.valid} (${pct}%)`;
    } else {
      overEl.textContent = "—";
    }
  }
  if (!tbody) return;
  tbody.innerHTML = "";
  if (!propsCourseWindowModeActive() && !propsFieldLeaderboardEnabled()) {
    const tr = document.createElement("tr");
    const td = document.createElement("td");
    td.colSpan = 6;
    td.className = "text-muted";
    td.textContent = HISTORY._partial
      ? window.matchMedia("(max-width: 699px)").matches
        ? "Selected-player history loaded. Full-field rankings load after history finishes (or open Course fit once)."
        : "Loading full-field rankings…"
      : "Full-field rankings need more player history loaded.";
    tr.appendChild(td);
    tbody.appendChild(tr);
    paintPropsTopTableSortHeaders();
    return;
  }
  const minR = propsTopHitMinRoundsForFilter();
  /** Pre-aggregate course-window rounds once (avoid O(field × history) rescans per golfer). */
  let courseWindowRoundsByDg = /** @type {Map<number, object[]> | null} */ (null);
  if (propsCourseWindowModeActive()) {
    courseWindowRoundsByDg = new Map();
    const list =
      windowEntriesList ||
      propsCourseWindowEntriesAfterWindow(
        courseWindowEntriesOpt || collectCourseWindowRoundEntriesFixed(),
        statKey,
        wn,
      );
    for (const e of list) {
      const id = e.dgId;
      if (!courseWindowRoundsByDg.has(id)) courseWindowRoundsByDg.set(id, []);
      courseWindowRoundsByDg.get(id).push(e.row);
    }
  }
  const ids = propsCourseWindowModeActive()
    ? [...(courseWindowRoundsByDg?.keys() || [])].map((id) => Math.round(num(id, NaN))).filter((x) => Number.isFinite(x))
    : Object.keys(HISTORY.byDgId || {})
        .map((k) => num(k, NaN))
        .filter((x) => Number.isFinite(x));
  const nameByDg = buildPropsGolferDisplayNameMap();
  const courseWindowNameByDg = new Map();
  if (propsCourseWindowModeActive() && courseWindowEntriesOpt?.length) {
    for (const e of courseWindowEntriesOpt) {
      const id = Math.round(num(e.dgId, NaN));
      if (!Number.isFinite(id) || courseWindowNameByDg.has(id)) continue;
      const nm = resolveGolferDisplayNameForDg(id, e.playerName, nameByDg);
      if (nm) courseWindowNameByDg.set(id, nm);
    }
  }
  const rows = [];
  for (const id of ids) {
    if (!propsCourseWindowModeActive() && propsMaxFiniteMarketRoundsUpperBound(id, statKey, minR) < minR) {
      continue;
    }
    const s = propsCourseWindowModeActive()
      ? propsFullHitStatsFromRoundList(statKey, line, courseWindowRoundsByDg?.get(id) || [])
      : propsFullHitStatsForDg(id, statKey, line, wn, true);
    if (s.valid < minR) continue;
    const name = propsCourseWindowModeActive()
      ? courseWindowNameByDg.get(id) || resolveGolferDisplayNameForDg(id, "", nameByDg)
      : resolveGolferDisplayNameForDg(id, nameByDg.get(id), nameByDg);
    if (!name) continue;
    rows.push({
      dgId: id,
      name,
      valid: s.valid,
      over: s.over,
      under: s.under,
      overRate: s.overRate,
      underRate: s.underRate,
    });
  }
  propsTopTableSortInPlace(rows, statKey);
  const top = rows.slice(0, 10);
  if (!top.length) {
    const tr = document.createElement("tr");
    const td = document.createElement("td");
    td.colSpan = 6;
    td.className = "text-muted";
    td.textContent = `No golfers with at least ${minR} qualifying rounds for this filter.`;
    tr.appendChild(td);
    tbody.appendChild(tr);
    paintPropsTopTableSortHeaders();
    return;
  }
  top.forEach((r, i) => {
    const tr = document.createElement("tr");
    if (r.dgId === dg) tr.classList.add("props-top-hit-current");
    const mk = (txt, cls) => {
      const td = document.createElement("td");
      td.textContent = txt;
      if (cls) td.className = cls;
      return td;
    };
    tr.appendChild(mk(String(i + 1), "num"));
    tr.appendChild(mk(r.name));
    tr.appendChild(mk(`${(r.overRate * 100).toFixed(1)}%`, "num"));
    tr.appendChild(mk(`${r.over} / ${r.valid}`, "num"));
    tr.appendChild(mk(`${(r.underRate * 100).toFixed(1)}%`, "num"));
    tr.appendChild(mk(`${r.under} / ${r.valid}`, "num"));
    tbody.appendChild(tr);
  });
  paintPropsTopTableSortHeaders();
}

function modelForHistoryRow(statKey, row) {
  const r = projectionRowForPlayerRound(row._playerName || "", getOuRound());
  if (!r) return NaN;
  const dgId = Math.round(num(r.dg_id, NaN));
  let base = NaN;
  if (statKey === "total") base = num(r.total_score, NaN);
  else if (statKey === "birdies") base = birdiesPlusEaglesFromRow(r);
  else if (statKey === "pars") base = num(r.pars, NaN);
  else if (statKey === "bogeys") base = num(r.bogeys, NaN);
  else if (statKey === "gir") base = girFairwaysCountFromRawForOu(num(r.gir, NaN), 18);
  else if (statKey === "fairways") base = girFairwaysCountFromRawForOu(num(r.fairways, NaN), fairwayHolesModeledFromData());
  else if (statKey === "putts") base = num(r.putts, NaN);
  if (!Number.isFinite(base)) return NaN;
  const liveRound =
    statKey === "total" && inPlayAffectsRoundOdds() ? liveCurrentRoundTotalScoreMuDelta(r) : 0;
  return (
    base +
    pricingModelHistoryNudge(statKey, dgId) +
    combinedCourseDifficultyOUMuAdjustment(ouMarketKeyFromStatKey(statKey), r) +
    liveRound
  );
}

/** Chart date string for a history round (see `historyRoundPlayMdY`). */
function propsTrendChartDateFromRow(r) {
  return historyRoundPlayMdY(r);
}

function shortPropsDateLabel(completed) {
  const t = String(completed || "").trim();
  const p = t.split("/");
  if (p.length >= 2) {
    const day = String(p[1]).replace(/-\d+$/, "").trim();
    return `${p[0]}/${day}`;
  }
  return t.length > 6 ? t.slice(0, 6) : t;
}

/** Chart x-axis: month/day only (no year). Strips trailing `-R` round suffix from day if present. */
function propsChartAxisLabel(completed) {
  const t = String(completed || "").trim();
  const parts = t.split("/").map((s) => s.trim());
  if (parts.length >= 2) {
    const day = String(parts[1]).replace(/-\d+$/, "").trim();
    return `${parts[0]}/${day}`;
  }
  const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    return `${parseInt(iso[2], 10)}/${parseInt(iso[3], 10)}`;
  }
  return shortPropsDateLabel(t);
}

/**
 * One string per bar for the x-axis (M/D; adds 'YY when the same calendar label spans multiple years).
 */
function buildPropsTrendXAxisLabels(series) {
  if (!series.length) return [];
  const bases = series.map((s) => propsChartAxisLabel(s.date || ""));
  const countByBase = new Map();
  for (const b of bases) countByBase.set(b, (countByBase.get(b) || 0) + 1);
  return series.map((s, i) => {
    const b = bases[i];
    if ((countByBase.get(b) || 0) <= 1) return b;
    const r = s._hist;
    const yr = num(r?.year, NaN);
    const sameBaseIdx = [];
    for (let j = 0; j < bases.length; j++) if (bases[j] === b) sameBaseIdx.push(j);
    const years = new Set(
      sameBaseIdx.map((j) => num(series[j]._hist?.year, NaN)).filter((y) => Number.isFinite(y) && y >= 1990),
    );
    if (years.size > 1 && Number.isFinite(yr)) return `${b} '${String(yr).slice(-2)}`;
    return b;
  });
}

/**
 * FanDuel-style x-axis: a few labels when many bars; duplicate display strings blanked.
 * `perBarLabels` = output of buildPropsTrendXAxisLabels (same length as series).
 * Returns Map barIndex → label string.
 */
function propsChartSparseTickLabels(perBarLabels, innerWidthPx) {
  const n = perBarLabels.length;
  const map = new Map();
  if (!n) return map;
  const minPx = n > 240 ? 96 : n > 120 ? 84 : 76;
  const maxTicks = Math.max(4, Math.min(12, Math.floor(innerWidthPx / minPx)));
  let indices;
  if (n <= maxTicks) {
    indices = Array.from({ length: n }, (_, i) => i);
  } else if (n === 1) {
    indices = [0];
  } else {
    const k = maxTicks;
    indices = [];
    for (let j = 0; j < k; j++) {
      indices.push(Math.round((j / (k - 1)) * (n - 1)));
    }
  }
  const uniq = [...new Set(indices)].sort((a, b) => a - b);
  for (const i of uniq) {
    map.set(i, String(perBarLabels[i] || "").trim());
  }
  const shown = new Set();
  for (const i of uniq) {
    const t = map.get(i);
    if (!t) continue;
    if (shown.has(t)) map.set(i, "");
    else shown.add(t);
  }
  return map;
}

/**
 * Value-sorted field charts: label each session at the horizontal span of that date's bars
 * (score-sorted x — use cluster IQR center so labels spread across the chart width).
 * @returns {{ cx: number, lab: string }[]}
 */
function propsChartXAxisValueSortSessionPlacements(perBarLabels, xCenter, padL, innerW) {
  if (!perBarLabels.length) return [];

  function mdSortKey(lab) {
    const p = String(lab || "").split("/");
    if (p.length >= 2) {
      const mo = parseInt(p[0], 10);
      const dy = parseInt(String(p[1]).replace(/[^0-9].*$/, ""), 10);
      if (Number.isFinite(mo) && Number.isFinite(dy)) return mo * 32 + dy;
    }
    return 0;
  }

  const groups = new Map();
  for (let i = 0; i < perBarLabels.length; i++) {
    const lab = String(perBarLabels[i] || "").trim();
    if (!lab) continue;
    if (!groups.has(lab)) groups.set(lab, { lab, sortKey: mdSortKey(lab) });
  }
  if (!groups.size) return [];

  const plotL = Number.isFinite(padL) ? padL : 0;
  const plotW =
    Number.isFinite(innerW) && innerW > 0
      ? innerW
      : xCenter?.length > 1
        ? xCenter[xCenter.length - 1] - xCenter[0]
        : 0;
  if (plotW <= 0) return [];

  const sessions = [...groups.values()].sort((a, b) => a.sortKey - b.sortKey || a.lab.localeCompare(b.lab));
  const minPx = 76;
  const maxTicks = Math.max(4, Math.min(12, Math.floor(plotW / minPx)));
  let tickIndices;
  if (sessions.length <= maxTicks) {
    tickIndices = sessions.map((_, i) => i);
  } else if (sessions.length === 1) {
    tickIndices = [0];
  } else {
    tickIndices = [];
    for (let j = 0; j < maxTicks; j++) {
      tickIndices.push(Math.round((j / (maxTicks - 1)) * (sessions.length - 1)));
    }
    tickIndices = [...new Set(tickIndices)].sort((a, b) => a - b);
  }
  const shown = new Set();
  const out = [];
  for (const idx of tickIndices) {
    const s = sessions[idx];
    if (!s?.lab || shown.has(s.lab)) continue;
    shown.add(s.lab);
    out.push({
      lab: s.lab,
      cx: plotL + ((idx + 0.5) / sessions.length) * plotW,
    });
  }
  return out;
}

/** @deprecated use propsChartXAxisValueSortSessionPlacements */
function propsChartXAxisValueSortSessionLabels(perBarLabels, innerW) {
  const n = perBarLabels.length;
  const map = new Map();
  if (!n) return map;
  const slotEq = Math.max(1, innerW / n);
  const padL = 42;
  const xCenter = Array.from({ length: n }, (_, i) => padL + (i + 0.5) * slotEq);
  for (const p of propsChartXAxisValueSortSessionPlacements(perBarLabels, xCenter)) {
    let best = 0;
    let bestD = Infinity;
    for (let i = 0; i < n; i++) {
      const d = Math.abs(xCenter[i] - p.cx);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    map.set(best, p.lab);
  }
  return map;
}

/** One label per bar for small samples; larger windows use sparse ticks to avoid clutter. */
function propsChartXAxisDateLabels(perBarLabels, innerW, opts = {}) {
  const n = perBarLabels.length;
  const map = new Map();
  if (!n) return map;
  if (opts.xAxisMode === "valueSort") {
    return propsChartXAxisValueSortSessionLabels(perBarLabels, innerW);
  }
  if (n <= 8) {
    for (let i = 0; i < n; i++) {
      map.set(i, String(perBarLabels[i] || "").trim());
    }
    return map;
  }
  return propsChartSparseTickLabels(perBarLabels, innerW);
}

/**
 * Equal spacing per round (rolling window). Keeps multi-year venue samples readable
 * without calendar gaps that leave most of the chart empty.
 */
function propsChartBarLayout(series, padL, innerW) {
  const n = series.length;
  const xCenter = new Array(n);
  const barW = new Array(n);
  if (n === 0) return { xCenter, barW };
  const slotEq = innerW / n;
  const bwFrac = n > 48 ? 0.44 : n > 24 ? 0.56 : 0.72;
  const minBarPx = n > 48 ? 4 : n > 24 ? 6 : 10;
  for (let i = 0; i < n; i++) {
    xCenter[i] = padL + (i + 0.5) * slotEq;
    if (n === 1) {
      barW[i] = Math.max(18, Math.min(innerW * 0.22, 72));
    } else {
      const maxW = Math.max(1, slotEq - 1);
      barW[i] = Math.max(1, Math.min(maxW, Math.max(minBarPx, slotEq * bwFrac)));
    }
  }
  return { xCenter, barW };
}

/** `course_name` from historical_rounds_all → JSON (only field used for “Course” in UI). */
function propsCourseNameFromRow(r) {
  if (!r || typeof r !== "object") return "";
  return formatCourseNameForDisplay(String(r.course_name ?? "").trim());
}

function propsCourseDisplay(s) {
  const r = s && s._hist;
  if (r && typeof r === "object") {
    const c = propsCourseNameFromRow(r);
    if (c) return c;
  }
  const raw = String(s?.course ?? "").trim();
  return raw ? formatCourseNameForDisplay(raw) : "—";
}

function pointInPropsChartHitRegion(canvasX, canvasY) {
  return propsChartHitRegions.some((r) => canvasX >= r.x0 && canvasX < r.x0 + r.w && canvasY >= r.y0 && canvasY < r.y0 + r.h);
}

/** Column index from x (center-weighted; equal-width slots). */
function propsChartHitIndexAtX(canvasX) {
  const L = propsChartHoverLayout;
  if (L.mode === "golferHorizontal") return -1;
  if (!L.n || !L.slotW || L.n !== propsChartHitRegions.length) return -1;
  if (canvasX < L.padL || canvasX > L.padL + L.n * L.slotW) return -1;
  return Math.min(L.n - 1, Math.max(0, Math.round((canvasX - L.padL - L.slotW * 0.5) / L.slotW)));
}

/** Row index from y for horizontal golfer bars. */
function propsChartHitIndexAtY(canvasY) {
  const L = propsChartHoverLayout;
  if (L.mode !== "golferHorizontal" || !L.n || !L.slotH) return -1;
  if (canvasY < L.padT || canvasY > L.padT + L.n * L.slotH) return -1;
  return Math.min(L.n - 1, Math.max(0, Math.floor((canvasY - L.padT) / L.slotH)));
}

function pickPropsChartHit(canvasX, canvasY) {
  const L = propsChartHoverLayout;
  if (L.mode === "golferHorizontal") {
    const inRows = L.n > 0 && canvasY >= L.padT && canvasY <= L.padT + L.n * L.slotH;
    let idx = propsChartHitIndexAtY(canvasY);
    if (idx < 0 || idx >= propsChartHitRegions.length) {
      if (inRows && propsChartStickyHitIndex >= 0) {
        return propsChartHitRegions[propsChartStickyHitIndex] || null;
      }
      if (!inRows) propsChartStickyHitIndex = -1;
      return null;
    }
    propsChartStickyHitIndex = idx;
    return propsChartHitRegions[idx] || null;
  }
  const inCols = L.n > 0 && canvasX >= L.padL && canvasX <= L.padL + L.n * L.slotW;
  let idx = propsChartHitIndexAtX(canvasX);
  if (idx < 0 || idx >= propsChartHitRegions.length) {
    if (inCols && propsChartStickyHitIndex >= 0) {
      return propsChartHitRegions[propsChartStickyHitIndex] || null;
    }
    if (!inCols) propsChartStickyHitIndex = -1;
    return null;
  }
  propsChartStickyHitIndex = idx;
  if (L.n > 12) return propsChartHitRegions[idx] || null;
  const r = propsChartHitRegions[idx];
  if (!r) return null;
  if (canvasY >= r.y0 && canvasY < r.y0 + r.h) return r;
  return inCols ? r : null;
}

function hidePropsChartTooltip() {
  propsChartTooltipPinned = false;
  propsChartTipLastKey = "";
  propsChartStickyHitIndex = -1;
  const tip = document.getElementById("props-chart-tooltip");
  if (tip) tip.hidden = true;
}

function propsTrendStatDisplayLabel(statKey) {
  const sel = document.getElementById("prop-stat");
  const opt = sel?.selectedOptions?.[0];
  const fromDom = String(opt?.textContent || "").trim();
  if (fromDom) return fromDom;
  return ouMarketKeyFromStatKey(statKey);
}

/** Year or span of years for chart tooltips (respects year filter when set). */
function propsChartYearLabelFromRows(rows) {
  const fy = selectedPropsYearFilter();
  if (Number.isFinite(fy)) return String(fy);
  const years = [];
  for (const r of rows || []) {
    const y = historyRoundSeasonYear(r);
    if (Number.isFinite(y)) years.push(y);
  }
  if (!years.length) return "All years";
  const min = Math.min(...years);
  const max = Math.max(...years);
  return min === max ? String(min) : `${min}–${max}`;
}

function propsChartHitYearLabel(hit) {
  const stored = String(hit?._yearLabel || "").trim();
  if (stored) return stored;
  const fy = selectedPropsYearFilter();
  if (Number.isFinite(fy)) return String(fy);
  const y = historyRoundSeasonYear(hit?._hist);
  return Number.isFinite(y) ? String(y) : "—";
}

function propsTipSetRowLabel(rowEl, label) {
  const strong = rowEl?.querySelector?.("strong");
  if (strong) strong.textContent = label;
}

function ensurePropsChartTooltipNodes(tip) {
  if (propsChartTipNodes?.stat) return propsChartTipNodes;
  propsChartTipNodes = null;
  tip.replaceChildren();
  const mk = (label) => {
    const div = document.createElement("div");
    div.className = "props-tip-row";
    const lb = document.createElement("strong");
    lb.textContent = label;
    const val = document.createElement("span");
    val.className = "props-tip-value";
    div.appendChild(lb);
    div.appendChild(val);
    tip.appendChild(div);
    return { row: div, val };
  };
  const date = mk("Date");
  const round = mk("Round");
  const golfer = mk("Golfer");
  const stat = mk("Stat");
  const year = mk("Year");
  const value = mk("Value");
  const course = mk("Course");
  propsChartTipNodes = {
    date: date.val,
    round: round.val,
    golfer: golfer.val,
    stat: stat.val,
    year: year.val,
    value: value.val,
    course: course.val,
    dateRow: date.row,
    roundRow: round.row,
    golferRow: golfer.row,
    statRow: stat.row,
    yearRow: year.row,
    valueRow: value.row,
    courseRow: course.row,
  };
  return propsChartTipNodes;
}

function propsChartFormatValue(statKey, v, opts = {}) {
  if (!Number.isFinite(v)) return "—";
  if (opts.aggregateAvg) {
    if (propsStatIsPct(statKey)) return `${v.toFixed(1)}%`;
    if (propsStatIsSg(statKey)) return v >= 0 ? `+${v.toFixed(2)}` : v.toFixed(2);
    return v.toFixed(1);
  }
  if (propsStatIsPct(statKey)) return `${v.toFixed(1)}%`;
  if (propsStatIsSg(statKey)) return v >= 0 ? `+${v.toFixed(2)}` : v.toFixed(2);
  if (
    statKey === "total" ||
    statKey === "birdies" ||
    statKey === "pars" ||
    statKey === "bogeys" ||
    statKey === "gir" ||
    statKey === "fairways" ||
    statKey === "putts"
  ) {
    return String(Math.round(v));
  }
  return v.toFixed(1);
}

/**
 * Map pointer to chart coordinates. Drawing + hit regions use logical CSS pixels (0..clientWidth)
 * after setTransform(dpr); bitmap width/height are dpr × logical — do not use canvas.width here.
 */
function canvasCoordsFromEvent(canvas, ev) {
  const rect = canvas.getBoundingClientRect();
  const lw = canvas.clientWidth || rect.width;
  const lh = canvas.clientHeight || rect.height;
  if (rect.width <= 0 || rect.height <= 0) return { x: 0, y: 0 };
  return {
    x: ((ev.clientX - rect.left) / rect.width) * lw,
    y: ((ev.clientY - rect.top) / rect.height) * lh,
  };
}

function showPropsChartTooltip(canvas, ev, hit) {
  const wrap = canvas.closest(".props-trends-chart-wrap");
  const tip = document.getElementById("props-chart-tooltip");
  if (!wrap || !tip) return;
  const avgN = Math.round(num(hit._golferAvgRounds, NaN));
  const aggregateAvg = Boolean(hit._aggregate) && avgN > 1;
  const tipKey = `${Math.round(num(hit.dgId, -1))}|${hit.statKey}|${hit.actual}|${aggregateAvg ? "avg" : `R${hit.roundNum ?? ""}`}|${hit._yearLabel || ""}`;
  const nodes = ensurePropsChartTooltipNodes(tip);
  const contentChanged = tipKey !== propsChartTipLastKey;
  if (contentChanged) {
    propsChartTipLastKey = tipKey;
    const courseKey = propsEffectiveCourseKey();
    const rnd = Math.round(num(hit.roundNum, NaN));
    const statLabel = propsTrendStatDisplayLabel(hit.statKey);
    const yearLabel = propsChartHitYearLabel(hit);

    if (nodes.dateRow) {
      nodes.date.textContent = hit.date || "—";
      nodes.dateRow.hidden = aggregateAvg || !(String(hit.date || "").trim());
    }
    if (nodes.roundRow) {
      nodes.round.textContent = Number.isFinite(rnd) && rnd >= 1 && rnd <= 4 ? `R${rnd}` : "—";
      nodes.roundRow.hidden = aggregateAvg || !(Number.isFinite(rnd) && rnd >= 1 && rnd <= 4);
    }
    if (nodes.golferRow) {
      nodes.golfer.textContent = hit.playerName || "—";
      nodes.golferRow.hidden = !hit.playerName;
    }
    if (nodes.statRow) {
      nodes.stat.textContent = statLabel;
      nodes.statRow.hidden = false;
    }
    if (nodes.yearRow) {
      nodes.year.textContent = yearLabel;
      nodes.yearRow.hidden = false;
    }
    if (nodes.valueRow) {
      propsTipSetRowLabel(nodes.valueRow, aggregateAvg ? "Average" : "Value");
      nodes.value.textContent = propsChartFormatValue(hit.statKey, hit.actual, { aggregateAvg });
    }
    if (nodes.courseRow) {
      const hideCourse = aggregateAvg || (hit._aggregate && !courseKey);
      const courseText = propsChartHitCourseLabel(hit._hist) || hit.courseLabel || propsCourseDisplay(hit);
      if (hideCourse || !courseText) {
        nodes.courseRow.hidden = true;
      } else {
        nodes.course.textContent = courseText;
        nodes.courseRow.hidden = false;
      }
    }
  }
  tip.hidden = false;
  const pad = 12;
  tip.style.position = "fixed";
  tip.style.zIndex = "1200";
  const wrapRect = wrap.getBoundingClientRect();
  const sidebar = document.querySelector(".props-trends-sidebar");
  const sideRect = sidebar?.getBoundingClientRect();
  let left = ev.clientX + pad;
  let top = ev.clientY + pad;
  const tw = tip.offsetWidth || 160;
  const th = tip.offsetHeight || 72;
  const maxRight = sideRect ? sideRect.left - pad : wrapRect.right - pad;
  const minLeft = wrapRect.left + pad;
  const minTop = wrapRect.top + pad;
  const maxBottom = wrapRect.bottom - pad;
  if (left + tw > maxRight) left = ev.clientX - tw - pad;
  if (left + tw > maxRight) left = maxRight - tw;
  if (left < minLeft) left = minLeft;
  if (top + th > maxBottom) top = ev.clientY - th - pad;
  if (top < minTop) top = minTop;
  if (top + th > maxBottom) top = maxBottom - th;
  left = Math.max(pad, Math.min(left, maxRight - tw));
  top = Math.max(pad, Math.min(top, window.innerHeight - th - pad));
  tip.style.left = `${left}px`;
  tip.style.top = `${top}px`;
}

function updatePropsTrendChartHover(canvas, ev) {
  if (ev) propsChartLastPointer = ev;
  if (!canvas || !propsChartHitRegions.length) {
    if (canvas) canvas.style.cursor = "";
    if (!propsChartTooltipPinned) hidePropsChartTooltip();
    return;
  }
  const { x, y } = canvasCoordsFromEvent(canvas, ev || propsChartLastPointer);
  const L = propsChartHoverLayout;
  const inCols =
    L.mode === "golferHorizontal"
      ? L.n > 0 && y >= L.padT && y <= L.padT + L.n * L.slotH
      : L.n > 0 && x >= L.padL && x <= L.padL + L.n * L.slotW;
  const hit = pickPropsChartHit(x, y);
  canvas.style.cursor = hit ? "pointer" : "default";
  if (propsChartTooltipPinned) return;
  if (!hit) {
    if (!inCols) hidePropsChartTooltip();
    return;
  }
  showPropsChartTooltip(canvas, ev || propsChartLastPointer, hit);
}

function refreshPropsChartHoverAfterDraw() {
  const canvas = document.getElementById("props-trend-canvas");
  if (!canvas || !propsChartLastPointer || !propsChartHitRegions.length) return;
  updatePropsTrendChartHover(canvas, propsChartLastPointer);
}

/** Gross round score band for chart (excludes score-to-par and corrupt rows). */
function propsChartGrossScoreBounds() {
  const par = Math.round(num(DATA?.meta?.course_par_18, NaN)) || 70;
  return { par, lo: par - 14, hi: par + 22 };
}

function propsChartNormalizeActual(statKey, s) {
  const v = num(s?.actual, NaN);
  if (!Number.isFinite(v)) return NaN;
  if (statKey !== "total") return v;
  const par =
    Math.round(num(s?._hist?.course_par, NaN)) ||
    Math.round(num(DATA?.meta?.course_par_18, NaN)) ||
    70;
  if (v >= par - 14 && v <= par + 24) return v;
  if (v > -14 && v < 22) return par + v;
  if (v >= 50 && v <= 99) return v;
  return NaN;
}

function propsChartPlotSeries(series, statKey) {
  const out = [];
  for (const s of series || []) {
    const actual = propsChartNormalizeActual(statKey, s);
    if (!Number.isFinite(actual)) continue;
    out.push({ ...s, actual });
  }
  return out;
}

/** Y-axis ticks: integers for round score / counting stats so grid lines match numeric labels. */
function propsChartYTickValues(minV, maxV, statKey) {
  const intLike =
    statKey === "total" ||
    statKey === "birdies" ||
    statKey === "pars" ||
    statKey === "bogeys" ||
    statKey === "gir" ||
    statKey === "fairways" ||
    statKey === "putts";
  if (!intLike) {
    const n = 5;
    const out = [];
    for (let g = 0; g <= n; g++) out.push(minV + ((maxV - minV) * g) / n);
    return out;
  }
  const lo = Math.floor(minV);
  const hi = Math.ceil(maxV);
  if (hi <= lo) return [lo, hi + 1];
  const span = hi - lo;
  let step;
  if (statKey === "total") {
    step = span <= 5 ? 1 : span <= 11 ? 2 : span <= 18 ? 3 : 4;
  } else {
    step = Math.max(1, Math.round(span / 5));
    if (step === 3 && span >= 18) step = 4;
  }
  const ticks = [];
  for (let t = Math.ceil(lo / step) * step; t <= hi; t += step) ticks.push(t);
  if (!ticks.length) return [lo, hi];
  if (statKey !== "total") {
    if (ticks[0] > lo) ticks.unshift(lo);
    if (ticks[ticks.length - 1] < hi) ticks.push(hi);
  } else if (ticks[0] > minV + 0.01) ticks.unshift(Math.round(minV));
  if (ticks[ticks.length - 1] < maxV - 0.01) ticks.push(Math.round(maxV));
  return [...new Set(ticks)].sort((a, b) => a - b);
}

/** Y-domain for props trend chart — tight to data min/max so bars use the plot height. */
function propsChartYDomain(vals, lineY, statKey, avgY) {
  let domainVals = vals.filter(Number.isFinite);
  if (!domainVals.length) return { minV: 0, maxV: 1 };
  if (statKey === "total") {
    const { lo, hi } = propsChartGrossScoreBounds();
    const gross = domainVals.filter((v) => v >= lo && v <= hi);
    if (gross.length >= Math.min(8, Math.ceil(domainVals.length * 0.35))) domainVals = gross;
  }
  const dataMin = Math.min(...domainVals);
  const dataMax = Math.max(...domainVals);
  let minV = dataMin;
  let maxV = dataMax;
  if (Number.isFinite(avgY)) {
    minV = Math.min(minV, avgY);
    maxV = Math.max(maxV, avgY);
  }
  if (Number.isFinite(lineY)) {
    if (statKey === "total") {
      const { lo, hi } = propsChartGrossScoreBounds();
      if (lineY >= lo && lineY <= hi) {
        minV = Math.min(minV, lineY);
        maxV = Math.max(maxV, lineY);
      }
    } else {
      minV = Math.min(minV, lineY);
      maxV = Math.max(maxV, lineY);
    }
  }
  const baseRange = Math.max(0.01, maxV - minV);
  if (statKey === "total") {
    const yPad = Math.min(1, Math.max(0.35, baseRange * 0.025));
    minV = Math.floor(minV - yPad);
    maxV = Math.ceil(maxV + yPad);
    const { lo } = propsChartGrossScoreBounds();
    minV = Math.max(lo, minV);
    if (maxV - minV < 3) {
      const mid = (dataMin + dataMax) / 2;
      minV = Math.floor(mid - 1.5);
      maxV = Math.ceil(mid + 1.5);
    }
  } else if (propsStatIsSg(statKey) || propsStatIsPct(statKey)) {
    const minSpan = propsStatIsPct(statKey) ? 20 : 3;
    const yPad = Math.max(0.35, Math.min(1.5, baseRange * 0.12));
    minV -= yPad;
    maxV += yPad;
    if (maxV - minV < minSpan) {
      const mid = (minV + maxV) / 2;
      minV = mid - minSpan / 2;
      maxV = mid + minSpan / 2;
    }
    if (propsStatIsPct(statKey)) minV = Math.max(0, minV);
    if (propsStatIsSg(statKey) && minV > 0 && dataMin >= 0) minV = Math.max(0, minV);
  } else {
    const minSpan = 6;
    const yPad = Math.max(0.75, Math.min(2, baseRange * 0.12));
    minV -= yPad;
    maxV += yPad;
    if (maxV - minV < minSpan) {
      const mid = (minV + maxV) / 2;
      minV = mid - minSpan / 2;
      maxV = mid + minSpan / 2;
    }
    minV = Math.max(0, minV);
    minV = Math.floor(minV);
    maxV = Math.ceil(maxV);
  }
  if (minV === maxV) {
    minV -= 1;
    maxV += 1;
  }
  return { minV, maxV };
}

function propsChartTickLabel(statKey, v) {
  const intLike =
    statKey === "total" ||
    statKey === "birdies" ||
    statKey === "pars" ||
    statKey === "bogeys" ||
    statKey === "gir" ||
    statKey === "fairways" ||
    statKey === "putts";
  if (propsStatIsPct(statKey)) return `${Math.round(v)}%`;
  if (propsStatIsSg(statKey)) {
    const s = Math.abs(v - Math.round(v)) < 0.05 ? String(Math.round(v)) : v.toFixed(1);
    return v > 0 ? `+${s}` : s;
  }
  if (intLike) return String(Math.round(v));
  return Math.abs(v - Math.round(v)) < 0.05 ? String(Math.round(v)) : String(Number(v.toFixed(1)));
}

/** Match CSS layout box to bitmap aspect ratio (avoids non-uniform scaling from height:auto + max-height). */
function syncPropsTrendCanvasCssBox(canvas, cssW, cssH) {
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  canvas.style.maxWidth = "100%";
  canvas.style.boxSizing = "border-box";
}

/** Horizontal bars: golfer on Y, stat value on X (field average mode). */
function drawPropsTrendCanvasGolferHorizontal(series, lineY, statKey, opts = {}) {
  const showGolferLabels = opts.showGolferLabels !== false;
  const plot = propsChartPlotSeries(series, statKey);
  propsChartHitRegions = [];
  propsChartHoverLayout = { mode: "golferHorizontal", padT: 0, slotH: 0, n: 0, padL: 0, innerW: 0 };
  const canvas = document.getElementById("props-trend-canvas");
  const wrap = canvas?.closest(".props-trends-chart-wrap");
  if (!canvas || !canvas.getContext) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const vhCap = typeof window !== "undefined" ? Math.min(520, Math.round(window.innerHeight * 0.48)) : 520;

  function paintEmptyBackground(cssW0, cssH0) {
    canvas.width = Math.round(cssW0 * dpr);
    canvas.height = Math.round(cssH0 * dpr);
    syncPropsTrendCanvasCssBox(canvas, cssW0, cssH0);
    const c0 = canvas.getContext("2d");
    if (!c0) return;
    c0.setTransform(dpr, 0, 0, dpr, 0, 0);
    c0.clearRect(0, 0, cssW0, cssH0);
    c0.fillStyle = "#0a0c0f";
    c0.fillRect(0, 0, cssW0, cssH0);
  }

  if (!plot.length) {
    const vis = wrap && wrap.clientWidth > 80 ? wrap.clientWidth - 28 : 800;
    paintEmptyBackground(vis, Math.round(clamp(vis * 0.42, 240, vhCap)));
    propsChartCache = { series: plot, lineY, statKey, xAxisMode: "golferHorizontal" };
    return;
  }

  const vals = plot.map((s) => s.actual);
  const graphMean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  const n = plot.length;
  const visibleW = wrap && wrap.clientWidth > 80 ? wrap.clientWidth - 28 : 400;
  const labelW = showGolferLabels
    ? Math.min(148, Math.max(88, ...plot.map((s) => propsChartGolferLabelShort(s.playerName).length * 6.5)))
    : 12;
  const pad = { l: Math.round(labelW + 12), r: 16, t: 14, b: 44 };
  const innerW = Math.max(80, visibleW - pad.l - pad.r);
  const rowH = clamp(36, 44, 52);
  const cssW = Math.round(visibleW);
  const cssH = Math.round(clamp(pad.t + pad.b + n * rowH, 220, Math.min(n * rowH + pad.t + pad.b + 40, vhCap)));
  syncPropsTrendCanvasCssBox(canvas, cssW, cssH);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const w = cssW;
  const h = cssH;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#0a0c0f";
  ctx.fillRect(0, 0, w, h);

  const yDom = propsChartYDomain(vals, NaN, statKey, graphMean);
  let minV = yDom.minV;
  let maxV = yDom.maxV;
  const innerH = h - pad.t - pad.b;
  const slotH = innerH / n;
  const lowerBetterX = propsStatLowerIsBetter(statKey);
  propsChartHoverLayout = {
    mode: "golferHorizontal",
    padT: pad.t,
    slotH,
    n,
    padL: pad.l,
    innerW,
    minV,
    maxV,
    lowerBetterX,
  };

  function xScale(v) {
    const t = (v - minV) / (maxV - minV);
    return pad.l + innerW * (lowerBetterX ? 1 - t : t);
  }

  const xBase = lowerBetterX ? xScale(maxV) : xScale(minV);
  const xTicks = propsChartYTickValues(minV, maxV, statKey);
  ctx.strokeStyle = "rgba(255, 255, 255, 0.07)";
  ctx.lineWidth = 1;
  for (const tv of xTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    const x = xScale(tv);
    ctx.beginPath();
    ctx.moveTo(x, pad.t);
    ctx.lineTo(x, h - pad.b);
    ctx.stroke();
  }
  ctx.strokeStyle = "#2b2e36";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad.l, pad.t);
  ctx.lineTo(pad.l, h - pad.b);
  ctx.lineTo(w - pad.r, h - pad.b);
  ctx.stroke();

  const barFrac = 0.62;
  const courseKey = propsEffectiveCourseKey();
  for (let i = 0; i < n; i++) {
    const v = plot[i].actual;
    const ySlotTop = pad.t + i * slotH;
    const bh = Math.max(8, slotH * barFrac);
    const yc = ySlotTop + slotH / 2;
    const y0 = yc - bh / 2;
    const xEnd = xScale(v);
    const x0 = Math.min(xBase, xEnd);
    const barW = Math.max(2, Math.abs(xEnd - xBase));
    const hist = plot[i]._hist;
    const rnd =
      Number.isFinite(plot[i].roundNum) && plot[i].roundNum >= 1
        ? plot[i].roundNum
        : Math.round(num(hist?.round_num, NaN));
    propsChartHitRegions.push({
      x0: pad.l,
      y0: ySlotTop,
      w: innerW,
      h: slotH,
      _hist: hist,
      _aggregate: Boolean(plot[i]._aggregate),
      _golferAvgRounds: plot[i]._golferAvgRounds,
      _yearLabel: plot[i]._yearLabel,
      date: String(plot[i].date || "").trim() || "—",
      playerName: String(plot[i].playerName || "").trim(),
      dgId: plot[i].dgId,
      roundNum: Number.isFinite(rnd) && rnd >= 1 && rnd <= 4 ? rnd : NaN,
      courseLabel: propsChartHitCourseLabel(hist),
      actual: v,
      statKey,
    });
    ctx.fillStyle = "#00c46b";
    ctx.fillRect(Math.round(x0), Math.round(y0), Math.round(barW), Math.round(bh));
    ctx.strokeStyle = "rgba(0,0,0,0.35)";
    ctx.lineWidth = 1;
    ctx.strokeRect(Math.round(x0) + 0.5, Math.round(y0) + 0.5, Math.round(barW) - 1, Math.round(bh) - 1);
    if (showGolferLabels) {
      ctx.fillStyle = "#c8cad2";
      ctx.font = "11px DM Sans, sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      ctx.fillText(propsChartGolferLabelShort(plot[i].playerName), pad.l - 8, yc);
    }
  }

  ctx.fillStyle = "#8b8f9c";
  ctx.font = "9px DM Sans, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  for (const tv of xTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    ctx.fillText(propsChartTickLabel(statKey, tv), xScale(tv), h - pad.b + 6);
  }
  ctx.textAlign = "left";
  propsChartCache = { series: plot, lineY, statKey, xAxisMode: "golferHorizontal" };
  refreshPropsChartHoverAfterDraw();
}

/** `series` items: `{ actual, date?, _hist? }` — `_hist` is raw round row (course_name, …). */
function drawPropsTrendCanvas(series, lineY, statKey, opts = {}) {
  if (opts.xAxisMode === "golferHorizontal") {
    drawPropsTrendCanvasGolferHorizontal(series, lineY, statKey, opts);
    return;
  }
  const xAxisMode = opts.xAxisMode === "valueSort" ? "valueSort" : opts.xAxisMode === "golferNames" || opts.xAxisMode === "golferDense" ? opts.xAxisMode : "chrono";
  const plot = propsChartPlotSeries(series, statKey);
  propsChartHitRegions = [];
  propsChartHoverLayout = { padL: 0, slotW: 0, n: 0 };
  const canvas = document.getElementById("props-trend-canvas");
  const wrap = canvas?.closest(".props-trends-chart-wrap");
  if (!canvas || !canvas.getContext) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const vhCap = typeof window !== "undefined" ? Math.min(480, Math.round(window.innerHeight * 0.42)) : 480;

  function paintEmptyBackground(cssW0, cssH0) {
    canvas.width = Math.round(cssW0 * dpr);
    canvas.height = Math.round(cssH0 * dpr);
    syncPropsTrendCanvasCssBox(canvas, cssW0, cssH0);
    const c0 = canvas.getContext("2d");
    if (!c0) return;
    c0.setTransform(dpr, 0, 0, dpr, 0, 0);
    c0.clearRect(0, 0, cssW0, cssH0);
    c0.fillStyle = "#0a0c0f";
    c0.fillRect(0, 0, cssW0, cssH0);
  }

  if (!plot.length) {
    const vis = wrap && wrap.clientWidth > 80 ? wrap.clientWidth - 28 : 800;
    const cssH0 = Math.round(clamp(vis * 0.48, 240, Math.min(420, vhCap)));
    paintEmptyBackground(vis, cssH0);
    propsChartCache = { series: plot, lineY, statKey };
    return;
  }
  const vals = plot.map((s) => s.actual);
  const graphMean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;

  const n = plot.length;
  const visibleW = wrap && wrap.clientWidth > 80 ? wrap.clientWidth - 28 : 400;
  const golferNameLabels = xAxisMode === "golferNames";
  const golferDenseLabels = xAxisMode === "golferDense";
  const denseXLabels = golferNameLabels ? n > 10 : n > 20;
  const pad = {
    l: 44,
    r: 14,
    t: 14,
    b: golferNameLabels ? (n > 10 ? 72 : 56) : denseXLabels ? 64 : n > 12 ? 56 : 48,
  };
  const innerW = Math.max(80, visibleW - pad.l - pad.r);
  const cssW = Math.round(visibleW);
  const cssH = Math.round(
    clamp(visibleW * (n > 200 ? 0.58 : 0.5), n > 200 ? 320 : 260, Math.min(n > 200 ? 520 : 480, vhCap)),
  );
  syncPropsTrendCanvasCssBox(canvas, cssW, cssH);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const w = cssW;
  const h = cssH;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#0a0c0f";
  ctx.fillRect(0, 0, w, h);

  const yDom = propsChartYDomain(vals, lineY, statKey, graphMean);
  let minV = yDom.minV;
  let maxV = yDom.maxV;
  const innerH = h - pad.t - pad.b;
  /** Numeric axis: smallest value at bottom of chart, largest at top (standard scale). */
  function yScale(v) {
    const t = (v - minV) / (maxV - minV);
    return pad.t + innerH * (1 - t);
  }
  const yBase = yScale(minV);
  const yTicks = propsChartYTickValues(minV, maxV, statKey);
  ctx.strokeStyle = "rgba(255, 255, 255, 0.07)";
  ctx.lineWidth = 1;
  for (const tv of yTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    const y = yScale(tv);
    ctx.beginPath();
    ctx.moveTo(pad.l, y);
    ctx.lineTo(w - pad.r, y);
    ctx.stroke();
  }
  ctx.strokeStyle = "#2b2e36";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad.l, pad.t);
  ctx.lineTo(pad.l, h - pad.b);
  ctx.lineTo(w - pad.r, h - pad.b);
  ctx.stroke();
  const slotW = innerW / n;
  propsChartHoverLayout = { padL: pad.l, slotW, n };
  const xAxisPerBar = golferNameLabels
    ? plot.map((s) => propsChartGolferLabelShort(s.playerName))
    : golferDenseLabels
      ? plot.map(() => "")
      : buildPropsTrendXAxisLabels(plot);
  const { xCenter, barW } = propsChartBarLayout(plot, pad.l, innerW);
  const lowerIsBetter = propsStatLowerIsBetter(statKey);
  for (let i = 0; i < n; i++) {
    const v = plot[i].actual;
    const bw = barW[i];
    const xc = xCenter[i];
    const x0 = Math.max(pad.l, Math.min(xc - bw / 2, pad.l + innerW - bw));
    const yTop = yScale(v);
    const hBar = Math.max(1, yBase - yTop);
    const slotLeft = pad.l + i * slotW;
    const hist = plot[i]._hist;
    const rnd =
      Number.isFinite(plot[i].roundNum) && plot[i].roundNum >= 1
        ? plot[i].roundNum
        : Math.round(num(hist?.round_num, NaN));
    propsChartHitRegions.push({
      x0: slotLeft,
      y0: pad.t,
      w: Math.max(1, slotW),
      h: yBase - pad.t,
      _hist: hist,
      _aggregate: Boolean(plot[i]._aggregate),
      _golferAvgRounds: plot[i]._golferAvgRounds,
      _yearLabel: plot[i]._yearLabel,
      date: String(plot[i].date || "").trim() || "—",
      playerName: String(plot[i].playerName || "").trim(),
      dgId: plot[i].dgId,
      roundNum: Number.isFinite(rnd) && rnd >= 1 && rnd <= 4 ? rnd : NaN,
      courseLabel: propsChartHitCourseLabel(hist),
      actual: v,
      statKey,
    });
    let fill = "#00c46b";
    const cmpLine = Number.isFinite(lineY) ? lineY : graphMean;
    if (Number.isFinite(cmpLine)) {
      if (lowerIsBetter) {
        if (v < cmpLine) fill = "#00c46b";
        else if (v > cmpLine) fill = "#ff4d4f";
        else fill = "#8b8f9c";
      } else {
        if (v > cmpLine) fill = "#00c46b";
        else if (v < cmpLine) fill = "#ff4d4f";
        else fill = "#8b8f9c";
      }
    }
    ctx.fillStyle = fill;
    ctx.fillRect(Math.round(x0), yTop, Math.round(bw), hBar);
    ctx.strokeStyle = "rgba(0,0,0,0.35)";
    ctx.lineWidth = 1;
    ctx.strokeRect(Math.round(x0) + 0.5, yTop + 0.5, Math.round(bw) - 1, hBar - 1);
  }
  /* Draw reference line + pill on top of bars (spans bar region; defaults to graph avg). */
  const refLineY = Number.isFinite(lineY) ? lineY : graphMean;
  if (Number.isFinite(refLineY) && n > 0) {
    const yL = yScale(refLineY);
    const lineX0 = xCenter[0] != null ? Math.max(pad.l, xCenter[0] - barW[0] / 2) : pad.l;
    const lineX1 =
      xCenter[n - 1] != null
        ? Math.min(w - pad.r, xCenter[n - 1] + barW[n - 1] / 2)
        : w - pad.r;
    ctx.strokeStyle = "#f5a623";
    ctx.lineWidth = 2;
    ctx.setLineDash([]);
    ctx.beginPath();
    ctx.moveTo(lineX0, yL);
    ctx.lineTo(lineX1, yL);
    ctx.stroke();
    const lineLbl = formatPropLineChartLabel(statKey, refLineY);
    ctx.font = "bold 10px DM Sans, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const padX = 6;
    const tw = ctx.measureText(lineLbl).width + padX * 2;
    const bh = 16;
    const bx = Math.max(pad.l + 4, lineX0 + 4);
    const by = yL - bh / 2;
    ctx.fillStyle = "#f5a623";
    ctx.beginPath();
    if (typeof ctx.roundRect === "function") ctx.roundRect(bx, by, tw, bh, 4);
    else ctx.rect(bx, by, tw, bh);
    ctx.fill();
    ctx.fillStyle = "#0a0c0f";
    ctx.fillText(lineLbl, bx + padX, yL);
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
  }
  ctx.fillStyle = "#8b8f9c";
  ctx.font = "9px DM Sans, sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  for (const tv of yTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    const y = yScale(tv);
    ctx.fillText(propsChartTickLabel(statKey, tv), 5, y);
  }
  ctx.textBaseline = "alphabetic";
  const xLabFont = n > 36 ? 10 : 12;
  ctx.font = `${xLabFont}px DM Sans, sans-serif`;
  ctx.textAlign = "center";
  ctx.fillStyle = "#9ca0ac";
  if (golferNameLabels) {
    const yLab = n > 10 ? h - 24 : h - 10;
    for (let i = 0; i < n; i++) {
      const lab = String(xAxisPerBar[i] || "").trim();
      if (!lab) continue;
      const cx = xCenter[i] != null ? xCenter[i] : pad.l + innerW / 2;
      if (n > 10) {
        ctx.save();
        ctx.translate(cx, yLab);
        ctx.rotate(-Math.PI / 6);
        ctx.textAlign = "right";
        ctx.fillText(lab, 0, 0);
        ctx.restore();
        ctx.textAlign = "center";
      } else {
        ctx.fillText(lab, cx, yLab);
      }
    }
  } else if (xAxisMode === "valueSort") {
    const sessionPlacements = propsChartXAxisValueSortSessionPlacements(xAxisPerBar, xCenter, pad.l, innerW);
    if (sessionPlacements.length > 1 && sessionPlacements.length <= 14) {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.06)";
      ctx.lineWidth = 1;
      for (let i = 1; i < sessionPlacements.length; i++) {
        const x = sessionPlacements[i].cx - (sessionPlacements[i].cx - sessionPlacements[i - 1].cx) / 2;
        ctx.beginPath();
        ctx.moveTo(x, pad.t);
        ctx.lineTo(x, h - pad.b);
        ctx.stroke();
      }
    }
    ctx.fillStyle = "#9ca0ac";
    const yLab = sessionPlacements.length > 8 ? h - 24 : h - 10;
    for (const p of sessionPlacements) {
      if (!p.lab) continue;
      if (sessionPlacements.length > 8) {
        ctx.save();
        ctx.translate(p.cx, yLab);
        ctx.rotate(-Math.PI / 6);
        ctx.textAlign = "right";
        ctx.fillText(p.lab, 0, 0);
        ctx.restore();
        ctx.textAlign = "center";
      } else {
        ctx.fillText(p.lab, p.cx, yLab);
      }
    }
  } else if (!golferDenseLabels) {
    const tickMap = propsChartXAxisDateLabels(xAxisPerBar, innerW, { xAxisMode });
    const yLab = denseXLabels ? h - 24 : h - 10;
    for (const [i, lab] of tickMap.entries()) {
      if (!lab) continue;
      const cx = xCenter[i] != null ? xCenter[i] : pad.l + innerW / 2;
      if (denseXLabels) {
        ctx.save();
        ctx.translate(cx, yLab);
        ctx.rotate(-Math.PI / 6);
        ctx.textAlign = "right";
        ctx.fillText(lab, 0, 0);
        ctx.restore();
        ctx.textAlign = "center";
      } else {
        ctx.fillText(lab, cx, yLab);
      }
    }
  }
  ctx.textAlign = "left";
  propsChartCache = { series: plot, lineY, statKey };
  refreshPropsChartHoverAfterDraw();
}

function syncPropsCourseWindowUiState() {
  const modeOn = propsCourseWindowModeOn();
  const on = propsCourseWindowModeActive();
  const hdr = document.getElementById("props-trends-header");
  if (hdr) hdr.classList.toggle("props-course-window-active", on);
  const topGolfer = document.querySelector(".props-trends-top-golfer");
  if (topGolfer) topGolfer.hidden = modeOn;
  const golferSearch = document.getElementById("prop-golfer-search");
  if (golferSearch) golferSearch.disabled = modeOn;
  const roundsStepper = document.querySelector(".props-chart-steppers .props-stepper-block");
  if (roundsStepper) roundsStepper.hidden = modeOn;
  const topRounds = document.querySelector(".props-trends-top-rounds");
  if (topRounds) topRounds.classList.toggle("props-trends-top-rounds-field", modeOn);
  if (!modeOn) propsCourseWindowLiveMergeAttempted = false;
  syncPropsAverageUiState();
}

/** Run Historical Trends immediately (cancels any pending debounced pass). */
function renderPropsTrendsNow() {
  window.clearTimeout(propsTrendsRenderDebounceT);
  propsTrendsRenderDebounceT = 0;
  renderPropsTrends();
}

/** Debounce Historical Trends rebuilds so typing line/filters does not rescan the full field every keystroke. */
function scheduleRenderPropsTrends(ms = 280) {
  window.clearTimeout(propsTrendsRenderDebounceT);
  propsTrendsRenderDebounceT = window.setTimeout(() => {
    propsTrendsRenderDebounceT = 0;
    renderPropsTrends();
  }, ms);
}

function paintPropsCourseWindowBuilding(message) {
  const empty = document.getElementById("props-chart-empty");
  if (empty) {
    empty.hidden = false;
    empty.textContent = message;
  }
}

function propsCourseShardLoadInFlight(courseKey) {
  return Boolean(
    courseKey && propsSingleCourseIndexPromise && propsSingleCourseIndexCourseKey === courseKey,
  );
}

function propsCourseWindowStructureContextKey() {
  const fromRaw = String(document.getElementById("props-filter-date-from")?.value || "").trim();
  const toRaw = String(document.getElementById("props-filter-date-to")?.value || "").trim();
  return [
    propsCourseWindowModeOn() ? 1 : 0,
    propsEffectiveCourseKey() || "all",
    fromRaw,
    toRaw,
    propsFilterDraftKingsOnlyOn() ? 1 : 0,
    statKeyFromPropSelect(),
    Number.isFinite(propsFieldEffectiveSeasonYear()) ? String(propsFieldEffectiveSeasonYear()) : "all",
  ].join("|");
}

function invalidateCourseWindowRoundEntriesCache() {
  courseWindowRoundEntriesCache = null;
  courseWindowRoundEntriesCacheSig = "";
  courseWindowRoundEntriesRawCache = null;
  courseWindowRoundEntriesRawCacheSig = "";
  propsFieldUncappedAggregateSeries = null;
  propsFieldUncappedEntriesAll = null;
  propsFieldPlayerCapOnlyRender = false;
}

/** Filter-only pass: reuse loaded history and course index (no dropdown rebuild / history restart). */
function renderPropsTrendsCourseWindowQuick() {
  const gen = propsCourseWindowRenderGen;
  const courseKey = propsEffectiveCourseKey();
  const bucket = courseKey ? propsGetSingleCourseBucketSync(courseKey) : null;
  if (propsFilterDraftKingsOnlyOn()) {
    void ensureDkAuditPropsIndexLoaded().then(() => {
      if (gen !== propsCourseWindowRenderGen || activeAppTabId() !== "props") return;
      renderPropsTrendsCourseWindowBody(gen, bucket);
    });
    return;
  }
  renderPropsTrendsCourseWindowBody(gen, bucket);
}

function renderPropsTrendsCourseWindow() {
  ensurePropsStatSelectValid();
  const gen = ++propsCourseWindowRenderGen;
  propsCourseWindowLastEntries = null;
  propsFieldUncappedAggregateSeries = null;
  propsFieldUncappedEntriesAll = null;
  propsFieldPlayerCapOnlyRender = false;
  syncPropsCourseWindowUiState();
  refreshPropsCourseFilterOptionsAllPlayers();
  if (ensurePropsCourseSelectedForWindow()) invalidateCourseWindowRoundEntriesCache();
  propsCourseWindowStructureKey = propsCourseWindowStructureContextKey();
  propsSanitizeFieldDateFilters();
  ensurePropsFieldYearDefault();
  syncPropsWindowNDefault();
  void loadPropsCoursesManifest();

  const courseKey = propsEffectiveCourseKey();
  const paintBody = (bucket) => {
    if (propsFilterDraftKingsOnlyOn()) {
      void ensureDkAuditPropsIndexLoaded().then(() => {
        if (gen !== propsCourseWindowRenderGen || activeAppTabId() !== "props") return;
        renderPropsTrendsCourseWindowBody(gen, bucket);
      });
      return;
    }
    renderPropsTrendsCourseWindowBody(gen, bucket);
  };

  if (!courseKey) {
    const fieldIds = [...propsFieldPlayerDgIds()];
    const seasonYear = selectedPropsYearFilter();
    const loadYear = Number.isFinite(seasonYear) ? seasonYear : NaN;
    const bucketReady = (id) =>
      Number.isFinite(loadYear) ? historyBucketReadyForFieldSeason(id, loadYear) : historyBucketLoaded(id);
    const readyCount = fieldIds.filter((id) => bucketReady(id)).length;
    const allReady = !fieldIds.length || readyCount >= fieldIds.length;

    if (!allReady && activeAppTabId() === "props") {
      const loadGen = ++propsFieldHistoryLoadGen;
      if (readyCount === 0) {
        paintPropsCourseWindowBuilding(
          Number.isFinite(loadYear)
            ? `Loading ${loadYear} field history…`
            : "Loading this week's field history…",
        );
      }
      void ensurePropsFieldPlayerHistoryLoaded({
        gen: loadGen,
        seasonYear: loadYear,
        onBatch: () => {
          if (loadGen !== propsFieldHistoryLoadGen || gen !== propsCourseWindowRenderGen) return;
          if (activeAppTabId() !== "props") return;
          invalidateCourseWindowRoundEntriesCache();
          window.clearTimeout(propsFieldHistoryBatchRenderT);
          propsFieldHistoryBatchRenderT = window.setTimeout(() => {
            propsFieldHistoryBatchRenderT = 0;
            scheduleRenderPropsTrends(80);
          }, 220);
        },
      }).then(() => {
        if (loadGen !== propsFieldHistoryLoadGen || gen !== propsCourseWindowRenderGen) return;
        if (activeAppTabId() !== "props") return;
        invalidateCourseWindowRoundEntriesCache();
        paintBody(null);
      });
      return;
    }
    paintBody(null);
    return;
  }

  const cached = propsGetSingleCourseBucketSync(courseKey);
  if (cached?.entries?.length) {
    paintBody(cached);
    return;
  }

  paintPropsCourseWindowBuilding("Loading all players at this course…");
  void ensurePropsCourseIndexForKeyAsync(courseKey).then((bucket) => {
    if (gen !== propsCourseWindowRenderGen || activeAppTabId() !== "props") return;
    invalidateCourseWindowRoundEntriesCache();
    paintBody(bucket);
  });
}

/** Fast repaint when only player cap / sample sort changes (reuse cached field aggregates). */
function renderPropsTrendsCourseWindowCapOnly(gen, statKey) {
  if (gen !== propsCourseWindowRenderGen) return;
  if (!propsFieldUncappedAggregateSeries?.length || !propsFieldUncappedEntriesAll) return;
  const empty = document.getElementById("props-chart-empty");
  if (empty) empty.hidden = true;
  const nWinEl = document.getElementById("props-window-n");
  const winN = clamp(
    Math.round(num(nWinEl?.value, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX,
  );
  if (nWinEl && document.activeElement !== nWinEl) nWinEl.value = String(winN);
  const entriesAll = propsFieldUncappedEntriesAll;
  propsCourseWindowLastEntries = entriesAll;
  const lineInp = document.getElementById("prop-line");
  let line = clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, lineInp?.value));
  if (!Number.isFinite(line)) line = propsTrendLastGoodLine;
  const avgOn = propsFieldAverageChartActive();
  const seriesChart = capFieldGolferSeriesForDisplay(statKey, [...propsFieldUncappedAggregateSeries], winN);
  drawPropsTrendCanvas(seriesChart, NaN, statKey, {
    xAxisMode: "golferHorizontal",
    showGolferLabels: avgOn && winN <= PROPS_FIELD_GOLFER_HORIZONTAL_MAX,
  });
  const chartKpiScope = propsCourseWindowChartKpiScope(seriesChart, entriesAll);
  const hitSt = propsFullHitStatsFromRoundList(statKey, line, chartKpiScope.roundRows, { courseWindow: true });
  paintPropsTrendKpiRowCourseWindow(statKey, hitSt, seriesChart, entriesAll);
  const chartLeg = document.getElementById("props-chart-line-legend");
  if (chartLeg) chartLeg.hidden = true;
}

function renderPropsTrendsCourseWindowBody(gen, courseBucket) {
  if (gen !== propsCourseWindowRenderGen) return;
  const statKey = statKeyFromPropSelect();
  const capOnly = propsFieldPlayerCapOnlyIntent();
  if (capOnly) {
    propsFieldPlayerCapOnlyRender = false;
    renderPropsTrendsCourseWindowCapOnly(gen, statKey);
    return;
  }
  syncPropsCourseWindowUiState();
  const bookWrapClear = document.getElementById("props-trends-book-lines");
  if (bookWrapClear) bookWrapClear.replaceChildren();
  const empty = document.getElementById("props-chart-empty");
  const titleEl = document.getElementById("props-trends-title");
  const flagEl = document.getElementById("props-flag");
  if (propsTopTableSortStatKey !== statKey) {
    propsTopTableSort = { key: "overRate", dir: -1 };
    propsTopTableSortStatKey = statKey;
  }
  const courseKey = propsEffectiveCourseKey();
  const yearFilter = selectedPropsYearFilter();
  const yearSuffix = Number.isFinite(yearFilter) ? ` · ${yearFilter}` : "";
  if (flagEl) flagEl.hidden = true;
  if (titleEl) {
    if (!courseKey) {
      titleEl.textContent = `This week's field · all courses${yearSuffix}`;
    } else {
      titleEl.textContent = `${courseFitPrettyCourseKey(courseKey)}${yearSuffix}`;
    }
  }
  const nWinEl = document.getElementById("props-window-n");
  const winN = clamp(
    Math.round(num(nWinEl?.value, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX,
  );
  if (nWinEl && document.activeElement !== nWinEl) nWinEl.value = String(winN);

  if (!propsCourseWindowModeOn()) {
    if (empty) {
      empty.hidden = false;
      empty.textContent = "Turn on This week's field to chart the projection field.";
    }
    drawPropsTrendCanvas([], NaN, statKey);
    paintPropsTrendsInsightHeader(null, statKey, NaN, { valid: 0, over: 0, under: 0, overRate: NaN, underRate: NaN }, [], NaN);
    const bookWrap = document.getElementById("props-trends-book-lines");
    if (bookWrap) bookWrap.replaceChildren();
    renderPropsHitRateAndTopTable(statKey, NaN, winN);
    return;
  }

  if (!HISTORY._ok) {
    if (empty) {
      empty.hidden = false;
      empty.textContent = HISTORY._loading ? "Loading player history..." : "No history file.";
    }
    drawPropsTrendCanvas([], NaN, statKey);
    renderPropsHitRateAndTopTable(statKey, NaN, winN);
    return;
  }

  if (!isFileProtocol() && !propsCourseWindowLiveMergeAttempted) {
    propsCourseWindowLiveMergeAttempted = true;
    void ensureLiveTournamentHistoryMerged({ useCache: true }).then((n) => {
      if (n > 0 && activeAppTabId() === "props" && propsCourseWindowModeOn()) {
        propsSingleCourseIndexSig = "";
        propsSingleCourseIndexCache = null;
        const ck = propsEffectiveCourseKey();
        if (ck) propsCourseRoundIndex.delete(ck);
        invalidateCourseWindowRoundEntriesCache();
        scheduleRenderPropsTrends(0);
      }
    });
  }
  const bookWrapEarly = document.getElementById("props-trends-book-lines");
  if (bookWrapEarly) bookWrapEarly.replaceChildren();
  if (empty) empty.hidden = true;

  const lineInp = document.getElementById("prop-line");
  const ctxKey = propsTrendLineContextKeyFromDom();
  const lineEditing = Boolean(lineInp && document.activeElement === lineInp);
  const dkOnly = propsFilterDraftKingsOnlyOn();
  const avgOn = propsFieldAverageChartActive();
  const entriesRaw = collectCourseWindowRoundEntriesFixed(courseBucket);
  const entriesAll = propsCourseWindowEntriesAfterWindow(entriesRaw, statKey, propsFieldRoundWindowN(winN));
  propsCourseWindowLastEntries = entriesAll;
  let line = clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, lineInp?.value));
  if (lineEditing && !Number.isFinite(line) && Number.isFinite(propsTrendLastGoodLine)) {
    line = propsTrendLastGoodLine;
  }
  if (
    !lineEditing &&
    !propsTrendLineUserOverride &&
    (!Number.isFinite(line) || propsTrendsLineContextKey !== ctxKey)
  ) {
    line = defaultLineForCourseWindow(statKey, entriesAll);
    if (lineInp) lineInp.value = formatPropLineValueForInput(line);
    propsTrendsLineContextKey = ctxKey;
  } else if (!lineEditing && lineInp) {
    lineInp.value = formatPropLineValueForInput(line);
  }
  if (Number.isFinite(line)) propsTrendLastGoodLine = line;

  const useGolferAggregate = propsFieldUseGolferAggregateChart(entriesAll, winN);
  let chartEntries = entriesAll;
  if (!useGolferAggregate) {
    if (chartEntries.length > PROPS_COURSE_WINDOW_MAX_CHART_BARS) {
      chartEntries = sampleCourseWindowChartEntriesEvenly(chartEntries, PROPS_COURSE_WINDOW_MAX_CHART_BARS);
    }
  }

  const nameByDgChart = buildPropsGolferDisplayNameMap();
  let seriesChart = [];
  let chartXAxisMode = "chrono";
  const tailMode = selectedPropsTailMode();

  if (useGolferAggregate) {
    const uncapped = buildFieldGolferAggregateSeries(entriesAll, statKey);
    propsFieldUncappedAggregateSeries = uncapped;
    propsFieldUncappedEntriesAll = entriesAll;
    seriesChart = capFieldGolferSeriesForDisplay(statKey, [...uncapped], winN);
    chartXAxisMode = "golferHorizontal";
  } else {
    const playerRowByDg = new Map(
      roundProjectionPlayersForOuRound()
        .map((p) => [Math.round(num(p.dg_id, NaN)), p])
        .filter(([id]) => Number.isFinite(id)),
    );
    for (const e of chartEntries) {
      const actual = dkOnly
        ? chartActualForDraftKingsCourseWindow(
            statKey,
            e,
            playerRowByDg.get(e.dgId) ||
              projectionPlayerRowForModel(e.dgId, getOuRound()) ||
              DATA.players?.find((p) => Math.round(num(p.dg_id, NaN)) === e.dgId),
          )
        : chartActualForCourseWindowEntry(statKey, e);
      if (!Number.isFinite(actual)) continue;
      const playerName = resolveGolferDisplayNameForDg(e.dgId, e.playerName, nameByDgChart);
      if (!playerName) continue;
      const date =
        e.row?._from_projection_chart && e.row?.chart_session_iso
          ? e.row.chart_session_iso
          : propsTrendChartDateFromRow(e.row);
      seriesChart.push({
        actual,
        date,
        playerName,
        dgId: e.dgId,
        roundNum: Math.round(num(e.row?.round_num, NaN)),
        _hist: e.row?._from_projection_chart ? null : e.row,
        _projection: Boolean(e.row?._from_projection_chart),
      });
    }
    if (tailMode === "best" || tailMode === "worst") {
      sortPropsFieldByCourseSeriesChart(statKey, seriesChart);
      chartXAxisMode = "valueSort";
    }
  }

  if (!seriesChart.length) {
    if (empty) {
      empty.hidden = false;
      const nAll = entriesAll.length;
      if (courseBucket?.shardMissing) {
        empty.textContent =
          "Field-by-course needs player-history/by-course data on the server. Run npm run build:history and redeploy (includes this venue).";
      } else if (dkOnly) {
        const dkField = roundProjectionPlayersForOuRound().filter((p) =>
          propsTrendPlayerHasDraftKingsLine(
            Math.round(num(p.dg_id, NaN)),
            resolveGolferDisplayNameForDg(Math.round(num(p.dg_id, NaN)), p.player_name, buildPropsGolferDisplayNameMap()),
            statKey,
          ),
        ).length;
        if (!draftKingsTournamentPropsAvailable()) {
          empty.textContent = "No DraftKings props loaded for this tournament — load props or turn off the DK filter.";
        } else if (!dkField) {
          empty.textContent = `No round-projection golfers with a DraftKings ${propMarketLabelFromKey(statKey)} line (try Round score, Birdies, GIR, etc.).`;
        } else if (!nAll) {
          empty.textContent =
            "No DraftKings rounds at this course in the selected date range. Widen From/To or turn off the DK filter.";
        } else {
          empty.textContent = `No chartable ${propMarketLabelFromKey(statKey)} values at ${courseFitPrettyCourseKey(courseKey) || "this course"} for ${dkField} DK golfers (try another market or relax weather filters).`;
        }
      } else if (avgOn && useGolferAggregate && nAll > 0) {
        empty.textContent = `No golfers with at least ${PROPS_FIELD_AVERAGE_MIN_ROUNDS} chartable rounds for this filter (relax filters or turn off Average).`;
      } else {
        empty.textContent = nAll
          ? "No chartable stat values for these rounds (try another stat)."
          : courseKey
            ? "No rounds at this course after filters. Widen dates or relax filters."
            : "No rounds for this week's field after filters. Clear From/To dates or relax filters.";
      }
    }
  }

  drawPropsTrendCanvas(
    seriesChart,
    chartXAxisMode === "golferHorizontal" ? NaN : line,
    statKey,
    {
      xAxisMode: chartXAxisMode,
      showGolferLabels: avgOn && winN <= PROPS_FIELD_GOLFER_HORIZONTAL_MAX,
    },
  );
  const chartKpiScope = propsCourseWindowChartKpiScope(seriesChart, entriesAll);
  const hitSt = propsFullHitStatsFromRoundList(statKey, line, chartKpiScope.roundRows, {
    courseWindow: true,
  });
  const bookWrap = document.getElementById("props-trends-book-lines");
  if (bookWrap) bookWrap.replaceChildren();
  paintPropsTrendKpiRowCourseWindow(statKey, hitSt, seriesChart, entriesAll);
  const chartLeg = document.getElementById("props-chart-line-legend");
  if (chartLeg) chartLeg.hidden = chartXAxisMode === "golferHorizontal" || !Number.isFinite(line);
  const hitGen = gen;
  requestAnimationFrame(() => {
    if (hitGen !== propsCourseWindowRenderGen) return;
    renderPropsHitRateAndTopTable(statKey, line, winN, entriesAll);
  });
}

function propsAutoTrendLineForContext(dg, statKey, playerRow) {
  const poolMean = propsTrendMeanActual(statKey, filteredHistoryRounds(dg));
  if (Number.isFinite(poolMean)) {
    return clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, poolMean));
  }
  const rproj = projectionRowForPlayerRound(playerRow?.player_name, getOuRound());
  const fallbackRaw =
    statKey === "total"
      ? num(rproj?.total_score, defaultPropLineForStat(statKey))
      : statKey === "birdies"
        ? birdiesPlusEaglesFromRow(rproj)
        : statKey === "gir" || statKey === "fairways"
          ? (() => {
              const c =
                statKey === "gir"
                  ? girFairwaysCountFromRawForOu(num(rproj?.gir, NaN), 18)
                  : girFairwaysCountFromRawForOu(num(rproj?.fairways, NaN), fairwayHolesModeledFromData());
              return Number.isFinite(c) ? c : defaultPropLineForStat(statKey);
            })()
          : num(rproj?.[statKey === "fairways" ? "fairways" : statKey], defaultPropLineForStat(statKey));
  let line = clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, fallbackRaw));
  if (!Number.isFinite(line)) line = clampPropLineForMarket(statKey, defaultPropLineForStat(statKey));
  return line;
}

function renderPropsTrends() {
  ensurePropsStatSelectValid();
  const fieldChartCapOnly =
    propsCourseWindowModeOn() &&
    propsAverageModeOn() &&
    propsFieldPlayerCapOnlyRender &&
    propsFieldUncappedAggregateSeries?.length &&
    propsFieldUncappedEntriesAll;
  if (!fieldChartCapOnly) ensurePropsRoundWeatherLoadedForTrends();
  syncPropsCourseWindowUiState();
  if (propsFieldVenueKpisEnabled()) ensurePropsFieldVenueHistoryLoaded();
  void ensurePropsDgIdNameManifestLoaded().then((m) => {
    if (!m?.size || activeAppTabId() !== "props" || propsDgIdNameManifestUiRefreshDone) return;
    propsDgIdNameManifestUiRefreshDone = true;
    scheduleRenderPropsTrends(0);
  });
  if (propsCourseWindowModeOn()) {
    const structKey = propsCourseWindowStructureContextKey();
    if (structKey !== propsCourseWindowStructureKey) {
      renderPropsTrendsCourseWindow();
    } else {
      renderPropsTrendsCourseWindowQuick();
    }
    return;
  }
  ensurePropsCourseHistoryForTrendsChart(selectedDgId());
  syncPropsWindowNDefault();
  syncPropsCourseWindowUiState();
  const dg = selectedDgId();
  const empty = document.getElementById("props-chart-empty");
  const titleEl = document.getElementById("props-trends-title");
  refreshPropsFilterOptionsForGolfer(dg);
  const statKey = statKeyFromPropSelect();
  const historyResolved = historyBucketResolved(dg);
  const selectedHistoryMissing = Number.isFinite(dg) && !historyBucketLoaded(dg);
  if (selectedHistoryMissing && historyBucketLoading(dg)) {
    if (empty) {
      empty.hidden = false;
      empty.textContent = "Loading player history...";
    }
    drawPropsTrendCanvas([], NaN, statKey);
    renderPropsHitRateAndTopTable(statKey, NaN, PROPS_HISTORY_ROUND_DEFAULT);
    return;
  }
  if (selectedHistoryMissing && !historyResolved && activeAppTabId() === "props") {
    void ensurePlayerHistoryLoadedForTab("props");
  }
  if (propsTopTableSortStatKey !== statKey) {
    propsTopTableSort = { key: "overRate", dir: -1 };
    propsTopTableSortStatKey = statKey;
  }
  const playerRow =
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg && samePlayerRound(p, 1)) || DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg);
  const flagEl = document.getElementById("props-flag");
  if (flagEl) flagEl.hidden = false;
  if (playerRow) {
    setPropsCountryFlag(playerRow);
    if (titleEl) titleEl.textContent = displayGolferName(playerRow.player_name) || "—";
  } else {
    if (titleEl) titleEl.textContent = "—";
  }
  const historyHasSelectedBucket =
    Number.isFinite(dg) &&
    historyBucketLoaded(dg) &&
    (propsCourseWindowModeOn() || !historyBucketIsSeasonSliceOnly(dg));
  if (
    Number.isFinite(dg) &&
    !propsCourseWindowModeOn() &&
    historyBucketIsSeasonSliceOnly(dg) &&
    !playerHistoryBucketLoadPromises.has(dg)
  ) {
    void ensurePlayerCareerHistoryLoaded(dg).then(() => {
      if (activeAppTabId() === "props") scheduleRenderPropsTrends(0);
    });
  }
  if (!HISTORY._ok || !historyHasSelectedBucket) {
    if (empty) {
      empty.hidden = false;
      const metaHint = String(HISTORY.meta?.note || "").trim();
      const waiting =
        historyBucketLoading(dg) ||
        (!historyResolved && HISTORY._loading && !historyHasSelectedBucket);
      empty.textContent = waiting
        ? "Loading player history..."
        : historyResolved && !historyHasSelectedBucket
        ? "No round history for this player in the export yet."
        : !HISTORY._ok
        ? "No history file."
        : metaHint ||
          "History export has no rounds yet. On Render: set GOLF_HISTORICAL_ROUNDS_FULL_HISTORY=1 (full PGA+LIV merge; slow), or widen GOLF_HISTORICAL_ROUNDS_RECENT_FETCH_YEARS if you use a capped merge — check deploy logs for update-historical-rounds-node / build-player-history. One-shot uncapped repair: GOLF_RENDER_FULL_HISTORICAL_MERGE_IF_EMPTY=1.";
    }
    const wnEarly = clamp(
      Math.round(num(document.getElementById("props-window-n")?.value, PROPS_HISTORY_ROUND_DEFAULT)),
      PROPS_HISTORY_ROUND_MIN,
      PROPS_HISTORY_ROUND_MAX
    );
    const lineInpEarly = document.getElementById("prop-line");
    const ctxKeyEarly = propsTrendLineContextKeyFromDom();
    const lineEditingEarly = Boolean(lineInpEarly && document.activeElement === lineInpEarly);
    let lineEarly = clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, lineInpEarly?.value));
    if (lineEditingEarly && !Number.isFinite(lineEarly) && Number.isFinite(propsTrendLastGoodLine)) {
      lineEarly = propsTrendLastGoodLine;
    }
    if (
      !lineEditingEarly &&
      !propsTrendLineUserOverride &&
      (!Number.isFinite(lineEarly) || propsTrendsLineContextKey !== ctxKeyEarly)
    ) {
      lineEarly = propsAutoTrendLineForContext(dg, statKey, playerRow);
      if (lineInpEarly) lineInpEarly.value = formatPropLineValueForInput(lineEarly);
      propsTrendsLineContextKey = ctxKeyEarly;
    } else if (!lineEditingEarly && lineInpEarly) {
      lineInpEarly.value = formatPropLineValueForInput(lineEarly);
    }
    if (Number.isFinite(lineEarly)) propsTrendLastGoodLine = lineEarly;
    const stEarly = propsFullHitStatsForDg(dg, statKey, lineEarly, wnEarly);
    paintPropsTrendsInsightHeader(playerRow, statKey, lineEarly, stEarly, [], dg);
    const chartLegEarly = document.getElementById("props-chart-line-legend");
    if (chartLegEarly) chartLegEarly.hidden = !Number.isFinite(lineEarly);
    drawPropsTrendCanvas([], lineEarly, statKey);
    renderPropsHitRateAndTopTable(statKey, lineEarly, wnEarly);
    return;
  }
  if (empty) empty.hidden = true;
  if (!isFileProtocol() && !propsTrendsLiveHistoryFetchQueued) {
    propsTrendsLiveHistoryFetchQueued = true;
    window.setTimeout(() => {
      void ensureLiveTournamentHistoryMerged({ useCache: true }).then((n) => {
        propsTrendsLiveHistoryFetchQueued = false;
        if (n > 0 && activeAppTabId() === "props") renderPropsTrends();
      });
    }, 0);
  }
  const nWinEl = document.getElementById("props-window-n");
  const winN = clamp(
    Math.round(num(nWinEl?.value, PROPS_HISTORY_ROUND_DEFAULT)),
    PROPS_HISTORY_ROUND_MIN,
    PROPS_HISTORY_ROUND_MAX
  );
  if (nWinEl && document.activeElement !== nWinEl) nWinEl.value = String(winN);
  const lineInp = document.getElementById("prop-line");
  const ctxKey = propsTrendLineContextKeyFromDom();
  const lineEditing = Boolean(lineInp && document.activeElement === lineInp);
  let line = clampPropLineForMarket(statKey, snapPropLineForMarket(statKey, lineInp?.value));
  if (lineEditing && !Number.isFinite(line) && Number.isFinite(propsTrendLastGoodLine)) {
    line = propsTrendLastGoodLine;
  }
  if (
    !lineEditing &&
    !propsTrendLineUserOverride &&
    (!Number.isFinite(line) || propsTrendsLineContextKey !== ctxKey)
  ) {
    line = propsAutoTrendLineForContext(dg, statKey, playerRow);
    if (lineInp) lineInp.value = formatPropLineValueForInput(line);
    propsTrendsLineContextKey = ctxKey;
  } else if (!lineEditing && lineInp) {
    lineInp.value = formatPropLineValueForInput(line);
  }
  if (Number.isFinite(line)) propsTrendLastGoodLine = line;
  const newestFirst = propsFilteredRoundsNewestFirst(dg, winN);
  const rawList = newestFirst.slice().sort((a, b) => historyRoundChronoKey(a) - historyRoundChronoKey(b));
  const seriesFull = [];
  for (const r of rawList) {
    const actual = actualForRoundRow(statKey, r);
    if (!Number.isFinite(actual)) continue;
    const m = modelForHistoryRow(statKey, { ...r, _playerName: playerRow?.player_name });
    seriesFull.push({
      _hist: r,
      date: propsTrendChartDateFromRow(r),
      course: propsCourseNameFromRow(r),
      actual,
      model: m,
      dif: Number.isFinite(m) ? actual - m : NaN,
    });
  }
  const seriesChartRaw = seriesFull.map((s) => ({
    actual: s.actual,
    date: s.date,
    _hist: s._hist,
    roundNum: Math.round(num(s._hist?.round_num, NaN)),
  }));
  let seriesChart = seriesChartRaw;
  if (selectedPropsTailMode() === "average" && seriesChart.length > 1) {
    const nums = seriesChart.map((s) => s.actual).filter((x) => Number.isFinite(x));
    const avg = nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : NaN;
    const last = seriesChart[seriesChart.length - 1];
    const aggRows = seriesChartRaw.map((s) => s._hist).filter(Boolean);
    seriesChart = [
      {
        actual: avg,
        date: "",
        _hist: last?._hist,
        roundNum: NaN,
        _aggregate: true,
        _golferAvgRounds: nums.length,
        _yearLabel: propsChartYearLabelFromRows(aggRows),
      },
    ];
  }
  if (!seriesChart.length && empty) {
    empty.hidden = false;
    const weatherHint = propsWeatherFilterEmptyMessage(dg);
    empty.textContent =
      weatherHint ||
      (newestFirst.length
        ? "No chartable values for this market in the filtered rounds."
        : "No rounds match the current filters.");
  } else if (empty) {
    empty.hidden = true;
  }
  const tailMode = selectedPropsTailMode();
  let chartXAxisMode = "chrono";
  if (!propsAverageModeOn() && (tailMode === "best" || tailMode === "worst")) {
    sortPropsFieldByCourseSeriesChart(statKey, seriesChart);
    chartXAxisMode = "valueSort";
  }
  drawPropsTrendCanvas(seriesChart, line, statKey, { xAxisMode: chartXAxisMode });
  const stNow = propsFullHitStatsForDg(dg, statKey, line, winN);
  paintPropsTrendsInsightHeader(playerRow, statKey, line, stNow, seriesChart, dg);
  const chartLeg = document.getElementById("props-chart-line-legend");
  if (chartLeg) chartLeg.hidden = !Number.isFinite(line);
  renderPropsHitRateAndTopTable(statKey, line, winN);
}

function updatePropsFooterEv() {
  const box = document.getElementById("ev-props");
  if (!box) return;
  const line = num(document.getElementById("prop-line")?.value, NaN);
  const oAm = num(document.getElementById("prop-over")?.value, NaN);
  const uAm = num(document.getElementById("prop-under")?.value, NaN);
  const dg = selectedDgId();
  const statKey = statKeyFromPropSelect();
  const rEv = getModelRoundForEv();
  const rproj =
    projectionPlayerRowForModel(dg, rEv) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg && samePlayerRound(p, rEv)) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg);
  const marketLabel = ouMarketKeyFromStatKey(statKey);
  const pOver =
    rproj && Number.isFinite(line) ? modelProbOverMarket(marketLabel, rproj, line) : NaN;
  const pUnder = Number.isFinite(pOver) ? 1 - pOver : NaN;
  const dO = decimalFromAmerican(oAm);
  const dU = decimalFromAmerican(uAm);
  const evO = Number.isFinite(pOver) && Number.isFinite(dO) ? pOver * dO - 1 : NaN;
  const evU = Number.isFinite(pUnder) && Number.isFinite(dU) ? pUnder * dU - 1 : NaN;
  let html = "";
  if (Number.isFinite(evO)) html += `<p class="${evO >= 0 ? "ev-pos" : "ev-neg"}">Over EV: ${(evO * 100).toFixed(1)}%</p>`;
  if (Number.isFinite(evU)) html += `<p class="${evU >= 0 ? "ev-pos" : "ev-neg"}">Under EV: ${(evU * 100).toFixed(1)}%</p>`;
  if (!html) html = "<p class=\"text-muted\">Enter odds to see EV.</p>";
  box.innerHTML = html;
}

function updatePropsHoleCard() {
  const courseSel = document.getElementById("props-hole-course");
  const roundSel = document.getElementById("props-hole-round");
  const holeTbody = document.querySelector("#props-hole-table tbody");
  if (!courseSel || !roundSel || !holeTbody) return;
  const dg = selectedDgId();
  const rec = HISTORY.byDgId && HISTORY.byDgId[String(dg)];
  const prow =
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg && samePlayerRound(p, 1)) ||
    DATA.players.find((p) => Math.round(num(p.dg_id, NaN)) === dg);
  const pname = String(rec?.player_name || prow?.player_name || "").trim();
  const pkey = playerKeyFromName(pname);
  const holesMap = (HISTORY.holesByPlayerKey && HISTORY.holesByPlayerKey[pkey]) || {};
  const byCourse = {};
  for (const fullKey of Object.keys(holesMap)) {
    const parts = fullKey.split("\t");
    const cname = (parts[0] || fullKey).trim() || fullKey;
    const rlabel = (parts[1] || "Round").trim();
    if (!byCourse[cname]) byCourse[cname] = [];
    byCourse[cname].push({ fullKey, rlabel });
  }
  const courseNames = Object.keys(byCourse).sort();
  const prevCourse = courseSel.dataset.lastCourse || "";
  const prevRound = roundSel.dataset.lastRound || "";
  courseSel.innerHTML = '<option value="">—</option>';
  for (const c of courseNames) {
    const o = document.createElement("option");
    o.value = c;
    o.textContent = formatCourseNameForDisplay(c);
    courseSel.appendChild(o);
  }
  if (prevCourse && courseNames.includes(prevCourse)) courseSel.value = prevCourse;
  else if (courseNames.length) courseSel.value = courseNames[0];
  courseSel.dataset.lastCourse = courseSel.value || "";
  const cPick = courseSel.value;
  roundSel.innerHTML = '<option value="">—</option>';
  const roundsForCourse = cPick ? byCourse[cPick] || [] : [];
  roundsForCourse.sort((a, b) => String(a.rlabel).localeCompare(String(b.rlabel)));
  for (const { fullKey, rlabel } of roundsForCourse) {
    const o = document.createElement("option");
    o.value = fullKey;
    o.textContent = rlabel || fullKey;
    roundSel.appendChild(o);
  }
  if (prevRound && [...roundSel.options].some((o) => o.value === prevRound)) roundSel.value = prevRound;
  else if (roundSel.options.length > 1) roundSel.selectedIndex = 1;
  roundSel.dataset.lastRound = roundSel.value || "";
  holeTbody.innerHTML = "";
  const full = roundSel.value;
  const arr = full ? (holesMap[full] || []).slice().sort((a, b) => num(a.hole, 0) - num(b.hole, 0)) : [];
  for (const h of arr) {
    const tr = document.createElement("tr");
    const t0 = document.createElement("td");
    t0.textContent = String(h.hole);
    const t1 = document.createElement("td");
    t1.textContent = String(h.par);
    const t2 = document.createElement("td");
    t2.textContent = String(h.score);
    const rel = num(h.score, NaN) - num(h.par, NaN);
    if (rel < 0) t2.classList.add("good");
    else if (rel > 0) t2.classList.add("bad");
    const t3 = document.createElement("td");
    t3.textContent = String(h.score_type || "");
    tr.appendChild(t0);
    tr.appendChild(t1);
    tr.appendChild(t2);
    tr.appendChild(t3);
    holeTbody.appendChild(tr);
  }
  renderPropsShotsForSelection(dg, full);
}


/** Yield one frame so the browser can paint / handle input before more main-thread work. */
function yieldToMain() {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => resolve());
    else setTimeout(resolve, 0);
  });
}

/** Live merge + course table: not needed for first paint; load after projections UI, then refresh affected tabs. */
function prefetchPostProjectionsSidecarsAfterPaint() {
  const jobs = [];
  if (!isFileProtocol()) {
    jobs.push(ensureLiveTournamentHistoryMerged({ useCache: false }));
    jobs.push(fetchAndMergeFieldTeeTimes({ force: true }));
    if (datagolfLiveOverlayEnabled()) jobs.push(fetchAndMergeDatagolfLiveInPlay({ force: true }));
  }
  jobs.push(loadCourseTableJson());
  return Promise.all(jobs).finally(() => {
    refreshPricingAffectedViews();
    updateStatusBar();
  });
}

/** Rebuild projection-driven UI for the visible tab only (avoids rebuilding +EV / matchups / O/U grids on every poll). */
async function refreshAll() {
  syncLbRoundToTournamentModelRound();
  updateRoundLabels();
  fillPropGolferSelect();
  fillLivePropGolferSelect();

  if (isHomeViewActive()) {
    updateHomePage();
    updateStatusBar();
    return;
  }

  const tab = activeAppTabId() || "ou";
  if (tab === "ou") {
    buildOuTable();
    void ensurePlayerHistoryLoadedForTab("ou");
  } else if (tab === "ev") buildEvTable();
  else if (tab === "matchup-analysis") buildMatchupAnalysisTool();

  const pm = document.getElementById("panel-matchups");
  if (pm && !pm.hidden) buildMatchupsTable();
  const po = document.getElementById("panel-outrights");
  if (po && !po.hidden) buildOutrightsTable();

  await yieldToMain();

  if (tab === "props") {
    await ensurePlayerHistoryLoadedForTab("props");
    renderPropsTrendsNow();
  }
  if (tab === "live-prop") renderLivePropPredictor();
  if (tab === "course-fit") {
    void ensurePlayerHistoryLoadedForTab("course-fit");
    await yieldToMain();
    buildCourseFitTab();
  }
  if (tab === "parlay-pro" && window.ParlayPro) void window.ParlayPro.render();
}

/**
 * @param {{ silent?: boolean, reloadSidecar?: boolean }} [opts]
 *   silent: on fetch failure, keep current DATA (for background poll).
 *   reloadSidecar: fetch player_round_history.json / player_shots_web.json (initial load only).
 */
async function loadProjections(opts = {}) {
  const silent = Boolean(opts.silent);
  const reloadSidecar = opts.reloadSidecar !== false;
  if (projectionsLoadInFlight) {
    if (silent) projectionsSilentReloadQueued = true;
    return;
  }
  projectionsLoadInFlight = true;
  if (!silent) setBootError("");

  const finishOk = async () => {
    lastProjectionsLoadedAtMs = Date.now();
    const blocking = [];
    if (reloadSidecar) blocking.push(loadPlayerShots());
    await Promise.all(blocking);
    if (HISTORY._ok) scrubNonActualRoundsFromHistoryBuckets();
    await yieldToMain();
    hydrateBakedWeatherFromPlayerFields();
    if (!isFileProtocol() && !HISTORY._ok && !playerHistoryLoadPromise) {
      void loadPlayerHistory();
    }
    await fetchAndMergeFieldTeeTimes({ force: true });
    await ensureForecastWeatherLoaded();
    void ensurePgatourEventRoundsLoaded().then(() => {
      if (HISTORY._ok && lastLiveInPlayBundleForHistory) {
        reapplyLiveInPlayHistoryMerge();
      }
      invalidateOuProjectionAvgCaches();
      HISTORY_ROUNDS_CHRONO_CACHE.clear();
      if (activeAppTabId() === "ou") scheduleBuildOuTable(true);
      if (activeAppTabId() === "live-stats") void buildLiveStatsTab();
    });
    await refreshAll();
    updateStatusBar();
    stopDatagolfLivePolling();
    stopFieldTeeTimesPolling();
    if (datagolfLiveOverlayEnabled() && !isFileProtocol()) {
      startDatagolfLivePolling();
    }
    if (!isFileProtocol()) startFieldTeeTimesPolling();
    requestAnimationFrame(() => {
      void prefetchPostProjectionsSidecarsAfterPaint();
    });
  };

  try {
    if (isFileProtocol()) {
      showFileProtocolBanner(true);
      dataSource = "bundled-file";
      applyPayload(DEFAULT_PROJECTIONS_PAYLOAD);
      if (isHomeViewActive()) updateHomePage();
      await finishOk();
      return;
    }
    showFileProtocolBanner(false);
    const url = cacheBustFetchUrl(projectionsJsonUrl());
    const fetchOpts = { cache: "no-store" };
    if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
      fetchOpts.signal = AbortSignal.timeout(45000);
    }
    const res = await fetch(url, fetchOpts);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const j = await res.json();
    const base = url.split("/").pop() || url;
    dataSource = base === "projections.json" ? "projections.json" : url;
    applyPayload(j);
    if (!silent) setBootError("");
    if (isHomeViewActive()) updateHomePage();
    await finishOk();
  } catch (e) {
    if (silent) {
      updateStatusBar();
    } else {
      dataSource = "bundled-demo";
      applyPayload(DEFAULT_PROJECTIONS_PAYLOAD);
      setBootError(`Could not load ${projectionsJsonUrl()} (${e.message || e}). Using bundled demo.`);
      if (isHomeViewActive()) updateHomePage();
      await finishOk();
    }
  } finally {
    projectionsLoadInFlight = false;
    if (projectionsSilentReloadQueued) {
      projectionsSilentReloadQueued = false;
      queueMicrotask(() => {
        void loadProjections({ silent: true, reloadSidecar: false });
      });
    }
  }
}

function isHomeViewActive() {
  const home = document.getElementById("panel-home");
  return Boolean(home && home.classList.contains("active") && !home.hidden);
}

function updateHomePage() {
  const lineEl = document.getElementById("home-event-line");
  const metaEl = document.getElementById("home-event-meta");
  if (!lineEl) return;
  const m = DATA?.meta || {};
  const ev = m.event_name ? String(m.event_name).trim() : "";
  const course = m.course_used ? formatCourseNameForDisplay(m.course_used) : "";
  const venue = metaEventVenueLabel();
  lineEl.textContent = venue && venue !== "—" ? venue : ev || "AlphaCaddie";
  if (metaEl) {
    metaEl.textContent = ev && course
      ? `${ev} at ${course} — choose a tool below to explore projections, history, and edge.`
      : "Choose a tool below to explore model projections, historical trends, course fit, and +EV opportunities.";
  }
}

function setToolsChromeVisible(visible) {
  const tabs = document.querySelector(".tabs--tool-nav");
  const status = document.getElementById("data-status-primary");
  if (tabs) tabs.hidden = !visible;
  if (status) status.hidden = !visible;
  document.getElementById("content-wrapper")?.classList.toggle("content-wrapper--home", !visible);
}

/** Live Stats tab: Live Course Insights board (round pills + SG heat). */
let liveStatsRoundFilter = "";
let liveStatsViewMode = "values"; // values | ranks
let liveStatsSortKey = "pos_sort";
let liveStatsSortDir = 1;
let liveStatsSortWired = false;
let liveStatsUiWired = false;

const LIVE_STATS_SG_KEYS = ["sg_putt", "sg_arg", "sg_app", "sg_ott", "sg_t2g", "sg_total"];
/** Columns colored vs field average (green better / red worse). */
const LIVE_STATS_HEAT_KEYS = [
  "event_to_par",
  "round_to_par",
  "sg_putt",
  "sg_arg",
  "sg_app",
  "sg_ott",
  "sg_t2g",
  "sg_total",
  "pars",
  "birdies",
  "bogeys",
  "fairways",
  "gir",
  "drv_acc",
  "gir_pct",
];
const LIVE_STATS_LOWER_BETTER = new Set(["event_to_par", "round_to_par", "bogeys", "pos_sort"]);

async function ensureLiveStatsSourcesLoaded() {
  await ensurePgatourEventRoundsLoaded();
  if (!lastLiveInPlayBundleForHistory && !isFileProtocol()) {
    try {
      const res = await fetch(cacheBustFetchUrl(liveInPlayJsonUrl()), { cache: "no-store" });
      if (res.ok) {
        const j = await res.json();
        lastLiveInPlayBundleForHistory = liveInPlayHistoryBundleWithActuals(j);
      }
    } catch {
      /* missing live file */
    }
  }
  // Soft-load field history so SG ARG can fill from completed-round CSV merges when LTS omits it.
  if (!isFileProtocol() && (!HISTORY._ok || HISTORY._partial)) {
    try {
      await loadPlayerHistory();
    } catch {
      /* optional */
    }
  }
}

function liveStatsBundleEventName() {
  const bundle = lastLiveInPlayBundleForHistory;
  if (!bundle || typeof bundle !== "object") return "";
  return String(
    bundle.field_updates?.event_name ||
      bundle.info?.event_name ||
      bundle.live_tournament_stats?.event_name ||
      "",
  ).trim();
}

/** True when live LTS/data is still last week while projections already rolled. */
function liveStatsFeedMatchesProjections() {
  const modelEv = String(DATA?.meta?.event_name || DATA?.event_name || "").trim();
  const liveEv = liveStatsBundleEventName();
  if (!modelEv || !liveEv) return true;
  return (
    eventNameMatchesCurrentSchedule(liveEv, modelEv) ||
    eventNameMatchesCurrentSchedule(modelEv, liveEv)
  );
}

function liveStatsIsPreEventSkeleton() {
  const bundle = lastLiveInPlayBundleForHistory;
  return !!(bundle?.info?.pre_event || bundle?.live_stats_pre_event);
}

function liveStatsDefaultRoundFilter() {
  const started = liveStatsStartedRoundSet();
  const display = Math.round(num(DATA?.meta?.display_round ?? DATA?.display_round, NaN));
  if (Number.isFinite(display) && started.has(display)) return String(display);
  const liveR = currentEventLiveRoundNum();
  if (Number.isFinite(liveR) && started.has(liveR)) return String(liveR);
  const maxStarted = Math.max(0, ...started);
  if (maxStarted >= 1) return String(maxStarted);
  return "1";
}

/** Rounds that have at least one real posted score (not LTS ghosts for unplayed rounds). */
function liveStatsStartedRoundSet() {
  /** @type {Set<number>} */
  const started = new Set();
  const inPlay = liveStatsInPlayByDg();
  for (const ip of inPlay.values()) {
    for (let rnd = 1; rnd <= 4; rnd++) {
      if (Number.isFinite(num(ip?.[`R${rnd}`], NaN)) && num(ip[`R${rnd}`], 0) > 0) started.add(rnd);
    }
  }
  const actuals = liveRoundActualsMapFromApp() || {};
  for (const per of Object.values(actuals)) {
    if (!per || typeof per !== "object") continue;
    for (const [rndKey, act] of Object.entries(per)) {
      const rnd = Math.round(num(rndKey, NaN));
      if (!Number.isFinite(rnd) || rnd < 1 || rnd > 4) continue;
      if (Number.isFinite(num(act?.round_score, NaN)) && num(act.round_score, 0) > 0) started.add(rnd);
    }
  }
  const pgRounds = Array.isArray(PGATOUR_EVENT_ROUNDS?.rounds) ? PGATOUR_EVENT_ROUNDS.rounds : [];
  const eventName = String(DATA?.meta?.event_name || "").trim();
  for (const r of pgRounds) {
    if (!r?._from_pgatour) continue;
    if (eventName && !pgatourRowBelongsToEvent(r, eventName)) continue;
    const rnd = Math.round(num(r.round_num, NaN));
    if (!Number.isFinite(rnd) || rnd < 1 || rnd > 4) continue;
    if (Number.isFinite(num(r.round_score, NaN)) && num(r.round_score, 0) > 0) started.add(rnd);
  }
  return started;
}

function liveStatsSgFromHistory(dg, rnd) {
  if (!HISTORY?._ok || !HISTORY.byDgId) return null;
  const bucket = HISTORY.byDgId[String(dg)] || HISTORY.byDgId[dg];
  const rounds = Array.isArray(bucket?.rounds) ? bucket.rounds : [];
  for (const row of rounds) {
    if (!historyRoundMatchesCurrentEvent(row)) continue;
    if (Math.round(num(row.round_num ?? row.round, NaN)) !== rnd) continue;
    return row;
  }
  return null;
}

function liveStatsLtsByDgRound() {
  /** @type {Map<string, object>} */
  const map = new Map();
  const bundle = lastLiveInPlayBundleForHistory;
  const byRound = bundle?.live_tournament_stats_by_round;
  if (!byRound || typeof byRound !== "object") return map;
  for (const [rndKey, pack] of Object.entries(byRound)) {
    const rnd = Math.round(num(rndKey, NaN));
    if (!Number.isFinite(rnd) || rnd < 1 || rnd > 4) continue;
    const stats = Array.isArray(pack?.live_stats) ? pack.live_stats : [];
    for (const row of stats) {
      const dg = Math.round(num(row?.dg_id ?? row?.dgId, NaN));
      if (!Number.isFinite(dg)) continue;
      map.set(`${dg}|${rnd}`, row);
    }
  }
  return map;
}

function liveStatsInPlayByDg() {
  /** @type {Map<number, object>} */
  const map = new Map();
  const bundle = lastLiveInPlayBundleForHistory;
  if (!Array.isArray(bundle?.data)) return map;
  for (const r of bundle.data) {
    const dg = Math.round(num(r?.dg_id ?? r?.dgId, NaN));
    if (!Number.isFinite(dg)) continue;
    map.set(dg, r);
  }
  return map;
}

function liveStatsPlayerNameByDg() {
  /** @type {Map<number, string>} */
  const map = new Map();
  for (const p of DATA?.players || []) {
    const dg = Math.round(num(p?.dg_id ?? p?.dgId, NaN));
    if (!Number.isFinite(dg)) continue;
    const name = String(p?.player_name || p?.playerName || "").trim();
    if (name && !map.has(dg)) map.set(dg, name);
  }
  for (const [dg, r] of liveStatsInPlayByDg()) {
    if (map.has(dg)) continue;
    const name = String(r?.player_name || r?.playerName || "").trim();
    if (name) map.set(dg, name);
  }
  return map;
}

function liveStatsDisplayName(name) {
  const s = String(name || "").trim();
  const m = s.match(/^([^,]+),\s*(.+)$/);
  if (m) return `${m[1].trim().toUpperCase()} ${m[2].trim()}`;
  return s;
}

function liveStatsPosSort(pos) {
  const s = String(pos || "").trim().toUpperCase();
  if (!s || s === "—" || s === "CUT" || s === "WD" || s === "DQ") return 9999;
  const m = s.match(/(\d+)/);
  return m ? Number(m[1]) : 9999;
}

function liveStatsFmtToPar(v) {
  if (!Number.isFinite(v)) return "—";
  const x = Math.round(v);
  if (x === 0) return "E";
  return x > 0 ? `+${x}` : String(x);
}

function liveStatsFmtThru(thru) {
  if (!Number.isFinite(thru) || thru <= 0) return "—";
  if (thru >= 18) return "F";
  return String(Math.round(thru));
}

function liveStatsFmtSg(v) {
  if (!Number.isFinite(v)) return "—";
  const x = Math.round(v * 100) / 100;
  if (Math.abs(x) < 0.005) return "0.00";
  return (x > 0 ? "+" : "") + x.toFixed(2);
}

function liveStatsFmtInt(v) {
  return Number.isFinite(v) ? String(Math.round(v)) : "—";
}

function liveStatsFmtPct(v) {
  if (!Number.isFinite(v)) return "—";
  return `${(v * 100).toFixed(1)}%`;
}

/** Conditional formatting: green / red / white cell backgrounds. */
function liveStatsSgHeatClass(v) {
  if (!Number.isFinite(v)) return "";
  if (v > 0.05) return "ls-heat ls-heat-pos";
  if (v < -0.05) return "ls-heat ls-heat-neg";
  return "ls-heat ls-heat-zero";
}

function liveStatsVsAvgClass(key, value, mean) {
  if (!Number.isFinite(value) || !Number.isFinite(mean)) return "";
  const lowerBetter = LIVE_STATS_LOWER_BETTER.has(key);
  const spread = Math.abs(mean) > 1e-6 ? Math.abs(mean) * 0.02 : 0.05;
  const eps = Math.max(0.02, spread);
  if (lowerBetter) {
    if (value < mean - eps) return "ls-heat ls-heat-pos";
    if (value > mean + eps) return "ls-heat ls-heat-neg";
  } else {
    if (value > mean + eps) return "ls-heat ls-heat-pos";
    if (value < mean - eps) return "ls-heat ls-heat-neg";
  }
  return "ls-heat ls-heat-zero";
}

function liveStatsFieldMeans(rows) {
  /** @type {Record<string, number>} */
  const means = {};
  for (const key of LIVE_STATS_HEAT_KEYS) {
    let s = 0;
    let n = 0;
    for (const r of rows) {
      const v = num(r[key], NaN);
      if (!Number.isFinite(v)) continue;
      s += v;
      n++;
    }
    means[key] = n ? s / n : NaN;
  }
  return means;
}

function liveStatsBuildSgParts(act, lts, histRow) {
  const pick = (...vals) => {
    for (const v of vals) {
      if (v == null || v === "") continue;
      const n = typeof v === "number" ? v : Number(v);
      if (Number.isFinite(n)) return n;
    }
    return NaN;
  };
  const sgOtt = pick(act?.sg_ott, lts?.sg_ott, histRow?.sg_ott);
  const sgApp = pick(act?.sg_app, lts?.sg_app, histRow?.sg_app);
  let sgArg = pick(
    act?.sg_arg,
    lts?.sg_arg,
    lts?.arg,
    lts?.sg_around,
    lts?.around_the_green,
    histRow?.sg_arg,
  );
  const sgPutt = pick(act?.sg_putt, lts?.sg_putt, histRow?.sg_putt);
  let sgT2g = pick(act?.sg_t2g, lts?.sg_t2g, histRow?.sg_t2g);
  let sgTotal = pick(act?.sg_total, lts?.sg_total, histRow?.sg_total);
  // Derive missing ARG / T2G / Total when the feed only has a subset.
  if (!Number.isFinite(sgT2g) && Number.isFinite(sgTotal) && Number.isFinite(sgPutt)) {
    sgT2g = sgTotal - sgPutt;
  }
  if (
    !Number.isFinite(sgArg) &&
    Number.isFinite(sgT2g) &&
    Number.isFinite(sgOtt) &&
    Number.isFinite(sgApp)
  ) {
    sgArg = sgT2g - sgOtt - sgApp;
  }
  if (!Number.isFinite(sgT2g)) {
    const parts = [sgOtt, sgApp, sgArg].filter((x) => Number.isFinite(x));
    if (parts.length) sgT2g = parts.reduce((a, b) => a + b, 0);
  }
  if (!Number.isFinite(sgTotal) && Number.isFinite(sgT2g) && Number.isFinite(sgPutt)) {
    sgTotal = sgT2g + sgPutt;
  } else if (!Number.isFinite(sgTotal)) {
    const parts = [sgOtt, sgApp, sgArg, sgPutt].filter((x) => Number.isFinite(x));
    if (parts.length >= 2) sgTotal = parts.reduce((a, b) => a + b, 0);
  }
  return { sg_ott: sgOtt, sg_app: sgApp, sg_arg: sgArg, sg_putt: sgPutt, sg_t2g: sgT2g, sg_total: sgTotal };
}

function collectLiveStatsRoundRows() {
  const actuals = liveRoundActualsMapFromApp() || {};
  const ltsMap = liveStatsLtsByDgRound();
  const names = liveStatsPlayerNameByDg();
  const inPlay = liveStatsInPlayByDg();
  const fwHoles = fairwayHolesModeledFromData();
  const par = num(DATA?.meta?.course_par_18, 70);
  /** @type {object[]} */
  const rows = [];
  const dgSet = new Set([...names.keys(), ...inPlay.keys()]);
  for (const k of Object.keys(actuals)) {
    const dg = Math.round(num(k, NaN));
    if (Number.isFinite(dg)) dgSet.add(dg);
  }
  for (const k of ltsMap.keys()) {
    const dg = Math.round(num(String(k).split("|")[0], NaN));
    if (Number.isFinite(dg)) dgSet.add(dg);
  }

  for (const dg of dgSet) {
    const per = actuals[String(dg)] || actuals[dg] || {};
    const ip = inPlay.get(dg) || null;
    for (let rnd = 1; rnd <= 4; rnd++) {
      const act = per[String(rnd)] || per[rnd] || null;
      const lts = ltsMap.get(`${dg}|${rnd}`) || null;
      const pg = pgatourEventRoundForDg(dg, rnd);
      const histRow = liveStatsSgFromHistory(dg, rnd);
      // Require a real posted score — LTS often echoes the prior round before R4 starts.
      const scoreCand = [
        num(ip?.[`R${rnd}`], NaN),
        num(act?.round_score, NaN),
        num(pg?.round_score, NaN),
        num(histRow?.round_score, NaN),
      ];
      const score = scoreCand.find((x) => Number.isFinite(x) && x > 0);
      if (!Number.isFinite(score)) continue;

      const roundToParLts = num(lts?.round, NaN);
      let thru = num(act?.thru, NaN);
      if (!Number.isFinite(thru) && Math.round(num(ip?.round, NaN)) === rnd) thru = num(ip?.thru, NaN);
      if (!Number.isFinite(thru) && Number.isFinite(score)) thru = 18;

      const roundToPar = Number.isFinite(score) && Number.isFinite(par) ? score - par : roundToParLts;
      const eventToPar = num(ip?.current_score ?? lts?.total, NaN);
      const pos = String(ip?.current_pos || lts?.position || "").trim() || "—";
      const sg = liveStatsBuildSgParts(act, lts, histRow);
      const birdies = birdiesPlusEaglesFromRow(pg || histRow || act || {});
      const bogeys = bogeysPlusDoublesFromRow(pg || histRow || act || {});
      const pars = num(pg?.pars ?? histRow?.pars ?? act?.pars, NaN);
      const fairways = Number.isFinite(num(act?.fairways, NaN))
        ? historyGirOrFairwaysCount(act.fairways, fwHoles)
        : Number.isFinite(num(lts?.accuracy, NaN))
          ? Math.round(num(lts.accuracy, NaN) * fwHoles)
          : NaN;
      const gir = Number.isFinite(num(act?.gir, NaN))
        ? historyGirOrFairwaysCount(act.gir, 18)
        : Number.isFinite(num(lts?.gir, NaN)) && num(lts.gir, 0) <= 1.0001
          ? Math.round(num(lts.gir, NaN) * 18)
          : num(lts?.gir, NaN);
      const drvAcc = num(lts?.accuracy, NaN);
      const girPct =
        Number.isFinite(num(lts?.gir, NaN)) && num(lts.gir, 0) <= 1.0001
          ? num(lts.gir, NaN)
          : Number.isFinite(gir)
            ? gir / 18
            : NaN;
      const player =
        names.get(dg) ||
        String(lts?.player_name || ip?.player_name || pg?.player_name || "").trim() ||
        `DG ${dg}`;

      rows.push({
        dg_id: dg,
        player,
        player_display: liveStatsDisplayName(player),
        round: rnd,
        pos,
        pos_sort: liveStatsPosSort(pos),
        event_to_par: eventToPar,
        thru,
        round_to_par: roundToPar,
        score,
        pars,
        birdies,
        bogeys,
        fairways,
        gir,
        drv_acc: drvAcc,
        gir_pct: girPct,
        ...sg,
      });
    }
  }
  return rows;
}

function collectLiveStatsTournamentRows(roundRows) {
  /** @type {Map<number, object>} */
  const byDg = new Map();
  for (const r of roundRows) {
    let agg = byDg.get(r.dg_id);
    if (!agg) {
      agg = {
        dg_id: r.dg_id,
        player: r.player,
        player_display: r.player_display,
        round: 0,
        pos: r.pos,
        pos_sort: r.pos_sort,
        event_to_par: r.event_to_par,
        thru: NaN,
        round_to_par: NaN,
        score: NaN,
        pars: 0,
        birdies: 0,
        bogeys: 0,
        fairways: 0,
        gir: 0,
        drv_acc: NaN,
        gir_pct: NaN,
        sg_putt: 0,
        sg_arg: 0,
        sg_app: 0,
        sg_ott: 0,
        sg_t2g: 0,
        sg_total: 0,
        _n: 0,
        _n_pars: 0,
        _n_bird: 0,
        _n_bog: 0,
        _n_fw: 0,
        _n_gir: 0,
        _n_acc: 0,
        _acc_sum: 0,
        _n_girpct: 0,
        _girpct_sum: 0,
      };
      byDg.set(r.dg_id, agg);
    }
    if (Number.isFinite(r.event_to_par)) agg.event_to_par = r.event_to_par;
    if (r.pos && r.pos !== "—") {
      agg.pos = r.pos;
      agg.pos_sort = r.pos_sort;
    }
    for (const k of LIVE_STATS_SG_KEYS) {
      if (Number.isFinite(r[k])) agg[k] += r[k];
    }
    if (Number.isFinite(r.pars)) {
      agg.pars += r.pars;
      agg._n_pars++;
    }
    if (Number.isFinite(r.birdies)) {
      agg.birdies += r.birdies;
      agg._n_bird++;
    }
    if (Number.isFinite(r.bogeys)) {
      agg.bogeys += r.bogeys;
      agg._n_bog++;
    }
    if (Number.isFinite(r.fairways)) {
      agg.fairways += r.fairways;
      agg._n_fw++;
    }
    if (Number.isFinite(r.gir)) {
      agg.gir += r.gir;
      agg._n_gir++;
    }
    if (Number.isFinite(r.drv_acc)) {
      agg._acc_sum += r.drv_acc;
      agg._n_acc++;
    }
    if (Number.isFinite(r.gir_pct)) {
      agg._girpct_sum += r.gir_pct;
      agg._n_girpct++;
    }
    agg._n++;
  }
  return [...byDg.values()].map((a) => {
    a.drv_acc = a._n_acc ? a._acc_sum / a._n_acc : NaN;
    a.gir_pct = a._n_girpct ? a._girpct_sum / a._n_girpct : NaN;
    if (!a._n_pars) a.pars = NaN;
    if (!a._n_bird) a.birdies = NaN;
    if (!a._n_bog) a.bogeys = NaN;
    if (!a._n_fw) a.fairways = NaN;
    if (!a._n_gir) a.gir = NaN;
    return a;
  });
}

function liveStatsApplyRanks(rows) {
  const higherBetter = new Set([
    "sg_putt",
    "sg_arg",
    "sg_app",
    "sg_ott",
    "sg_t2g",
    "sg_total",
    "birdies",
    "bogeys",
    "fairways",
    "gir",
    "drv_acc",
    "gir_pct",
    "pars",
  ]);
  const lowerBetter = new Set(["event_to_par", "round_to_par", "pos_sort", "bogeys"]);
  // bogeys: lower is better for ranks — remove from higherBetter
  higherBetter.delete("bogeys");
  const keys = [...higherBetter, ...lowerBetter];
  const out = rows.map((r) => ({ ...r }));
  for (const key of keys) {
    const ranked = out
      .map((r, i) => ({ i, v: r[key] }))
      .filter((x) => Number.isFinite(x.v))
      .sort((a, b) => (higherBetter.has(key) ? b.v - a.v : a.v - b.v));
    ranked.forEach((x, rank) => {
      out[x.i][`${key}_rank`] = rank + 1;
    });
  }
  return out;
}

function sortLiveStatsRows(rows) {
  const key = liveStatsSortKey;
  const dir = liveStatsSortDir;
  const rankMode = liveStatsViewMode === "ranks";
  return [...rows].sort((a, b) => {
    if (key === "player" || key === "player_display") {
      const c = String(a.player_display || a.player).localeCompare(String(b.player_display || b.player));
      if (c) return c * dir;
      return (a.round - b.round) * dir;
    }
    if (key === "pos") {
      const d = a.pos_sort - b.pos_sort;
      if (d) return d * dir;
    }
    const ak = rankMode && Number.isFinite(a[`${key}_rank`]) ? `${key}_rank` : key;
    const bk = rankMode && Number.isFinite(b[`${key}_rank`]) ? `${key}_rank` : key;
    const av = a[ak];
    const bv = b[bk];
    const aOk = Number.isFinite(av);
    const bOk = Number.isFinite(bv);
    if (aOk && bOk && av !== bv) return (av - bv) * dir;
    if (aOk !== bOk) return aOk ? -1 : 1;
    return a.pos_sort - b.pos_sort;
  });
}

function liveStatsRenderThead(roundNum) {
  const thead = document.getElementById("live-stats-thead");
  if (!thead) return;
  const rndLabel = Number.isFinite(roundNum) ? `R${roundNum}` : "—";
  const th = (key, label, cls = "num") =>
    `<th class="${cls} sortable" data-live-stats-sort="${key}" scope="col">${label}<span class="sort-ind"><span class="sort-up">▲</span><span class="sort-down">▼</span></span></th>`;
  thead.innerHTML = `<tr>
    ${th("pos", "Pos", "ls-th-pos")}
    ${th("player_display", "Player", "ls-th-player")}
    ${th("event_to_par", "Score")}
    ${th("thru", "Thru")}
    ${th("round_to_par", rndLabel)}
    ${th("sg_putt", "SG Putt")}
    ${th("sg_arg", "SG ARG")}
    ${th("sg_app", "SG App")}
    ${th("sg_ott", "SG OTT")}
    ${th("sg_t2g", "SG T2G")}
    ${th("sg_total", "SG Total")}
    ${th("pars", "Pars")}
    ${th("birdies", "Birdie+")}
    ${th("bogeys", "Bogeys")}
    ${th("fairways", "FW")}
    ${th("gir", "GIR")}
    ${th("drv_acc", "Drv Acc%")}
    ${th("gir_pct", "GIR%")}
  </tr>`;
}

function liveStatsCell(key, row, rankMode, means) {
  const heat =
    LIVE_STATS_HEAT_KEYS.includes(key) && Number.isFinite(row[key])
      ? liveStatsVsAvgClass(key, row[key], means?.[key])
      : "";
  if (rankMode && Number.isFinite(row[`${key}_rank`])) {
    return { html: String(row[`${key}_rank`]), cls: `num ls-rank ${heat}`.trim() };
  }
  if (LIVE_STATS_SG_KEYS.includes(key)) {
    const v = row[key];
    return { html: liveStatsFmtSg(v), cls: `num ${heat || liveStatsSgHeatClass(v)}`.trim() };
  }
  if (key === "event_to_par" || key === "round_to_par") {
    const v = row[key];
    const base = Number.isFinite(v) && v < 0 ? "num ls-score-under" : "num";
    return { html: liveStatsFmtToPar(v), cls: `${base} ${heat}`.trim() };
  }
  if (key === "thru") return { html: liveStatsFmtThru(row.thru), cls: "num" };
  if (key === "drv_acc" || key === "gir_pct") {
    return { html: liveStatsFmtPct(row[key]), cls: `num ${heat}`.trim() };
  }
  if (key === "pars" || key === "birdies" || key === "bogeys" || key === "fairways" || key === "gir") {
    return { html: liveStatsFmtInt(row[key]), cls: `num ${heat}`.trim() };
  }
  return { html: "—", cls: "num" };
}

function wireLiveStatsUiOnce() {
  if (liveStatsUiWired) return;
  liveStatsUiWired = true;
  if (!liveStatsRoundFilter || !["1", "2", "3", "4", "tournament"].includes(liveStatsRoundFilter)) {
    liveStatsRoundFilter = liveStatsDefaultRoundFilter();
  }
  document.getElementById("live-stats-round-pills")?.addEventListener("click", (ev) => {
    const btn = /** @type {HTMLElement} */ (ev.target)?.closest?.("[data-live-stats-round]");
    if (!btn || btn.disabled || btn.classList.contains("is-disabled")) return;
    liveStatsRoundFilter = String(btn.getAttribute("data-live-stats-round") || "1");
    buildLiveStatsTab();
  });
  document.querySelector(".live-stats-view-toggle")?.addEventListener("click", (ev) => {
    const btn = /** @type {HTMLElement} */ (ev.target)?.closest?.("[data-live-stats-view]");
    if (!btn) return;
    liveStatsViewMode = String(btn.getAttribute("data-live-stats-view") || "values");
    buildLiveStatsTab();
  });
  document.getElementById("live-stats-search")?.addEventListener("input", () => buildLiveStatsTab());
  if (liveStatsSortWired) return;
  liveStatsSortWired = true;
  // Delegate from table so header rebuilds never drop the listener.
  document.getElementById("table-live-stats")?.addEventListener("click", (ev) => {
    const th = /** @type {HTMLElement} */ (ev.target)?.closest?.("th.sortable[data-live-stats-sort]");
    if (!th || !th.closest("#table-live-stats")) return;
    const key = String(th.getAttribute("data-live-stats-sort") || "");
    if (!key) return;
    const sortKey = key === "pos" ? "pos_sort" : key;
    if (liveStatsSortKey === sortKey) liveStatsSortDir *= -1;
    else {
      liveStatsSortKey = sortKey;
      liveStatsSortDir =
        sortKey === "player_display" || sortKey === "pos_sort" || sortKey === "event_to_par" || sortKey === "round_to_par" || sortKey === "bogeys"
          ? 1
          : -1;
    }
    buildLiveStatsTab();
  });
}

async function buildLiveStatsTab() {
  wireLiveStatsUiOnce();
  const tbody = document.querySelector("#table-live-stats tbody");
  const countEl = document.getElementById("live-stats-count");
  if (!tbody) return;
  await ensureLiveStatsSourcesLoaded();

  const modelEv = String(DATA?.meta?.event_name || DATA?.event_name || "").trim();
  const liveEv = liveStatsBundleEventName();
  if (!liveStatsFeedMatchesProjections() || liveStatsIsPreEventSkeleton()) {
    document.querySelectorAll("#live-stats-round-pills .live-stats-round-pill").forEach((btn) => {
      const key = String(btn.getAttribute("data-live-stats-round") || "");
      btn.disabled = key !== "tournament";
      btn.classList.toggle("is-disabled", key !== "tournament");
      btn.classList.toggle("active", key === "tournament");
      btn.setAttribute("aria-pressed", key === "tournament" ? "true" : "false");
    });
    liveStatsRoundFilter = "tournament";
    liveStatsRenderThead(NaN);
    const titleRound = document.getElementById("live-stats-title-round");
    if (titleRound) titleRound.textContent = "Tournament";
    const why = liveStatsIsPreEventSkeleton()
      ? `Waiting for live round stats for ${modelEv || "this event"}.`
      : `Live Stats feed is still on ${liveEv || "prior event"} while projections are ${modelEv || "current"} — re-run push:live.`;
    if (countEl) countEl.textContent = why;
    tbody.innerHTML = `<tr><td colspan="18">${escapeHtml(why)}</td></tr>`;
    return;
  }

  if (!liveStatsRoundFilter || !["1", "2", "3", "4", "tournament"].includes(liveStatsRoundFilter)) {
    liveStatsRoundFilter = liveStatsDefaultRoundFilter();
  }

  document.querySelectorAll("#live-stats-round-pills .live-stats-round-pill").forEach((btn) => {
    const key = String(btn.getAttribute("data-live-stats-round") || "");
    const started = liveStatsStartedRoundSet();
    const disabled = key !== "tournament" && !started.has(Math.round(num(key, NaN)));
    btn.disabled = disabled;
    btn.classList.toggle("is-disabled", disabled);
    btn.title = disabled ? "Round has not started" : "";
    const on = key === liveStatsRoundFilter;
    btn.classList.toggle("active", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });
  document.querySelectorAll(".live-stats-view-btn").forEach((btn) => {
    const on = btn.getAttribute("data-live-stats-view") === liveStatsViewMode;
    btn.classList.toggle("active", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });

  const isTournament = liveStatsRoundFilter === "tournament";
  const roundNum = isTournament ? NaN : Math.round(num(liveStatsRoundFilter, NaN));
  const started = liveStatsStartedRoundSet();
  if (!isTournament && Number.isFinite(roundNum) && !started.has(roundNum)) {
    liveStatsRoundFilter = liveStatsDefaultRoundFilter();
    return void buildLiveStatsTab();
  }
  const titleRound = document.getElementById("live-stats-title-round");
  if (titleRound) titleRound.textContent = isTournament ? "Tournament" : `Round ${roundNum}`;

  liveStatsRenderThead(roundNum);

  const allRoundRows = collectLiveStatsRoundRows();
  let rows = isTournament
    ? collectLiveStatsTournamentRows(allRoundRows)
    : allRoundRows.filter((r) => r.round === roundNum);

  const q = String(document.getElementById("live-stats-search")?.value || "")
    .trim()
    .toLowerCase();
  if (q) {
    rows = rows.filter(
      (r) =>
        String(r.player).toLowerCase().includes(q) ||
        String(r.player_display).toLowerCase().includes(q),
    );
  }

  const means = liveStatsFieldMeans(rows);
  rows = liveStatsApplyRanks(rows);
  rows = sortLiveStatsRows(rows);

  document.querySelectorAll("#table-live-stats thead th.sortable").forEach((th) => {
    const key = th.getAttribute("data-live-stats-sort");
    const activeKey = liveStatsSortKey === "pos_sort" ? "pos" : liveStatsSortKey;
    th.setAttribute(
      "aria-sort",
      key === activeKey ? (liveStatsSortDir > 0 ? "ascending" : "descending") : "none",
    );
  });

  const rankMode = liveStatsViewMode === "ranks";
  if (countEl) {
    countEl.textContent = `${rows.length} player${rows.length === 1 ? "" : "s"} · ${
      rankMode ? "field ranks" : "raw values"
    } · green/red vs field average`;
  }

  if (!rows.length) {
    const emptyMsg =
      !isTournament && Number.isFinite(roundNum) && !started.has(roundNum)
        ? `Round ${roundNum} has not started yet.`
        : "No live round stats yet for this filter.";
    tbody.innerHTML = `<tr><td colspan="18">${emptyMsg}</td></tr>`;
    return;
  }

  tbody.innerHTML = rows
    .map((r) => {
      const keys = [
        "event_to_par",
        "thru",
        "round_to_par",
        "sg_putt",
        "sg_arg",
        "sg_app",
        "sg_ott",
        "sg_t2g",
        "sg_total",
        "pars",
        "birdies",
        "bogeys",
        "fairways",
        "gir",
        "drv_acc",
        "gir_pct",
      ];
      const cells = keys
        .map((k) => {
          // Tournament mode: hide per-round thru / round-to-par
          if (isTournament && (k === "thru" || k === "round_to_par")) {
            return `<td class="num">—</td>`;
          }
          const c = liveStatsCell(k, r, rankMode, means);
          return `<td class="${c.cls}">${c.html}</td>`;
        })
        .join("");
      return `<tr>
        <td class="ls-pos">${escapeHtml(r.pos)}</td>
        <td class="ls-player">${escapeHtml(r.player_display || r.player)}</td>
        ${cells}
      </tr>`;
    })
    .join("");
}

function showHomeView() {
  document.querySelectorAll(".tabs .tab").forEach((b) => {
    b.classList.remove("active");
    b.setAttribute("aria-selected", "false");
  });
  document.querySelectorAll(".panel").forEach((p) => {
    const isHome = p.id === "panel-home";
    p.classList.toggle("active", isHome);
    p.hidden = !isHome;
  });
  setToolsChromeVisible(false);
  updateHomePage();
}

function showAppTab(tab) {
  if (!tab) {
    showHomeView();
    return;
  }
  setToolsChromeVisible(true);
  const btn = document.querySelector(`.tabs .tab[data-tab="${tab}"]`);
  document.querySelectorAll(".tabs .tab").forEach((b) => {
    const on = b === btn;
    b.classList.toggle("active", on);
    b.setAttribute("aria-selected", on ? "true" : "false");
  });
  document.querySelectorAll(".panel").forEach((p) => {
    const on = p.id === `panel-${tab}`;
    p.classList.toggle("active", on);
    p.hidden = !on;
  });
  if (tab === "ou")
    requestAnimationFrame(() => {
      void ensurePlayerHistoryLoadedForTab("ou");
      scheduleBuildOuTable(true);
      syncOuChartCard();
      const ouProjCanvas = document.querySelector("#table-ou tbody .ou-proj-detail-canvas");
      if (ouProjCanvas && ouProjExpandedDetail) {
        drawOuProjDetailDistribution(
          ouProjCanvas,
          ouProjExpandedDetail.market,
          ouProjExpandedDetail.player,
          ouProjExpandedDetail.line,
        );
      }
    });
  if (tab === "props") {
    requestAnimationFrame(() => {
      void ensurePlayerHistoryLoadedForTab("props");
    });
  }
  if (tab === "matchup-analysis") {
    requestAnimationFrame(() => buildMatchupAnalysisTool());
  }
  if (tab === "live-prop") {
    requestAnimationFrame(() => renderLivePropPredictor());
  }
  if (tab === "course-fit") {
    requestAnimationFrame(() => {
      void ensurePlayerHistoryLoadedForTab("course-fit");
      buildCourseFitTab();
    });
  }
  if (tab === "course-breakdown") {
    requestAnimationFrame(() => buildCourseBreakdownTab());
  }
  if (tab === "live-stats") {
    requestAnimationFrame(() => {
      void buildLiveStatsTab();
    });
  }
  if (tab === "ev") {
    requestAnimationFrame(() => {
      syncEvTabOddsAfterShow();
      if (!isFileProtocol()) {
        void loadProjections({ silent: true, reloadSidecar: false });
      }
    });
  }
  if (tab === "parlay-pro") {
    requestAnimationFrame(() => {
      if (window.ParlayPro) void window.ParlayPro.render();
    });
  }
  if (tab === "results") {
    requestAnimationFrame(() => {
      loadResultsPayload();
      renderResultsTab();
    });
  }
}

function activeAppTabId() {
  if (isHomeViewActive()) return "";
  const active = document.querySelector(".tabs .tab.active");
  return active ? String(active.getAttribute("data-tab") || "") : "";
}

function ensurePlayerHistoryLoadedForTab(tab) {
  if (!["props", "course-fit", "ou"].includes(String(tab || ""))) return Promise.resolve();
  const p =
    tab === "props"
      ? (async () => {
          const dg = selectedDgId();
          if (!Number.isFinite(dg)) return false;
          await ensurePlayerCareerHistoryLoaded(dg);
          if (!historyBucketLoaded(dg) && !historyBucketResolved(dg)) {
            await extractHistoryBucketFromEmbedded(dg);
          }
          if (!historyBucketLoaded(dg) && !historyBucketResolved(dg)) {
            if (!HISTORY._ok || HISTORY._partial) {
              await loadPlayerHistory();
            }
            if (!historyBucketLoaded(dg) && !historyBucketResolved(dg)) {
              markPlayerHistoryAbsent(dg);
            }
          }
          return historyBucketLoaded(dg) || historyBucketResolved(dg);
        })()
      : tab === "ou"
        ? scheduleOuProjectionFieldHistoryLoad()
        : HISTORY._ok && !HISTORY._partial
        ? Promise.resolve(true)
        : loadPlayerHistory();
  return p.then(() => {
    if (activeAppTabId() !== tab) return;
    if (tab === "props") renderPropsTrendsNow();
    if (tab === "course-fit") buildCourseFitTab();
    if (tab === "ou") buildOuTable();
  }).catch(() => {
    if (activeAppTabId() === "props") renderPropsTrendsNow();
    if (activeAppTabId() === "ou") buildOuTable();
  });
}

/** Rebuild the Odds Screen from already-loaded sportsbook and DataGolf prices. */
function syncEvTabOddsAfterShow() {
  buildEvTable();
}

function resultsJsonUrl() {
  return "data/results_backtest.json";
}

function resultsStatus(text) {
  const el = document.getElementById("results-status");
  if (el) el.textContent = String(text || "");
}

function resultsSelectValue(id, fallback = "__all__") {
  const el = document.getElementById(id);
  if (!el) return fallback;
  return String(el.value || fallback);
}

function loadResultsPayload() {
  if (!resultsFeatureEnabled()) return;
  if (RESULTS.loaded || RESULTS.loading) return;
  RESULTS.loading = true;
  resultsStatus("Loading results...");
  fetch(cacheBustFetchUrl(resultsJsonUrl()), { cache: "no-store" })
    .then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    })
    .then((j) => {
      RESULTS.payload = j && typeof j === "object" ? j : null;
      RESULTS.loaded = true;
      RESULTS.error = "";
      initResultsFilters();
      renderResultsTab();
    })
    .catch((e) => {
      RESULTS.error = e?.message || String(e);
      resultsStatus(`Results file missing: ${resultsJsonUrl()} (${RESULTS.error})`);
    })
    .finally(() => {
      RESULTS.loading = false;
    });
}

function resultsAllMarkets() {
  const p = RESULTS.payload || {};
  const a = Array.isArray(p?.markets?.matchups) ? p.markets.matchups : [];
  const b = Array.isArray(p?.markets?.outrights) ? p.markets.outrights : [];
  return [...new Set([...a, ...b])]
    .filter((m) => m && m !== "__all__" && m !== "__combined__")
    .sort();
}

function resultsAllBooks() {
  const p = RESULTS.payload || {};
  const a = Array.isArray(p?.books?.matchups) ? p.books.matchups : [];
  const b = Array.isArray(p?.books?.outrights) ? p.books.outrights : [];
  return [...new Set([...a, ...b])].filter((bk) => bk && bk !== "__all__").sort();
}

function refillResultsMarketSelect(items, prev) {
  const sel = document.getElementById("results-filter-market");
  if (!sel) return;
  sel.innerHTML = "";
  for (const it of items) {
    if (!it || it === "__all__" || it === "__combined__") continue;
    const o = document.createElement("option");
    o.value = it;
    o.textContent = resultsMarketDisplayName(it);
    sel.appendChild(o);
  }
  if (!sel.options.length) return;
  const prevOk =
    prev &&
    prev !== "__combined__" &&
    prev !== "__all__" &&
    [...sel.options].some((o) => o.value === prev);
  sel.value = prevOk ? prev : sel.options[0].value;
}

function resultsDefaultMarketValue() {
  const sel = document.getElementById("results-filter-market");
  if (!sel || !sel.options.length) return "";
  return String(sel.options[0].value || "");
}

function refillResultsBookSelect(items, prev = "__all__") {
  const sel = document.getElementById("results-filter-book");
  if (!sel) return;
  sel.innerHTML = "";
  const all = document.createElement("option");
  all.value = "__all__";
  all.textContent = "All books";
  sel.appendChild(all);
  for (const it of items) {
    const o = document.createElement("option");
    o.value = it;
    const m = bookMeta(it);
    o.textContent = m.short;
    o.title = m.label;
    sel.appendChild(o);
  }
  if ([...sel.options].some((o) => o.value === prev)) sel.value = prev;
  else sel.value = "__all__";
}

function refillResultsCourseSelect(prev = "__all__") {
  const sel = document.getElementById("results-filter-course");
  if (!sel) return;
  const tuples = kellyBetTuples();
  const names = new Set();
  for (const row of tuples) {
    if (String(row[2] || "") !== "outrights") continue;
    const en = kellyTupleEventName(row);
    if (en) names.add(en);
  }
  const items = [...names].sort((a, b) => a.localeCompare(b));
  sel.innerHTML = "";
  const all = document.createElement("option");
  all.value = "__all__";
  all.textContent = "All tournaments";
  sel.appendChild(all);
  for (const it of items) {
    const o = document.createElement("option");
    o.value = it;
    o.textContent = it;
    sel.appendChild(o);
  }
  if (prev && prev !== "__all__" && [...sel.options].some((o) => o.value === prev)) sel.value = prev;
  else sel.value = "__all__";
}

function refillResultsPlayerSelect(prev = "__all__") {
  const sel = document.getElementById("results-filter-player");
  if (!sel) return;
  const tuples = kellyBetTuples();
  const byKey = new Map();
  for (const row of tuples) {
    const key = resultsPlayerFilterKey(row);
    const nm = String(row[10] ?? "").trim();
    if (!key || !nm) continue;
    if (!byKey.has(key)) byKey.set(key, nm);
  }
  const sorted = [...byKey.entries()].sort((a, b) =>
    displayGolferName(a[1]).localeCompare(displayGolferName(b[1]), undefined, { sensitivity: "base" }),
  );
  sel.innerHTML = "";
  const all = document.createElement("option");
  all.value = "__all__";
  all.textContent = "All players";
  sel.appendChild(all);
  for (const [val, rawName] of sorted) {
    const o = document.createElement("option");
    o.value = val;
    o.textContent = displayGolferName(rawName);
    sel.appendChild(o);
  }
  if (prev && prev !== "__all__" && [...sel.options].some((o) => o.value === prev)) sel.value = prev;
  else sel.value = "__all__";
}

function syncResultsKellyAuxFilters() {
  const prevC = resultsSelectValue("results-filter-course", "__all__");
  const prevP = resultsSelectValue("results-filter-player", "__all__");
  refillResultsCourseSelect(prevC);
  refillResultsPlayerSelect(prevP);
}

function initResultsFilters() {
  if (!RESULTS.payload) return;
  const prevM = resultsSelectValue("results-filter-market", "");
  const prevB = resultsSelectValue("results-filter-book", "__all__");
  refillResultsMarketSelect(resultsAllMarkets(), prevM);
  refillResultsBookSelect(resultsAllBooks(), prevB);
  syncResultsBookLogoUi();
}

function resultsMaxDateIso(rows) {
  let max = "";
  for (const r of rows) {
    const d = String(r.date || "").trim().slice(0, 10);
    if (/^\d{4}-\d{2}-\d{2}$/.test(d) && d > max) max = d;
  }
  return max;
}

function resultsTimeRangeStartIso(maxD, rangeKey) {
  if (!maxD || rangeKey === "all") return "";
  const m = maxD.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return "";
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const day = Number(m[3]);
  const maxT = Date.UTC(y, mo - 1, day);
  let startT = maxT;
  if (rangeKey === "1w") startT = maxT - 6 * 86400000;
  else if (rangeKey === "1m") startT = maxT - 29 * 86400000;
  else if (rangeKey === "1y") startT = maxT - 364 * 86400000;
  else if (rangeKey === "ytd") startT = Date.UTC(y, 0, 1);
  else return "";
  return new Date(startT).toISOString().slice(0, 10);
}

function resultsRowsInTimeRange(rows, rangeKey) {
  if (!rows.length || rangeKey === "all") return rows;
  const maxD = resultsMaxDateIso(rows);
  if (!maxD) return rows;
  const start = resultsTimeRangeStartIso(maxD, rangeKey);
  if (!start) return rows;
  return rows.filter((r) => String(r.date || "").slice(0, 10) >= start);
}

function resultsRangeCaption(rangeKey) {
  if (rangeKey === "1w") return "Last 7 days";
  if (rangeKey === "1m") return "Last 30 days";
  if (rangeKey === "1y") return "Last 365 days";
  if (rangeKey === "ytd") return "Year to date (sample year)";
  return "All history";
}

function syncResultsRangePillsUi() {
  if (!resultsFeatureEnabled()) return;
  document.querySelectorAll(".results-range-pill[data-results-range]").forEach((b) => {
    b.classList.toggle("active", (b.getAttribute("data-results-range") || "") === resultsTimeRange);
  });
}

function kellyBetsJsonUrl() {
  return "data/results_kelly_bets.json";
}

function loadKellyBetsPayload() {
  if (KELLY.loaded || KELLY.loading) return Promise.resolve();
  KELLY.loading = true;
  KELLY.error = "";
  return fetch(cacheBustFetchUrl(kellyBetsJsonUrl()), { cache: "no-store" })
    .then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    })
    .then((j) => {
      KELLY.payload = j && typeof j === "object" ? j : null;
      KELLY.loaded = true;
    })
    .catch((e) => {
      KELLY.error = e?.message || String(e);
      KELLY.payload = null;
      KELLY.loaded = true;
    })
    .finally(() => {
      KELLY.loading = false;
    });
}

/** @returns {number[][]} */
function kellyBetTuples() {
  const b = KELLY.payload?.bets;
  return Array.isArray(b) ? b : [];
}

function kellyTupleEventName(row) {
  return Array.isArray(row) && row.length > 11 ? String(row[11] ?? "").trim() : "";
}

function kellyTupleDgId(row) {
  return Array.isArray(row) && row.length > 12 ? String(row[12] ?? "").trim() : "";
}

function resultsPlayerNameNormKey(name) {
  return String(name || "")
    .toLowerCase()
    .replace(/,/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Stable value for results-filter-player (dg:id or nm:key). */
function resultsPlayerFilterKey(row) {
  const id = kellyTupleDgId(row);
  if (id) return `dg:${id}`;
  const nm = String(row[10] ?? "").trim();
  if (!nm) return "";
  return `nm:${resultsPlayerNameNormKey(nm)}`;
}

function filterKellyBetTuples(tuples) {
  const market = resultsSelectValue("results-filter-market", resultsDefaultMarketValue());
  const book = resultsSelectValue("results-filter-book", "__all__");
  const minEv = num(document.getElementById("results-filter-min-ev")?.value, 0);
  return tuples.filter((row) => {
    const mkt = String(row[3] || "");
    const bk = String(row[4] || "");
    if (market && mkt !== market) return false;
    if (book !== "__all__" && bk !== book) return false;
    const evPct = num(row[5], NaN);
    if (!Number.isFinite(evPct) || evPct < minEv) return false;
    return true;
  });
}

function resultsPricingModeValue() {
  const raw = String(resultsSelectValue("results-filter-pricing-mode", "default") || "default").toLowerCase();
  return ["default", "recent", "course", "skill"].includes(raw) ? raw : "default";
}

function resultsPricingSkillKeyForRow(row) {
  const src = String(row?.[2] || "").toLowerCase();
  const mkt = String(row?.[3] || "").toLowerCase();
  if (src === "outrights") {
    if (mkt === "win") return "sg_total";
    if (mkt === "top_5" || mkt === "top_10" || mkt === "top_20") return "sg_t2g";
    if (mkt === "make_cut" || mkt === "mc") return "sg_ott";
    return "sg_total";
  }
  if (mkt === "3_balls") return "sg_app";
  if (mkt === "round_matchups") return "sg_t2g";
  return "sg_total";
}

function buildResultsDgIdLookupFromTuples(tuples) {
  const byName = new Map();
  for (const row of tuples || []) {
    const id = Math.round(num(row?.[12], NaN));
    const nameKey = resultsPlayerNameNormKey(String(row?.[10] || ""));
    if (!nameKey || !Number.isFinite(id) || id <= 0) continue;
    const prev = byName.get(nameKey);
    if (!prev) byName.set(nameKey, { id, n: 1 });
    else if (prev.id === id) prev.n += 1;
    else if (prev.n <= 1) byName.set(nameKey, { id, n: 1 });
  }
  const out = new Map();
  for (const [k, v] of byName.entries()) out.set(k, v.id);
  return out;
}

function resultsTupleDgIdResolved(row, dgIdLookup) {
  const id = Math.round(num(row?.[12], NaN));
  if (Number.isFinite(id) && id > 0) return id;
  const nm = resultsPlayerNameNormKey(String(row?.[10] || ""));
  if (!nm) return NaN;
  const lk = Math.round(num(dgIdLookup?.get(nm), NaN));
  return Number.isFinite(lk) && lk > 0 ? lk : NaN;
}

function applyPricingModeProbAdjust(baseP, row, pricingMode, dgIdLookup) {
  if (!Number.isFinite(baseP)) return NaN;
  const p = clamp(baseP, 1e-6, 1 - 1e-6);
  if (pricingMode === "default") return p;
  const dgId = resultsTupleDgIdResolved(row, dgIdLookup);
  if (!Number.isFinite(dgId)) return p;
  const skillKey = pricingMode === "skill" ? resultsPricingSkillKeyForRow(row) : PRICING_STATE.skill;
  const b = pricingModeMuSgBonusForMode(dgId, pricingMode, skillKey);
  if (!Number.isFinite(b) || b === 0) return p;
  const logit = Math.log(p / (1 - p));
  const z = logit + b * 0.85;
  const ez = Math.exp(clamp(z, -12, 12));
  return ez / (1 + ez);
}

/**
 * Keep rows where calibrated model has strictly positive edge vs book decimal (same rule as Kelly stake sizing).
 * Ensures Results uses **all +EV opportunities**, not binned EV approximations.
 */
function filterKellyTuplesPositiveModelEdge(tuples, pricingMode = "default", dgIdLookup = null) {
  return tuples.filter((row) => {
    const pBase = num(row[6], NaN);
    const dec = num(row[7], NaN);
    if (!Number.isFinite(pBase) || !Number.isFinite(dec) || dec <= 1) return false;
    const p = applyPricingModeProbAdjust(pBase, row, pricingMode, dgIdLookup);
    return p * dec - 1 > 1e-12;
  });
}

/**
 * Outrights only: keep top-N +EV runners by model EV% per (event × book × market).
 * Balances sample size and avoids betting the full field for one market snapshot.
 */
function filterOutrightTopNPerEventBookMarket(tuples, topN = 5) {
  const k = Math.max(1, Math.min(20, Math.round(num(topN, 5))));
  const keepNonOutrights = [];
  const buckets = new Map();
  for (const row of tuples) {
    const src = String(row[2] || "");
    if (src !== "outrights") {
      keepNonOutrights.push(row);
      continue;
    }
    const eid = String(row[9] || "").trim();
    const bk = String(row[4] || "").trim().toLowerCase();
    const mkt = String(row[3] || "").trim().toLowerCase();
    const date = String(row[1] || "").slice(0, 10);
    const key = eid ? `${eid}|${bk}|${mkt}` : `${date}|${bk}|${mkt}`;
    let arr = buckets.get(key);
    if (!arr) {
      arr = [];
      buckets.set(key, arr);
    }
    arr.push(row);
  }
  const keepOutrights = [];
  for (const arr of buckets.values()) {
    arr.sort((a, b) => num(b[5], -Infinity) - num(a[5], -Infinity) || num(a[0], 0) - num(b[0], 0));
    for (let i = 0; i < arr.length && i < k; i++) keepOutrights.push(arr[i]);
  }
  return [...keepNonOutrights, ...keepOutrights];
}

/**
 * Outright win rows are mutually exclusive outcomes, but keeping only one runner/event is too sparse.
 * Keep top-N model EV% win runners per event × book so sample size is usable.
 */
function filterOutrightWinTopNPerEventBook(tuples, topN = 3) {
  const k = Math.max(1, Math.min(20, Math.round(num(topN, 3))));
  const nonWin = [];
  const buckets = new Map();
  for (const row of tuples) {
    const src = String(row[2] || "");
    const mkt = String(row[3] || "");
    if (src !== "outrights" || mkt !== "win") {
      nonWin.push(row);
      continue;
    }
    const eid = String(row[9] || "").trim();
    const bk = String(row[4] || "").trim().toLowerCase();
    const date = String(row[1] || "").slice(0, 10);
    const key = eid ? `${eid}|${bk}` : `${date}|${bk}`;
    let arr = buckets.get(key);
    if (!arr) {
      arr = [];
      buckets.set(key, arr);
    }
    arr.push(row);
  }
  const keepWin = [];
  for (const arr of buckets.values()) {
    arr.sort((a, b) => num(b[5], -Infinity) - num(a[5], -Infinity) || num(a[0], 0) - num(b[0], 0));
    for (let i = 0; i < arr.length && i < k; i++) keepWin.push(arr[i]);
  }
  return [...nonWin, ...keepWin];
}

function kellyMaxDateIsoFromTuples(tuples) {
  let max = "";
  for (const row of tuples) {
    const d = String(row[1] || "").slice(0, 10);
    if (/^\d{4}-\d{2}-\d{2}$/.test(d) && d > max) max = d;
  }
  return max;
}

function kellyTuplesInTimeRange(tuples, rangeKey) {
  if (!tuples.length || rangeKey === "all") return tuples;
  const maxD = kellyMaxDateIsoFromTuples(tuples);
  if (!maxD) return tuples;
  const start = resultsTimeRangeStartIso(maxD, rangeKey);
  if (!start) return tuples;
  return tuples.filter((row) => String(row[1] || "").slice(0, 10) >= start);
}

/**
 * Kelly sim; tuple indices through dg_id when schema ≥ 3 (see build-results-backtest.mjs).
 * Stake fractions use **starting** bankroll B0 only (flat sizing). Equity is tracked without flooring at 0
 * so the series does not flatline after ruin when thousands of +EV bets share settlement days.
 * Same-day gross stake is capped to **one B0** (proportional scale), not to trailing equity.
 * @returns {{ series: object[], topWins: object[], nDays: number }}
 */
function simulateKellyDailySeriesDetailed(tuples, meta) {
  const B0 = num(meta?.bankroll0, 100);
  const kFrac = num(meta?.kelly_fraction, 0.25);
  const capF = num(meta?.max_kelly_stake_frac, 0.15);
  const pricingMode = String(meta?.pricing_mode || "default").toLowerCase();
  const dgIdLookup = meta?.dg_id_lookup || null;
  let equity = B0;
  let cumStake = 0;
  let nB = 0;
  const series = [];
  let lastTs = 0;
  /** @type {{ date: string, cumPnlUnits: number, profitUnits: number, stakeUnits: number, bankrollBeforeUnits: number, source: string, market: string, book: string, dec: number, player: string }[]} */
  const wins = [];
  const sorted = [...tuples].sort((a, b) => num(a[0], 0) - num(b[0], 0));
  const groups = new Map();
  for (const row of sorted) {
    const date = String(row[1] || "").slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
    let arr = groups.get(date);
    if (!arr) {
      arr = [];
      groups.set(date, arr);
    }
    arr.push(row);
  }
  const dates = [...groups.keys()].sort();
  const nDays = dates.length;
  for (const date of dates) {
    const rows = groups.get(date) || [];
    const sized = [];
    for (const row of rows) {
      const pBase = num(row[6], NaN);
      const decN = num(row[7], NaN);
      const w = num(row[8], 0) === 1 ? 1 : 0;
      const player = String(row[10] ?? "");
      const src = String(row[2] || "");
      const mkt = String(row[3] || "");
      const bk = String(row[4] || "");
      if (!Number.isFinite(decN) || decN <= 1 || !Number.isFinite(pBase)) continue;
      const pN = applyPricingModeProbAdjust(pBase, row, pricingMode, dgIdLookup);
      const edge = pN * decN - 1;
      let f = edge > 0 ? edge / (decN - 1) : 0;
      if (!Number.isFinite(f) || f <= 0) continue;
      f *= kFrac;
      f = Math.min(f, capF);
      if (!Number.isFinite(f) || f <= 0) continue;
      sized.push({ t: num(row[0], 0), f, decN, w, player, src, mkt, bk });
    }
    sized.sort(
      (a, b) =>
        a.t - b.t ||
        String(a.mkt).localeCompare(String(b.mkt)) ||
        String(a.bk).localeCompare(String(b.bk)) ||
        String(a.player).localeCompare(String(b.player)),
    );
    const nominalStakes = sized.map((s) => Math.min(Math.max(0, B0 * s.f), B0));
    const nominalTotal = nominalStakes.reduce((a, b) => a + b, 0);
    // Softer compression than linear scaling so high-volume days still show meaningful volatility.
    const dayScale = nominalTotal > 0 ? Math.min(1, Math.sqrt(B0 / nominalTotal)) : 0;
    for (let i = 0; i < sized.length; i++) {
      const s = sized[i];
      const stake = nominalStakes[i] * dayScale;
      if (!Number.isFinite(stake) || stake <= 0) continue;
      const bankrollBeforeUnits = equity;
      cumStake += stake;
      nB += 1;
      if (s.w) {
        const profitU = stake * (s.decN - 1);
        equity += profitU;
        wins.push({
          date,
          cumPnlUnits: equity - B0,
          profitUnits: profitU,
          stakeUnits: stake,
          bankrollBeforeUnits,
          source: s.src,
          market: s.mkt,
          book: s.bk,
          dec: s.decN,
          player: s.player,
        });
      } else {
        equity -= stake;
      }
      const ts = Math.max(lastTs + 1, num(s.t, 0));
      lastTs = ts;
      series.push({
        date,
        ts,
        cumBets: nB,
        cumStake,
        cumPnl: equity - B0,
        cumRoiPct: B0 > 0 ? (equity / B0 - 1) * 100 : 0,
        _kellyBr: equity,
      });
    }
  }
  wins.sort((a, b) => b.profitUnits - a.profitUnits);
  const topWins = wins.slice(0, 8);
  return { series, topWins, nDays };
}

function resultsBankrollDollarsFromUi() {
  const raw = num(document.getElementById("results-bankroll-dollars")?.value, 10000);
  return Math.max(100, raw);
}

function formatUsdCompact(n) {
  if (!Number.isFinite(n)) return "—";
  const sign = n < 0 ? "-" : "";
  const v = Math.abs(n);
  if (v >= 1e6) return `${sign}$${(v / 1e6).toFixed(2)}M`;
  if (v >= 10000) return `${sign}$${Math.round(v).toLocaleString("en-US")}`;
  if (v >= 1000) return `${sign}$${(v / 1000).toFixed(1)}k`;
  return `${sign}$${v.toFixed(0)}`;
}

function resultsMarketDisplayName(key) {
  const k = String(key || "").trim().toLowerCase();
  const map = {
    win: "Win",
    top_5: "Top 5",
    top_10: "Top 10",
    top_20: "Top 20",
    make_cut: "Make cut",
    mc: "Miss cut",
    tournament_matchups: "Tournament matchups",
    round_matchups: "Round matchups",
    "3_balls": "3-Balls",
  };
  if (map[k]) return map[k];
  return String(key || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function syncResultsBookLogoUi() {
  const wrap = document.getElementById("results-book-logo-wrap");
  if (!wrap) return;
  wrap.innerHTML = "";
  const bk = resultsSelectValue("results-filter-book", "__all__");
  if (bk === "__all__") return;
  const m = bookMeta(bk);
  const img = document.createElement("img");
  img.className = "results-book-logo-img";
  img.alt = m.label;
  const fb = document.createElement("span");
  fb.className = "results-book-logo-fallback";
  fb.textContent = m.short;
  fb.style.display = "none";
  wrap.appendChild(img);
  wrap.appendChild(fb);
  attachBookLogoWithFallback(img, fb, m.domain);
}

async function renderResultsKellyPnL() {
  if (!resultsFeatureEnabled()) return;
  await loadKellyBetsPayload();
  const bankrollDollars = resultsBankrollDollarsFromUi();
  const B0Fallback = num(KELLY.payload?.bankroll0, 100);
  const metaFallback = {
    bankroll0: B0Fallback,
    kelly_fraction: num(KELLY.payload?.kelly_fraction, 0.25),
    max_kelly_stake_frac: num(KELLY.payload?.max_kelly_stake_frac, 0.15),
    bankrollDollars,
  };
  const tuples0 = kellyBetTuples();
  if (!KELLY.payload || !tuples0.length) {
    resultsStatus(
      KELLY.error ? `Unable to load bet history (${KELLY.error})` : "Bet history unavailable. Run npm run build:results.",
    );
    drawResultsChart([], { bankrollDollars, bankroll0: B0Fallback, totalBets: 0, winMarkers: [] });
    renderResultsSummaryKellyUsd([], metaFallback, bankrollDollars);
    syncResultsBookLogoUi();
    return;
  }
  const pricingMode = resultsPricingModeValue();
  const dgIdLookup = buildResultsDgIdLookupFromTuples(tuples0);
  let t = filterKellyBetTuples(tuples0);
  t = filterKellyTuplesPositiveModelEdge(t, pricingMode, dgIdLookup);
  t = filterOutrightTopNPerEventBookMarket(t, 5);
  const selectedMarket = resultsSelectValue("results-filter-market", resultsDefaultMarketValue());
  t = kellyTuplesInTimeRange(t, resultsTimeRange);
  const meta = {
    bankroll0: num(KELLY.payload.bankroll0, 100),
    kelly_fraction: num(KELLY.payload.kelly_fraction, 0.25),
    max_kelly_stake_frac: num(KELLY.payload.max_kelly_stake_frac, 0.15),
    pricing_mode: pricingMode,
    dg_id_lookup: dgIdLookup,
  };
  const B0 = meta.bankroll0;
  const { series, nDays } = simulateKellyDailySeriesDetailed(t, meta);
  const points = series.map((p) => ({
    ...p,
    cumPnlUsd: (p.cumPnl / B0) * bankrollDollars,
    cumStakeUsd: (p.cumStake / B0) * bankrollDollars,
  }));
  const winMarkers = [];
  const kfPct = (num(meta.kelly_fraction, 0.25) * 100).toFixed(0);
  const capPct = (num(meta.max_kelly_stake_frac, 0.15) * 100).toFixed(0);
  resultsStatus("");
  drawResultsChart(points, {
    bankrollDollars,
    bankroll0: B0,
    totalBets: t.length,
    winMarkers,
  });
  renderResultsSummaryKellyUsd(points, { ...meta, bankrollDollars }, bankrollDollars);
  syncResultsBookLogoUi();
}

function syncResultsChartCanvasCssBox(canvas, cssW, cssH) {
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  canvas.style.maxWidth = "100%";
  canvas.style.boxSizing = "border-box";
}

const RESULTS_MONTH_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** Axis / table: include year for clarity (e.g. Jan 20, 2026). */
function resultsChartFormatDateLong(iso) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return String(iso || "");
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  const mon = RESULTS_MONTH_SHORT[mo - 1] || String(mo);
  return `${mon} ${d}, ${y}`;
}

/** Compact axis label (e.g. Jan '19) — even spacing uses index ticks; short text avoids overlap. */
function resultsChartFormatDateAxis(iso) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return String(iso || "").slice(0, 9);
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const mon = RESULTS_MONTH_SHORT[mo - 1] || String(mo);
  const yy = y % 100;
  return `${mon} '${yy < 10 ? `0${yy}` : String(yy)}`;
}

/** `count` tick positions from 0 … n-1 at equal index gaps (symmetric on chart width). */
function resultsChartEvenXTickIndices(n, count) {
  if (n <= 0) return [];
  const k = Math.max(2, Math.min(count, n));
  if (n === 1) return [0];
  const out = [];
  for (let j = 0; j < k; j++) {
    out.push(Math.round((j / (k - 1)) * (n - 1)));
  }
  return [...new Set(out)].sort((a, b) => a - b);
}

function resultsChartNiceYTicks(lo, hi, wantInt = false) {
  const span = Math.max(1e-9, hi - lo);
  const raw = span / 4;
  const pow10 = 10 ** Math.floor(Math.log10(raw));
  const fr = raw / pow10;
  let step = pow10;
  if (fr < 1.5) step = pow10;
  else if (fr < 3.5) step = 2 * pow10;
  else if (fr < 8) step = 5 * pow10;
  else step = 10 * pow10;
  const start = Math.floor(lo / step) * step;
  const out = [];
  for (let v = start; v <= hi + step * 0.001; v += step) {
    if (v >= lo - 1e-9 && v <= hi + 1e-9) out.push(v);
    if (out.length > 8) break;
  }
  if (wantInt) return out.map((x) => Math.round(x));
  return out;
}

function drawResultsChart(points, opts = {}) {
  resultsChartHitRegions = [];
  hideResultsChartTooltip();
  const bankrollDollars = num(opts.bankrollDollars, 10000);
  const bankroll0 = num(opts.bankroll0, 100);
  const totalBets = Math.round(
    num(opts.totalBets, points.length ? points[points.length - 1].cumBets : 0),
  );
  const winMarkers = Array.isArray(opts.winMarkers) ? opts.winMarkers : [];

  function rowUsd(p) {
    if (Number.isFinite(p.cumPnlUsd)) return p.cumPnlUsd;
    return (num(p.cumPnl, 0) / bankroll0) * bankrollDollars;
  }

  const canvas = document.getElementById("results-chart-canvas");
  const wrap = canvas?.closest(".results-chart-wrap");
  if (!canvas || !canvas.getContext) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  const kpiMain = document.getElementById("results-kpi-main");
  const kpiSub = document.getElementById("results-kpi-sub");
  const kpiLab = document.getElementById("results-kpi-label");
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const vhCap = typeof window !== "undefined" ? Math.min(520, Math.round(window.innerHeight * 0.42)) : 520;

  function paintEmpty(msg, cssW0, cssH0) {
    canvas.width = Math.round(cssW0 * dpr);
    canvas.height = Math.round(cssH0 * dpr);
    syncResultsChartCanvasCssBox(canvas, cssW0, cssH0);
    const c0 = canvas.getContext("2d");
    if (!c0) return;
    c0.setTransform(dpr, 0, 0, dpr, 0, 0);
    c0.clearRect(0, 0, cssW0, cssH0);
    c0.fillStyle = "#111216";
    c0.fillRect(0, 0, cssW0, cssH0);
    c0.fillStyle = "#8b8f9c";
    c0.font = "13px DM Sans, system-ui, sans-serif";
    c0.textAlign = "left";
    c0.textBaseline = "top";
    c0.fillText(msg, 14, 14);
  }

  const visibleW = wrap && wrap.clientWidth > 80 ? wrap.clientWidth - 4 : 800;
  const cssW = Math.round(visibleW);
  const cssH = Math.round(clamp(visibleW * 0.42, 240, vhCap));

  if (!points.length) {
    if (kpiLab) kpiLab.textContent = "Cumulative Kelly PnL";
    if (kpiMain) {
      kpiMain.textContent = "—";
      kpiMain.classList.remove("results-kpi-pos", "results-kpi-neg");
    }
    if (kpiSub) kpiSub.textContent = "";
    paintEmpty("No bets for current filters.", cssW, cssH);
    return;
  }

  syncResultsChartCanvasCssBox(canvas, cssW, cssH);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cssW, cssH);
  ctx.fillStyle = "#111216";
  ctx.fillRect(0, 0, cssW, cssH);

  const pad = { l: 62, r: 16, t: 14, b: 44 };
  const innerW = Math.max(60, cssW - pad.l - pad.r);
  const innerH = Math.max(60, cssH - pad.t - pad.b);

  const vals = points.map((p) => rowUsd(p));
  let minV = Math.min(...vals);
  let maxV = Math.max(...vals);
  const span0 = Math.max(1e-9, maxV - minV);
  const padAbs = Math.max(250, span0 * 0.15);
  minV -= padAbs;
  maxV += padAbs;
  if (maxV - minV < 800) {
    const mid = (minV + maxV) / 2;
    minV = mid - 400;
    maxV = mid + 400;
  }

  const yScale = (v) => pad.t + innerH * (1 - (v - minV) / (maxV - minV));
  const yTicks = resultsChartNiceYTicks(minV, maxV, false);

  ctx.strokeStyle = "rgba(255, 255, 255, 0.07)";
  ctx.lineWidth = 1;
  for (const tv of yTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    const y = yScale(tv);
    ctx.beginPath();
    ctx.moveTo(pad.l, y);
    ctx.lineTo(pad.l + innerW, y);
    ctx.stroke();
  }

  ctx.strokeStyle = "#2b2e36";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad.l, pad.t);
  ctx.lineTo(pad.l, pad.t + innerH);
  ctx.lineTo(pad.l + innerW, pad.t + innerH);
  ctx.stroke();

  ctx.fillStyle = "#8b8f9c";
  ctx.font = "10px DM Sans, system-ui, sans-serif";
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  for (const tv of yTicks) {
    if (tv < minV - 1e-9 || tv > maxV + 1e-9) continue;
    const y = yScale(tv);
    ctx.fillText(formatUsdCompact(tv), pad.l - 8, y);
  }

  ctx.save();
  ctx.translate(12, pad.t + innerH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = "#6b7280";
  ctx.font = "11px DM Sans, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("Cumulative Kelly PnL ($)", 0, 0);
  ctx.restore();

  const xByIndex = (i) => pad.l + (i / Math.max(1, points.length - 1)) * innerW;

  const zeroY = minV <= 0 && maxV >= 0 ? yScale(0) : NaN;
  if (Number.isFinite(zeroY)) {
    ctx.strokeStyle = "rgba(255,255,255,0.22)";
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(pad.l, zeroY);
    ctx.lineTo(pad.l + innerW, zeroY);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  const grad = ctx.createLinearGradient(pad.l, 0, pad.l + innerW, 0);
  grad.addColorStop(0, "#00c46b");
  grad.addColorStop(1, "rgba(0, 196, 107, 0.45)");
  ctx.strokeStyle = grad;
  ctx.lineWidth = 2.25;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";
  ctx.beginPath();
  for (let i = 0; i < points.length; i++) {
    const p = points[i];
    const px = xByIndex(i);
    const py = yScale(rowUsd(p));
    if (!Number.isFinite(px) || !Number.isFinite(py)) continue;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.stroke();

  const nPts = points.length;
  const maxTicks = innerW < 480 ? 5 : innerW < 680 ? 6 : innerW < 900 ? 7 : 8;
  const xTickIdx = resultsChartEvenXTickIndices(nPts, maxTicks);

  const xFontPx = nPts > 400 || innerW < 560 ? 9 : 10;
  ctx.fillStyle = "#8b8f9c";
  ctx.font = `${xFontPx}px DM Sans, system-ui, sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  for (const idx of xTickIdx) {
    const p = points[idx];
    const px = xByIndex(idx);
    if (!Number.isFinite(px)) continue;
    const lab = resultsChartFormatDateAxis(p.date);
    ctx.fillText(lab, px, pad.t + innerH + 8);
    ctx.strokeStyle = "rgba(255,255,255,0.08)";
    ctx.beginPath();
    ctx.moveTo(px, pad.t + innerH);
    ctx.lineTo(px, pad.t + innerH + 5);
    ctx.stroke();
  }

  ctx.fillStyle = "#8b8f9c";
  ctx.font = "10px DM Sans, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  ctx.fillText("Date", pad.l + innerW / 2, cssH - 12);

  for (const wm of winMarkers) {
    const i = Math.max(0, Math.min(points.length - 1, Math.round(num(wm.pointIndex, 0))));
    const px = xByIndex(i) + num(wm.xShift, 0);
    const py = yScale(rowUsd(points[i]));
    if (!Number.isFinite(px) || !Number.isFinite(py)) continue;
    ctx.beginPath();
    ctx.arc(px, py, 6, 0, Math.PI * 2);
    ctx.fillStyle = "#facc15";
    ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,0.92)";
    ctx.lineWidth = 2;
    ctx.stroke();
    resultsChartHitRegions.push({
      kind: "win",
      cx: px,
      cy: py,
      r: 14,
      tipHtml: wm.tipHtml || "",
    });
  }

  const last = points[points.length - 1];
  const first = points[0];
  if (kpiLab) kpiLab.textContent = "Cumulative Kelly PnL";
  if (kpiMain) {
    const rawEnd = rowUsd(last);
    const endStr = `${rawEnd > 0 ? "+" : ""}${formatUsdCompact(rawEnd)}`;
    kpiMain.textContent = endStr;
    kpiMain.classList.remove("results-kpi-pos", "results-kpi-neg");
    if (rawEnd > 25) kpiMain.classList.add("results-kpi-pos");
    else if (rawEnd < -25) kpiMain.classList.add("results-kpi-neg");
  }
  if (kpiSub) kpiSub.textContent = "";
}

function renderResultsSummaryKellyUsd(points, meta, bankrollDollars) {
  const trh = document.querySelector("#table-results-summary thead tr");
  if (trh) {
    trh.innerHTML =
      "<th class=\"num\">Bets</th><th class=\"num\">Total staked</th><th class=\"num\">Net P&amp;L</th><th class=\"num\">Return</th><th>Period</th>";
  }
  const tb = document.querySelector("#table-results-summary tbody");
  if (!tb) return;
  tb.innerHTML = "";
  const tr = document.createElement("tr");
  const B0 = num(meta?.bankroll0, 100);
  const last = points.length ? points[points.length - 1] : null;
  const bets = last ? Math.round(last.cumBets) : 0;
  let stakeUsd = 0;
  let netUsd = 0;
  let roiPct = 0;
  if (last) {
    stakeUsd = Number.isFinite(last.cumStakeUsd)
      ? last.cumStakeUsd
      : (num(last.cumStake, 0) / B0) * bankrollDollars;
    netUsd = Number.isFinite(last.cumPnlUsd)
      ? last.cumPnlUsd
      : (num(last.cumPnl, 0) / B0) * bankrollDollars;
    roiPct = Number.isFinite(last.cumRoiPct) ? last.cumRoiPct : 0;
  }
  const firstDate = points.length ? resultsChartFormatDateLong(points[0].date) : "—";
  const lastDate = points.length ? resultsChartFormatDateLong(points[points.length - 1].date) : "—";
  const cells = [
    bets.toLocaleString(),
    formatUsdCompact(stakeUsd),
    `${netUsd >= 0 ? "+" : ""}${formatUsdCompact(netUsd)}`,
    `${roiPct >= 0 ? "+" : ""}${roiPct.toFixed(2)}%`,
    `${firstDate} – ${lastDate}`,
  ];
  for (let i = 0; i < cells.length; i++) {
    const td = document.createElement("td");
    td.textContent = cells[i];
    if (i < 4) td.className = "num";
    tr.appendChild(td);
  }
  tb.appendChild(tr);
  const kf = num(meta?.kelly_fraction, 0.25);
  const cap = num(meta?.max_kelly_stake_frac, 0.15);
  tr.title = `Model bankroll ${B0} u · scaled to $${Math.round(bankrollDollars).toLocaleString("en-US")} · ${(kf * 100).toFixed(0)}% Kelly · max ${(cap * 100).toFixed(0)}% per bet`;
}

